/* Bigorna Rooms: the map generator. A map is an experience, not a heap of rooms: why the heroes go in (the premise),
   how the tension grows and breathes (the beats, each a room of an archetype), a gimmick that changes how the map is
   played (three keys, captives to lead out, seals of a ritual, waves to hold, a collapse to outrun…), the objectives
   along the way and the end. The rooms come from the room generator (gerador.js), one after the other, each born at an
   edge of the one before it. Everything is plain data below and can be edited. */
'use strict';

/* Portuguese joins a preposition and the article of the place: "em a fortaleza" → "na fortaleza" */
const CONTRACOES = { 'a a': 'à', 'a as': 'às', 'a o': 'ao', 'a os': 'aos', 'em a': 'na', 'em as': 'nas', 'em o': 'no', 'em os': 'nos', 'de a': 'da', 'de as': 'das', 'de o': 'do', 'de os': 'dos', 'por a': 'pela', 'por as': 'pelas', 'por o': 'pelo', 'por os': 'pelos' };
// (a whole word only: "começa a brilhar" once became "começà brilhar", \b taking the ç for a break)
const contrair = t => LP() !== 'pt' ? t : t.replace(/(?<![\p{L}\p{N}])(a|em|de|por) (a|as|o|os) (?=\S)/giu, (m, p1, p2) => { const r = CONTRACOES[p1.toLowerCase() + ' ' + p2.toLowerCase()]; return r ? (p1[0] === p1[0].toUpperCase() ? r.charAt(0).toUpperCase() + r.slice(1) : r) + ' ' : m; });
const preencher = (t, v) => { v = v || {}; const r = contrair(generos(TXT(t), v).replace(/\{(\w+)(?::([^{}]+))?\}/g, (x, k, f) => v[k] === undefined ? x : f && OUTRA_LINGUA ? formaNaLingua(v[k], f) : v[k]));   // (v353: {lugar:dat}, a form of the name in the language)
  // (v259: in the other languages, any letter of theirs, after their own quotes too)
  return OUTRA_LINGUA ? pecaNaLingua(r.replace(/(^|[.!?]\s+|[。！？])(["“«„「]?)(\p{Ll})/gu, (m, a, q, c) => a + q + c.toUpperCase())) : r.replace(/(^|[.!?]\s+)(["“«]?)([a-zà-ú])/g, (m, a, q, c) => a + q + c.toUpperCase()); };   // (v365: « too, the quote of Portuguese)   // (also after an opening quote: "{vilao} waits…")

/* v326: the gender of a drawn word, for the marks ⟨key:m|f⟩ and ⟨key:ms|fs|mp|fp⟩: the drawn ones carry it (v._g), the rest
   come from their article (os/as/o/a) */
const generoDe = (v, k) => (v._g && v._g[k]) || (s => /^as /i.test(s) ? 'fp' : /^os /i.test(s) ? 'mp' : /^a [^,]* e as /i.test(s) ? 'fp' : /^[ao] [^,]* e [ao]s? /i.test(s) ? 'mp' : /^a /i.test(s) ? 'fs' : 'ms')(String(v[k] || ''));   // (v330: «a noiva e as damas» is plural)
const generos = (t, v) => String(t).replace(/⟨(\w+):([^⟩]*)⟩/g, (m, k, ops) => { if (OUTRA_LINGUA && /=/.test(ops)) { const r = rotuloNaLingua(v[k] ?? '', ops, typeof v[k] === 'number'); if (r != null) return r; }   // (v353: ⟨vilao:m=er|f=sie|n=es⟩, by the name's sheet in the language)
  const g = generoDe(v, k); const o = ops.split('|');
  return o.length >= 4 ? o[['ms', 'fs', 'mp', 'fp'].indexOf(g)] : o[g[0] === 'f' ? 1 : 0]; });

// ------------------------------------------------------------ premises: why the heroes go in
/* fields: id, nome, resumo; truques (the gimmicks that fit, first is the favourite); faccao (monsters); final (how the
   map ends: boss = defeat the last room, relic = use the relic, exit = use the way out, counter = the gimmick's count, destroy = tear down
   a great thing in the last room);
   textos: titulo, intro, climax, fim (with {vilao}, {lugar}, {alvo}, {n}) */
const PREMISSAS_MAPA = [
  { id: 'resgate', nome: { en: 'Rescue', pt: 'Resgate' }, resumo: { en: 'Captives are held inside: find them all and lead them out.', pt: 'Há prisioneiros lá dentro: achem todos e levem-nos para fora.' },
    truques: ['resgate'], faccao: 'bandidos', final: 'exit', alvo: { en: 'the captives', pt: 'os prisioneiros' },
    titulo: { en: ['The Cells of {vilao}', 'No One Left Behind', 'Chains in {lugar}'], pt: ['As Celas de {vilao}', 'Ninguém Fica para Trás', 'Correntes em {lugar}'] },
    intro: { en: ["Now you can see what happened: {cativos} came through here tied up, and the one who took them was {vilao}. From the care they were handled with, they are worth more alive. Someone means to collect on them."], pt: ["Agora dá para entender o que aconteceu: {cativos} passaram por aqui amarrados, e quem os levou foi {vilao}. Pelo cuidado com que foram tratados, valem mais vivos. Alguém pretende cobrar por eles."] },
    climax: { en: ["{vilao} stands between you and the way out, the end of the rope wound around one fist."], pt: ["{vilao} está entre vocês e a saída, com a ponta da corda enrolada no punho."] },
    fim: { en: ["{cativos} blink in the daylight, rubbing the rope marks on their wrists. Someone laughs, then someone cries, and nobody is quite sure who started."], pt: ["{cativos} piscam sob a luz do dia, esfregando os pulsos marcados pela corda. Alguém ri, depois alguém chora, e ninguém sabe direito quem começou."] },
    linhas: [{"id": "mineiros", "t": ["caverna"], "resgate": "mineiros-do-turno", "titulo": {"en": ["The Mine of {vilao}", "Below the Shaft", "The Lost Shift"], "pt": ["A Mina de {vilao}", "Abaixo do Poço", "O Turno Perdido"]}, "chegada": {"en": ["The women of the hillside have waited at the head of the road, lanterns lit, for three nights. Bandits took {lugar} and set {cativos} to dig by force. Without their hands, the houses will have no firewood and no bread this winter, and the eldest already blows out her lantern to save oil."], "pt": ["As mulheres da encosta esperam na boca da estrada, de lampião aceso, há três noites. Bandidos tomaram {lugar} e puseram {cativos} para cavar à força. Sem os braços deles, as casas ficam sem lenha e sem pão no inverno, e a mais velha já apaga o lampião para poupar óleo."]}, "intro": {"en": ["The whole story is here: a vein of silver, and {vilao} set on tearing it out of the rock at the cost of {cativos}. The sound of picks still comes from below. While they ring, someone is alive."], "pt": ["A história está toda aqui: um veio de prata, e {vilao} decidido a tirá-lo da rocha à custa de {cativos}. Lá do fundo ainda vem o som das picaretas. Enquanto baterem, tem gente viva."]}, "climax": {"en": ["{vilao} stands between you and the way out, among the stolen silver."], "pt": ["{vilao} está entre vocês e a saída, no meio da prata roubada."]}, "fim": {"en": ["{cativos} climb into the light covered in silver dust, leaning on one another. One of them stops at the way out, looks back and spits on the mine."], "pt": ["{cativos} sobem para a luz cobertos de pó de prata, apoiados uns nos outros. Um deles para na saída, olha para trás e cospe na mina."]}}, {"id": "casamento", "vilao": "ele", "resgate": "noiva-e-damas", "titulo": {"en": ["The Interrupted Wedding", "The Stolen Bride", "Before the Families Go to War"], "pt": ["O Casamento Interrompido", "A Noiva Roubada", "Antes que as Famílias Briguem"]}, "chegada": {"en": ["There are still petals along the road. In the middle of the feast, armed men took {cativos}, and the groom's family swears it was treachery by the bride's. “If she is back by tomorrow, I can still hold my sons,” says the groom's father. “After that, no one can.” The tracks end at {lugar}."], "pt": ["Ainda há pétalas pela estrada. No meio da festa, homens armados levaram {cativos}, e a família do noivo jura que foi traição da família da noiva. «Se ela voltar até amanhã, eu ainda seguro meus filhos», diz o pai do noivo. «Depois disso, ninguém segura.» Os rastros terminam em {lugar}."]}, "intro": {"en": ["Now it all fits: the attack on the feast was ordered by {vilao}, who asked for the bride's hand last year and heard a no. By the look of it, still hoping to hear a yes."], "pt": ["Agora tudo se encaixa: o ataque à festa foi encomenda de {vilao}, que pediu a mão da noiva no ano passado e ouviu um não. Pelo jeito, ainda espera ouvir um sim."]}, "climax": {"en": ["{vilao} stands between you and the way out, still dressed for a wedding that will never be."], "pt": ["{vilao} está entre vocês e a saída, ainda vestido para um casamento que não vai acontecer."]}, "fim": {"en": ["{cativos} come out into the light still in their feast clothes, torn and caked with earth. The bride pulls off her veil, looks at you and asks whether there is still time to be married today."], "pt": ["{cativos} saem para a luz ainda com as roupas da festa, rasgadas e sujas de terra. A noiva arranca o véu, olha para vocês e pergunta se ainda dá tempo de casar hoje."]}}] },
  { id: 'reliquia', nome: { en: 'Relic', pt: 'Relíquia' }, resumo: { en: 'Something of power lies at the heart of the place: take it before the enemy does.', pt: 'Algo de poder jaz no coração do lugar: tomem-no antes do inimigo.' },
    truques: [null, 'desabamento'], faccao: 'mortos', final: 'relic', alvo: { en: 'the relic', pt: 'a relíquia' },
    titulo: { en: ['The Vault of {lugar}', 'What {vilao} Guards', 'The Last Reliquary'], pt: ['A Cripta de {lugar}', 'O Que {vilao} Guarda', 'O Último Relicário'] },
    intro: { en: ["Someone got here first: {vilao}, who has already robbed two shrines looking for {alvo}, is inside turning every room upside down. From the mess, still searching. Whoever gets there first decides what comes next."], pt: ["Alguém chegou primeiro: {vilao}, que já saqueou dois santuários atrás de {alvo}, está aqui dentro revirando cada sala. Pela bagunça, ainda está procurando. Quem chegar antes decide o que vem depois."] },
    climax: { en: ["There it is, on its pedestal, and {vilao} is already reaching for it."], pt: ["Lá está ela, no pedestal, e {vilao} já estende a mão."] },
    fim: { en: ["{alvo} is heavier than it looks, and the air around it hums softly, as if it were breathing. You wrap it in a cloth, and the humming settles."], pt: ["{alvo} pesa mais do que parece, e o ar em volta dela zumbe baixinho, como se respirasse. Vocês a enrolam num pano, e o zumbido se acalma."] } },
  { id: 'ritual', nome: { en: 'Stop the ritual', pt: 'Impedir o ritual' }, resumo: { en: 'A rite is under way: break what feeds it and face whoever leads it.', pt: 'Um rito está em curso: quebrem o que o alimenta e enfrentem quem o conduz.' },
    truques: ['selos', null], faccao: 'culto', final: 'boss', alvo: { en: 'the rite', pt: 'o rito' },
    titulo: { en: ['The Rite of {vilao}', 'Blood on {lugar}', 'Before the Last Chant'], pt: ['O Rito de {vilao}', 'Sangue em {lugar}', 'Antes do Último Cântico'] },
    intro: { en: ["The hum has an explanation: {vilao} leads a cult in here, and the chant is calling something across. Every verse brings it closer. Before the reckoning, what feeds the rite must be broken."], pt: ["O zumbido tem explicação: {vilao} rege um culto aqui dentro, e o cântico está chamando algo para este lado. Cada verso o traz mais perto. Antes do confronto, é preciso quebrar o que alimenta o rito."] },
    climax: { en: ["At the centre of the circle, {vilao} stops chanting. The chant goes on anyway."], pt: ["No centro do círculo, {vilao} para de cantar. O cântico continua assim mesmo."] },
    fim: { en: ["The chant breaks off in the middle of a word. The silence left behind is so deep you can hear water dripping far below."], pt: ["O cântico se interrompe no meio de uma palavra. O silêncio que fica é tão grande que dá para ouvir a água pingando lá no fundo."] },
    linhas: [{"id": "grimorio", "t": ["masmorra", "cripta", "fortaleza"], "truques": ["selos"], "pecas": "copias-do-grimorio", "titulo": {"en": ["The Black Grimoire", "The Copyists of {lugar}", "Ink and Ash"], "pt": ["O Grimório Negro", "Os Copistas de {lugar}", "Tinta e Cinza"]}, "chegada": {"en": ["The temple librarian hands you a torch and a flask of oil. A forbidden grimoire has vanished from the shelves and is now being copied in {lugar}. “Every copy that leaves there carries the same evil to another city,” he says. “Burn it all. The original too. Especially the original.”"], "pt": ["O bibliotecário do templo entrega a vocês uma tocha e um frasco de óleo. Um grimório proibido sumiu das estantes e agora é copiado em {lugar}. «Cada cópia que sair de lá leva o mesmo mal a outra cidade», diz ele. «Queimem tudo. Até o original. Principalmente o original.»"]}, "intro": {"en": ["The stolen grimoire ended up here: {vilao} had it copied, and every new page feeds the rite. The copies must burn before they leave."], "pt": ["O grimório roubado veio parar aqui: {vilao} o mandou copiar, e cada página nova alimenta o rito. As cópias precisam queimar antes de sair."]}, "climax": {"en": ["At the centre of the circle, {vilao} reads the original aloud, eyes alight."], "pt": ["No centro do círculo, {vilao} lê o original em voz alta, os olhos em brasa."]}, "fim": {"en": ["The grimoire crackles in the fire like green wood, and its pages writhe as if trying to escape. Soon, only ash is left."], "pt": ["O grimório estala no fogo como lenha verde, e as páginas se retorcem como se tentassem fugir. Logo, sobra só cinza."]}}] },
  { id: 'cacada', nome: { en: 'The hunt', pt: 'A caçada' }, resumo: { en: 'A beast preys on the region: follow its tracks to its lair.', pt: 'Uma fera ataca a região: sigam os rastros até o covil.' },
    truques: ['fera', 'ninhos'], faccao: 'feras', final: 'boss', alvo: { en: 'the beast', pt: 'a fera' },
    viloes: ['cervo-cinzento', 'pai-lobo', 'serpente-de-brasa', 'rei-das-presas', 'rainha-mariposa'],   // (v335: the villain of the hunt is the beast: no tamer, no huntress)
    titulo: { en: ['The Lair of {vilao}', 'Tracks in {lugar}', 'The Hunter\'s Price'], pt: ['O Covil de {vilao}', 'Rastros em {lugar}', 'O Preço do Caçador'] },
    intro: { en: ["This is the den of {vilao}, the beast that came down from the hills at the last moon. From the bones scattered about, it eats well. Read the tracks carefully, because it reads yours too."], pt: ["Este é o covil de {vilao}, a fera que desceu das colinas na última lua. Pelos ossos espalhados, ela come bem. Leiam os rastros com cuidado, porque ela também lê os de vocês."] },
    climax: { en: ['Bones everywhere. A low growl. {vilao} was waiting.'], pt: ['Ossos por toda parte. Um rosnado grave. {vilao} estava esperando.'] },
    fim: { en: ["{vilao} falls, and the ground shakes with the weight. For a moment, nobody moves, just to be sure."], pt: ["{vilao} cai, e o chão treme com o peso. Por um instante, ninguém se mexe, só para ter certeza."] } },
  { id: 'investigacao', nome: { en: 'Investigation', pt: 'Investigação' }, resumo: { en: 'People have vanished: gather the clues and find the truth at the end.', pt: 'Pessoas sumiram: juntem as pistas e achem a verdade no fim.' },
    truques: [null], faccao: 'bandidos', final: 'relic', alvo: { en: 'the truth', pt: 'a verdade' }, missao: { en: 'Uncover the truth', pt: 'Descubram a verdade' },
    titulo: { en: ['The Silence of {lugar}', 'Where the Missing Went', 'A Name in the Ledger'], pt: ['O Silêncio de {lugar}', 'Para Onde Foram os Desaparecidos', 'Um Nome no Livro'] },
    intro: { en: ["The sums add up: travellers vanish on this road because {vilao} pays the garrison to look the other way. What becomes of them lies further in."], pt: ["A conta fecha: os viajantes somem nesta estrada porque {vilao} paga a guarnição para olhar para o outro lado. O que fazem com eles está mais adiante."] },
    climax: { en: ['The last door. Behind it, the answer, and {vilao}.'], pt: ['A última porta. Atrás dela, a resposta, e {vilao}.'] },
    fim: { en: ["In the last room, the belongings of the missing wait in piles, each one with a tag. The answer is hard, but it is an answer."], pt: ["Na última sala, os pertences dos desaparecidos esperam em pilhas, cada um com uma etiqueta. A resposta é dura, mas é uma resposta."] },
    linhas: [{"id": "traidor", "t": ["aldeia", "fortaleza"], "titulo": {"en": ["The Traitor of {lugar}", "Sold from Within", "The Council's Secret"], "pt": ["O Traidor de {lugar}", "Vendidos por Dentro", "O Segredo do Conselho"]}, "chegada": {"en": ["The attacks on {lugar} always fall where the guard is weakest, at the exact hour the watch changes. Captain Aldo suspects the council, the seven who decide everything there. “Six of them are honest,” he says. “I dine with all seven every week, and I cannot tell which one is the other.”"], "pt": ["Os ataques a {lugar} caem sempre onde a guarda está mais fraca, na hora exata da troca de turno. O capitão Aldo desconfia do conselho, os sete que decidem tudo ali. «Seis são honestos», diz ele. «Eu janto com os sete toda semana e não sei dizer qual é o outro.»"]}, "intro": {"en": ["The betrayal has half a face: someone on the council sells the secrets of {lugar} to {vilao}, for gold and the promise of a house spared. Gold leaves a trail."], "pt": ["A traição tem um rosto pela metade: alguém do conselho vende os segredos de {lugar} para {vilao}, em troca de ouro e da promessa de ter a casa poupada. O ouro deixa rastro."]}, "climax": {"en": ["The last door. Behind it, the proof of who sold you all, and {vilao}, come for the last secret."], "pt": ["A última porta. Atrás dela, a prova de quem vendeu todos, e {vilao}, que veio buscar o último segredo."]}, "fim": {"en": ["The name is there, in a letter sealed with a seal you have already seen on the council table. Now there is no more doubt."], "pt": ["O nome está ali, numa carta lacrada com um selo que vocês já viram na mesa do conselho. Agora não há mais dúvida."]}, "alvo": {"en": "the proof of the betrayal", "pt": "a prova da traição"}, "missao": {"en": "Find the proof of the betrayal", "pt": "Encontrem a prova da traição"}}, {"id": "pedagio", "t": ["ermo", "aldeia"], "titulo": {"en": ["The Toll of {lugar}", "The Bridge That Takes", "Pay or Vanish"], "pt": ["O Pedágio de {lugar}", "A Ponte que Cobra", "Pague ou Suma"]}, "chegada": {"en": ["On the bridge near {lugar}, armed men collect a toll no lord ever allowed. Whoever pays crosses; whoever argues vanishes, wagon and all, and the brother-in-law of Bento the drover always did like to argue. The fair is a week away."], "pt": ["Na ponte perto de {lugar}, homens armados cobram um pedágio que nenhum senhor autorizou. Quem paga atravessa; quem discute some com carroça e tudo, e o cunhado do tropeiro Bento sempre gostou de discutir. A feira é daqui a uma semana."]}, "intro": {"en": ["The bridge has a new owner: {vilao}, who took it over the body of the old keeper. Whoever argued about the price ended up in here, wagon and all."], "pt": ["A ponte tem dono novo: {vilao}, que a tomou por cima do corpo do antigo guarda. Quem discutiu o preço veio parar aqui dentro, com carroça e tudo."]}, "climax": {"en": ["At the back, the carts of those who did not pay. And {vilao}, counting the toll money."], "pt": ["No fundo, as carroças de quem não pagou. E {vilao}, contando o dinheiro do pedágio."]}, "fim": {"en": ["The toll chest is there, heavy with the coins of people who only wanted to cross. Beside it, the missing drovers, thin and alive."], "pt": ["O cofre do pedágio está lá, pesado de moedas de gente que só queria atravessar. Junto dele, os carroceiros sumidos, magros e vivos."]}, "alvo": {"en": "the toll chest", "pt": "o cofre do pedágio"}, "missao": {"en": "Take the toll chest", "pt": "Tomem o cofre do pedágio"}}] },
  { id: 'fuga', nome: { en: 'Escape', pt: 'Fuga' }, resumo: { en: 'The place is coming down: reach the way out before it buries you.', pt: 'O lugar está desabando: alcancem a saída antes que ele os enterre.' },
    truques: ['desabamento'], faccao: 'mortos', final: 'exit', alvo: { en: 'the way out', pt: 'a saída' },
    titulo: { en: ['Out of {lugar}', 'The Falling Halls', 'Before the Dust Settles'], pt: ['Fora de {lugar}', 'Os Salões que Caem', 'Antes que a Poeira Assente'] },
    intro: { en: ["One look is enough: {vilao} woke something in the deepest galleries, and {lugar} is coming down with it. The only way out is at the far end."], pt: ["Basta um olhar: {vilao} acordou algo nas galerias mais fundas, e {lugar} vai desabar junto. A única saída fica no extremo."] },
    climax: { en: ['Daylight ahead. And {vilao}, blocking it.'], pt: ['Luz do dia adiante. E {vilao}, bloqueando o caminho.'] },
    fim: { en: ["You tumble out into the light, and behind you {lugar} swallows itself in a cloud of dust. For a long while, nobody says a word. Then someone starts to laugh."], pt: ["Vocês saem rolando para a luz, e atrás de vocês {lugar} engole a si mesmo numa nuvem de pó. Por um bom tempo, ninguém diz nada. Depois, alguém começa a rir."] } },
  { id: 'defesa', nome: { en: 'Hold the line', pt: 'Segurar a linha' }, resumo: { en: 'Reach the stand and hold it against the waves.', pt: 'Alcancem o ponto de defesa e segurem-no contra as ondas.' },
    truques: [null], faccao: 'legiao', final: 'counter', alvo: { en: 'the stand', pt: 'o ponto de defesa' },
    titulo: { en: ['The Stand at {lugar}', 'Until the Horn Sounds', 'Hold {lugar}'], pt: ['A Resistência em {lugar}', 'Até a Trombeta Soar', 'Segurem {lugar}'] },
    intro: { en: ["The signs are clear: {vilao} is coming with the horde, and has already burned two villages on the way. The only point worth holding is at the heart of {lugar}, where the passage narrows."], pt: ["Os sinais são claros: {vilao} vem com a horda, e já queimou duas aldeias no caminho. O único ponto que dá para segurar fica no coração de {lugar}, onde a passagem se estreita."] },
    climax: { en: ['This is the place. Here, they will not pass.'], pt: ['Este é o lugar. Daqui, eles não passam.'] },
    fim: { en: ["The last wave breaks, and the horde falls back, trampling its own dead. Only then do you notice your hands still shaking on your weapons."], pt: ["A última onda se quebra, e a horda recua pisando nos próprios mortos. Só então vocês percebem que as mãos ainda tremem nas armas."] } },
  { id: 'selos', nome: { en: 'Seal the rifts', pt: 'Selar as fendas' }, resumo: { en: 'Rifts bleed into the world: close every one of them.', pt: 'Fendas sangram para dentro do mundo: fechem todas.' },
    truques: ['selos'], faccao: 'culto', final: 'counter', alvo: { en: 'the rifts', pt: 'as fendas' },
    titulo: { en: ['The Wounds of {lugar}', 'Close the Veil', 'Where the World Is Thin'], pt: ['As Feridas de {lugar}', 'Fechem o Véu', 'Onde o Mundo É Fino'] },
    intro: { en: ["Someone opened this on purpose: {vilao}, who broke the first ward. Things crawl through the rifts, and the ones left can still be closed, one by one."], pt: ["Alguém abriu isso de propósito: {vilao}, que rompeu a primeira proteção. Coisas rastejam pelas fendas, e as que restam ainda podem ser fechadas, uma a uma."] },
    climax: { en: ["The last rift throbs like a heart, and {vilao} has one hand thrust into it up to the wrist."], pt: ["A última fenda pulsa como um coração, e {vilao} tem uma das mãos enfiada nela até o pulso."] },
    fim: { en: ["The last rift closes with a sound like a sigh, and the light falls straight again. For the first time, you notice the crickets singing."], pt: ["A última fenda se fecha com um som de suspiro, e a luz volta a cair reta. Pela primeira vez, vocês notam o canto dos grilos."] } },
  { id: 'escolta', nome: { en: 'Escort', pt: 'Escolta' }, resumo: { en: 'Someone who knows the way must cross the place alive.', pt: 'Alguém que conhece o caminho precisa atravessar o lugar com vida.' },
    truques: ['escolta'], faccao: 'bandidos', final: 'exit', alvo: { en: 'the guide', pt: 'o guia' },
    titulo: { en: ['Safe Passage', 'Through {lugar}', 'The Last Guide'], pt: ['Passagem Segura', 'Através de {lugar}', 'O Último Guia'] },
    intro: { en: ["The other guides are dead. {vilao} got them all, one a week, and now only I am left. Take me to the other side, and I will open the way for you and for whoever comes after. Stay close. I tire quickly."], pt: ["Os outros guias estão mortos. {vilao} pegou todos, um por semana, e agora só falto eu. Me levem ao outro lado, e eu abro o caminho para vocês e para quem vier depois. Fiquem perto. Eu canso rápido."] },
    climax: { en: ["The way out is right there, and {vilao} is smiling in front of it."], pt: ["A saída está logo ali, e {vilao} sorri na frente dela."] },
    fim: { en: ["On the other side, the guide says three words, and the way closes behind you like water. {vilao} is left on the wrong side, pounding on the stone."], pt: ["Do outro lado, o guia diz três palavras, e o caminho se fecha atrás de vocês como água. {vilao} fica do lado errado, batendo na pedra."] },
    linhas: [{"id": "testemunha", "escolta": "testemunha-tobin", "titulo": {"en": ["The Witness", "To the Court Alive", "What Tobin Saw"], "pt": ["A Testemunha", "Vivo até o Tribunal", "O Que Tobin Viu"]}, "chegada": {"en": ["A carter saw the baron kill the tax collector, and only a living witness before the court can bring a baron to trial. The court sits on the other side of {lugar}. The baron has a lot of gold and little patience, and the road behind you is already watched."], "pt": ["Um carroceiro viu o barão matar o cobrador de impostos, e só uma testemunha viva diante do tribunal leva um barão a julgamento. O tribunal fica do outro lado de {lugar}. O barão tem muito ouro e pouca paciência, e a estrada atrás de vocês já está vigiada."]}, "intro": {"en": ["I saw it. The baron wiped his knife on the dead man's coat and had the body thrown in the river. Now he has paid {vilao} to find me before the trial. I have children. Get me there in one piece."], "pt": ["Eu vi. O barão limpou a faca no casaco do morto e mandou jogar o corpo no rio. Agora pagou {vilao} para me achar antes do julgamento. Eu tenho filhos. Me levem inteiro até lá."]}, "climax": {"en": ["The court's doors are right there. So is {vilao}."], "pt": ["As portas do tribunal estão logo ali. {vilao} também."]}, "fim": {"en": ["The witness takes the stand with trembling hands and tells it all, from beginning to end. When it is over, the hall is silent, and the baron is pale."], "pt": ["A testemunha sobe ao banco com as mãos tremendo e conta tudo, do começo ao fim. Quando termina, o salão está em silêncio, e o barão, pálido."]}, "alvo": {"en": "the witness", "pt": "a testemunha"}}] },
  { id: 'maquina', nome: { en: 'War machine', pt: 'Máquina de guerra' }, resumo: { en: 'The Legion is raising a siege engine deep inside: reach it and tear it down.', pt: 'A Legião monta uma arma de cerco no fundo do lugar: cheguem lá e destruam-na.' },
    truques: [null], faccao: 'legiao', final: 'destroy', alvo: { en: 'the engine', pt: 'a máquina' },
    titulo: { en: ['The Engine of {vilao}', 'Iron in {lugar}', 'Before the Walls Fall'], pt: ['A Máquina de {vilao}', 'Ferro em {lugar}', 'Antes que as Muralhas Caiam'] },
    intro: { en: ["The timber and iron had a purpose: {vilao} is building a siege engine the size of a tower here, and has already brought down walls bigger than the city's. From the noise, it is nearly done."], pt: ["A madeira e o ferro tinham destino: {vilao} está montando aqui uma máquina de cerco do tamanho de uma torre, e já derrubou muralhas maiores que as da cidade. Pelo barulho, falta pouco."] },
    climax: { en: ['There it stands, taller than the walls it was made to break. {vilao} guards it.'], pt: ['Lá está ela, mais alta que as muralhas que foi feita para derrubar. {vilao} a guarda.'] },
    fim: { en: ["The engine groans, leans and collapses with a crash that raises dust everywhere. When it settles, what remains is a very expensive pile of firewood."], pt: ["A máquina geme, se inclina e desaba com um estrondo que levanta pó por todo lado. Quando a poeira assenta, sobra uma pilha de lenha muito cara."] } },
  { id: 'carga', nome: { en: 'Stolen cargo', pt: 'Carga roubada' }, resumo: { en: 'A caravan was raided: recover its cargo, crate by crate.', pt: 'Uma caravana foi saqueada: recuperem a carga, caixote por caixote.' },
    truques: [null], faccao: 'bandidos', final: 'counter', alvo: { en: 'the cargo', pt: 'a carga' },
    titulo: { en: ['The Raided Caravan', 'Crates of {lugar}', 'What {vilao} Took'], pt: ['A Caravana Saqueada', 'Os Caixotes de {lugar}', 'O Que {vilao} Levou'] },
    intro: { en: ["The cargo's trail ends here: {vilao} gathered the raiders of the road, struck the caravan and dragged the crates inside. Some have been opened already. The rest can still be saved."], pt: ["O caminho da carga termina aqui: {vilao} juntou os saqueadores da estrada, atacou a caravana e arrastou os caixotes para dentro. Alguns já foram abertos. Os outros ainda podem ser salvos."] },
    climax: { en: ["{vilao} sits on the last crates, eating a loaf that belonged to the village."], pt: ["{vilao} está sentado nos últimos caixotes, comendo um pão que era da aldeia."] },
    fim: { en: ["The crates go back on the wagons, nearly all of them whole. One bottle of medicine is half empty, and one of the raiders, lying nearby, looks very healthy."], pt: ["Os caixotes voltam às carroças, quase todos inteiros. Um frasco de remédio está pela metade, e um dos saqueadores, caído ali perto, parece muito saudável."] },
    linhas: [{"id": "sal", "t": ["ermo", "aldeia"], "titulo": {"en": ["The Salt of {lugar}", "Across the Bridge", "What {vilao} Holds Back"], "pt": ["O Sal de {lugar}", "Do Outro Lado da Ponte", "O Que {vilao} Retém"]}, "chegada": {"en": ["Without salt, the meat rots before the snow. The village's salt wagons were stranded on the far side of the bridge near {lugar}, and the salt is already paid for. Lúcia the carter makes a point of showing you the receipt, her finger on the amount."], "pt": ["Sem sal, a carne apodrece antes da neve. As carroças de sal da aldeia ficaram presas do outro lado da ponte perto de {lugar}, e o sal já foi pago. A carroceira Lúcia faz questão de mostrar o recibo a vocês, com o dedo em cima do valor."]}, "intro": {"en": ["The sum is simple and dirty: {vilao} took the bridge, stored the village's salt here and means to sell it back at three times the price."], "pt": ["A conta é simples e suja: {vilao} tomou a ponte, guardou aqui o sal da aldeia e quer vendê-lo de volta pelo triplo do preço."]}, "climax": {"en": ["{vilao} sits on the last crates, counting the profit."], "pt": ["{vilao} está sentado nos últimos caixotes, fazendo as contas do lucro."]}, "fim": {"en": ["The sacks of salt go out stacked on the wagons, which creak under the weight. The price list stays behind, nailed to the wall, for whoever comes next to laugh at."], "pt": ["Os sacos de sal saem empilhados nas carroças, que rangem com o peso. A tabela de preços fica para trás, pregada na parede, para quem vier depois achar graça."]}}] },
  { id: 'tenente', nome: { en: 'The lieutenant', pt: 'O tenente' }, resumo: { en: 'An enemy officer carries the orders: take them before the escape.', pt: 'Um oficial inimigo carrega as ordens: tomem-nas antes da fuga.' },
    truques: [null], faccao: 'legiao', final: 'boss', alvo: { en: 'the orders', pt: 'as ordens' },
    titulo: { en: ['The Legion’s Orders', 'Stop {vilao}', 'Sealed Orders'], pt: ['As Ordens da Legião', 'Detenham {vilao}', 'Ordens Lacradas'] },
    intro: { en: ["The orders are here, in the hands of {vilao}, who brought them from the Legion's command and leaves at nightfall. On learning you have arrived, {vilao} will run with them."], pt: ["As ordens estão aqui, nas mãos de {vilao}, que as trouxe do comando da Legião e parte ao anoitecer. Ao saber que vocês chegaram, vai fugir com elas."] },
    climax: { en: ['{vilao} sees you and shouts for the guard. There is little time.'], pt: ['{vilao} vê vocês e grita pela guarda. Há pouco tempo.'] },
    fim: { en: ["The seal breaks in your hands. There it is, map and all: the place where the blow was to fall, and the hour."], pt: ["O lacre se parte nas mãos de vocês. Ali está, com mapa e tudo, o lugar onde o golpe ia cair, e a hora."] } },
  { id: 'pocos', nome: { en: 'Poisoned wells', pt: 'Poços envenenados' }, resumo: { en: 'A plague of the dead fouls the water: purify the springs.', pt: 'Uma praga dos mortos contamina a água: purifiquem as fontes.' },
    truques: [null], faccao: 'mortos', final: 'counter', alvo: { en: 'the springs', pt: 'as fontes' },
    titulo: { en: ['Black Water', 'The Springs of {lugar}', 'What Poisons {lugar}'], pt: ['Água Negra', 'As Fontes de {lugar}', 'O Que Envenena {lugar}'] },
    intro: { en: ["The water tells the story: the springs were poisoned on purpose, and the one who did it was {vilao}, back from the grave at the last moon. Every spring cleansed is a village saved."], pt: ["A água conta a história: as nascentes foram envenenadas de propósito, e quem fez isso foi {vilao}, que voltou do túmulo na última lua. Cada fonte limpa é uma aldeia salva."] },
    climax: { en: ['The source itself bubbles black here. {vilao} tends it.'], pt: ['A própria nascente borbulha negra aqui. {vilao} cuida dela.'] },
    fim: { en: ["The water clears little by little, and a living fish slips between your boots. The air still smells of rot, but it smells of something else too."], pt: ["A água clareia aos poucos, e um peixe vivo passa entre as botas de vocês. O ar ainda cheira a podre, mas já cheira a outra coisa também."] },
    linhas: [{"id": "peste", "t": ["aldeia", "ermo"], "focos": true, "titulo": {"en": ["The Plague of {lugar}", "Burn the Sickness", "What Rises from the Graves"], "pt": ["A Peste de {lugar}", "Queimem a Doença", "O Que Sobe das Covas"]}, "chegada": {"en": ["In {lugar}, more houses shutter their windows every day. The plague rises from the open graves of the cemetery, and the fair begins in a week. If it opens with the plague, the sickness will leave on the merchants' wagons, for the whole region."], "pt": ["Em {lugar}, a cada dia mais casas fecham as janelas. A peste sai das covas abertas do cemitério, e a feira começa em uma semana. Se abrir com a peste, a doença vai embora nas carroças dos mercadores, para a região inteira."]}, "intro": {"en": ["The plague has an owner: {vilao} came back from the grave and spreads the plague from here. The sources must burn before the fair."], "pt": ["A peste tem dono: {vilao} voltou do túmulo e espalha a peste a partir daqui. Os focos precisam queimar antes da feira."]}, "climax": {"en": ["The largest pit steams here, among the graves. {vilao} tends it."], "pt": ["O maior foco fumega aqui, no meio das covas. {vilao} cuida dele."]}, "fim": {"en": ["The last source goes out with a hiss, and the yellow smoke comes apart in the wind. The smell left behind is only wet earth."], "pt": ["O último foco se apaga com um chiado, e a fumaça amarela se desfaz no vento. O cheiro que fica é só de terra molhada."]}, "alvo": {"en": "the plague pits", "pt": "os focos da peste"}}] },
  { id: 'rei', nome: { en: 'The sleeping king', pt: 'O rei que dorme' }, resumo: { en: 'A necromancer is waking an ancient king: stop the rite before he rises for good.', pt: 'Um necromante está despertando um rei antigo: parem o rito antes que ele se levante de vez.' },
    truques: [null, 'selos'], faccao: 'mortos', final: 'boss', alvo: { en: 'the king', pt: 'o rei' },
    titulo: { en: ['The King Beneath {lugar}', 'Let Him Sleep', 'The Waking Crown'], pt: ['O Rei Sob {lugar}', 'Deixem-no Dormir', 'A Coroa que Desperta'] },
    intro: { en: ["The frost points the way: {vilao} stole the keys to the mausoleum and is calling back a king who ruled these lands in blood. The deeper you go, the closer he is to waking."], pt: ["A geada aponta o caminho: {vilao} roubou as chaves do mausoléu e chama de volta um rei que governou estas terras com sangue. Quanto mais fundo, mais perto ele está de acordar."] },
    climax: { en: ['The sarcophagus is open. The king sits up, and {vilao} laughs.'], pt: ['O sarcófago está aberto. O rei se senta, e {vilao} ri.'] },
    fim: { en: ["The king lies back down, this time for good. When you come out, the frost is already melting on the grass, and the sun warms your backs."], pt: ["O rei volta a se deitar, desta vez para sempre. Quando vocês saem, a geada já derrete na grama, e o sol esquenta as costas."] } },
  { id: 'refugio', nome: { en: 'Refuge', pt: 'Refúgio' }, resumo: { en: 'Survivors hide in the ruins: carry them to the sanctuary.', pt: 'Sobreviventes se escondem nas ruínas: carreguem-nos até o santuário.' },
    truques: [null, 'ninhos'], faccao: 'feras', final: 'counter', alvo: { en: 'the survivors', pt: 'os sobreviventes' },
    titulo: { en: ['The Last Refuge', 'Sanctuary', 'Out of the Ruins'], pt: ['O Último Refúgio', 'Santuário', 'Fora das Ruínas'] },
    intro: { en: ["Last night can be read on the walls: {vilao} loosed the beasts on {lugar} all at once. There are still survivors hiding, too hurt to walk, and the old sanctuary at the far end still stands."], pt: ["A noite passada se lê nas paredes: {vilao} soltou as feras sobre {lugar} de uma vez. Ainda há sobreviventes escondidos, feridos demais para andar, e o velho santuário no extremo continua de pé."] },
    climax: { en: ["The doors of the sanctuary are right there, and {vilao} sits on the steps, waiting."], pt: ["As portas do santuário estão logo ali, e {vilao} está sentado nos degraus, esperando."] },
    fim: { en: ["Inside the sanctuary, the survivors sleep for the first time in days. A child sleeps clinging to one of your boots, and nobody has the heart to pull it free."], pt: ["Dentro do santuário, os sobreviventes dormem pela primeira vez em dias. Uma criança dorme agarrada à bota de um de vocês, e ninguém tem coragem de tirar."] } },
  {"id": "ovo", "nome": {"en": "The dragon egg", "pt": "O ovo do dragão"}, "resumo": {"en": "Hunters stole a dragon's egg: take it back before the mother lays the valley waste.", "pt": "Caçadores roubaram o ovo de uma dragoa: tomem-no de volta antes que a mãe arrase o vale."}, "truques": [null], "faccao": "feras", "final": "relic", "alvo": {"en": "the egg", "pt": "o ovo"}, "missao": {"en": "Take back the egg", "pt": "Recuperem o ovo"}, "temas": ["caverna", "ermo", "masmorra"], "pressao": "limite", "relogio": "mae-dragoa", "viloes": ["domador-orrin", "cacadora-vessa"], "titulo": {"en": ["The Dragon Egg", "What {vilao} Stole", "Before the Mother Comes"], "pt": ["O Ovo do Dragão", "O Que {vilao} Roubou", "Antes que a Mãe Chegue"]}, "intro": {"en": ["Whoever took the egg left a trail: {vilao} took it from the nest and hid it here, to sell it as the hide of the last dragon was sold. The mother will burn first and ask later."], "pt": ["Quem levou o ovo deixou rastro: {vilao} o tirou do ninho e o escondeu aqui, para vender como já vendeu o couro do último dragão. A mãe vai queimar primeiro e perguntar depois."]}, "climax": {"en": ["There it is, warm in a nest of furs. {vilao} stands over it, spear in hand."], "pt": ["Lá está ele, quente num ninho de peles. {vilao} está de pé ao lado dele, de lança na mão."]}, "fim": {"en": ["The egg goes back to the nest, still warm. High above, the mother makes one slow turn over the valley, stares at you for a moment and leaves. You prefer to believe it was a thank-you."], "pt": ["O ovo volta ao ninho, ainda quente. Lá no alto, a mãe dá uma volta lenta sobre o vale, encara vocês por um instante e vai embora. Vocês preferem acreditar que foi um agradecimento."]}},
  {"id": "matilha", "nome": {"en": "The tamed pack", "pt": "A matilha domesticada"}, "resumo": {"en": "A beast-tamer keeps starved beasts in cages to loose them on the fair: open the cages before the festival.", "pt": "Um domador mantém feras famintas em jaulas para soltá-las na feira: abram as jaulas antes do festival."}, "truques": [null], "faccao": "feras", "final": "counter", "alvo": {"en": "the cages", "pt": "as jaulas"}, "temas": ["ermo", "caverna", "masmorra"], "pressao": "limite", "relogio": "festival-da-feira", "viloes": ["domador-orrin", "cacadora-vessa"], "menosMonstros": true, "jaulas": {"contador": {"en": "Cages", "pt": "Jaulas"}, "um": {"en": "Open the cage and stop the beast", "pt": "Abram a jaula e detenham a fera"}, "varios": {"en": "Open the {0} cages and stop the beasts", "pt": "Abram as {0} jaulas e detenham as feras"}, "olhar": {"en": "A cage of iron bars, and something inside throwing itself against them.", "pt": "Uma jaula de barras de ferro, e algo lá dentro se jogando contra elas."}, "revela": {"en": "A cage stands here; something inside it growls.", "pt": "Uma jaula está aqui; algo dentro dela rosna."}, "abre": {"en": "You break the lock. The beast bursts out, mad with hunger: defeat it before it reaches the road!", "pt": "Vocês arrebentam o cadeado. A fera salta para fora, louca de fome: derrotem-na antes que chegue à estrada!"}, "conta": {"en": "Beasts dealt with: [n] of [total].", "pt": "Feras contidas: [n] de [total]."}, "cai": {"en": "The beast falls, and {0} has one weapon less.", "pt": "A fera cai, e {0} tem uma arma a menos."}}, "titulo": {"en": ["The Tamed Pack", "The Cages of {vilao}", "Before the Fair"], "pt": ["A Matilha Domesticada", "As Jaulas de {vilao}", "Antes da Feira"]}, "intro": {"en": ["The plan is plain to see: {vilao}, whom the city banished for loosing a bear on a merchant, wants to repeat the feat in the square, on the day of the fair, this time with many more beasts."], "pt": ["O plano está à vista: {vilao}, que a cidade expulsou por soltar um urso em cima de um mercador, quer repetir a façanha na praça, no dia da feira, desta vez com muito mais feras."]}, "climax": {"en": ["The last cage, and the biggest. {vilao} keeps the key on a chain around the neck."], "pt": ["A última jaula, e a maior. {vilao} carrega a chave numa corrente no pescoço."]}, "fim": {"en": ["The cages are empty, and the smell of beast will take a long time to leave. The fair, at least, will open in peace."], "pt": ["As jaulas estão vazias, e o cheiro de fera vai demorar a sair dali. A feira, pelo menos, vai abrir em paz."]}},
  {"id": "santo", "nome": {"en": "The desecrated saint", "pt": "O santo profanado"}, "resumo": {"en": "The body of a saint was stolen from the chapel: bring it back, so the dead can rest.", "pt": "O corpo de um santo foi roubado da capela: tragam-no de volta, para que os mortos descansem."}, "truques": [null], "faccao": "mortos", "final": "relic", "alvo": {"en": "the body of the saint", "pt": "o corpo do santo"}, "missao": {"en": "Recover the body of the saint", "pt": "Recuperem o corpo do santo"}, "temas": ["cripta", "masmorra", "aldeia"], "titulo": {"en": ["The Desecrated Saint", "What {vilao} Took from the Chapel", "Let the Dead Rest"], "pt": ["O Santo Profanado", "O Que {vilao} Tirou da Capela", "Que os Mortos Descansem"]}, "intro": {"en": ["The theft was done calmly and with tools: {vilao} spent the winter buying bones from grave robbers, and now has the saint's body. Away from his tomb, the dead walk."], "pt": ["O roubo foi feito com calma e com ferramenta: {vilao} passou o inverno comprando ossos de saqueadores de túmulos, e agora tem o corpo do santo. Longe do túmulo dele, os mortos andam."]}, "climax": {"en": ["The saint lies on a stone slab, ringed by black candles. {vilao} stands over him."], "pt": ["O santo jaz numa laje de pedra, cercado de velas negras. {vilao} está de pé ao lado dele."]}, "fim": {"en": ["The saint weighs little, almost nothing, and you carry him more carefully than you would carry a wounded man."], "pt": ["O santo pesa pouco, quase nada, e vocês o carregam com mais cuidado do que carregariam um ferido."]}},
  {"id": "coroa", "nome": {"en": "The false crown", "pt": "A coroa falsa"}, "resumo": {"en": "A Legion officer poses as the baron's heir: unmask him before the fief surrenders.", "pt": "Um oficial da Legião se faz passar pelo herdeiro do barão: desmascarem-no antes que o feudo se renda."}, "truques": [null], "faccao": "legiao", "final": "boss", "alvo": {"en": "the truth", "pt": "a verdade"}, "temas": ["fortaleza", "aldeia"], "viloes": ["tenente-quarta-coorte", "prefeito-de-ferro", "porta-estandarte-kael", "marechal-marcha-cinzenta", "capitao-sapador-hesk"], "titulo": {"en": ["The False Crown", "The Heir Who Was Not", "Unmask {vilao}"], "pt": ["A Coroa Falsa", "O Herdeiro que Não Era", "Desmascarem {vilao}"]}, "intro": {"en": ["The fraud shows itself whole: the heir who came back is {vilao}, who served the Legion and tore the family's secrets out of a prisoner. The proof of the lie is somewhere in here."], "pt": ["A farsa aparece inteira: o herdeiro que voltou é {vilao}, que serviu à Legião e arrancou os segredos da família de um prisioneiro. A prova da mentira está em algum lugar daqui."]}, "climax": {"en": ["The great hall, and the false heir in the baron's chair. {vilao} smiles: the Legion is already at the gates."], "pt": ["O grande salão, e o falso herdeiro na cadeira do barão. {vilao} sorri: a Legião já está nos portões."]}, "fim": {"en": ["The mask falls before the whole hall. For a moment, no one speaks. Then someone at the back asks, very quietly, where the real heir is."], "pt": ["A máscara cai diante de todo o salão. Por um momento, ninguém fala. Depois, alguém lá do fundo pergunta, baixinho, onde está o herdeiro de verdade."]}},
  {"id": "sino", "nome": {"en": "The cracked bell", "pt": "O sino rachado"}, "resumo": {"en": "The cult recast the abbey bell, and each toll calls the dead: break it to silence the call.", "pt": "O culto refundiu o sino da abadia, e cada badalada chama os mortos: quebrem-no para calar o chamado."}, "truques": [null], "faccao": "culto", "final": "destroy", "alvo": {"en": "the bell", "pt": "o sino"}, "temas": ["fortaleza", "cripta", "masmorra", "aldeia"], "destruir": {"objeto": "Bell", "contador": {"en": "Bell", "pt": "Sino"}, "missao": {"en": "Break the bell", "pt": "Quebrem o sino"}, "teste": {"en": "Thick bronze, with runes cut into it: it will take more than one blow.", "pt": "Bronze grosso, com runas cortadas nele: vai precisar de mais de um golpe."}, "ok": {"en": "The bronze cracks with a note that hurts the teeth.", "pt": "O bronze racha com uma nota que dói nos dentes."}, "falha": {"en": "The bell rings under the blow, and the dead hear it.", "pt": "O sino toca com o golpe, e os mortos ouvem."}, "olhar": {"en": "The abbey bell, recast in black bronze, humming on its own.", "pt": "O sino da abadia, refundido em bronze negro, zumbindo sozinho."}, "revela": {"en": "The black bell hangs at the back of the room.", "pt": "O sino negro está pendurado no fundo da sala."}, "evento": {"en": "The bell tolls! Every hero in its room tests Willpower; whoever fails suffers 2 damage.", "pt": "O sino badala! Cada herói na sala dele faz um teste de disposição; quem falhar sofre 2 de dano."}}, "titulo": {"en": ["The Cracked Bell", "The Toll of {vilao}", "Silence the Abbey"], "pt": ["O Sino Rachado", "A Badalada de {vilao}", "Calem a Abadia"]}, "intro": {"en": ["The sound has a source: {vilao} melted the old bell down with the bones of the abbey's founders and rings it from here, every midnight. Breaking the bell ends the call."], "pt": ["O som tem origem: {vilao} fundiu o sino velho com os ossos dos fundadores da abadia e o toca daqui, toda meia-noite. Quebrar o sino acaba com o chamado."]}, "climax": {"en": ["The black bell hangs above you, still trembling from the last toll. {vilao} holds the rope."], "pt": ["O sino negro está pendurado acima de vocês, ainda tremendo da última badalada. {vilao} segura a corda."]}, "fim": {"en": ["The bell splits in two, and its last sound drags across the valley until it fades. For a while, all you hear is your own heartbeat."], "pt": ["O sino se parte em dois, e o último som dele se arrasta pelo vale até sumir. Por um tempo, vocês ouvem só o próprio coração."]}},
  {"id": "colheita", "nome": {"en": "The stolen harvest", "pt": "A colheita roubada"}, "resumo": {"en": "Starving beasts dragged the grain into their den: bring it back, or the village starves this winter.", "pt": "Feras famintas arrastaram os grãos para o covil: tragam-nos de volta, ou a aldeia passa fome no inverno."}, "truques": [null], "faccao": "feras", "final": "counter", "alvo": {"en": "the grain", "pt": "os grãos"}, "temas": ["caverna", "ermo"], "viloes": ["pai-lobo", "rei-das-presas", "cervo-cinzento", "serpente-de-brasa", "matrona-espinheiros"], "caixas": {"contador": {"en": "Sacks", "pt": "Sacos"}, "achar": {"en": "A sack of grain, torn but still half full. You drag it out of the beasts' reach.", "pt": "Um saco de grãos, rasgado mas ainda pela metade. Vocês o arrastam para longe das feras."}, "objetivo3": {"en": "Recover the 3 sacks of grain", "pt": "Recuperem os 3 sacos de grãos"}, "um": {"en": "Recover the sack of grain", "pt": "Recuperem o saco de grãos"}, "varios": {"en": "Recover the {0} sacks of grain", "pt": "Recuperem os {0} sacos de grãos"}, "olhar": {"en": "A sack of grain, gnawed at one corner.", "pt": "Um saco de grãos, roído num canto."}, "revela": {"en": "A sack of the stolen grain lies here.", "pt": "Um saco dos grãos roubados está aqui."}}, "titulo": {"en": ["The Stolen Harvest", "The Den of {vilao}", "Bread for the Winter"], "pt": ["A Colheita Roubada", "O Covil de {vilao}", "Pão para o Inverno"]}, "intro": {"en": ["The trail of grain leads here: {vilao} brought the pack down from the hills when the frost came early, and keeps the village's winter in this place."], "pt": ["A trilha de grãos leva até aqui: {vilao} trouxe a matilha das colinas quando a geada chegou cedo, e guarda neste lugar o inverno da aldeia."]}, "climax": {"en": ["{vilao} guards the last sacks, teeth bared."], "pt": ["{vilao} guarda os últimos sacos, mostrando os dentes."]}, "fim": {"en": ["The sacks come out torn, slobbered on and short, but they come out. There is bread in that. Maybe not the finest bread."], "pt": ["Os sacos saem rasgados, babados e incompletos, mas saem. Dá para fazer pão com isso. Talvez sem caprichar no pão."]}}
];
/* v325: the person of the first room speaks her own words (fala), the clue keeps the narrator (intro); fecho: the payoff of
   whoever called the heroes (call mode only); contexto: one sentence for the surprise mode, where the arrival text is gone */
const TEXTOS_V325 = {"resgate": {"fala": {"en": ["They came through here tied by the neck, one behind the other. I saw it all through that crack. The one pulling the rope was {vilao}, counting heads the way you count coins. They are still alive. For now. Go that way, quickly."], "pt": ["Eles passaram por aqui amarrados pelo pescoço, um atrás do outro. Eu vi tudo daquela fresta. Quem puxava a corda era {vilao}, contando cabeças como quem conta moedas. Ainda estão vivos. Por enquanto. Vão por ali, depressa."]}, "fecho": {"en": ["Back in the village, Marta puts down her hammer for the first time in two days, just to hug her brother."], "pt": ["Na aldeia, Marta solta o martelo pela primeira vez em dois dias, só para abraçar o irmão."]}}, "resgate/mineiros": {"fala": {"en": ["They found silver down there, a vein as thick as an arm. Since then {vilao} keeps everyone digging, day and night, and whoever drops from exhaustion stays where they fell. Listen: the picks are still ringing. While they ring, someone is alive."], "pt": ["Acharam prata lá embaixo, um veio grosso como um braço. Desde então {vilao} mantém todo mundo cavando, dia e noite, e quem cai de cansaço fica onde caiu. Ouçam: as picaretas ainda batem. Enquanto baterem, tem gente viva."]}, "fecho": {"en": ["On the hillside, the lanterns go out one by one: no one has to wait on the road any more."], "pt": ["Na encosta, os lampiões se apagam um a um: ninguém mais precisa esperar na estrada."]}}, "resgate/casamento": {"fala": {"en": ["They went straight for the bride, as if they already knew where she would be sitting. The one who paid was {vilao}, who asked for her hand last year and heard a no. By the look of it, still hoping to hear a yes."], "pt": ["Foram direto até a noiva, como quem já sabia onde ela estaria sentada. Quem pagou foi {vilao}, que pediu a mão dela no ano passado e ouviu um não. Pelo jeito, ainda espera ouvir um sim."]}, "fecho": {"en": ["The musicians strike up again, and the two fathers, swords still at their belts, share the same jug of wine."], "pt": ["Os músicos voltam a tocar, e os dois pais, de espada ainda na cintura, dividem a mesma jarra de vinho."]}, "contexto": {"en": ["There are flower petals on the floor, and a feast shoe dropped in a corner: someone was brought here straight from a wedding."], "pt": ["Há pétalas de flor pelo chão, e um sapato de festa largado num canto: alguém foi trazido para cá direto de um casamento."]}}, "reliquia": {"fala": {"en": ["You came for it too? Then move. {vilao} came through yesterday, with people to dig and a sack full of what was taken from two shrines. Still searching. From the shouting in there, running out of patience."], "pt": ["Vocês também vieram atrás dela? Então andem. {vilao} passou por aqui ontem, com gente para cavar e um saco cheio do que tirou de dois santuários. Ainda está procurando. Pelos gritos que vêm lá de dentro, está perdendo a paciência."]}, "fecho": {"en": ["At the temple, Brother Teodoro takes {alvo} in silence and burns the map: the way to it dies with it."], "pt": ["No templo, o irmão Teodoro recebe {alvo} em silêncio e queima o mapa: o caminho até ela morre com ele."]}, "contexto": {"en": ["There are fresh digging marks everywhere. Whoever dug was looking for {alvo}, said to be hidden here since before the war."], "pt": ["Há marcas de escavação recentes por toda parte. Quem cavou procurava {alvo}, que dizem estar escondida aqui desde antes da guerra."]}}, "ritual": {"fala": {"en": ["They have been chanting for three nights, without stopping even for water. {vilao} leads the cult in there, and with every verse the air gets heavier. Something on the other side is listening. Break what feeds the chant before it answers."], "pt": ["Eles cantam há três noites, sem parar nem para beber água. {vilao} rege o culto lá dentro, e a cada verso o ar fica mais pesado. Tem alguma coisa do outro lado, ouvindo. Quebrem o que alimenta o canto antes que ela responda."]}, "fecho": {"en": ["In the village, the children sleep until morning, and none of them remembers what they dreamed. Father Anselmo prefers to leave it that way."], "pt": ["Na aldeia, as crianças dormem até de manhã, e nenhuma lembra o que sonhou. O padre Anselmo prefere deixar assim."]}}, "ritual/grimorio": {"fala": {"en": ["They copy day and night, with an ink that smells of iron. {vilao} reads aloud, and the copyists write without blinking, as if asleep. Every new page feeds the rite. Burn the copies first."], "pt": ["Eles copiam dia e noite, com uma tinta que cheira a ferro. {vilao} lê em voz alta, e os copistas escrevem sem piscar, como se dormissem. Cada página nova alimenta o rito. Queimem as cópias primeiro."]}, "fecho": {"en": ["The librarian strikes the title from the temple's catalogue, slowly, until the pen goes through the paper."], "pt": ["O bibliotecário risca o título do catálogo do templo, devagar, até a pena furar o papel."]}, "contexto": {"en": ["The smell of ink and parchment reaches the way in. They say a forbidden grimoire, stolen from a temple, is being copied here."], "pt": ["O cheiro de tinta e pergaminho chega até a entrada. Dizem que um grimório proibido, roubado de um templo, está sendo copiado aqui."]}}, "cacada": {"fala": {"en": ["Three farms, three nights, no survivors. The name they give the beast is {vilao}. It came down from the hills at the last moon, and this hole is its den. And listen well: it learns. At the third farm, it came in through the back door."], "pt": ["Três fazendas, três noites, nenhum sobrevivente. O nome que dão à fera é {vilao}. Desceu das colinas na última lua, e este buraco é a toca. E escutem bem: ela aprende. Na terceira fazenda, entrou pela porta dos fundos."]}, "fecho": {"en": ["The farmers will want the hide hung in the square. The hat goes around again, this time to pay for your beer."], "pt": ["Os fazendeiros vão querer o couro pendurado na praça. O chapéu das moedas volta a circular, desta vez para pagar a cerveja de vocês."]}}, "investigacao": {"fala": {"en": ["The garrison shrugs. Someone pays them to shrug. They say it is {vilao}, and that whoever asks too many questions becomes one more portrait on the road. I asked. That is how I ended up here."], "pt": ["A guarnição dá de ombros. Alguém paga para eles darem de ombros. Dizem que é {vilao}, e que quem pergunta demais vira mais um retrato na estrada. Eu perguntei. Por isso vim parar aqui."]}, "fecho": {"en": ["On the road, the old woman takes her grandson's portrait down from the post and holds it to her chest. At the garrison, the dice vanish from the table."], "pt": ["Na estrada, a velha tira o retrato do neto do poste e o guarda junto ao peito. Na guarnição, os dados somem da mesa."]}, "contexto": {"en": ["On the road that leads here, travellers have been vanishing without a trace, and the garrison meant to protect them pretends not to see."], "pt": ["Pela estrada que leva até aqui, viajantes vêm sumindo sem deixar rastro, e a guarnição que devia protegê-los finge não ver."]}}, "investigacao/traidor": {"fala": {"en": ["One of the seven sells the watch rotas for gold. The buyer is {vilao}, who promised to spare the traitor's house when the city falls. Follow the gold, and the name turns up at the end."], "pt": ["Um dos sete vende os turnos da guarda por ouro. Quem compra é {vilao}, que prometeu poupar a casa do traidor quando a cidade cair. Sigam o ouro, e o nome aparece no fim."]}, "fecho": {"en": ["The traitor goes to trial before the other six. Captain Aldo keeps dining with the council, now with one chair fewer."], "pt": ["O traidor vai a julgamento diante dos outros seis. O capitão Aldo continua jantando com o conselho, agora com uma cadeira a menos."]}, "contexto": {"en": ["The attacks on {lugar} always strike where the guard is weakest, and people suspect someone on the council, the seven who decide everything there."], "pt": ["Os ataques a {lugar} sempre acertam onde a guarda está mais fraca, e o povo desconfia de alguém do conselho, os sete que decidem tudo ali."]}}, "investigacao/pedagio": {"fala": {"en": ["The old bridge keeper is buried under it. Now {vilao} collects, and whoever complains about the price becomes cargo. They take everything inside: the wagons, the mules and the people. Not always in that order."], "pt": ["O antigo guarda da ponte está enterrado embaixo dela. Agora quem cobra é {vilao}, e quem reclama do preço vira carga. Levam tudo para dentro: as carroças, as mulas e as pessoas. Nem sempre nessa ordem."]}, "fecho": {"en": ["Bento finds his brother-in-law, who is already arguing about how to split the chest. On the bridge, the drovers cross singing."], "pt": ["Bento reencontra o cunhado, que já começa a discutir a partilha do cofre. Na ponte, os tropeiros passam cantando."]}, "contexto": {"en": ["On the bridge nearby, armed men collect a toll no lord ever allowed, and whoever argues vanishes, wagon and all."], "pt": ["Na ponte aqui perto, homens armados cobram um pedágio que nenhum senhor autorizou, e quem discute some com carroça e tudo."]}}, "fuga": {"fala": {"en": ["Earthquake, my foot. {vilao} woke something in the deep galleries, and it is coming up. This whole place is going to collapse. There is only one way out, at the far end. Run, and I will run behind you!"], "pt": ["Terremoto coisa nenhuma. {vilao} acordou alguma coisa nas galerias fundas, e ela está subindo. Este lugar inteiro vai desabar. Só existe uma saída, lá no extremo. Corram, que eu corro atrás!"]}, "fecho": {"en": ["The reeve counts the coins in the purse slowly, watching the cloud of dust, and adds a few more."], "pt": ["O prefeito conta as moedas da bolsa devagar, olhando a nuvem de pó, e acrescenta mais algumas."]}}, "defesa": {"fala": {"en": ["Two villages burned on the border, and {vilao} is coming for the third. Only the heart of this place can be held: in there, the passage is narrow. Get there before they do. You can already hear the drums from here."], "pt": ["Duas aldeias queimadas na fronteira, e {vilao} vem atrás da terceira. Só o coração deste lugar dá para segurar: lá dentro, a passagem é estreita. Cheguem lá antes deles. Daqui já se ouvem os tambores."]}, "fecho": {"en": ["Far off, the city bells ring. The gates closed in time, and Commander Isolda sends word that the first round is on her."], "pt": ["Lá longe, os sinos da cidade tocam. Os portões fecharam a tempo, e a comandante Isolda manda dizer que a primeira rodada é dela."]}}, "selos": {"fala": {"en": ["First there was one rift, then three. {vilao} broke the first ward and feeds the others. Close them one by one, before they join into one. For a rift that size, no word is enough."], "pt": ["Primeiro foi uma fenda, depois três. {vilao} rompeu a primeira proteção e alimenta as outras. Fechem uma a uma, antes que se juntem numa só. Para uma fenda desse tamanho, palavra nenhuma basta."]}, "fecho": {"en": ["The warden Edda hears the whole tale in silence. At the end, she asks whether anyone touched the rifts, and examines each of your hands."], "pt": ["A guardiã Edda ouve o relato inteiro calada. No fim, pergunta se alguém tocou nas fendas, e examina as mãos de cada um."]}}, "escolta": {"fecho": {"en": ["Tomorrow, the first refugees pass through here. The guide promises to teach the three words to someone younger. “Someone who runs faster,” he says."], "pt": ["Amanhã, os primeiros refugiados passam por aqui. O guia promete ensinar as três palavras a alguém mais novo. «Alguém que corra mais», diz."]}}, "escolta/testemunha": {"fecho": {"en": ["The judge brings down the gavel, and {vilao} goes unpaid."], "pt": ["O juiz bate o martelo, e {vilao} fica sem a paga."]}}, "maquina": {"fala": {"en": ["A whole week hauling beams, and now we know what for. {vilao} is building a siege engine the size of a tower, and has already brought down walls bigger than ours. Listen to the hammers. When they stop, it is ready."], "pt": ["Uma semana inteira carregando vigas, e agora sabemos para quê. {vilao} está montando uma máquina de cerco do tamanho de uma torre, e já derrubou muralhas maiores que as nossas. Ouçam os martelos. Quando eles pararem, ela está pronta."]}, "fecho": {"en": ["On the walls, Commander Varel hears the crash and orders the last barrel of wine opened. Someone celebrates too early, and this time they are right."], "pt": ["Das muralhas, o comandante Varel ouve o estrondo e manda abrir o último barril de vinho. Alguém comemora antes da hora, e desta vez tem razão."]}}, "carga": {"fala": {"en": ["{vilao} gathered the raiders of the road and fell on the caravan at the bend of the river. They dragged the crates inside. They do not even know how to use the medicine: they are opening the bottles to see if it is drink."], "pt": ["{vilao} juntou os saqueadores da estrada e caiu em cima da caravana na curva do rio. Arrastaram os caixotes para dentro. Os remédios eles nem sabem usar: estão abrindo os frascos para ver se é bebida."]}, "fecho": {"en": ["Gaspar checks the cargo item by item and, for the first time in his life, forgets to complain about the price."], "pt": ["Gaspar confere a carga item por item e, pela primeira vez na vida, esquece de reclamar do preço."]}, "contexto": {"en": ["Wheel ruts leave the road and come in here: three wagons of medicine and grain, bound for a village, never reached it."], "pt": ["Marcas de rodas saem da estrada e entram aqui: três carroças de remédio e grão, a caminho de uma aldeia, nunca chegaram ao destino."]}}, "carga/sal": {"fala": {"en": ["They took the bridge at the end of summer and carried the salt inside. Now {vilao} wants to sell the village its own salt, at three times the price. There is even a price list nailed to the wall."], "pt": ["Tomaram a ponte no fim do verão e levaram o sal para dentro. Agora {vilao} quer vender à aldeia o próprio sal, pelo triplo do preço. Já tem até tabela pregada na parede."]}, "fecho": {"en": ["In the village, the meat is already hanging, and the smell of smoking rises before nightfall."], "pt": ["Na aldeia, a carne já espera pendurada, e o cheiro de defumado sobe antes do anoitecer."]}, "contexto": {"en": ["The village nearby has no salt for the winter: its salt wagons vanished on the far side of the bridge."], "pt": ["A aldeia daqui perto está sem sal para o inverno: as carroças de sal sumiram do outro lado da ponte."]}}, "tenente": {"fala": {"en": ["The rider came in last night, with a scroll sealed in red wax. {vilao} keeps the orders close and leaves at nightfall. You have until then. Once you are seen, it will be a race."], "pt": ["O cavaleiro chegou ontem à noite, com um rolo selado em cera vermelha. {vilao} guarda as ordens consigo e parte ao anoitecer. Vocês têm até lá. Depois que forem vistos, vai ser uma corrida."]}, "fecho": {"en": ["In the city, the Legion will find the defence exactly where it was counting on emptiness."], "pt": ["Na cidade, a Legião vai encontrar a defesa exatamente onde contava com o vazio."]}, "contexto": {"en": ["The Legion, the army that besieges the region, is preparing an attack, and its sealed orders pass through here on the way to the troops."], "pt": ["A Legião, o exército que cerca a região, prepara um ataque, e as ordens seladas passam por aqui a caminho das tropas."]}}, "pocos": {"fala": {"en": ["Whoever drinks that water dies, and then gets up. {vilao} came back from the grave at the last moon and poisoned the springs, one by one. Cleanse each of them before the plague goes down the river. And by the gods, drink from your canteens."], "pt": ["Quem bebe dessa água morre, e depois levanta. {vilao} voltou do túmulo na última lua e envenenou as nascentes, uma por uma. Limpem cada uma antes que a praga desça o rio. E pelos deuses, bebam do cantil."]}, "fecho": {"en": ["Inês the healer will still have work to do, but the villages drink from the stream again."], "pt": ["A curandeira Inês ainda vai ter trabalho, mas as aldeias voltam a beber do riacho."]}}, "pocos/peste": {"fala": {"en": ["The graves opened from the inside. A yellow smoke comes out of them, and whoever breathes it coughs until they spit blood. It was {vilao}, back from the grave, who spread it. Cover your mouths and burn the sources."], "pt": ["As covas se abriram por dentro. Sai uma fumaça amarela delas, e quem respira tosse até cuspir sangue. Foi {vilao}, que voltou do túmulo, quem espalhou isso. Cubram a boca e queimem os focos."]}, "fecho": {"en": ["In {lugar}, one window opens, then another, and in the square someone starts setting up the stalls for the fair."], "pt": ["Em {lugar}, uma janela se abre, depois outra, e na praça alguém começa a montar as barracas da feira."]}}, "rei": {"fala": {"en": ["They stole the keys to the mausoleum. {vilao} found the tomb of the king who ruled these lands by rope and blood, and is calling him. The deeper you go, the colder it gets. If someone down there calls your names, keep quiet."], "pt": ["Roubaram as chaves do mausoléu. {vilao} achou a tumba do rei que governou estas terras na forca e no sangue, e está chamando por ele. Quanto mais fundo vocês forem, mais frio. Se alguém lá embaixo chamar seus nomes, fiquem calados."]}, "fecho": {"en": ["The gravekeeper closes the graves with his shovel, whistling. Out of tune, but whistling."], "pt": ["O coveiro fecha os túmulos com a pá, assobiando. Desafinado, mas assobiando."]}}, "refugio": {"fala": {"en": ["The beasts came all at once, in a single night. The one who loosed them was {vilao}, who had been prowling the fields for weeks. There are still people hiding, too hurt to walk. The old sanctuary, at the far end, is holding. Take them all there."], "pt": ["As feras vieram todas de uma vez, numa noite só. Quem soltou foi {vilao}, que rondava os campos havia semanas. Ainda tem gente escondida, ferida demais para andar. O velho santuário, lá no fundo, aguenta. Levem todos para lá."]}, "fecho": {"en": ["Outside, someone ties the bell rope back up, for the next time it is needed."], "pt": ["Lá fora, alguém amarra a corda do sino de novo, para a próxima vez que precisarem."]}}, "ovo": {"fala": {"en": ["They climbed to the nest at dawn and came down with the egg wrapped in furs. {vilao} sold the hide of the last dragon to a duke and means to sell this one too. The mother will burn first and ask later. If she asks at all."], "pt": ["Subiram ao ninho de madrugada e desceram com o ovo embrulhado em peles. {vilao} vendeu o couro do último dragão a um duque e quer vender este também. A mãe vai queimar primeiro e perguntar depois. Se é que pergunta."]}, "fecho": {"en": ["In the village, the smith finally puts down his bucket and lets the roof dry."], "pt": ["No vilarejo, o ferreiro enfim larga o balde e deixa o telhado secar."]}}, "matilha": {"fala": {"en": ["They are keeping the beasts hungry on purpose. {vilao}, whom the city banished for loosing a bear on a merchant, wants to open the cages in the middle of the square, on the day of the fair. Open them here first, and deal with whatever comes out."], "pt": ["Estão deixando as feras com fome de propósito. {vilao}, que a cidade expulsou por soltar um urso em cima de um mercador, quer abrir as jaulas no meio da praça, no dia da feira. Abram aqui primeiro, e deem conta do que sair."]}, "fecho": {"en": ["In the square, the merchant of the bear tells the story again to anyone who will listen, now with you at the end."], "pt": ["Na praça, o mercador do urso conta a história de novo para quem quiser ouvir, agora com vocês no final."]}}, "santo": {"fala": {"en": ["They opened the tomb from the outside, with tools and with care, like someone who knows the trade. {vilao} spent the winter buying bones from grave robbers, and now has taken the saint. Without him, the dead walk. Bring the saint back."], "pt": ["Abriram o túmulo por fora, com ferramenta e com cuidado, como quem sabe o que faz. {vilao} passou o inverno comprando ossos de saqueadores de túmulos, e agora levou o santo. Sem ele, os mortos andam. Tragam o santo de volta."]}, "fecho": {"en": ["Father Gil closes the slab and leans the shovel against the wall. The next morning, for the first time in weeks, the bell rings for mass, and the chapel fills."], "pt": ["O padre Gil fecha a laje e encosta a pá na parede. Na manhã seguinte, pela primeira vez em semanas, o sino toca para a missa, e a capela enche."]}, "contexto": {"en": ["In the cemetery of the nearby village, the tomb of Saint Aldric was broken open, and since then the dead climb out of their graves."], "pt": ["No cemitério da aldeia vizinha, o túmulo de Santo Aldrico foi violado, e desde então os mortos saem das covas."]}}, "coroa": {"fala": {"en": ["The true heir had a birthmark on his neck, and this one only ever wears a high collar. The name is {vilao}, who served the Legion on the border and tore the family's secrets out of a prisoner. The proof is in here. Find it before dawn."], "pt": ["O herdeiro verdadeiro tinha uma marca de nascença no pescoço, e esse aí só anda de gola alta. Chama-se {vilao}, serviu à Legião na fronteira e arrancou os segredos da família de um prisioneiro. A prova está aqui dentro. Achem antes do amanhecer."]}, "fecho": {"en": ["The keys go back to Ambrósio, who puts them in his apron pocket and keeps his hand over them for the rest of the night."], "pt": ["As chaves voltam para Ambrósio, que as guarda no bolso do avental e mantém a mão em cima delas pelo resto da noite."]}, "contexto": {"en": ["A stranger turned up claiming to be the lost heir of the barony, and tomorrow he will hand the keys of the fief to the Legion, the army that besieges the region."], "pt": ["Um estranho apareceu dizendo ser o herdeiro sumido do baronato, e amanhã vai entregar as chaves do feudo à Legião, o exército que cerca a região."]}}, "sino": {"fala": {"en": ["They melted the old bell down with the bones of the abbey's founders. {vilao} rings it in person, every night, at midnight sharp. Break the bell, and the dead go back to sleep. Until then, stop your ears however you can."], "pt": ["Fundiram o sino velho com os ossos dos fundadores da abadia. {vilao} toca a corda pessoalmente, toda noite, à meia-noite em ponto. Quebrem o sino, e os mortos voltam a dormir. Até lá, tapem os ouvidos como puderem."]}, "fecho": {"en": ["At the abbey, Abbess Clara takes the wool out of her ears and asks everyone for silence, just to listen."], "pt": ["Na abadia, a abadessa Clara tira a lã dos ouvidos e pede silêncio a todos, só para ouvir."]}}, "colheita": {"fala": {"en": ["They came down from the hills when the frost came early, a whole pack, and {vilao} leads them. They hoard the grain in there the way a squirrel hoards nuts. Very big squirrels. Bring back every sack you can."], "pt": ["Vieram das colinas quando a geada chegou cedo, uma matilha inteira, e quem guia é {vilao}. Guardam os grãos aí dentro como esquilo guarda nozes. Esquilos bem grandes. Tragam cada saco que der."]}, "fecho": {"en": ["Joaquim wipes the sums off the door frame and puts a new bolt on the barn. Then another, just in case."], "pt": ["Joaquim apaga as contas do batente e põe uma tranca nova no celeiro. Depois, outra, por garantia."]}}};
PREMISSAS_MAPA.forEach(p => { Object.assign(p, TEXTOS_V325[p.id] || {}); (p.linhas || []).forEach(l => Object.assign(l, TEXTOS_V325[p.id + '/' + l.id] || {})); });

/* v326: the stories of the premises, three lines each (doc claude/bigorna-roteiros-v6.md and bigorna-elementos-sorteados.md):
   the notice (a call for help), the opening, the person of room 1 (elo in call mode, fala in both), the clue of room 1 (its own
   object), the last room, the boss scene, the ending and the payoff; in the surprise mode, the omen, the hero at the way in
   and the key point. Portuguese only for now (the English keys are the Portuguese text) */
const ROTEIROS_V6 = {"resgate": {"tit": {"en": ["The Cells of {vilao}", "No One Left Behind", "The Rope of {vilao}"], "pt": ["As Celas de {vilao}", "Ninguém Fica para Trás", "A Corda de {vilao}"]}, "aviso": {"en": ["Help {povoado}. {cativos} were taken last night, and the tracks lead to {lugar}, where no one from here dares to go.", "Please help us bring {cativos} back. They were taken from {povoado} last night, and the tracks end at {lugar}.", "{povoado} needs help. Armed men carried off {cativos} during the night, and since then {gente} {gentefaz}."], "pt": ["Ajudem {povoado}. Levaram {cativos} na noite passada, e os rastros vão até {lugar}, onde ninguém daqui ousa entrar.", "Por favor, ajudem a trazer {cativos} de volta. Foram levad⟨cativos:o|a|os|as⟩ de {povoado} na noite passada, e os rastros terminam em {lugar}.", "{povoado} precisa de ajuda. Homens armados levaram {cativos} durante a noite, e desde então {gente} {gentefaz}."]}, "abert": {"en": ["The heroes follow the tracks to {lugar}. At the entrance, they find a piece of cut rope."], "pt": ["Os heróis seguem os rastros até {lugar}. Na entrada, eles acham um pedaço de corda cortada."]}, "fala": {"en": ["I hid here when they went by. {cativos} walked in single file, all tied to the same rope, and the one leading them was {vilao}. I heard talk of a ransom, so much a head. If they want money, the captives must still be alive, somewhere deep inside."], "pt": ["Eu me escondi aqui quando eles passaram. {cativos} iam em fila, pres⟨cativos:o|a|os|as⟩ pela mesma corda, e quem ia na frente era {vilao}. Ouvi quando disse que vai cobrar resgate por cabeça. Se querem dinheiro, é porque ainda estão viv⟨cativos:o|a|os|as⟩, em algum lugar lá no fundo."]}, "pista": {"nome": {"en": "A torn shawl", "pt": "Um xale rasgado"}, "olhar": {"en": "A torn shawl, caught on a nail, and drag marks in the dirt.", "pt": "Um xale rasgado, preso num prego, e marcas de arrasto na terra."}, "revela": {"en": "Something is caught on a nail near the entrance.", "pt": "Algo está preso num prego perto da entrada."}, "texto": {"en": ["You free the shawl from the nail and realize this is where the line stopped to rest. {cativos} sat on the ground, still tied to the same rope, and someone left the shawl hooked there on purpose, to mark the way. Whoever was leading them must have noticed later, because a threatening note is pinned to the wall with a knife: “Thirty coins a head. Whoever wants them back can come and pay.” It is signed: {vilao}."], "pt": ["Vocês soltam o xale do prego e percebem que foi aqui que a fila parou para descansar. {cativos} se sentaram no chão, ainda pres⟨cativos:o|a|os|as⟩ pela mesma corda, e alguém deixou o xale enganchado de propósito, para marcar o caminho. Parece que quem ⟨cativos:o|a|os|as⟩ levava percebeu depois, pois pregou na parede, com uma faca, um bilhete ameaçador: «Trinta moedas por cabeça. Quem quiser de volta, que venha pagar.» Assinado: {vilao}."]}}, "ultima": {"en": ["{cativos} are backed against the far wall, still tied to the rope. In front of them stands {vilao}, sword in hand."], "pt": ["{cativos} estão encostad⟨cativos:o|a|os|as⟩ na parede do fundo, ainda pres⟨cativos:o|a|os|as⟩ pela corda. Na frente del⟨cativos:e|a|es|as⟩ está {vilao}, de espada na mão."]}, "narr": {"en": ["As you come in, {vilao} pulls on the rope, and the whole line shrinks back against the wall."], "pt": ["Quando vocês entram, {vilao} puxa a corda, e a fila inteira se encolhe contra a parede."]}, "vil": {"en": ["Armed folk. So someone in {povoado} decided to pay another way."], "pt": ["Gente armada. Então alguém de {povoado} decidiu pagar de outro jeito."]}, "hc": {"en": ["{povoado} wants every one of them back. Today."], "pt": ["{povoado} quer tod⟨cativos:o|a|os|as⟩ de volta. Hoje."]}, "hs": {"en": ["Let go of the rope."], "pt": ["Soltem a corda."]}, "fim": {"en": ["{cativos} step out into the daylight rubbing their necks, still marked by the rope. The eldest counts the others twice, to be sure no one was left behind."], "pt": ["{cativos} saem para a luz do dia esfregando o pescoço, ainda marcado pela corda. ⟨cativos:O mais velho|A mais velha|O mais velho|A mais velha⟩ conta ⟨cativos:os companheiros|as companheiras|os companheiros|as companheiras⟩ duas vezes, para ter certeza de que ninguém ficou para trás."]}, "fecho": {"en": ["In {povoado}, the doors stay open late that night, and {gente} go back to work the next day."], "pt": ["Em {povoado}, as portas ficam abertas até tarde naquela noite, e {gente} voltam ao trabalho no dia seguinte."]}, "pa": {"en": ["Fresh ruts, and deep ones. Someone was dragged through here."], "pt": ["Sulcos frescos, e fundos. Alguém foi arrastado por aqui."]}, "pb": {"en": ["More than one. And none of them willingly."], "pt": ["Mais de um. E todos à força."]}, "entr": {"en": ["The ruts lead into {lugar}. Listen: someone is crying softly in there."], "pt": ["Os sulcos entram em {lugar}. Escutem: tem alguém chorando baixinho lá dentro."]}, "chave": {"en": ["A scream comes from deep inside. A moment later, {vilao} makes a threat: “One more peep and the price drops by half.”"], "pt": ["Ouve-se um grito lá do fundo. Logo depois, {vilao} ameaça: «Mais um pio e o preço cai pela metade.»"]}, "chc": {"en": ["A scream comes from deep inside. A moment later, {vilao} makes a threat: “One more peep and the price drops by half.” They are the people taken from {povoado}, and they are still alive."], "pt": ["Ouve-se um grito lá do fundo. Logo depois, {vilao} ameaça: «Mais um pio e o preço cai pela metade.» É a gente levada de {povoado}, e ela ainda está viva."]}, "chs": {"en": ["A scream comes from deep inside. A moment later, {vilao} makes a threat: “One more peep and the price drops by half.” The ruts on the road were left by people dragged here, and those people are still alive."], "pt": ["Ouve-se um grito lá do fundo. Logo depois, {vilao} ameaça: «Mais um pio e o preço cai pela metade.» Os sulcos da estrada eram de gente arrastada até aqui, e essa gente ainda está viva."]}, "elos": [{"t": "n", "txt": {"en": ["Nailed to a post just ahead is a hastily written note: “To whoever comes from {povoado}: they also took those who tried to stop them. Please bring everyone back.”"], "pt": ["Pregado num poste, logo adiante, há um bilhete escrito às pressas: «Quem vier de {povoado}: levaram também quem tentou impedir. Por favor, tragam todos.»"]}}, {"t": "n", "txt": {"en": ["On the stone at the entrance, someone has drawn in charcoal an arrow pointing inside and a single word: “Help.”"], "pt": ["Na pedra da entrada, alguém riscou com carvão uma seta para dentro e uma palavra só: «Socorro.»"]}}, {"t": "h", "txt": {"en": ["These are the tracks the notice spoke of. And look: there is blood on them. Someone fought back."], "pt": ["Esses são os rastros de que o aviso falava. E reparem: tem sangue neles. Alguém resistiu."]}}]}, "resgate/mineiros": {"tit": {"en": ["The Mine of {vilao}", "Below the Shaft", "The Lost Shift"], "pt": ["A Mina de {vilao}", "Abaixo do Poço", "O Turno Perdido"]}, "aviso": {"en": ["Help {povoado}. Bandits have taken {lugar} and put the miners to digging by force. For three nights the families have waited on the road, lanterns lit.", "Please bring our men back. Bandits have taken {lugar}, and {desde} the miners of {povoado} have been held down there, digging for them.", "{povoado} needs help. The miners went down into {lugar} for the night shift and were caught by bandits, who now force them to dig."], "pt": ["Ajudem {povoado}. Bandidos tomaram {lugar} e puseram os mineiros para cavar à força. Há três noites as famílias esperam na estrada, de lampião aceso.", "Por favor, tragam os nossos homens de volta. Bandidos tomaram {lugar}, e {desde} os mineiros de {povoado} estão presos lá embaixo, cavando para eles.", "{povoado} precisa de ajuda. Os mineiros desceram a {lugar} para o turno da noite e foram pegos por bandidos, que agora os fazem cavar à força."]}, "abert": {"en": ["The heroes follow the road to the mouth of {lugar}. From below comes the sound of pickaxes."], "pt": ["Os heróis seguem a estrada até a boca de {lugar}. Lá de baixo vem o som de picaretas."]}, "fala": {"en": ["The bandits found silver down there, a vein as thick as an arm. Ever since, {vilao} has had everyone digging day and night, and whoever drops from exhaustion stays where he fell. As long as the pickaxes are striking, there are people alive. Follow the noise."], "pt": ["Os bandidos acharam prata lá embaixo, um veio grosso como um braço. Desde então {vilao} manda todo mundo cavar dia e noite, e quem cai de cansaço fica onde caiu. Enquanto as picaretas baterem é porque tem gente viva. Sigam o barulho."]}, "pista": {"nome": {"en": "A fallen lantern", "pt": "Um lampião caído"}, "olhar": {"en": "A miner's lantern, fallen and dark, its handle bent.", "pt": "Um lampião de mineiro, caído e apagado, com a alça torta."}, "revela": {"en": "A lantern lies near the entrance.", "pt": "Há um lampião caído perto da entrada."}, "texto": {"en": ["The lantern still has oil in it, and you can tell it fell during a struggle: there are boot prints and drag marks all around. On the wall, the miners have scratched a message with the point of a pickaxe for whoever might come: “{vilao} rules here. There are still eleven of us.”"], "pt": ["O lampião ainda tem óleo, e vocês percebem que caiu durante uma briga, porque há marcas de botas e de arrasto em volta. Na parede, os mineiros riscaram com a ponta da picareta um aviso para quem viesse: «{vilao} manda aqui. Ainda somos onze.»"]}}, "ultima": {"en": ["Amid the piled-up silver, {vilao} is counting what the miners have torn from the rock. {cativos} dig at the back, chained to the wall."], "pt": ["No meio da prata empilhada, {vilao} conta o que os mineiros tiraram da rocha. {cativos} cavam no fundo, acorrentad⟨cativos:o|a|os|as⟩ à parede."]}, "narr": {"en": ["The pickaxes all stop at once as you come in."], "pt": ["As picaretas param todas de uma vez quando vocês entram."]}, "vil": {"en": ["Who told you to stop? Back to digging. And you, drop your weapons and pick up a pickaxe."], "pt": ["Quem mandou parar? Voltem a cavar. E vocês, larguem as armas e peguem uma picareta."]}, "hc": {"en": ["The families of {povoado} want their miners back. Today."], "pt": ["As famílias de {povoado} querem os mineiros de volta. Hoje."]}, "hs": {"en": ["[advancing, eyes fixed on {vilao}] The shift is over."], "pt": ["[avançando, sem tirar os olhos de {vilao}] Acabou o turno."]}, "fim": {"en": ["{cativos} climb up into the light covered in silver dust, leaning on one another. One of them stops at the exit, looks back and spits at the mine."], "pt": ["{cativos} sobem para a luz cobert⟨cativos:o|a|os|as⟩ de pó de prata, apoiad⟨cativos:o|a|os|as⟩ uns nos outros. Um deles para na saída, olha para trás e cospe na mina."]}, "fecho": {"en": ["On the road to {povoado}, the lanterns go out one by one, because no one needs to wait any longer."], "pt": ["Na estrada de {povoado}, os lampiões se apagam um a um, porque ninguém mais precisa esperar."]}, "pa": {"en": ["Hear that? Pickaxes, down below."], "pt": ["Ouviram? Picaretas, lá embaixo."]}, "pb": {"en": ["At this hour? Any miner worth his salt is long in bed."], "pt": ["A esta hora? Mineiro que se preze já foi dormir."]}, "entr": {"en": ["These mine-cart rails lead into {lugar}. Can you hear the pickaxes and the chains down there?"], "pt": ["Esses trilhos de carrinho de mina entram em {lugar}. Estão ouvindo as picaretas e as correntes lá embaixo?"]}, "chave": {"en": ["A pickaxe stops striking. A moment later, {vilao} shouts: “Get that one out of there and put another in his place.”"], "pt": ["Uma picareta para de bater. Logo depois, {vilao} grita: «Tirem esse daí e ponham outro no lugar.»"]}, "chc": {"en": ["A pickaxe stops striking. A moment later, {vilao} shouts: “Get that one out of there and put another in his place.” The miners of {povoado} are down there, and one of them has just fallen."], "pt": ["Uma picareta para de bater. Logo depois, {vilao} grita: «Tirem esse daí e ponham outro no lugar.» Os mineiros de {povoado} estão lá embaixo, e um deles acabou de cair."]}, "chs": {"en": ["A pickaxe stops striking. A moment later, {vilao} shouts: “Get that one out of there and put another in his place.” The pickaxes you heard from the road belong to captive miners, and one of them has just fallen."], "pt": ["Uma picareta para de bater. Logo depois, {vilao} grita: «Tirem esse daí e ponham outro no lugar.» As picaretas que vocês ouviram na estrada são de mineiros presos, e um deles acabou de cair."]}, "elos": [{"t": "n", "txt": {"en": ["At the mouth of the mine, someone has left a lit lantern with a note under it: “For whoever comes for the men. They are still down there.”"], "pt": ["Na boca da mina, alguém deixou um lampião aceso e um bilhete embaixo: «Para quem vier buscar os homens. Ainda estão lá embaixo.»"]}}, {"t": "h", "txt": {"en": ["Listen to the pickaxes. If they are still striking, the miners from the notice are alive."], "pt": ["Escutem as picaretas. Se ainda estão batendo, é porque os mineiros do aviso estão vivos."]}}, {"t": "n", "txt": {"en": ["From below, between one pickaxe blow and the next, someone shouts a name, and then another, like a man counting how many are still on their feet."], "pt": ["Lá de baixo, entre uma picaretada e outra, alguém grita um nome, e depois outro, como quem conta quantos ainda estão de pé."]}}]}, "resgate/casamento": {"tit": {"en": ["The Stolen Bride", "The Wedding of {vilao}", "Before the Altar"], "pt": ["A Noiva Roubada", "O Casamento de {vilao}", "Antes do Altar"]}, "aviso": {"en": ["Help {povoado}. Armed men carried off {cativos} in the middle of a wedding feast, and the two families are already accusing each other of treachery. If the bride is not back soon, the quarrel between the houses will turn into a war.", "Please bring the bride back. {cativos} were taken from the wedding feast in {povoado}, and the tracks lead to {lugar}.", "{povoado} needs help before the two families kill each other. The bride was taken in the middle of the feast, and each family swears the other is to blame."], "pt": ["Ajudem {povoado}. Homens armados levaram {cativos} no meio de uma festa de casamento, e as duas famílias já se acusam de traição. Se a noiva demorar a voltar, a briga entre as casas vira guerra.", "Por favor, tragam a noiva de volta. Levaram {cativos} da festa de casamento em {povoado}, e os rastros vão até {lugar}.", "{povoado} precisa de ajuda antes que as duas famílias se matem. A noiva foi levada no meio da festa, e cada família jura que a culpa é da outra."]}, "abert": {"en": ["The heroes follow the petals of the feast along the road to {lugar}."], "pt": ["Os heróis seguem as pétalas da festa pela estrada até {lugar}."]}, "fala": {"en": ["I was pouring the wine when they came in. They went straight to the bride, as if they already knew where she was sitting. One of them shouted the name of the man who paid them: {vilao}, who asked for her hand last year and was told no. It seems he is still hoping to hear a yes."], "pt": ["Eu servia o vinho quando eles entraram. Foram direto até a noiva, como quem já sabia onde ela estava sentada. Um deles gritou o nome de quem pagou: {vilao}, que pediu a mão dela no ano passado e ouviu um não. Pelo jeito, ainda espera ouvir um sim."]}, "pista": {"nome": {"en": "A bridal veil", "pt": "Um véu de noiva"}, "olhar": {"en": "A torn bridal veil, tied to a branch with a firm knot.", "pt": "Um véu de noiva, rasgado, preso num galho com um nó firme."}, "revela": {"en": "A white cloth is tied up near the entrance.", "pt": "Há um pano branco preso perto da entrada."}, "texto": {"en": ["The veil is tied to the branch with a firm knot, made in a hurry: the bride left it there on purpose. Farther on, flowers from the feast are scattered on the ground, and from deep inside comes a man's voice, rehearsing: “I, {vilao}, take you as my wife.”"], "pt": ["O véu está preso ao galho por um nó firme, que alguém deu com pressa: a noiva o deixou ali de propósito. Mais adiante há flores da festa espalhadas pelo chão, e lá do fundo vem uma voz de homem, ensaiando: «Eu, {vilao}, aceito você como esposa.»"]}}, "ultima": {"en": ["The bride sits on a chair decked with flowers stolen from the feast, and beside her stands {vilao}, dressed for his wedding."], "pt": ["A noiva está sentada numa cadeira enfeitada com flores roubadas da festa, e ao lado dela está {vilao}, vestido para casar."]}, "narr": {"en": ["As you come in, {vilao} rises and straightens his groom's clothes."], "pt": ["Quando vocês entram, {vilao} se levanta e ajeita a roupa de noivo."]}, "vil": {"en": ["You are just in time. Every ceremony needs witnesses."], "pt": ["Chegaram a tempo. Toda cerimônia precisa de testemunhas."]}, "hc": {"en": ["The feast in {povoado} goes on. Without you."], "pt": ["A festa em {povoado} continua. Sem você."]}, "hs": {"en": ["[looking at the bride] Hold on a little longer. We are getting you out of here."], "pt": ["[olhando para a noiva] Aguenta mais um pouco. Já vamos tirar você daqui."]}, "fim": {"en": ["{cativos} step out into the light still in their feast clothes, torn and stained with earth. The bride pulls off her veil, looks at you and asks whether there is still time to be married today."], "pt": ["{cativos} saem para a luz ainda com as roupas da festa, rasgadas e sujas de terra. A noiva arranca o véu, olha para vocês e pergunta se ainda dá tempo de casar hoje."]}, "fecho": {"en": ["In {povoado}, the musicians strike up again, and the two fathers, swords still at their belts, share the same jug of wine."], "pt": ["Em {povoado}, os músicos voltam a tocar, e os dois pais, de espada ainda na cintura, dividem a mesma jarra de vinho."]}, "pa": {"en": ["Petals on the ground. Still fresh."], "pt": ["Pétalas no chão. Ainda frescas."]}, "pb": {"en": ["Wedding guests do not usually come this way."], "pt": ["Gente de festa não costuma passar por aqui."]}, "entr": {"en": ["The petals lead into {lugar}. See that little shoe by the door?"], "pt": ["As pétalas entram em {lugar}. Viu esse pequeno sapato ao lado da porta?"]}, "chave": {"en": ["From deep inside comes the sound of a flute, badly out of tune. A moment later, {vilao} says: “Smile. Today is the happiest day of your life.”"], "pt": ["Lá do fundo vem uma música de flauta bastante desafinada. Logo depois, {vilao} diz: «Sorria. Hoje é o dia mais feliz da sua vida.»"]}, "chc": {"en": ["From deep inside comes the sound of a flute, badly out of tune. A moment later, {vilao} says: “Smile. Today is the happiest day of your life.” The bride from the notice is in there, and someone means to marry her by force."], "pt": ["Lá do fundo vem uma música de flauta bastante desafinada. Logo depois, {vilao} diz: «Sorria. Hoje é o dia mais feliz da sua vida.» A noiva do aviso está lá dentro, e alguém quer casar com ela à força."]}, "chs": {"en": ["From deep inside comes the sound of a flute, badly out of tune. A moment later, {vilao} says: “Smile. Today is the happiest day of your life.” The petals on the road came from a wedding feast, and someone in there means to marry the bride by force."], "pt": ["Lá do fundo vem uma música de flauta bastante desafinada. Logo depois, {vilao} diz: «Sorria. Hoje é o dia mais feliz da sua vida.» As pétalas da estrada eram da festa de um casamento, e alguém lá dentro quer casar com a noiva à força."]}, "elos": [{"t": "n", "txt": {"en": ["Tied to a branch at the entrance is a white ribbon from the feast, held by a firm knot. Someone left it there on purpose, for whoever came after."], "pt": ["Presa num galho na entrada, há uma fita de festa, branca, com um nó firme. Alguém a deixou ali de propósito, para quem viesse atrás."]}}, {"t": "h", "txt": {"en": ["A little dancing shoe lies at the side of the path. The bride from the notice was dragged through here."], "pt": ["Um sapatinho de festa, caído na beira do caminho. A noiva do aviso passou por aqui arrastada."]}}, {"t": "n", "txt": {"en": ["From inside comes a woman's voice, softly singing a wedding song. The voice trembles at the end of every line."], "pt": ["Lá de dentro vem uma voz de mulher, cantando baixinho uma música de casamento. A voz treme no fim de cada verso."]}}]}, "reliquia": {"tit": {"en": ["The Race for {alvo}", "What {vilao} Seeks", "The Last Reliquary"], "pt": ["A Corrida por {alvo}", "O Que {vilao} Procura", "O Último Relicário"]}, "aviso": {"en": ["Help us recover {alvo}, which has been kept in {lugar} {origem}. {alvo} is a danger in the wrong hands, and {desde} there have been people digging there.", "Please get there before the thieves. {alvo}, kept in {lugar} {origem}, is being sought by people who wish {povoado} no good.", "{povoado} needs help. Someone is turning {lugar} upside down in search of {alvo}, which has been kept there {origem}. In the wrong hands, {alvo} could put everything at risk."], "pt": ["Ajudem a buscar {alvo}, que está guardad⟨alvo:o|a|os|as⟩ em {lugar} {origem}. {alvo} é um perigo nas mãos erradas, e {desde} há gente cavando por lá.", "Por favor, cheguem antes dos ladrões. {alvo}, guardad⟨alvo:o|a|os|as⟩ em {lugar} {origem}, está sendo procurad⟨alvo:o|a|os|as⟩ por gente que não quer o bem de {povoado}.", "{povoado} precisa de ajuda. Alguém está revirando {lugar} atrás de {alvo}, que ficou guardad⟨alvo:o|a|os|as⟩ lá {origem}. Nas mãos erradas, {alvo} pode pôr tudo em risco."]}, "abert": {"en": ["The heroes reach {lugar} and find fresh shovel marks at the entrance."], "pt": ["Os heróis chegam a {lugar} e acham marcas de pá recentes na entrada."]}, "fala": {"en": ["The one after {alvo} is {vilao}, who came through here yesterday with a crew of diggers and a sack full of loot from other shrines. They have not found what they are looking for yet: I can hear the shouting from inside, from someone who is running out of patience."], "pt": ["Quem está atrás de {alvo} é {vilao}. Passou por aqui ontem, com gente para cavar e um saco cheio do que tirou de outros santuários. Ainda não achou o que procura, porque eu ouço os gritos lá de dentro, de alguém que está perdendo a paciência."]}, "pista": {"nome": {"en": "A broken shovel", "pt": "Uma pá quebrada"}, "olhar": {"en": "A shovel with a broken handle, left on a mound of fresh earth.", "pt": "Uma pá de cabo quebrado, largada sobre um monte de terra fresca."}, "revela": {"en": "A shovel has been left near the entrance.", "pt": "Há uma pá largada perto da entrada."}, "texto": {"en": ["The shovel broke against the stone, and whoever was using it dropped it there and went to fetch another: there are footprints going and coming back. From inside, a voice shouts orders at the diggers: “{vilao} wants {alvo} by nightfall!”"], "pt": ["A pá quebrou contra a pedra, e quem a usava a largou ali e foi buscar outra, porque há pegadas indo e voltando. Lá de dentro, uma voz grita ordens aos cavadores: «{vilao} quer {alvo} até a noite!»"]}}, "ultima": {"en": ["{alvo} rests on a stone pedestal, and beside it stands {vilao}, hand outstretched."], "pt": ["{alvo} está num pedestal de pedra, e ao lado está {vilao}, de mão estendida."]}, "narr": {"en": ["As you come in, {vilao} closes that hand a palm's width from {alvo}."], "pt": ["Quando vocês entram, {vilao} fecha a mão a um palmo de {alvo}."]}, "vil": {"en": ["Three months of digging, and now you. This is mine."], "pt": ["Três meses cavando, e agora vocês. Isto aqui é meu."]}, "hc": {"en": ["{povoado} thinks otherwise."], "pt": ["{povoado} pensa diferente."]}, "hs": {"en": ["It was yours until we got here."], "pt": ["Era seu até a gente chegar."]}, "fim": {"en": ["{alvo} is heavier than it looks, and the air around it hums softly. You wrap ⟨alvo:it|it|them|them⟩ in a cloth, and the humming settles."], "pt": ["{alvo} pesa mais do que parece, e o ar em volta zumbe baixinho. Vocês ⟨alvo:o|a|os|as⟩ enrolam num pano, e o zumbido se acalma."]}, "fecho": {"en": ["In {povoado}, {alvo} is hidden away in a place only three people know, and the shovels of {lugar} fall still for good."], "pt": ["Em {povoado}, {alvo} é guardad⟨alvo:o|a|os|as⟩ num lugar que só três pessoas conhecem, e as pás de {lugar} ficam paradas para sempre."]}, "pa": {"en": ["My hair is standing on end."], "pt": ["Meus cabelos estão em pé."]}, "pb": {"en": ["Mine too. And the sky is clear."], "pt": ["Os meus também. E o céu está limpo."]}, "entr": {"en": ["Look at the shovel marks at the entrance of {lugar}, and the mounds of fresh earth on both sides. Someone has been digging here not long ago."], "pt": ["Olhem as marcas de pá na entrada de {lugar}, e os montes de terra fresca dos dois lados. Alguém cavou aqui faz pouco tempo."]}, "chave": {"en": ["From deep inside comes the sound of a heavy stone being dragged. A moment later, {vilao} shouts: “We have found the chamber. Dig faster.”"], "pt": ["Ao fundo, ouve-se uma pedra pesada sendo arrastada. Logo depois, {vilao} grita: «Achamos a câmara. Cavem mais depressa.»"]}, "chc": {"en": ["From deep inside comes the sound of a heavy stone being dragged. A moment later, {vilao} shouts: “We have found the chamber. Dig faster.” Whoever is digging here is after {alvo}, and is already close."], "pt": ["Ao fundo, ouve-se uma pedra pesada sendo arrastada. Logo depois, {vilao} grita: «Achamos a câmara. Cavem mais depressa.» Quem cava aqui está atrás de {alvo}, e já está perto."]}, "chs": {"en": ["From deep inside comes the sound of a heavy stone being dragged. A moment later, {vilao} shouts: “We have found the chamber. Dig faster.” That is why your hair stood on end on the road: there is something very old here, and someone has almost reached it."], "pt": ["Ao fundo, ouve-se uma pedra pesada sendo arrastada. Logo depois, {vilao} grita: «Achamos a câmara. Cavem mais depressa.» Por isso os cabelos de vocês ficaram em pé na estrada: há alguma coisa muito antiga aqui, e alguém está quase chegando nela."]}, "elos": [{"t": "h", "txt": {"en": ["From the size of these mounds of earth, they dug all night. It is just as the notice said: there are people after {alvo}."], "pt": ["Pelo tamanho desses montes de terra, cavaram a noite toda. É o que o aviso dizia: tem gente atrás de {alvo}."]}}, {"t": "n", "txt": {"en": ["At the entrance lies a map torn in half, trampled into the mud. The half that is left points inside, with a cross drawn in red."], "pt": ["Na entrada, há um mapa rasgado ao meio, pisado na lama. A metade que sobrou aponta para dentro, com uma cruz desenhada em vermelho."]}}, {"t": "n", "txt": {"en": ["From inside comes the noise of shovels striking stone, and of someone shouting at them to dig faster."], "pt": ["Lá de dentro vem o barulho de pás batendo em pedra, e alguém gritando para cavarem mais depressa."]}}]}, "reliquia/despertar": {"tit": {"en": ["The Awakening of {alvo}", "The Earth Shakes in {lugar}", "What Slept in {lugar}"], "pt": ["O Despertar de {alvo}", "A Terra Treme em {lugar}", "O Que Dormia em {lugar}"]}, "aviso": {"en": ["Help {povoado}. {desde}, {sinal} around {lugar}, and {gente} {gentefaz}. {alvo} has been kept there {origem}, and the elders say it is to blame.", "Help {povoado}. {desde}, {sinal} around {lugar}, and {gente} {gentefaz}. It all began when {alvo}, kept there {origem}, started to glow again.", "Help {povoado}. {desde}, {sinal} around {lugar}, and {gente} {gentefaz}. Those who understand such things say that {alvo}, hidden there {origem}, has awakened."], "pt": ["Ajudem {povoado}. {desde}, {sinal} em volta de {lugar}, e {gente} {gentefaz}. {alvo} estava guardad⟨alvo:o|a|os|as⟩ lá {origem}, e os mais velhos dizem que a culpa é d⟨alvo:ele|ela|eles|elas⟩.", "Ajudem {povoado}. {desde}, {sinal} em volta de {lugar}, e {gente} {gentefaz}. Tudo começou quando {alvo}, guardad⟨alvo:o|a|os|as⟩ ali {origem}, voltou a brilhar.", "Ajudem {povoado}. {desde}, {sinal} em volta de {lugar}, e {gente} {gentefaz}. Quem entende dessas coisas diz que {alvo}, escondid⟨alvo:o|a|os|as⟩ ali {origem}, acordou."]}, "abert": {"en": ["The heroes reach {lugar}, and the ground trembles faintly under their feet."], "pt": ["Os heróis chegam a {lugar}, e o chão treme de leve sob os pés deles."]}, "fala": {"en": ["{alvo} has awakened, and someone got here before you to make use of it: {vilao} is in there, close to it, drawing on its power for something. Every time the earth shakes, that is {vilao} pulling harder. Get {alvo} out of there before {povoado} comes down."], "pt": ["{alvo} acordou, e alguém chegou antes de vocês para aproveitar: {vilao} está lá dentro, perto d⟨alvo:ele|ela|eles|elas⟩, usando o poder para alguma coisa. Cada vez que a terra treme, é {vilao} puxando mais. Tirem {alvo} de lá antes que {povoado} desabe."]}, "pista": {"nome": {"en": "A glowing crack", "pt": "Uma rachadura que brilha"}, "olhar": {"en": "A crack in the wall, with a faint light pulsing inside it.", "pt": "Uma rachadura na parede, com uma luz fraca pulsando lá dentro."}, "revela": {"en": "A faint light pulses in a wall near the entrance.", "pt": "Uma luz fraca pulsa numa parede perto da entrada."}, "texto": {"en": ["The light pulses in time with the trembling of the ground, and you realize it comes from deep inside, where {alvo} is kept. On the floor beside the crack are fresh candles and a circle scratched in the stone: someone is taking advantage of this. On a scrap of leather left there is a list of requests, and at the top, the name of the one making them: {vilao}."], "pt": ["A luz pulsa no mesmo ritmo do tremor do chão, e vocês percebem que vem do fundo, onde {alvo} está guardad⟨alvo:o|a|os|as⟩. No chão, ao lado da rachadura, há velas novas e um círculo riscado: alguém está tirando proveito disso. Num pedaço de couro largado ali, uma lista de pedidos, e no alto, o nome de quem os faz: {vilao}."]}}, "ultima": {"en": ["{alvo} glows in the middle of the room, and {vilao} kneels before it, hands outstretched, drinking in the light."], "pt": ["{alvo} brilha no meio da sala, e {vilao} está de joelhos na frente, de mãos estendidas, bebendo a luz."]}, "narr": {"en": ["As you come in, the whole room shakes, and {vilao} rises without looking away from {alvo}."], "pt": ["Quando vocês entram, a sala inteira treme, e {vilao} se levanta sem tirar os olhos de {alvo}."]}, "vil": {"en": ["Did you feel that? It is only the beginning. Leave, if you still have legs to carry you."], "pt": ["Vocês sentiram isso? É só o começo. Saiam, se ainda tiverem pernas."]}, "hc": {"en": ["{povoado} wants to sleep without the ground shaking. Let go of that."], "pt": ["{povoado} quer dormir sem tremor. Larga isso."]}, "hs": {"en": ["Let go of that. Now."], "pt": ["Larga isso agora."]}, "fim": {"en": ["When you touch {alvo}, the glow goes out, and the trembling stops all at once. For a moment, the silence seems louder than the shaking was."], "pt": ["Quando vocês tocam {alvo}, o brilho se apaga, e o tremor para de uma vez. Por um instante, o silêncio parece mais alto que o tremor."]}, "fecho": {"en": ["In {povoado}, the earth stops shaking that very night, and {gente} go back to work the next morning."], "pt": ["Em {povoado}, a terra para de tremer naquela mesma noite, e {gente} voltam ao trabalho na manhã seguinte."]}, "pa": {"en": ["Did the ground just shake?"], "pt": ["O chão tremeu agora?"]}, "pb": {"en": ["It did. And that was not the first time."], "pt": ["Tremeu. E não foi o primeiro."]}, "entr": {"en": ["The earth shakes harder here, near {lugar}. Do you see that light coming from the entrance?"], "pt": ["A terra treme mais forte aqui, perto de {lugar}. Estão vendo aquela luz saindo da entrada?"]}, "chave": {"en": ["The whole room shakes, and a stone falls from the ceiling. From deep inside comes the laughter of {vilao}: “More. I want more.”"], "pt": ["A sala inteira treme, e uma pedra cai do teto. Lá do fundo, ouve-se {vilao} rindo: «Mais. Quero mais.»"]}, "chc": {"en": ["The whole room shakes, and a stone falls from the ceiling. From deep inside comes the laughter of {vilao}: “More. I want more.” It is the trembling the notice spoke of, and whoever is causing it is deep inside."], "pt": ["A sala inteira treme, e uma pedra cai do teto. Lá do fundo, ouve-se {vilao} rindo: «Mais. Quero mais.» É o tremor de que o aviso falava, e quem o provoca está lá no fundo."]}, "chs": {"en": ["The whole room shakes, and a stone falls from the ceiling. From deep inside comes the laughter of {vilao}: “More. I want more.” The tremors on the road came from here, and someone deep inside is causing them on purpose."], "pt": ["A sala inteira treme, e uma pedra cai do teto. Lá do fundo, ouve-se {vilao} rindo: «Mais. Quero mais.» Os tremores da estrada vinham daqui, e alguém lá no fundo os provoca de propósito."]}, "elos": [{"t": "h", "txt": {"en": ["Did you feel that? The ground shook again. The notice said it came from here, and so it does."], "pt": ["Sentiram? O chão tremeu de novo. O aviso dizia que vinha daqui, e vem mesmo."]}}, {"t": "n", "txt": {"en": ["A faint light pulses deep inside, in time with the trembling that is felt in {povoado}."], "pt": ["Uma luz fraca pulsa lá no fundo, no mesmo ritmo do tremor que se sente em {povoado}."]}}, {"t": "n", "txt": {"en": ["At the entrance, someone has nailed up a board with one word carved by knife: “Keep away.” The board is split down the middle."], "pt": ["Na entrada, alguém pregou uma tábua com uma palavra escrita a faca: «Afastem-se.» A tábua está rachada ao meio."]}}]}, "reliquia/guardiao": {"tit": {"en": ["The Guardian of {lugar}", "The Letters That Stopped", "Who Guarded {alvo}"], "pt": ["O Guardião de {lugar}", "As Cartas que Pararam", "Quem Guardava {alvo}"]}, "aviso": {"en": ["Help us find out what happened in {lugar}. The one who looked after {alvo} in there has sent no word {desde}.", "Please go to {lugar}. The guardian who lives there, looking after {alvo} {origem}, used to send news to {povoado} every week, and {desde} no news has come.", "{povoado} asks someone to go to {lugar}. The guardian of {alvo} has been missing {desde}, and at night, those who pass nearby say they hear someone weeping inside."], "pt": ["Ajudem a descobrir o que aconteceu em {lugar}. Quem cuidava de {alvo} lá dentro está sem dar notícias {desde}.", "Por favor, vão até {lugar}. O guardião que vive lá, cuidando de {alvo} {origem}, mandava notícias para {povoado} toda semana, e {desde} elas pararam de chegar.", "{povoado} pede que alguém vá até {lugar}. O guardião de {alvo} está sumido {desde}, e de noite, quem passa por perto diz ouvir alguém chorando lá dentro."]}, "abert": {"en": ["The heroes reach {lugar} and find the door open. No one answers when they call."], "pt": ["Os heróis chegam a {lugar} e acham a porta aberta. Ninguém responde quando eles chamam."]}, "fala": {"en": ["The guardian changed. First he stopped eating, then he stopped sleeping, and in the end he began talking to {alvo} as if it could hear him. Now {vilao} gives the orders here, and the guardian does whatever he is told. Be careful: he still knows every passage in this place."], "pt": ["O guardião mudou. Primeiro deixou de comer, depois deixou de dormir, e no fim começou a falar sozinho com {alvo}. Agora quem manda aqui é {vilao}, e o guardião faz tudo o que mandam. Tomem cuidado: ele ainda sabe todos os caminhos deste lugar."]}, "pista": {"nome": {"en": "The last letter", "pt": "A última carta"}, "olhar": {"en": "An unfinished letter, with ink still spilled across the table.", "pt": "Uma carta inacabada, com a tinta ainda espalhada pela mesa."}, "revela": {"en": "A letter lies on a table near the entrance.", "pt": "Há uma carta sobre uma mesa perto da entrada."}, "texto": {"en": ["The letter is from the guardian to {povoado}, and it stops in the middle of a sentence. The first lines speak of routine, of candles and cleaning. The last ones are in a different hand, larger and crooked: “Someone came. {vilao} says that {alvo} wants to get out, and I believe it.”"], "pt": ["A carta é do guardião para {povoado}, e para no meio de uma frase. As primeiras linhas falam de rotina, de velas e de limpeza. As últimas têm outra letra, maior e torta: «Alguém veio. {vilao} diz que {alvo} quer sair, e eu acredito.»"]}}, "ultima": {"en": ["{alvo} rests on an altar. Before it, the guardian prays on his knees, and beside him stands {vilao}."], "pt": ["{alvo} está sobre um altar. Na frente del⟨alvo:e|a|es|as⟩, o guardião reza de joelhos, e ao lado está {vilao}."]}, "narr": {"en": ["As you come in, the guardian rises and places himself between you and {alvo}."], "pt": ["Quando vocês entram, o guardião se levanta e fica entre vocês e {alvo}."]}, "vil": {"en": ["He looked after this for years and never knew what it was for. I know."], "pt": ["Ele cuidou disso por anos e nunca soube para quê. Eu sei."]}, "hc": {"en": ["{povoado} wants its guardian back."], "pt": ["{povoado} quer o guardião de volta."]}, "hs": {"en": ["We came for the guardian."], "pt": ["Viemos buscar o guardião."]}, "fim": {"en": ["With {alvo} far from the altar, the guardian sinks to the floor and weeps, like a man waking from a bad dream. He asks to go with you."], "pt": ["Com {alvo} longe do altar, o guardião cai sentado e chora, como quem acorda de um sonho ruim. Ele pede para ir com vocês."]}, "fecho": {"en": ["In {povoado}, the guardian is welcomed with hot soup and a great many questions. He answers them all but one."], "pt": ["Em {povoado}, o guardião é recebido com sopa quente e muitas perguntas. Ele responde a todas, menos a uma."]}, "pa": {"en": ["The door is open, and no one answers."], "pt": ["A porta está aberta, e ninguém responde."]}, "pb": {"en": ["Whoever lives in a place like this keeps the door locked."], "pt": ["Quem mora num lugar desses deixa a porta trancada."]}, "entr": {"en": ["The door of {lugar} is open. Did you hear that weeping inside?"], "pt": ["A porta de {lugar} está aberta. Ouviram esse choro lá dentro?"]}, "chave": {"en": ["From deep inside, a weary voice repeats over and over: “I keep it safe, I keep it safe, I keep it safe.” It sounds like the guardian."], "pt": ["Lá do fundo, uma voz cansada repete sem parar: «Eu cuido, eu cuido, eu cuido.» Parece que é o guardião."]}, "chc": {"en": ["From deep inside, a weary voice repeats over and over: “I keep it safe, I keep it safe, I keep it safe.” It sounds like the guardian. The guardian from the notice is alive, and someone is holding him deep inside."], "pt": ["Lá do fundo, uma voz cansada repete sem parar: «Eu cuido, eu cuido, eu cuido.» Parece que é o guardião. O guardião do aviso está vivo, e alguém o prende lá no fundo."]}, "chs": {"en": ["From deep inside, a weary voice repeats over and over: “I keep it safe, I keep it safe, I keep it safe.” It sounds like the guardian. That is why the door was open: someone took the guardian deep inside."], "pt": ["Lá do fundo, uma voz cansada repete sem parar: «Eu cuido, eu cuido, eu cuido.» Parece que é o guardião. Por isso a porta estava aberta: alguém levou o guardião lá para o fundo."]}, "elos": [{"t": "n", "txt": {"en": ["On the door is a letter from the guardian that was never sent, addressed to {povoado}. The ink is smudged on the last line."], "pt": ["Na porta, há uma carta do guardião que nunca foi enviada, endereçada a {povoado}. A tinta borrou na última linha."]}}, {"t": "h", "txt": {"en": ["The lamp at the entrance is still burning. Whoever looks after this place lit it not long ago."], "pt": ["A lamparina da entrada ainda está acesa. Quem cuida daqui acendeu faz pouco tempo."]}}, {"t": "n", "txt": {"en": ["From inside comes a weary voice, praying alone, always the same sentence."], "pt": ["Lá de dentro vem uma voz cansada, rezando sozinha, sempre a mesma frase."]}}]}, "ritual": {"tit": {"en": ["The Rite of {vilao}", "Break the Circle", "What {vilao} Calls"], "pt": ["O Rito de {vilao}", "Quebrem o Círculo", "O Que {vilao} Chama"]}, "aviso": {"en": ["Help {povoado}. {desde}, {sinal}, and no one sleeps well. A chant rises from {lugar}, and the elders say it is calling {entidade}.", "Please put a stop to the chanting in {lugar}. {desde}, {sinal} in {povoado}, and {gente} {gentefaz}.", "{povoado} is calling for help. Someone has been chanting in {lugar} {desde}, and ever since, {sinal}. The chant calls for {entidade}."], "pt": ["Ajudem {povoado}. {desde}, {sinal}, e ninguém dorme direito. Um canto sobe de {lugar}, e os mais velhos dizem que está chamando {entidade}.", "Por favor, façam parar o canto de {lugar}. {desde}, {sinal} em {povoado}, e {gente} {gentefaz}.", "{povoado} pede socorro. Alguém está cantando em {lugar} {desde}, e desde então {sinal}. O canto chama por {entidade}."]}, "abert": {"en": ["The heroes follow the chant to {lugar}, and it grows louder with every step."], "pt": ["Os heróis seguem o canto até {lugar}, e ele fica mais forte a cada passo."]}, "fala": {"en": ["I was part of the cult until yesterday. They have been chanting for three nights, without stopping even to drink water, and the one leading the chant is {vilao}. The chant is calling {entidade}. Before it reaches its end, break what feeds the rite, or it will go on even with no one left to chant."], "pt": ["Eu fazia parte do culto até ontem. Eles cantam há três noites, sem parar nem para beber água, e quem conduz o canto é {vilao}. O canto está chamando {entidade}. Antes de chegar ao fim, quebrem o que alimenta o rito, ou ele continua mesmo sem quem canta."]}, "pista": {"nome": {"en": "A circle of ashes", "pt": "Um círculo de cinzas"}, "olhar": {"en": "A circle of ashes on the floor, still warm.", "pt": "Um círculo de cinzas no chão, ainda morno."}, "revela": {"en": "A circle is drawn on the floor near the entrance.", "pt": "Há um círculo desenhado no chão perto da entrada."}, "texto": {"en": ["The ashes are still warm: the rite passed through here a short while ago. The symbols around the circle form a prayer to {entidade}, and one name is repeated at the end of every line, like the word that closes a prayer: {vilao}."], "pt": ["As cinzas ainda estão mornas, porque o rito passou por aqui há pouco. Os símbolos em volta do círculo formam uma oração a {entidade}, e um mesmo nome se repete no fim de cada linha, como a palavra que fecha uma reza: {vilao}."]}}, "ultima": {"en": ["At the center of a circle of candles, {vilao} leads the chant. The cultists repeat every verse."], "pt": ["No centro de um círculo de velas, {vilao} conduz o canto. Os cultistas repetem cada verso."]}, "narr": {"en": ["As you come in, {vilao} stops chanting, and the chant goes on all the same."], "pt": ["Quando vocês entram, {vilao} para de cantar, e o canto continua assim mesmo."]}, "vil": {"en": ["You are here for the last verse. Stay. You will be the first to see {entidade}."], "pt": ["Chegaram para o último verso. Fiquem. Vão ser os primeiros a ver {entidade}."]}, "hc": {"en": ["{povoado} wants to sleep. Enough chanting."], "pt": ["{povoado} quer dormir. Chega de canto."]}, "hs": {"en": ["No one here wants to see that."], "pt": ["Ninguém aqui quer ver."]}, "fim": {"en": ["The chant breaks off in the middle of a word. The silence is so deep that you can hear water dripping far inside."], "pt": ["O canto se interrompe no meio de uma palavra. O silêncio é tão grande que dá para ouvir a água pingando lá no fundo."]}, "fecho": {"en": ["In {povoado}, everyone sleeps until morning, and no one remembers their dreams."], "pt": ["Em {povoado}, todo mundo dorme até de manhã, e ninguém lembra o que sonhou."]}, "pa": {"en": ["Do you hear chanting?"], "pt": ["Vocês ouvem um cântico?"]}, "pb": {"en": ["I do. And I have never heard that language before."], "pt": ["Ouço. E essa língua eu nunca ouvi."]}, "entr": {"en": ["The chant is coming from inside {lugar}. Did you see the melted black candles at the entrance?"], "pt": ["O canto vem de dentro de {lugar}. Vocês viram as velas negras derretidas na entrada?"]}, "chave": {"en": ["The chant changes pitch, and the walls begin to sweat blood. The rite seems to have reached its last part: if the chant is finished, {entidade} will cross over."], "pt": ["O canto muda de tom, e as paredes começam a suar sangue. Parece que o rito chegou à última parte: se o canto terminar, {entidade} vai atravessar."]}, "chc": {"en": ["The chant changes pitch, and the walls begin to sweat blood. The rite seems to have reached its last part: if the chant is finished, {entidade} will cross over. It is the chant that robs {povoado} of its sleep."], "pt": ["O canto muda de tom, e as paredes começam a suar sangue. Parece que o rito chegou à última parte: se o canto terminar, {entidade} vai atravessar. É o canto que tira o sono de {povoado}."]}, "chs": {"en": ["The chant changes pitch, and the walls begin to sweat blood. The rite seems to have reached its last part: if the chant is finished, {entidade} will cross over. It is the same chanting you heard from the road, in the language no one knows."], "pt": ["O canto muda de tom, e as paredes começam a suar sangue. Parece que o rito chegou à última parte: se o canto terminar, {entidade} vai atravessar. É o mesmo cântico que vocês ouviram na estrada, na língua que ninguém conhece."]}, "elos": [{"t": "n", "txt": {"en": ["The chant the notice described is coming from inside. Even out here, you can tell there are many voices, and that none of them stops for breath."], "pt": ["O canto que o aviso descrevia sai de dentro. Daqui de fora, dá para ouvir que são muitas vozes, e que nenhuma para para respirar."]}}, {"t": "n", "txt": {"en": ["On the stone at the entrance, someone has drawn a circle in ash, and inside it a name the children of {povoado} repeat in their sleep: {entidade}."], "pt": ["Na pedra da entrada, alguém desenhou com cinza um círculo, e dentro dele um nome que as crianças de {povoado} repetem dormindo: {entidade}."]}}, {"t": "h", "txt": {"en": ["This is where the chant comes from. Listen: it is calling someone. It is calling for {entidade}."], "pt": ["É daqui que vem o canto. Escutem: ele chama alguém. Chama por {entidade}."]}}]}, "ritual/grimorio": {"tit": {"en": ["The Copies of {livro}", "Ink and Blood", "The Scriptorium of {vilao}"], "pt": ["As Cópias de {livro}", "Tinta e Sangue", "O Escriptório de {vilao}"]}, "aviso": {"en": ["Help us burn {livro}. It was stolen and is being copied in {lugar}, and every copy that leaves there carries the same evil to another town.", "Please go to {lugar} before the copies leave. Someone is copying {livro} in there, and {desde} {sinal} in {povoado}.", "{povoado} needs help. {livro}, which had been locked away {origem}, was stolen, and now it is being copied in {lugar} day and night."], "pt": ["Ajudem a queimar {livro}. Ele foi roubado e está sendo copiado em {lugar}, e cada cópia que sair de lá leva o mesmo mal a outra cidade.", "Por favor, vão até {lugar} antes que as cópias saiam. Alguém está copiando {livro} lá dentro, e {desde} {sinal} em {povoado}.", "{povoado} precisa de ajuda. {livro}, que estava trancado {origem}, foi roubado, e agora é copiado em {lugar} dia e noite."]}, "abert": {"en": ["The heroes reach {lugar} and smell ink before they are even through the entrance."], "pt": ["Os heróis chegam a {lugar} e sentem o cheiro de tinta já na entrada."]}, "fala": {"en": ["They copy day and night, with an ink that smells of iron. {vilao} reads {livro} aloud, and the scribes write without blinking, as if they were asleep. Every new page feeds the rite, so burn the copies first."], "pt": ["Eles copiam dia e noite, com uma tinta que cheira a ferro. {vilao} lê {livro} em voz alta, e os copistas escrevem sem piscar, como se dormissem. Cada página nova alimenta o rito, por isso queimem as cópias primeiro."]}, "pista": {"nome": {"en": "Burnt pages", "pt": "Páginas queimadas"}, "olhar": {"en": "A heap of half-burnt pages, still smoking.", "pt": "Um monte de páginas meio queimadas, ainda soltando fumaça."}, "revela": {"en": "A heap of burnt paper lies near the entrance.", "pt": "Há um monte de papel queimado perto da entrada."}, "texto": {"en": ["Someone tried to burn a copy and was stopped halfway: half the pages escaped the fire. On one surviving scrap, an order is written in the margin in a firm hand: “Twelve more copies by the full moon. Whoever stops writing becomes ink.” Below it, the signature: {vilao}."], "pt": ["Alguém tentou queimar uma cópia e foi interrompido no meio, porque metade das páginas escapou do fogo. Num pedaço que sobrou, há uma ordem anotada na margem, com letra firme: «Mais doze cópias até a lua cheia. Quem parar de escrever, vira tinta.» Embaixo, a assinatura: {vilao}."]}}, "ultima": {"en": ["{livro} lies open on an altar. {vilao} reads aloud, and the scribes write all around."], "pt": ["Sobre um altar está {livro}, abert⟨livro:o|a⟩. {vilao} lê em voz alta, e os copistas escrevem em volta."]}, "narr": {"en": ["As you come in, the scribes drop their quills at the same moment."], "pt": ["Quando vocês entram, os copistas largam as penas ao mesmo tempo."]}, "vil": {"en": ["Fire in a library? What dreadful manners."], "pt": ["Fogo numa biblioteca? Que falta de educação."]}, "hc": {"en": ["{povoado} wants that book burned."], "pt": ["{povoado} quer esse livro queimado."]}, "hs": {"en": ["We brought a torch. This book needs some light."], "pt": ["Trouxemos uma tocha. Este livro precisa de luz."]}, "fim": {"en": ["{livro} crackles in the fire like green wood, and the pages twist as they burn. Soon, only ash is left."], "pt": ["{livro} estala no fogo como lenha verde, e as páginas se retorcem enquanto queimam. Logo, sobra só cinza."]}, "fecho": {"en": ["In {povoado}, those who had nightmares sleep the whole night through for the first time in weeks."], "pt": ["Em {povoado}, quem tinha pesadelos dorme a noite inteira pela primeira vez em semanas."]}, "pa": {"en": ["Smell that? Ink. A great deal of ink."], "pt": ["Sentem? Cheiro de tinta. Muita tinta."]}, "pb": {"en": ["And blood. Someone is writing with both."], "pt": ["E de sangue. Alguém está escrevendo com as duas."]}, "entr": {"en": ["There are loose sheets scattered at the entrance of {lugar}, all in the same small handwriting. Someone is copying a great deal in there."], "pt": ["Tem folhas soltas espalhadas na entrada de {lugar}, todas com a mesma letra miúda. Alguém está copiando muita coisa aí dentro."]}, "chave": {"en": ["By the door is a stack of finished copies, tied up for travel. It looks as if the first ones are about to leave."], "pt": ["Junto à porta há uma pilha de cópias prontas, amarradas para viagem. Parece que as primeiras já estão de saída."]}, "chc": {"en": ["By the door is a stack of finished copies, tied up for travel. It looks as if the first ones are about to leave. These are the copies the notice spoke of."], "pt": ["Junto à porta há uma pilha de cópias prontas, amarradas para viagem. Parece que as primeiras já estão de saída. São as cópias de que o aviso falava."]}, "chs": {"en": ["By the door is a stack of finished copies, tied up for travel. It looks as if the first ones are about to leave. The loose sheets at the entrance were pages of these copies."], "pt": ["Junto à porta há uma pilha de cópias prontas, amarradas para viagem. Parece que as primeiras já estão de saída. As folhas soltas da entrada eram páginas destas cópias."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance lies a loose sheet, copied in a small hand and red ink. It is a page of {livro}."], "pt": ["Na entrada, há uma folha solta, copiada com letra miúda e tinta vermelha. É uma página de {livro}."]}}, {"t": "h", "txt": {"en": ["Look: this page came from inside. So the copies the notice spoke of are being made right here."], "pt": ["Olhem: essa página veio de dentro. Então as cópias de que o aviso falava são feitas aqui mesmo."]}}, {"t": "n", "txt": {"en": ["From inside comes the murmur of many voices reading at once, and the scratching of dozens of quills."], "pt": ["Lá de dentro vem um murmúrio de muitas vozes lendo ao mesmo tempo, e o arranhar de dezenas de penas."]}}]}, "ritual/romaria": {"tit": {"en": ["The Pilgrims of {lugar}", "Those Who Came Back Silent", "The Pilgrimage of {vilao}"], "pt": ["Os Peregrinos de {lugar}", "Os que Voltaram Calados", "A Romaria de {vilao}"]}, "aviso": {"en": ["Help {povoado}. {desde}, those who make the pilgrimage to {lugar} have come back silent and empty-eyed, and at night they leave their homes and walk back there.", "Please find out what is in {lugar}. The pilgrims of {povoado} came back from there changed, and now {sinal}.", "{povoado} is calling for help. Half of those who went to pray in {lugar} came back without speaking, and the other half did not come back."], "pt": ["Ajudem {povoado}. {desde}, quem faz a romaria até {lugar} volta calado e de olhos vazios, e à noite sai de casa andando para lá.", "Por favor, descubram o que há em {lugar}. Os peregrinos de {povoado} voltaram de lá mudados, e agora {sinal}.", "{povoado} pede socorro. Metade dos que foram rezar em {lugar} voltou sem falar, e a outra metade não voltou."]}, "abert": {"en": ["The heroes follow the pilgrims' trail to {lugar}. At the entrance, they find sandals left in a row, as if their owners meant to return."], "pt": ["Os heróis seguem a trilha dos peregrinos até {lugar}. Na entrada, eles acham sandálias deixadas em fila, como se os donos fossem voltar."]}, "fala": {"en": ["Inside, {vilao} welcomes the pilgrims with water and bread, and whoever eats the bread begins to hear a voice. The voice belongs to {entidade}, and it asks them to come back, and to bring more people. I spat the bread out. The others did not."], "pt": ["Lá dentro, {vilao} recebe os peregrinos com água e pão, e quem come o pão começa a ouvir uma voz. A voz é de {entidade}, e ela pede que voltem, e que tragam mais gente. Eu cuspi o pão. Os outros, não."]}, "pista": {"nome": {"en": "Sandals in a row", "pt": "Sandálias em fila"}, "olhar": {"en": "Pilgrims' sandals, carefully lined up, all pointing inside.", "pt": "Sandálias de peregrino, alinhadas com cuidado, todas viradas para dentro."}, "revela": {"en": "Sandals are lined up near the entrance.", "pt": "Há sandálias enfileiradas perto da entrada."}, "texto": {"en": ["The sandals are carefully lined up, and you can tell their owners went in barefoot: there are bare footprints in the dust. Beside them is a basket with scraps of bread, and a note of welcome in fine handwriting: “Eat, rest and listen. Signed, {vilao}.”"], "pt": ["As sandálias estão alinhadas com cuidado, e vocês percebem que os donos entraram descalços, porque há pegadas nuas na poeira. Ao lado, uma cesta com restos de pão, e um bilhete de boas-vindas escrito com letra bonita: «Comam, descansem e escutem. Assinado, {vilao}.»"]}}, "ultima": {"en": ["The pilgrims sit in a ring, eyes closed. In the middle of the ring, {vilao} is sharing out the bread."], "pt": ["Os peregrinos estão sentados em roda, de olhos fechados. No meio da roda, {vilao} reparte o pão."]}, "narr": {"en": ["As you come in, all the pilgrims open their eyes at the same moment."], "pt": ["Quando vocês entram, todos os peregrinos abrem os olhos ao mesmo tempo."]}, "vil": {"en": ["More pilgrims. Sit down. There is bread for everyone."], "pt": ["Mais peregrinos. Sentem-se. Há pão para todos."]}, "hc": {"en": ["{povoado} wants its people back."], "pt": ["{povoado} quer os seus de volta."]}, "hs": {"en": ["We did not come hungry."], "pt": ["Viemos sem fome."]}, "fim": {"en": ["With {vilao} fallen, the pilgrims blink and look around, not knowing where they are. One of them asks what day it is."], "pt": ["Com {vilao} caído, os peregrinos piscam e olham em volta, sem saber onde estão. Um deles pergunta que dia é hoje."]}, "fecho": {"en": ["In {povoado}, the pilgrims return home, and each one tells a different part of the story."], "pt": ["Em {povoado}, os peregrinos voltam para casa, e cada um conta uma parte diferente da história."]}, "pa": {"en": ["A sandal in the middle of the road."], "pt": ["Uma sandália no meio da estrada."]}, "pb": {"en": ["And another farther on. Someone took them off along the way."], "pt": ["E outra adiante. Alguém foi tirando pelo caminho."]}, "entr": {"en": ["Look at these sandals lined up at the entrance of {lugar}, all pointing inside."], "pt": ["Olhem essas sandálias enfileiradas na entrada de {lugar}, todas viradas para dentro."]}, "chave": {"en": ["From deep inside comes a low chorus, always the same sentence. The pilgrims seem to be calling {entidade} together."], "pt": ["Do fundo vem um coro baixo, sempre a mesma frase. Parece que os peregrinos estão chamando {entidade} juntos."]}, "chc": {"en": ["From deep inside comes a low chorus, always the same sentence. The pilgrims seem to be calling {entidade} together. They are the pilgrims of {povoado}, the ones who leave their homes at night."], "pt": ["Do fundo vem um coro baixo, sempre a mesma frase. Parece que os peregrinos estão chamando {entidade} juntos. São os romeiros de {povoado}, os que saem de casa à noite."]}, "chs": {"en": ["From deep inside comes a low chorus, always the same sentence. The pilgrims seem to be calling {entidade} together. The owners of the sandals on the road are all here."], "pt": ["Do fundo vem um coro baixo, sempre a mesma frase. Parece que os peregrinos estão chamando {entidade} juntos. Os donos das sandálias da estrada estão todos aqui."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance is a pair of pilgrim's sandals, carefully lined up, with a note tucked into them: “Mother, do not look for me.”"], "pt": ["Na entrada, há um par de sandálias de peregrino, alinhadas com cuidado, e um bilhete preso nelas: «Mãe, não me procure.»"]}}, {"t": "h", "txt": {"en": ["The bare footprints go in and do not come out. This is the way the pilgrims of {povoado} went."], "pt": ["As pegadas descalças entram e não saem. É por aqui que os peregrinos de {povoado} passaram."]}}, {"t": "n", "txt": {"en": ["From inside comes a low chorus, and you recognize the tune: it is a prayer of {povoado}, sung backward."], "pt": ["Lá de dentro vem um coro baixo, e vocês reconhecem a melodia: é uma reza de {povoado}, cantada ao contrário."]}}]}, "cacada": {"tit": {"en": ["The Lair of {vilao}", "The Hunt", "Tracks in {lugar}"], "pt": ["O Covil de {vilao}", "A Caçada", "Rastros em {lugar}"]}, "aviso": {"en": ["Help {povoado}. A beast comes down from the hills and takes the herds, and {desde} it has begun taking people: a girl went to fetch water, and only the bucket came back.", "Please hunt down the beast of {lugar}. {desde} it has been attacking the herds of {povoado}, and now {gente} {gentefaz}.", "{povoado} needs hunters. The beast that lives in {lugar} has already taken three cows, two dogs and a man."], "pt": ["Ajudem {povoado}. Uma fera desce das colinas e leva os rebanhos, e {desde} começou a levar gente: uma moça foi buscar água, e só o balde voltou.", "Por favor, cacem a fera de {lugar}. {desde} ela ataca os rebanhos de {povoado}, e agora {gente} {gentefaz}.", "{povoado} precisa de caçadores. A fera que mora em {lugar} já levou três vacas, dois cães e um homem."]}, "abert": {"en": ["The heroes follow the beast's tracks from the pastures to {lugar}."], "pt": ["Os heróis seguem os rastros da fera dos pastos até {lugar}."]}, "fala": {"en": ["Three farms, three nights, no survivors. The name they give the beast is {vilao}. It came down from the hills at the last moon, and it hides here. And mark this well: it learns. At the third farm, it came in through the back door."], "pt": ["Três fazendas, três noites, nenhum sobrevivente. O nome que dão à fera é {vilao}. Desceu das colinas na última lua, e se esconde aqui. E escutem bem: ela aprende. Na terceira fazenda, entrou pela porta dos fundos."]}, "pista": {"nome": {"en": "A mangled carcass", "pt": "Uma carcaça dilacerada"}, "olhar": {"en": "What is left of an ox. The bite marks are enormous.", "pt": "O que sobrou de um boi. As mordidas são enormes."}, "revela": {"en": "A carcass lies near the entrance.", "pt": "Há uma carcaça perto da entrada."}, "texto": {"en": ["The ox was dragged from the pasture all the way here without a single stop: the trail on the ground runs straight. The bite marks are the size of a human head. In this region, only one beast bites like that, and the people of {povoado} have already given it a name: {vilao}."], "pt": ["O boi foi arrastado do pasto até aqui sem uma parada, porque o rastro no chão é reto. As mordidas têm o tamanho de uma cabeça humana. Na região, só uma fera morde assim, e os moradores de {povoado} já lhe deram nome: {vilao}."]}}, "ultima": {"en": ["There are bones everywhere, and in the midst of them {vilao} lies resting."], "pt": ["Há ossos por toda parte, e no meio deles {vilao} descansa."]}, "narr": {"en": ["As you come in, {vilao} rises slowly, larger than any track could have led you to imagine."], "pt": ["Quando vocês entram, {vilao} se levanta devagar, maior do que qualquer rastro deixava imaginar."]}, "vil": {"en": ["(A growl so deep that the walls shake.)"], "pt": ["(Um rosnado tão fundo que as paredes tremem.)"]}, "hc": {"en": ["They were not exaggerating in {povoado}."], "pt": ["Em {povoado} não exageraram."]}, "hs": {"en": ["Now the tracks make sense."], "pt": ["Agora entendi os rastros."]}, "fim": {"en": ["{vilao} falls, and the ground shakes under the weight. For a moment, no one moves, just to be sure."], "pt": ["{vilao} cai, e o chão treme com o peso. Por um instante, ninguém se mexe, só para ter certeza."]}, "fecho": {"en": ["In {povoado}, they want the hide hung up in the square, and your beer is on the house."], "pt": ["Em {povoado}, querem o couro pendurado na praça, e a cerveja de vocês fica por conta da casa."]}, "pa": {"en": ["Claw marks in the stone, higher than my head."], "pt": ["Marcas de garra na pedra, mais altas que a minha cabeça."]}, "pb": {"en": ["Good. I was afraid it would be a small one."], "pt": ["Que bom. Eu estava com medo de que fosse pequena."]}, "entr": {"en": ["This trail of blood leads into {lugar}. It looks as if someone dragged a whole ox in there."], "pt": ["Esse rastro de sangue entra em {lugar}. Parece que alguém arrastou um boi inteiro até aí."]}, "chave": {"en": ["You find a fresh carcass, still warm. {vilao} knows you are here, and now the hunt runs both ways."], "pt": ["Vocês acham uma carcaça fresca, ainda quente. {vilao} sabe que vocês estão aqui, e agora a caçada corre nos dois sentidos."]}, "chc": {"en": ["You find a fresh carcass, still warm. It is the latest kill of the beast from the notice, and from the marks it left here a short while ago. {vilao} knows you are here, and now the hunt runs both ways."], "pt": ["Vocês acham uma carcaça fresca, ainda quente. É a presa mais recente da fera do aviso, e pelas marcas ela saiu daqui há pouco. {vilao} sabe que vocês estão aqui, e agora a caçada corre nos dois sentidos."]}, "chs": {"en": ["You find a fresh carcass, still warm. The claw marks are the same as those on the stone by the road, and the tracks that brought you here were its own. {vilao} knows you are here, and now the hunt runs both ways."], "pt": ["Vocês acham uma carcaça fresca, ainda quente. As marcas de garra são as mesmas da pedra na estrada, e eram dela os rastros que trouxeram vocês até aqui. {vilao} sabe que vocês estão aqui, e agora a caçada corre nos dois sentidos."]}, "elos": [{"t": "h", "txt": {"en": ["These tracks belong to the beast from the notice. Look at the size: a head would fit inside each footprint."], "pt": ["Esses rastros são da fera do aviso. Olhem o tamanho: cabe uma cabeça dentro de cada pegada."]}}, {"t": "n", "txt": {"en": ["At the entrance lies a wooden bucket, crushed as if something had bitten it."], "pt": ["Na entrada, há um balde de madeira caído, amassado como se alguém o tivesse mordido."]}}, {"t": "n", "txt": {"en": ["From inside comes a long growl, and then the sound of bones being gnawed."], "pt": ["Lá de dentro vem um rosnado longo, e depois o barulho de ossos sendo roídos."]}}]}, "cacada/cacadores": {"tit": {"en": ["The Hunters Who Did Not Return", "The Last Trap", "After {vilao}"], "pt": ["Os Caçadores que Não Voltaram", "A Última Armadilha", "Atrás de {vilao}"]}, "aviso": {"en": ["Help {povoado}. The hunters went after the beast of {lugar}, and {desde} no one has had word of them.", "Please find our hunters. They went into {lugar} after a beast, and only one of their dogs came back, wounded.", "{povoado} needs help. We sent our best hunters against the beast of {lugar}, and now not even the hunters come back."], "pt": ["Ajudem {povoado}. Os caçadores foram atrás da fera de {lugar}, e {desde} ninguém tem notícia deles.", "Por favor, achem os nossos caçadores. Eles entraram em {lugar} atrás de uma fera, e só voltou o cachorro de um deles, ferido.", "{povoado} precisa de ajuda. Mandamos os melhores caçadores contra a fera de {lugar}, e agora nem os caçadores voltam."]}, "abert": {"en": ["The heroes follow the hunters' tracks to {lugar}. Beside them run much larger tracks."], "pt": ["Os heróis seguem os rastros dos caçadores até {lugar}. Ao lado deles, há rastros muito maiores."]}, "fala": {"en": ["We set the traps as we always do, but the beast sprang every one of them, one by one, and then came after us. Its name is {vilao}. It does not eat hunters on the spot: it carries them to its den, deep inside. There may still be someone alive."], "pt": ["Armamos as armadilhas como sempre, mas a fera desarmou todas, uma por uma, e depois veio atrás de nós. O nome dela é {vilao}. Ela não come os caçadores na hora: leva para a toca, lá no fundo. Pode ser que ainda tenha alguém vivo."]}, "pista": {"nome": {"en": "A sprung trap", "pt": "Uma armadilha desarmada"}, "olhar": {"en": "An iron trap, open and clean, with the bait untouched.", "pt": "Uma armadilha de ferro, aberta e limpa, com a isca intacta."}, "revela": {"en": "An iron trap lies near the entrance.", "pt": "Há uma armadilha de ferro perto da entrada."}, "texto": {"en": ["The trap was sprung with care, and the bait was not even touched. You can tell the beast understands traps: there are three more ahead, all sprung the same way. On the tree trunk beside it, a hunter drove in his knife and scratched a name, the one they give the beast in {povoado}: {vilao}."], "pt": ["A armadilha foi desarmada com cuidado, e a isca nem foi tocada. Vocês percebem que a fera entende de armadilhas, porque há outras três adiante, todas desarmadas do mesmo jeito. No tronco ao lado, um caçador cravou a faca e riscou um nome, o que dão à fera em {povoado}: {vilao}."]}}, "ultima": {"en": ["Broken hunting weapons are scattered across the floor, and at the back of the den {vilao} waits, eyes open."], "pt": ["Há armas de caçador quebradas espalhadas pelo chão, e no fundo da toca {vilao} espera, de olhos abertos."]}, "narr": {"en": ["As you come in, {vilao} nudges a broken bow toward you with its snout."], "pt": ["Quando vocês entram, {vilao} empurra com o focinho um arco quebrado na direção de vocês."]}, "vil": {"en": ["(A low growl, almost a laugh.)"], "pt": ["(Um rosnado baixo, quase uma risada.)"]}, "hc": {"en": ["No traps this time. Just us."], "pt": ["Esta vez não tem armadilha. Só a gente."]}, "hs": {"en": ["It has been waiting for us."], "pt": ["Ela está nos esperando."]}, "fim": {"en": ["{vilao} falls, and at the back of the den you find two hunters, wounded but alive, hidden behind the rocks."], "pt": ["{vilao} cai, e no fundo da toca vocês acham dois caçadores feridos, mas vivos, escondidos atrás das pedras."]}, "fecho": {"en": ["In {povoado}, the hunters tell the story all night long, and each time the beast gets bigger."], "pt": ["Em {povoado}, os caçadores contam a história a noite inteira, e a cada vez a fera fica maior."]}, "pa": {"en": ["An arrow stuck in the tree, high up."], "pt": ["Uma flecha cravada na árvore, bem alta."]}, "pb": {"en": ["They shot at something big. And missed."], "pt": ["Atiraram em alguma coisa grande. E erraram."]}, "entr": {"en": ["These hunters' tracks lead into {lugar}, and beside them run much larger tracks. Do you see them?"], "pt": ["Esses rastros de caçador entram em {lugar}, e ao lado tem rastros muito maiores. Estão vendo?"]}, "chave": {"en": ["You find a dead hunter, his bow still in his hand. The tracks around him show that the beast circled the body several times, as if waiting for someone to come and fetch it."], "pt": ["Vocês acham um caçador morto, com o arco ainda na mão. Os rastros em volta mostram que a fera rodeou o corpo várias vezes, como quem espera alguém vir buscá-lo."]}, "chc": {"en": ["You find a dead hunter, his bow still in his hand. He is one of the hunters of {povoado}. The tracks around him show that the beast circled the body several times, as if waiting for someone to come and fetch it."], "pt": ["Vocês acham um caçador morto, com o arco ainda na mão. É um dos caçadores de {povoado}. Os rastros em volta mostram que a fera rodeou o corpo várias vezes, como quem espera alguém vir buscá-lo."]}, "chs": {"en": ["You find a dead hunter, his bow still in his hand. The arrow stuck in the tree by the road was his. The tracks around him show that the beast circled the body several times, as if waiting for someone to come and fetch it."], "pt": ["Vocês acham um caçador morto, com o arco ainda na mão. A flecha cravada na árvore da estrada era dele. Os rastros em volta mostram que a fera rodeou o corpo várias vezes, como quem espera alguém vir buscá-lo."]}, "elos": [{"t": "n", "txt": {"en": ["Stuck in the tree at the entrance is an arrow with a cloth tied to it, the sign the hunters of {povoado} use to show they have gone in."], "pt": ["Cravada na árvore da entrada, há uma flecha com um pano amarrado, o sinal que os caçadores de {povoado} usam para avisar que entraram."]}}, {"t": "h", "txt": {"en": ["A broken arrow, fletched in the manner of the hunters of {povoado}. They shot, and the beast kept coming."], "pt": ["Uma flecha quebrada, com as penas dos caçadores de {povoado}. Eles atiraram, e a fera seguiu em frente."]}}]}, "cacada/inverno": {"tit": {"en": ["The Winter Beast", "Before the Snow", "The Hunger of {vilao}"], "pt": ["A Fera do Inverno", "Antes da Neve", "A Fome de {vilao}"]}, "aviso": {"en": ["Help {povoado}. With the cold, the beast of {lugar} has lost its fear and now comes into the village at night. {gente} {gentefaz}.", "Please hunt the beast down before the snow. {desde} it has been coming down from {lugar} to the houses of {povoado}, and it has already broken into two pens.", "{povoado} needs hunters {ate}. The beast of {lugar} is hungry, and every night it comes closer to the houses."], "pt": ["Ajudem {povoado}. Com o frio, a fera de {lugar} perdeu o medo e agora entra na vila à noite. {gente} {gentefaz}.", "Por favor, cacem a fera antes da neve. {desde} ela desce de {lugar} até as casas de {povoado}, e já arrombou dois currais.", "{povoado} precisa de caçadores {ate}. A fera de {lugar} está com fome, e cada noite chega mais perto das casas."]}, "abert": {"en": ["The heroes follow the beast's footprints from the houses of {povoado} to {lugar}."], "pt": ["Os heróis seguem as pegadas da fera das casas de {povoado} até {lugar}."]}, "fala": {"en": ["The beast is called {vilao}, and the cold has made it hungry. It used to stay here, deep inside, but now it goes out every night. If winter comes and it is still alive, it will be one house a night."], "pt": ["A fera se chama {vilao}, e o frio a deixou com fome. Antes ela ficava aqui no fundo, mas agora sai toda noite. Se o inverno chegar e ela continuar viva, vai ser uma casa por noite."]}, "pista": {"nome": {"en": "A broken pen", "pt": "Um curral arrombado"}, "olhar": {"en": "The gate of a cattle pen, torn off and dragged all the way here.", "pt": "Uma porteira de curral, arrancada e arrastada até aqui."}, "revela": {"en": "A broken gate lies near the entrance.", "pt": "Há uma porteira quebrada perto da entrada."}, "texto": {"en": ["The gate came from a pen in {povoado}, and you can tell the beast dragged it here out of rage: there is no meat anywhere near, only splinters of bitten wood. Scratched on the gate, someone has written the name they give the creature: {vilao}."], "pt": ["A porteira veio de um curral de {povoado}, e vocês percebem que a fera a arrastou até aqui de raiva, porque não há carne nenhuma por perto, só lascas de madeira mordida. Riscado na porteira, alguém escreveu o nome que dão ao bicho: {vilao}."]}}, "ultima": {"en": ["{vilao} lies at the back of the den, surrounded by the bones of oxen and goats."], "pt": ["{vilao} está deitad⟨vilao:o|a⟩ no fundo da toca, cercada de ossos de bois e cabras."]}, "narr": {"en": ["As you come in, {vilao} rises and sniffs the air, as if recognizing the scent of {povoado}."], "pt": ["Quando vocês entram, {vilao} se levanta e fareja o ar, como quem reconhece o cheiro de {povoado}."]}, "vil": {"en": ["(A growl, and the beast's breath turns to mist in the cold.)"], "pt": ["(Um rosnado, e o hálito da fera vira fumaça no frio.)"]}, "hc": {"en": ["{povoado} will spend this winter in peace."], "pt": ["{povoado} vai passar este inverno em paz."]}, "hs": {"en": ["Today it eats out of our hand."], "pt": ["Hoje ela come na nossa mão."]}, "fim": {"en": ["{vilao} falls, and its warm breath slowly fades into the cold air of the den."], "pt": ["{vilao} cai, e o hálito quente d⟨vilao:ele|ela⟩ some aos poucos no ar frio da toca."]}, "fecho": {"en": ["In {povoado}, the pens are mended, and for the first time this winter the children play in the street after dark."], "pt": ["Em {povoado}, os currais são consertados, e pela primeira vez no inverno as crianças brincam na rua depois do escurecer."]}, "pa": {"en": ["Footprints in the mud, heading for the houses."], "pt": ["Pegadas na lama, indo para as casas."]}, "pb": {"en": ["And coming back. It comes and goes as if it owned the place."], "pt": ["E voltando. Ela vem e vai como se fosse dona do lugar."]}, "entr": {"en": ["The beast's footprints lead back to {lugar}. There is even a gate dragged up to the entrance here."], "pt": ["As pegadas da fera voltam para {lugar}. Tem até uma porteira arrastada aqui na entrada."]}, "chave": {"en": ["A howl echoes from deep inside, followed by the sound of something large running. It seems {vilao} is setting out to hunt, and its path runs straight through you."], "pt": ["Um uivo ecoa lá do fundo, e logo depois vem o barulho de algo grande correndo. Parece que {vilao} está saindo para caçar, e o caminho d⟨vilao:ele|ela⟩ passa por vocês."]}, "chc": {"en": ["A howl echoes from deep inside, followed by the sound of something large running. It seems {vilao} is setting out to hunt, and its path runs straight through you. It is the same beast that comes into {povoado} at night."], "pt": ["Um uivo ecoa lá do fundo, e logo depois vem o barulho de algo grande correndo. Parece que {vilao} está saindo para caçar, e o caminho d⟨vilao:ele|ela⟩ passa por vocês. É a mesma fera que entra em {povoado} à noite."]}, "chs": {"en": ["A howl echoes from deep inside, followed by the sound of something large running. It seems {vilao} is setting out to hunt, and its path runs straight through you. The footprints in the mud, on the road, were its own."], "pt": ["Um uivo ecoa lá do fundo, e logo depois vem o barulho de algo grande correndo. Parece que {vilao} está saindo para caçar, e o caminho d⟨vilao:ele|ela⟩ passa por vocês. As pegadas na lama, na estrada, eram dela."]}, "elos": [{"t": "h", "txt": {"en": ["The footprints that come from {povoado} end here. This is the den of the beast from the notice."], "pt": ["As pegadas que vêm de {povoado} terminam aqui. É a toca da fera do aviso."]}}, {"t": "n", "txt": {"en": ["At the entrance lies the gate of a cattle pen, torn off and dragged all the way here, with tooth marks in the wood."], "pt": ["Na entrada, há uma porteira de curral arrancada e arrastada até aqui, com marcas de dente na madeira."]}}]}, "investigacao": {"tit": {"en": ["The Road of Portraits", "The Silence of {lugar}", "Who Pays the Garrison"], "pt": ["A Estrada dos Retratos", "O Silêncio de {lugar}", "Quem Paga a Guarnição"]}, "aviso": {"en": ["Help us find out what is happening on the road to {lugar}. {desde}, eleven travelers have taken that road and never arrived, and the families of {povoado} hang their portraits on the posts.", "Please find out where the travelers who pass through {lugar} end up. The garrison that should be guarding the road says it has seen nothing.", "{povoado} needs answers. People who take the road to {lugar} vanish without a trace, and meanwhile the soldiers of the garrison play dice."], "pt": ["Ajudem a descobrir o que acontece na estrada de {lugar}. {desde}, onze viajantes pegaram a estrada e nunca chegaram, e as famílias de {povoado} penduram os retratos deles nos postes.", "Por favor, descubram para onde vão os viajantes que passam por {lugar}. A guarnição que devia proteger a estrada diz que não viu nada.", "{povoado} precisa de respostas. Gente que pega a estrada de {lugar} some sem deixar rastro, e os soldados da guarnição jogam dados enquanto isso."]}, "abert": {"en": ["The heroes follow the road of portraits to {lugar}. The garrison stands at the roadside, and the soldiers look away as they pass."], "pt": ["Os heróis seguem a estrada dos retratos até {lugar}. A guarnição fica na beira do caminho, e os soldados viram o rosto quando eles passam."]}, "fala": {"en": ["The garrison shrugs because someone pays it to. They say it is {vilao}, and that whoever asks too many questions becomes one more portrait on the road. I asked. That is why I came here to hide."], "pt": ["A guarnição dá de ombros porque alguém paga para isso. Dizem que é {vilao}, e que quem pergunta demais vira mais um retrato na estrada. Eu perguntei. Por isso vim me esconder aqui."]}, "pista": {"nome": {"en": "An abandoned pack", "pt": "Uma mochila abandonada"}, "olhar": {"en": "A traveler's pack, dropped and never picked up.", "pt": "A mochila de um viajante, largada e nunca recolhida."}, "revela": {"en": "A pack has been left near the entrance.", "pt": "Há uma mochila largada perto da entrada."}, "texto": {"en": ["In the pack is a letter addressed to {povoado}. Whoever wrote it never sent it, and it stops in the middle of a sentence: “The soldiers told me to go on through {lugar}, and said that a man of {vilao} would guide me to the other side.”"], "pt": ["Na mochila há uma carta endereçada a {povoado}. Quem a escreveu nunca a enviou, e ela para no meio de uma frase: «Os soldados me mandaram seguir por dentro de {lugar}, e disseram que um homem de {vilao} vai me guiar até o outro lado.»"]}}, "ultima": {"en": ["There are tables covered with belongings sorted into piles, each with a tag, and behind them {vilao} is doing sums."], "pt": ["Há mesas cheias de pertences separados em pilhas, com etiquetas, e atrás delas {vilao} faz contas."]}, "narr": {"en": ["As you come in, {vilao} closes the account book without hurry."], "pt": ["Quando vocês entram, {vilao} fecha o livro de contas sem pressa."]}, "vil": {"en": ["More travelers. Sit down. I already have tags for you."], "pt": ["Mais viajantes. Sentem-se. Já tenho etiqueta para vocês."]}, "hc": {"en": ["We came for the tags of every one of them."], "pt": ["Viemos buscar as etiquetas de todos eles."]}, "hs": {"en": ["Today, the one who loses a tag is you."], "pt": ["Hoje, quem perde a etiqueta é você."]}, "fim": {"en": ["In the last room, the belongings of the missing wait in piles, each with a tag and a name. It is a hard answer, but it is an answer."], "pt": ["Na última sala, os pertences dos desaparecidos esperam em pilhas, cada um com uma etiqueta e um nome. A resposta é dura, mas é uma resposta."]}, "fecho": {"en": ["In {povoado}, the families take the portraits down from the posts, one by one. At the garrison, the dice disappear from the table."], "pt": ["Em {povoado}, as famílias tiram os retratos dos postes, um a um. Na guarnição, os dados somem da mesa."]}, "pa": {"en": ["A boot at the side of the road. Just one."], "pt": ["Uma bota na beira da estrada. Uma só."]}, "pb": {"en": ["That is the third ownerless thing we have found today."], "pt": ["É a terceira coisa sem dono que achamos hoje."]}, "entr": {"en": ["Did you notice how the soldiers of that garrison looked away as we passed? The entrance of {lugar} is just ahead."], "pt": ["Repararam que os soldados daquela guarnição viraram o rosto quando passamos? A entrada de {lugar} fica logo adiante."]}, "chave": {"en": ["Behind the door is a pile of boots, coats and rings, carefully sorted. The missing came through here, and someone did the sums."], "pt": ["Atrás da porta há uma pilha de botas, casacos e anéis, separados com cuidado. Os desaparecidos passaram por aqui, e alguém fez as contas."]}, "chc": {"en": ["Behind the door is a pile of boots, coats and rings, carefully sorted. These are the belongings of the travelers in the portraits. The missing came through here, and someone did the sums."], "pt": ["Atrás da porta há uma pilha de botas, casacos e anéis, separados com cuidado. São as coisas dos viajantes dos retratos. Os desaparecidos passaram por aqui, e alguém fez as contas."]}, "chs": {"en": ["Behind the door is a pile of boots, coats and rings, carefully sorted. Among them is the mate of the boot you found on the road. The missing came through here, and someone did the sums."], "pt": ["Atrás da porta há uma pilha de botas, casacos e anéis, separados com cuidado. Entre elas, está o par da bota que vocês acharam na estrada. Os desaparecidos passaram por aqui, e alguém fez as contas."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance, fixed to a stone, is one more portrait, just like those on the posts of {povoado}. Someone brought it all the way here."], "pt": ["Na entrada, preso a uma pedra, há mais um retrato, igual aos dos postes de {povoado}. Alguém o trouxe até aqui."]}}, {"t": "h", "txt": {"en": ["This is the road of portraits from the notice. One of them is nailed up here, and the face has been slashed with a knife."], "pt": ["Este é o caminho dos retratos do aviso. Um deles está pregado aqui, e o rosto foi riscado com uma faca."]}}, {"t": "n", "txt": {"en": ["Scratched on the wall at the entrance is a list of names, and the last one is only half written, as if the writer had been interrupted."], "pt": ["Riscado na parede da entrada, há uma lista de nomes, e o último está pela metade, como se quem escrevia tivesse sido interrompido."]}}]}, "investigacao/traidor": {"tit": {"en": ["Sold from Within", "One of the Seven", "The Gold of {vilao}"], "pt": ["Vendidos por Dentro", "Um dos Sete", "O Ouro de {vilao}"]}, "aviso": {"en": ["Help {povoado}. The attacks always fall where the guard is weakest, at the exact hour the watch changes. Only the seven members of the council know the watches, and one of them is selling the town.", "We ask for the help of outsiders, people no one here knows. Someone on the council of {povoado} is selling the watches of the guard, and the trail of the gold leads to {lugar}.", "{povoado} has been betrayed from within. {desde}, every attack has known where the guard is weakest, and only seven people knew that."], "pt": ["Ajudem {povoado}. Os ataques caem sempre onde a guarda está mais fraca, na hora exata da troca de turno. Só os sete do conselho conhecem os turnos, e um deles está vendendo a cidade.", "Pedimos a ajuda de gente de fora, que ninguém aqui conheça. Alguém do conselho de {povoado} vende os turnos da guarda, e os rastros do ouro levam a {lugar}.", "{povoado} foi traída por dentro. {desde}, cada ataque sabe onde a guarda está mais fraca, e só sete pessoas sabiam disso."]}, "abert": {"en": ["The heroes follow the rumors about the traitor's gold to {lugar}."], "pt": ["Os heróis seguem os boatos sobre o ouro do traidor até {lugar}."]}, "fala": {"en": ["I saw the gold change hands. One of the seven on the council is selling the watches of the guard, and the buyer is {vilao}, who has promised to spare the traitor's house when the town falls. Follow the gold, and the name will turn up at the end."], "pt": ["Eu vi o ouro trocar de mão. Um dos sete do conselho vende os turnos da guarda, e quem compra é {vilao}, que prometeu poupar a casa do traidor quando a cidade cair. Sigam o ouro, que o nome aparece no fim."]}, "pista": {"nome": {"en": "A sealed letter", "pt": "Uma carta lacrada"}, "olhar": {"en": "A letter bearing the seal of the council, lying on the floor.", "pt": "Uma carta com o selo do conselho, caída no chão."}, "revela": {"en": "A letter lies near the entrance.", "pt": "Há uma carta caída perto da entrada."}, "texto": {"en": ["The sealed letter bears the seal of the council of {povoado}, and inside is the list of tomorrow's watches. Whoever was to deliver it dropped everything and fled in a hurry. On the outside is the name of the one who was to receive it, written carefully so as to make no mistake: {vilao}."], "pt": ["A carta lacrada traz o selo do conselho de {povoado}, e dentro está a lista dos turnos de amanhã. Quem ia entregá-la largou tudo e fugiu às pressas. Por fora, o endereço de quem devia recebê-la, escrito com cuidado para não errar: {vilao}."]}}, "ultima": {"en": ["On a table lie maps of {povoado} covered in notes, and {vilao} is checking the watches, candle in hand."], "pt": ["Sobre uma mesa há mapas de {povoado} cheios de anotações, e {vilao} confere os turnos com uma vela na mão."]}, "narr": {"en": ["As you come in, {vilao} is burning the corner of a paper in the candle flame."], "pt": ["Quando vocês entram, {vilao} queima o canto de um papel na vela."]}, "vil": {"en": ["You are too late. The name you are looking for is already ash."], "pt": ["Vocês chegaram tarde. O nome que procuram já virou cinza."]}, "hc": {"en": ["The guard of {povoado} will enjoy reading your copy."], "pt": ["A guarda de {povoado} vai gostar de ler a sua cópia."]}, "hs": {"en": ["Then we will take you in the traitor's place."], "pt": ["Então vamos levar você no lugar dele."]}, "fim": {"en": ["Among the papers that are left is a letter with the traitor's name and the seal of the council. Now there is no doubt."], "pt": ["Entre os papéis que sobraram, há uma carta com o nome do traidor e o selo do conselho. Agora não há dúvida."]}, "fecho": {"en": ["In {povoado}, the traitor stands trial before the other six, and at the council table one chair is left empty."], "pt": ["Em {povoado}, o traidor vai a julgamento diante dos outros seis, e na mesa do conselho sobra uma cadeira vazia."]}, "pa": {"en": ["A broken wax seal. This belongs to the council."], "pt": ["Selo de cera quebrado. Isto aqui é do conselho."]}, "pb": {"en": ["And what is a council letter doing in a place like this?"], "pt": ["E o que uma carta do conselho faz num lugar destes?"]}, "entr": {"en": ["I found a broken wax seal here at the entrance of {lugar}. It is the crest of {povoado}."], "pt": ["Achei um selo de cera quebrado aqui na entrada de {lugar}. É o brasão de {povoado}."]}, "chave": {"en": ["You find a list of tomorrow's watches of the guard, carefully copied out. It looks as if the next attack already has its hour set."], "pt": ["Vocês acham uma lista com os turnos da guarda de amanhã, copiada com cuidado. Parece que o próximo ataque já tem hora marcada."]}, "chc": {"en": ["You find a list of tomorrow's watches of the guard, carefully copied out. It looks as if the next attack already has its hour set. Only someone on the council knows these watches."], "pt": ["Vocês acham uma lista com os turnos da guarda de amanhã, copiada com cuidado. Parece que o próximo ataque já tem hora marcada. Só alguém do conselho conhece esses turnos."]}, "chs": {"en": ["You find a list of tomorrow's watches of the guard, carefully copied out. It looks as if the next attack already has its hour set. The handwriting is the same as on the council letter you found on the road."], "pt": ["Vocês acham uma lista com os turnos da guarda de amanhã, copiada com cuidado. Parece que o próximo ataque já tem hora marcada. A letra é a mesma da carta do conselho que vocês acharam na estrada."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance lies a broken wax seal, with the crest of the council of {povoado}."], "pt": ["Na entrada, há um selo de cera quebrado, com o brasão do conselho de {povoado}."]}}, {"t": "h", "txt": {"en": ["New coins on the ground, and from far away. The trail of gold the notice spoke of runs through here."], "pt": ["Moedas novas no chão, e de longe. Os rastros do ouro de que o aviso falava passam por aqui."]}}]}, "investigacao/pedagio": {"tit": {"en": ["The Toll of {vilao}", "Pay or Vanish", "The Bridge of {povoado}"], "pt": ["O Pedágio de {vilao}", "Pague ou Suma", "A Ponte de {povoado}"]}, "aviso": {"en": ["Help {povoado}. On the bridge near {lugar}, armed men are charging a toll that no lord ever authorized. Those who pay may cross, and those who argue vanish, cart and all.", "Please open the bridge at {lugar} {ate}. Whoever crosses there pays a toll that belongs to no lord, and whoever complains about the price never reaches the other side.", "{povoado} needs help. {desde}, the bridge near {lugar} has had a new master, and the drovers who argued over the price have vanished."], "pt": ["Ajudem {povoado}. Na ponte perto de {lugar}, homens armados cobram um pedágio que nenhum senhor autorizou. Quem paga atravessa, e quem discute some com carroça e tudo.", "Por favor, abram a ponte de {lugar} {ate}. Quem passa por ali paga um pedágio sem dono, e quem reclama do preço não chega ao outro lado.", "{povoado} precisa de ajuda. {desde}, a ponte perto de {lugar} tem dono, e os tropeiros que discutiram o preço sumiram."]}, "abert": {"en": ["The heroes follow the bridge road, which turns off toward {lugar}. There are cart tracks going in, and none coming out."], "pt": ["Os heróis seguem a estrada da ponte, que desvia para {lugar}. Há marcas de carroça entrando, e nenhuma saindo."]}, "fala": {"en": ["The old bridge keeper is buried underneath it. Now the one collecting is {vilao}, and whoever complains about the price becomes cargo. They take everything inside: the carts, the mules and the people, and not always in that order."], "pt": ["O antigo guarda da ponte está enterrado embaixo dela. Agora quem cobra é {vilao}, e quem reclama do preço vira carga. Levam tudo para dentro: as carroças, as mulas e as pessoas, e nem sempre nessa ordem."]}, "pista": {"nome": {"en": "A toll receipt", "pt": "Um recibo de pedágio"}, "olhar": {"en": "A crumpled receipt, with a strange stamp on it.", "pt": "Um recibo amassado, com um carimbo estranho."}, "revela": {"en": "A crumpled paper lies near the entrance.", "pt": "Há um papel amassado perto da entrada."}, "texto": {"en": ["The receipt carries a stamp that no lord of the region uses: that of {vilao}. On the back, someone wrote in anger, pressing the quill so hard it tore the paper: “I paid and they locked me up all the same.”"], "pt": ["O recibo tem um carimbo que nenhum senhor da região usa: o de {vilao}. No verso, alguém escreveu com raiva, apertando tanto a pena que rasgou o papel: «Paguei e mesmo assim me prenderam.»"]}}, "ultima": {"en": ["On a table sits a heavy strongbox, and {vilao} is counting the toll coins."], "pt": ["Sobre uma mesa há um cofre pesado, e {vilao} conta as moedas do pedágio."]}, "narr": {"en": ["As you come in, {vilao} closes the strongbox and rests a hand on top of it."], "pt": ["Quando vocês entram, {vilao} fecha o cofre e pousa a mão em cima dele."]}, "vil": {"en": ["Three coins a head to cross. To leave this place, the price is different."], "pt": ["Três moedas por cabeça para atravessar. Para sair daqui, o preço é outro."]}, "hc": {"en": ["The drovers of {povoado} are settling the bill. All at once."], "pt": ["Os tropeiros de {povoado} pagam a conta. Em uma moeda só."]}, "hs": {"en": ["Today the bridge is free."], "pt": ["Hoje a ponte é de graça."]}, "fim": {"en": ["The strongbox is there, heavy with the coins of people who only wanted to cross. Beside it are the missing carters, thin and alive."], "pt": ["O cofre está lá, pesado de moedas de gente que só queria atravessar. Junto dele, os carroceiros sumidos, magros e vivos."]}, "fecho": {"en": ["On the bridge, the drovers of {povoado} cross singing, and one of the freed carters is already arguing over how to share out the strongbox."], "pt": ["Na ponte, os tropeiros de {povoado} passam cantando, e um dos carroceiros soltos já discute a partilha do cofre."]}, "pa": {"en": ["Cart tracks. All going in."], "pt": ["Rastros de carroça. Todos entrando."]}, "pb": {"en": ["And none coming out. What kind of road is this?"], "pt": ["E nenhum saindo. Que tipo de estrada é essa?"]}, "entr": {"en": ["The cart tracks lead into {lugar}. Did you read the sign beside the door? “Toll. Three coins.”"], "pt": ["Os rastros de carroça entram em {lugar}. Vocês leram a placa ao lado da porta? «Pedágio. Três moedas.»"]}, "chave": {"en": ["You find a pile of cart wheels, taken apart and numbered. It seems that whoever did not pay the toll was turned into spare parts."], "pt": ["Vocês encontram uma pilha de rodas de carroça, desmontadas e numeradas. Parece que quem não pagou o pedágio virou peça."]}, "chc": {"en": ["You find a pile of cart wheels, taken apart and numbered. It seems that whoever did not pay the toll was turned into spare parts. These are the carts of those who argued at the bridge."], "pt": ["Vocês encontram uma pilha de rodas de carroça, desmontadas e numeradas. Parece que quem não pagou o pedágio virou peça. São as carroças de quem discutiu na ponte."]}, "chs": {"en": ["You find a pile of cart wheels, taken apart and numbered. It seems that whoever did not pay the toll was turned into spare parts. The tracks on the road, all going in, were left by these carts."], "pt": ["Vocês encontram uma pilha de rodas de carroça, desmontadas e numeradas. Parece que quem não pagou o pedágio virou peça. Eram destas carroças os rastros da estrada, todos entrando."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance, a wooden sign is nailed up crooked: “Toll. Three coins.” Underneath, someone has scratched: “Do not pay.”"], "pt": ["Na entrada, há uma placa de madeira pregada torta: «Pedágio. Três moedas.» Embaixo, alguém riscou: «Não paguem.»"]}}, {"t": "h", "txt": {"en": ["Look at the sign: “Toll. Three coins.” This is the toll the notice spoke of."], "pt": ["Olhem a placa: «Pedágio. Três moedas.» É o pedágio de que o aviso falava."]}}]}, "fuga": {"tit": {"en": ["The Falling Halls", "Before the Dust Settles", "The Depths of {lugar}"], "pt": ["Os Salões que Caem", "Antes que a Poeira Assente", "O Fundo de {lugar}"]}, "aviso": {"en": ["Help {povoado}. Something is moving under {lugar}, and those who went down to look never came back. That makes four so far.", "Please find out what lies under {lugar}. {desde}, the ground of {povoado} has been shaking at night, and the four who went down to look have vanished.", "{povoado} needs brave people. The ground has been shaking {desde}, and the shaking comes from {lugar}."], "pt": ["Ajudem {povoado}. Algo se mexe embaixo de {lugar}, e quem desceu para ver nunca voltou. Já foram quatro.", "Por favor, descubram o que há embaixo de {lugar}. {desde}, o chão de {povoado} treme à noite, e os quatro que desceram para ver sumiram.", "{povoado} precisa de gente corajosa. O chão treme {desde}, e o tremor vem de {lugar}."]}, "abert": {"en": ["The heroes go down into {lugar}, and down there the ground shakes for the first time."], "pt": ["Os heróis descem a {lugar}, e lá embaixo o chão treme pela primeira vez."]}, "fala": {"en": ["Earthquake, my foot. {vilao} woke something in the deep galleries, and it is on its way up. This whole place is going to collapse. There is only one way out, at the far end. Run, and I will be right behind you!"], "pt": ["Terremoto coisa nenhuma. {vilao} acordou alguma coisa nas galerias fundas, e ela está subindo. Este lugar inteiro vai desabar. Só existe uma saída, lá no extremo. Corram, que eu corro atrás!"]}, "pista": {"nome": {"en": "A fresh crack", "pt": "Uma rachadura recente"}, "olhar": {"en": "A crack climbs the wall, wider with every minute.", "pt": "Uma rachadura sobe pela parede, mais larga a cada minuto."}, "revela": {"en": "There is a deep crack in a wall near the entrance.", "pt": "Há uma rachadura funda numa parede perto da entrada."}, "texto": {"en": ["The crack widens as you watch, and dust rises through it instead of falling: something is pushing from below. Beside it, scratched on the wall by one of those who went down before, is a warning: “{vilao} woke what was sleeping. The way out is at the end. Do not turn back.”"], "pt": ["A rachadura alarga enquanto vocês olham, e a poeira sobe por ela em vez de cair: algo empurra lá de baixo. Ao lado, riscado na parede por um dos que desceram antes, há um aviso: «{vilao} acordou o que dormia. A saída é no fim. Não voltem.»"]}}, "ultima": {"en": ["Daylight comes in at the end of the corridor, and in front of it stands {vilao}."], "pt": ["A luz do dia entra pelo fim do corredor, e na frente dela está {vilao}."]}, "narr": {"en": ["The ceiling groans above you as {vilao} raises both arms."], "pt": ["O teto range sobre vocês quando {vilao} levanta os braços."]}, "vil": {"en": ["No one leaves. No one ever leaves."], "pt": ["Ninguém sai. Ninguém nunca sai."]}, "hc": {"en": ["In {povoado}, they will want to hear otherwise."], "pt": ["Em {povoado} vão querer ouvir o contrário."]}, "hs": {"en": ["Today someone does."], "pt": ["Hoje sai."]}, "fim": {"en": ["You tumble out into the light, and behind you {lugar} collapses in a cloud of dust. For a good while, no one says anything. Then someone starts to laugh."], "pt": ["Vocês saem rolando para a luz, e atrás de vocês {lugar} desaba numa nuvem de pó. Por um bom tempo, ninguém diz nada. Depois, alguém começa a rir."]}, "fecho": {"en": ["In {povoado}, the ground stops shaking, and those who had left their homes in fear sleep in their own beds again."], "pt": ["Em {povoado}, o chão para de tremer, e quem tinha saído de casa com medo volta a dormir na própria cama."]}, "pa": {"en": ["Did the ground just shake?"], "pt": ["O chão acabou de tremer?"]}, "pb": {"en": ["It did. And that was the second time."], "pt": ["Tremeu. E foi a segunda vez."]}, "entr": {"en": ["Did you feel the ground shake? A stone just fell from above, right at the entrance of {lugar}."], "pt": ["Sentiram o chão tremer? Uma pedra acabou de cair lá de cima, bem na entrada de {lugar}."]}, "chave": {"en": ["A crack runs across the ceiling, and the corridor you came through collapses. The only way now is forward."], "pt": ["Uma rachadura corre pelo teto, e o corredor por onde vocês vieram desaba. O único caminho agora é para frente."]}, "chc": {"en": ["A crack runs across the ceiling, and the corridor you came through collapses. The only way now is forward. Those who went down before you were trapped the same way."], "pt": ["Uma rachadura corre pelo teto, e o corredor por onde vocês vieram desaba. O único caminho agora é para frente. Quem desceu antes de vocês ficou preso do mesmo jeito."]}, "chs": {"en": ["A crack runs across the ceiling, and the corridor you came through collapses. The only way now is forward. The tremors on the road came from down here."], "pt": ["Uma rachadura corre pelo teto, e o corredor por onde vocês vieram desaba. O único caminho agora é para frente. Os tremores da estrada vinham daqui de baixo."]}, "elos": [{"t": "h", "txt": {"en": ["The shaking the notice spoke of comes from here. Did you feel it just now?"], "pt": ["O tremor de que o aviso falava vem daqui. Sentiram agora?"]}}, {"t": "n", "txt": {"en": ["At the entrance, a rope is tied to a rock and runs down into the dark. At the other end of the rope, no one answers."], "pt": ["Na entrada, há uma corda amarrada numa pedra, descendo para o escuro. Do outro lado da corda, ninguém responde."]}}, {"t": "n", "txt": {"en": ["From below comes a dull rumble, and a cloud of dust rises through the entrance."], "pt": ["Lá de baixo vem um estrondo surdo, e uma nuvem de poeira sobe pela entrada."]}}]}, "fuga/tesouro": {"tit": {"en": ["The Treasure of {lugar}", "Gold and Stone", "The Deep Gallery"], "pt": ["O Tesouro de {lugar}", "Ouro e Pedra", "A Galeria do Fundo"]}, "aviso": {"en": ["Help us get people out of {lugar}. A band of treasure hunters went down there, and {desde} the ground has been shaking.", "Please go to {lugar} before everything collapses. Those who went down after the gold disturbed what they should not have, and {povoado} feels the shaking every night.", "{povoado} asks for help. A treasure map of {lugar} made the rounds of the taverns, and now the ground shakes under the whole village."], "pt": ["Ajudem a tirar gente de {lugar}. Um bando de caçadores de tesouro desceu lá, e {desde} o chão treme.", "Por favor, vão até {lugar} antes que tudo desabe. Os que desceram atrás do ouro mexeram no que não deviam, e {povoado} sente o tremor toda noite.", "{povoado} pede ajuda. O mapa de um tesouro em {lugar} correu pelas tavernas, e agora o chão treme sob a vila inteira."]}, "abert": {"en": ["The heroes go down into {lugar}. There are abandoned pickaxes and coins scattered across the floor."], "pt": ["Os heróis descem a {lugar}. Há picaretas largadas e moedas espalhadas pelo chão."]}, "fala": {"en": ["We found the treasure, but {vilao} wanted more and broke the seal of the deep gallery. Ever since, everything shakes, and what was down there is on its way up. The others ran deeper in, after the gold. I ran this way. The way out is at the far end."], "pt": ["Achamos o tesouro, mas {vilao} quis mais e quebrou o selo da galeria do fundo. Desde então, tudo treme, e o que estava lá embaixo está subindo. Os outros correram para o fundo atrás do ouro. Eu corri para cá. A saída é no extremo."]}, "pista": {"nome": {"en": "An old coin", "pt": "Uma moeda antiga"}, "olhar": {"en": "An old gold coin, lying in the dust.", "pt": "Uma moeda de ouro antiga, caída no meio da poeira."}, "revela": {"en": "Something glints on the floor near the entrance.", "pt": "Algo brilha no chão perto da entrada."}, "texto": {"en": ["The coin is old, and it fell from a sack with a hole in it: others are scattered in a trail leading deep inside. Among them, someone dropped a treasure map, and on its edge is written who sold it in the taverns: {vilao}."], "pt": ["A moeda é antiga e caiu de um saco furado, porque há outras espalhadas numa trilha até o fundo. Junto delas, alguém deixou cair um mapa de tesouro, e na borda está escrito quem o vendeu nas tavernas: {vilao}."]}}, "ultima": {"en": ["Daylight comes in at the end of the corridor, and in front of it stands {vilao}, clutching a sack of gold."], "pt": ["A luz do dia entra pelo fim do corredor, e na frente dela está {vilao}, abraçad⟨vilao:o|a⟩ a um saco de ouro."]}, "narr": {"en": ["As you arrive, {vilao} hugs the sack of gold tighter."], "pt": ["Quando vocês chegam, {vilao} aperta o saco de ouro contra o peito."]}, "vil": {"en": ["The gold is mine. Get out of my way, or stay down here with me."], "pt": ["O ouro é meu. Saiam do caminho, ou fiquem aqui embaixo comigo."]}, "hc": {"en": ["Gold is no use to anyone under the ground."], "pt": ["Ouro não serve de nada embaixo da terra."]}, "hs": {"en": ["Drop the sack. Run."], "pt": ["Larga o saco. Corre."]}, "fim": {"en": ["You tumble out into the light, and behind you {lugar} collapses, taking the gold with it. Someone shakes the dust from a pocket, and a coin falls to the ground."], "pt": ["Vocês saem rolando para a luz, e atrás de vocês {lugar} desaba, levando o ouro junto. Alguém sacode a poeira do bolso, e uma moeda cai no chão."]}, "fecho": {"en": ["In {povoado}, the treasure map is burned in the square, and no one speaks of gold in {lugar} again."], "pt": ["Em {povoado}, o mapa do tesouro é queimado na praça, e ninguém mais fala de ouro em {lugar}."]}, "pa": {"en": ["A gold coin in the middle of the road."], "pt": ["Uma moeda de ouro no meio da estrada."]}, "pb": {"en": ["And another farther on. Someone is leaving a very expensive trail."], "pt": ["E outra adiante. Alguém está deixando um rastro bem caro."]}, "entr": {"en": ["There are coins scattered at the entrance of {lugar}, and the pickaxes were dropped in a hurry. Someone ran out of here."], "pt": ["Tem moedas espalhadas na entrada de {lugar}, e as picaretas foram largadas às pressas. Alguém saiu correndo daqui."]}, "chave": {"en": ["The ceiling groans, and a whole gallery collapses behind you, taking a pile of gold with it. The only way now is forward."], "pt": ["O teto range, e uma galeria inteira desaba atrás de vocês, levando junto uma pilha de ouro. O único caminho agora é para frente."]}, "chc": {"en": ["The ceiling groans, and a whole gallery collapses behind you, taking a pile of gold with it. The only way now is forward. The treasure hunters must be trapped farther on."], "pt": ["O teto range, e uma galeria inteira desaba atrás de vocês, levando junto uma pilha de ouro. O único caminho agora é para frente. Os caçadores de tesouro devem estar presos mais adiante."]}, "chs": {"en": ["The ceiling groans, and a whole gallery collapses behind you, taking a pile of gold with it. The only way now is forward. The coins on the road led here, and whoever lost them is trapped farther on."], "pt": ["O teto range, e uma galeria inteira desaba atrás de vocês, levando junto uma pilha de ouro. O único caminho agora é para frente. As moedas da estrada levavam até aqui, e quem as perdeu está preso mais adiante."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance lies a crumpled treasure map, just like the ones making the rounds of the taverns of {povoado}."], "pt": ["Na entrada, há um mapa de tesouro amassado, igual aos que correm pelas tavernas de {povoado}."]}}, {"t": "h", "txt": {"en": ["Coins on the ground, and abandoned pickaxes. The treasure hunters from the notice came through here, and left at a run."], "pt": ["Moedas no chão, e picaretas largadas. Os caçadores de tesouro do aviso passaram por aqui, e saíram correndo."]}}]}, "fuga/eco": {"tit": {"en": ["The Knocking of {lugar}", "Who Knocks Down Below", "The Echo from the Deep"], "pt": ["As Batidas de {lugar}", "Quem Bate Lá Embaixo", "O Eco do Fundo"]}, "aviso": {"en": ["Help {povoado}. {desde}, knocking has been heard from under {lugar}, always three knocks, always at midnight.", "Please find out who is knocking under {lugar}. The knocking wakes {povoado} every night, and those who went down to look did not come back.", "{povoado} needs help. The knocking under {lugar} grows louder every night, and now the walls of the houses are cracking."], "pt": ["Ajudem {povoado}. {desde}, ouvem-se batidas vindas de baixo de {lugar}, sempre três, sempre à meia-noite.", "Por favor, descubram quem bate embaixo de {lugar}. As batidas acordam {povoado} toda noite, e quem desceu para ver não voltou.", "{povoado} precisa de ajuda. As batidas embaixo de {lugar} ficam mais fortes a cada noite, e agora as paredes das casas racham."]}, "abert": {"en": ["The heroes go down into {lugar}. From deep below come three knocks, and the ground shakes at each one."], "pt": ["Os heróis descem a {lugar}. Lá do fundo vêm três batidas, e o chão treme a cada uma."]}, "fala": {"en": ["The knocking is {vilao}, down at the bottom, trying to open a door that has stayed shut for centuries. With every knock, a gallery falls. When the door opens, this whole place will collapse. The way out is at the far end."], "pt": ["As batidas são de {vilao}, lá no fundo, que tenta abrir uma porta que ficou fechada por séculos. A cada batida, uma galeria cai. Quando a porta abrir, este lugar inteiro desaba. A saída é no extremo."]}, "pista": {"nome": {"en": "An iron hammer", "pt": "Um martelo de ferro"}, "olhar": {"en": "A huge iron hammer, worn from so much pounding.", "pt": "Um martelo de ferro enorme, gasto de tanto bater."}, "revela": {"en": "A huge hammer has been left near the entrance.", "pt": "Há um martelo enorme largado perto da entrada."}, "texto": {"en": ["The hammer is too big for an ordinary person, and the handle is worn smooth with use. You can tell someone left it here and took a larger one: the mark on the floor shows it was dragged. Branded into the handle is the owner's name: {vilao}."], "pt": ["O martelo é grande demais para uma pessoa comum, e o cabo está gasto de tanto uso. Vocês percebem que alguém o largou aqui e pegou outro maior, porque a marca no chão mostra que ele foi arrastado. No cabo, gravado a ferro, o nome do dono: {vilao}."]}}, "ultima": {"en": ["Daylight comes in at the end of the corridor, and in front of it stands {vilao}, a huge hammer resting on one shoulder."], "pt": ["A luz do dia entra pelo fim do corredor, e na frente dela está {vilao}, com um martelo enorme no ombro."]}, "narr": {"en": ["As you arrive, {vilao} strikes the floor with the hammer three times, and the whole ceiling shudders."], "pt": ["Quando vocês chegam, {vilao} bate o martelo no chão três vezes, e o teto inteiro estremece."]}, "vil": {"en": ["Three knocks. Only the last one was missing."], "pt": ["Três batidas. Faltava só a última."]}, "hc": {"en": ["In {povoado}, they want to sleep tonight."], "pt": ["Em {povoado} querem dormir hoje."]}, "hs": {"en": ["Enough knocking."], "pt": ["Chega de bater."]}, "fim": {"en": ["You tumble out into the light, and behind you {lugar} collapses in a cloud of dust. Down below, the door stays shut."], "pt": ["Vocês saem rolando para a luz, e atrás de vocês {lugar} desaba numa nuvem de pó. Lá embaixo, a porta continua fechada."]}, "fecho": {"en": ["In {povoado}, midnight passes in silence, and the cracks in the walls stop growing."], "pt": ["Em {povoado}, a meia-noite passa em silêncio, e as rachaduras nas paredes param de crescer."]}, "pa": {"en": ["Listen. Three knocks."], "pt": ["Escutem. Três batidas."]}, "pb": {"en": ["And again. There is someone down there."], "pt": ["E de novo. Tem alguém lá embaixo."]}, "entr": {"en": ["Did you hear those three knocks from under {lugar}? The ground shook with them."], "pt": ["Ouviram essas três batidas vindo de baixo de {lugar}? O chão tremeu junto."]}, "chave": {"en": ["Three enormous knocks shake everything, and the corridor you came through collapses. The only way now is forward."], "pt": ["Três batidas enormes sacodem tudo, e o corredor por onde vocês vieram desaba. O único caminho agora é para frente."]}, "chc": {"en": ["Three enormous knocks shake everything, and the corridor you came through collapses. This is the knocking that {povoado} hears every midnight. The only way now is forward."], "pt": ["Três batidas enormes sacodem tudo, e o corredor por onde vocês vieram desaba. São as batidas que {povoado} ouve toda meia-noite. O único caminho agora é para frente."]}, "chs": {"en": ["Three enormous knocks shake everything, and the corridor you came through collapses. They are the same three knocks you heard from the road. The only way now is forward."], "pt": ["Três batidas enormes sacodem tudo, e o corredor por onde vocês vieram desaba. São as mesmas três batidas que vocês ouviram na estrada. O único caminho agora é para frente."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance, the cracks in the walls are fresh, just like those in the houses of {povoado}."], "pt": ["Na entrada, as rachaduras das paredes estão frescas, iguais às das casas de {povoado}."]}}, {"t": "h", "txt": {"en": ["The knocking the notice spoke of comes from here. Count with me: one, two, three."], "pt": ["As batidas de que o aviso falava são daqui. Contem comigo: uma, duas, três."]}}]}, "defesa": {"tit": {"en": ["The Stand at {lugar}", "Until the Bells Ring", "No One Gets Through"], "pt": ["A Resistência em {lugar}", "Até os Sinos Tocarem", "Ninguém Passa"]}, "aviso": {"en": ["Help {povoado}. The horde is coming down the road, and we need time to close the gates and carry out the wounded. Someone has to hold it at {lugar} until the bells ring.", "Please hold the horde at {lugar}. {povoado} still has people leaving through the gates, and every hour counts.", "{povoado} is calling for help. The horde of {vilao} has already burned two villages, and the only way to us runs through {lugar}."], "pt": ["Ajudem {povoado}. A horda vem pela estrada, e precisamos de tempo para fechar os portões e tirar os feridos. Alguém precisa segurá-la em {lugar} até os sinos tocarem.", "Por favor, segurem a horda em {lugar}. {povoado} ainda tem gente saindo pelos portões, e cada hora conta.", "{povoado} pede socorro. A horda de {vilao} já queimou duas aldeias, e o único caminho até nós passa por {lugar}."]}, "abert": {"en": ["The heroes take up position in {lugar}, on the road the horde must take."], "pt": ["Os heróis tomam posição em {lugar}, no caminho por onde a horda tem de passar."]}, "fala": {"en": ["Two villages burned on the border, and {vilao} is coming for the third. Only the heart of this place can be held, because in there the passage is narrow. Get there before they do. You can already hear the drums from here."], "pt": ["Duas aldeias queimadas na fronteira, e {vilao} vem atrás da terceira. Só o coração deste lugar dá para segurar, porque lá dentro a passagem é estreita. Cheguem lá antes deles. Daqui já se ouvem os tambores."]}, "pista": {"nome": {"en": "A war horn", "pt": "Uma trompa de guerra"}, "olhar": {"en": "A cracked war horn, with fresh blood on it.", "pt": "Uma trompa de guerra rachada, com sangue fresco."}, "revela": {"en": "A horn lies near the entrance.", "pt": "Há uma trompa caída perto da entrada."}, "texto": {"en": ["The horn bears the blood of the one who tried to sound the alarm, and the mouthpiece is cracked from sheer force: the sentry blew until the end. Beside the body lies a black arrow with its feathers painted red, the colors of {vilao}."], "pt": ["A trompa tem o sangue de quem tentou dar o alarme, e o bocal está rachado de tanta força: a sentinela soprou até o fim. Ao lado do corpo, há uma flecha negra com as penas pintadas de vermelho, as cores de {vilao}."]}}, "ultima": {"en": ["This is the heart of the place, where the passage narrows. From here, they do not get through."], "pt": ["Aqui é o coração do lugar, onde a passagem se estreita. Daqui, eles não passam."]}, "narr": {"en": ["The horde halts at the entrance, and {vilao} comes forward a few steps, alone."], "pt": ["A horda para na entrada, e {vilao} avança sozinh⟨vilao:o|a⟩ alguns passos."]}, "vil": {"en": ["Stand aside, and you may live."], "pt": ["Saiam da frente, e talvez sobrevivam."]}, "hc": {"en": ["{povoado} asked for time. It will have it."], "pt": ["{povoado} pediu tempo. Vai ter."]}, "hs": {"en": ["No one gets past this point."], "pt": ["Daqui, ninguém passa."]}, "fim": {"en": ["The last wave breaks, and the horde falls back, trampling its own dead. Only then do you notice that your hands are still shaking on your weapons."], "pt": ["A última onda se quebra, e a horda recua pisando nos próprios mortos. Só então vocês percebem que as mãos ainda tremem nas armas."]}, "fecho": {"en": ["Far away, the bells of {povoado} are ringing: the gates were closed in time."], "pt": ["Lá longe, os sinos de {povoado} tocam: os portões fecharam a tempo."]}, "pa": {"en": ["Drums. Far off, but many."], "pt": ["Tambores. Longe, mas muitos."]}, "pb": {"en": ["Armies march to drums like those."], "pt": ["Exércitos marcham com tambores assim."]}, "entr": {"en": ["That rider who went by shouting said the horde is right behind. The entrance of {lugar} is the only place where it can be held."], "pt": ["Aquele cavaleiro que passou gritando disse que a horda vem logo atrás. A entrada de {lugar} é o único lugar onde dá para segurá-la."]}, "chave": {"en": ["The drums stop. In the silence, a horn answers, and that means they are coming."], "pt": ["Os tambores param. No silêncio, uma trompa responde, e isso quer dizer que eles estão vindo."]}, "chc": {"en": ["The drums stop. In the silence, a horn answers, and that means they are coming. Now the horde must be held until the bells of {povoado} ring."], "pt": ["Os tambores param. No silêncio, uma trompa responde, e isso quer dizer que eles estão vindo. Agora é segurar a horda até os sinos de {povoado} tocarem."]}, "chs": {"en": ["The drums stop. In the silence, a horn answers, and that means they are coming. They are the same drums you heard from afar, on the road."], "pt": ["Os tambores param. No silêncio, uma trompa responde, e isso quer dizer que eles estão vindo. São os mesmos tambores que vocês ouviram de longe, na estrada."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance, a rider gallops past without stopping and shouts that the horde is less than an hour away."], "pt": ["Na entrada, um cavaleiro passa a galope, sem parar, e grita que a horda está a menos de uma hora."]}}, {"t": "h", "txt": {"en": ["This is the passage from the notice. If the horde comes down the road, it has to come through here."], "pt": ["Esta é a passagem do aviso. Se a horda vier pela estrada, tem que passar por aqui."]}}]}, "defesa/retirada": {"tit": {"en": ["The Retreat from {povoado}", "Time to Flee", "The Last Line"], "pt": ["A Retirada de {povoado}", "Tempo para Fugir", "A Última Fila"]}, "aviso": {"en": ["Help {povoado} to flee. The horde arrives {ate}, and the only road away from here runs through {lugar}. Someone has to hold the passage while the people cross.", "Please hold {lugar}. {gente} of {povoado} are fleeing with the wagons, and the horde is right behind.", "{povoado} is going to be abandoned. We need someone to hold the horde at {lugar} until the last wagon is through."], "pt": ["Ajudem {povoado} a fugir. A horda chega {ate}, e a única estrada para longe daqui passa por {lugar}. Alguém precisa segurar a passagem enquanto o povo atravessa.", "Por favor, segurem {lugar}. {gente} de {povoado} estão fugindo com as carroças, e a horda vem logo atrás.", "{povoado} vai ser abandonad⟨povoado:o|a⟩. Precisamos de quem segure a horda em {lugar} até a última carroça passar."]}, "abert": {"en": ["The heroes reach {lugar} as the wagons of {povoado} go by, one after another. Behind them, in the distance, rises the dust of the horde."], "pt": ["Os heróis chegam a {lugar} enquanto as carroças de {povoado} passam, uma atrás da outra. Atrás delas, ao longe, sobe a poeira da horda."]}, "fala": {"en": ["The horde belongs to {vilao}, and it does not stop to plunder: it comes straight after those who flee. At the heart of this place, the passage is narrow. If you hold it there, the wagons get through. If not, the horde catches everyone on the road."], "pt": ["A horda é de {vilao}, e ela não para para saquear: vem direto atrás de quem foge. No coração deste lugar, a passagem é estreita. Se vocês segurarem ali, as carroças passam. Se não, alcançam todo mundo na estrada."]}, "pista": {"nome": {"en": "A wagon wheel", "pt": "Uma roda de carroça"}, "olhar": {"en": "A broken wheel, left behind in the middle of the road.", "pt": "Uma roda quebrada, deixada para trás no meio da estrada."}, "revela": {"en": "A broken wheel lies in the way.", "pt": "Há uma roda quebrada no caminho."}, "texto": {"en": ["The wheel is from one of the wagons of {povoado}, and whoever lost it went on by foot: the footprints carry on ahead. In the other direction, far off, the banners of the horde are already showing on the hill, in the colors of {vilao}."], "pt": ["A roda é de uma das carroças de {povoado}, e quem a perdeu seguiu viagem a pé, porque as pegadas continuam adiante. Na outra direção, ao longe, os estandartes da horda já aparecem na colina, com as cores de {vilao}."]}}, "ultima": {"en": ["This is the heart of the place, where the passage narrows. Behind you, the last wagon is still going through."], "pt": ["Aqui é o coração do lugar, onde a passagem se estreita. Atrás de vocês, a última carroça ainda está passando."]}, "narr": {"en": ["The horde halts at the entrance, and {vilao} looks over your heads, at the wagons."], "pt": ["A horda para na entrada, e {vilao} olha por cima de vocês, para as carroças."]}, "vil": {"en": ["You are few, and they are slow. Stand aside."], "pt": ["Vocês são poucos, e eles são lentos. Saiam da frente."]}, "hc": {"en": ["The last wagon is going through."], "pt": ["A última carroça vai passar."]}, "hs": {"en": ["Today, those who flee arrive."], "pt": ["Hoje, quem foge chega."]}, "fim": {"en": ["The last wave breaks, and when you look back, the road is empty: every wagon got through."], "pt": ["A última onda se quebra, e quando vocês olham para trás, a estrada está vazia: todas as carroças passaram."]}, "fecho": {"en": ["Far from there, the people of {povoado} make camp and count the families. No one is missing."], "pt": ["Longe dali, o povo de {povoado} monta acampamento e conta as famílias. Não falta ninguém."]}, "pa": {"en": ["Dust on the road. A great deal of it."], "pt": ["Poeira na estrada. Muita."]}, "pb": {"en": ["Wagons, and behind them, something else."], "pt": ["Carroças, e atrás delas, outra coisa."]}, "entr": {"en": ["The wagons of {povoado} are passing through {lugar}. And look at the dust back there: the horde is coming."], "pt": ["As carroças de {povoado} estão passando por {lugar}. E vejam a poeira lá atrás: a horda vem chegando."]}, "chave": {"en": ["A wagon gets stuck in the passage, and the people cry out. In the distance, the drums of the horde grow louder."], "pt": ["Uma carroça atola na passagem, e o povo grita. Ao longe, os tambores da horda ficam mais altos."]}, "chc": {"en": ["A wagon gets stuck in the passage, and the people cry out. In the distance, the drums of the horde grow louder. Many people of {povoado} have yet to cross."], "pt": ["Uma carroça atola na passagem, e o povo grita. Ao longe, os tambores da horda ficam mais altos. Ainda falta muita gente de {povoado} atravessar."]}, "chs": {"en": ["A wagon gets stuck in the passage, and the people cry out. In the distance, the drums of the horde grow louder. The dust you saw on the road is the horde, and it is close."], "pt": ["Uma carroça atola na passagem, e o povo grita. Ao longe, os tambores da horda ficam mais altos. A poeira que vocês viram na estrada é a horda, e ela está perto."]}, "elos": [{"t": "n", "txt": {"en": ["A child waves from the top of the last wagon, and the mother pulls the child back down under the canvas."], "pt": ["Uma criança acena do alto da última carroça, e a mãe a puxa de volta para baixo da lona."]}}, {"t": "h", "txt": {"en": ["Look at the line of wagons. As long as there is a single one on the road, we hold."], "pt": ["Olhem a fila de carroças. Enquanto houver uma só na estrada, a gente segura."]}}]}, "defesa/ponte": {"tit": {"en": ["The Bridge of {lugar}", "Until the Bridge Falls", "Fire on the Bridge"], "pt": ["A Ponte de {lugar}", "Até a Ponte Cair", "Fogo na Ponte"]}, "aviso": {"en": ["Help {povoado}. The horde has to cross the bridge of {lugar} to reach us, and we are preparing the fire to bring it down. Someone has to hold the horde until the bridge falls.", "Please hold the bridge of {lugar}. The oil is already on the beams, and all we lack is time to light it.", "{povoado} is calling for help. If the horde crosses {lugar}, nothing else stands between it and the village."], "pt": ["Ajudem {povoado}. A horda precisa atravessar a ponte de {lugar} para chegar até nós, e estamos preparando o fogo para derrubá-la. Alguém precisa segurar a horda até a ponte cair.", "Por favor, segurem a ponte de {lugar}. O óleo já está nas vigas, e só falta tempo para acender.", "{povoado} pede socorro. Se a horda atravessar {lugar}, nada mais a separa da vila."]}, "abert": {"en": ["The heroes reach the bridge of {lugar}, which reeks of oil. Down below, the river runs strong."], "pt": ["Os heróis chegam à ponte de {lugar}, que cheira a óleo. Lá embaixo, o rio corre forte."]}, "fala": {"en": ["The horde belongs to {vilao}, and it is coming along the far bank. We are soaking the beams in oil, but the fire takes time to catch. Hold the heart of this place, where the passage narrows, until the bridge falls."], "pt": ["A horda é de {vilao}, e chega pela outra margem. Estamos encharcando as vigas de óleo, mas o fogo leva tempo para pegar. Segurem o coração deste lugar, onde a passagem se estreita, até a ponte cair."]}, "pista": {"nome": {"en": "A barrel of oil", "pt": "Um barril de óleo"}, "olhar": {"en": "A barrel of oil, open, its strong smell in the air.", "pt": "Um barril de óleo, aberto, com o cheiro forte no ar."}, "revela": {"en": "An open barrel stands near the entrance.", "pt": "Há um barril aberto perto da entrada."}, "texto": {"en": ["The barrel is half empty, and whoever was carrying it left at a run: the lid and gloves are on the ground. On the other side of the bridge, the banners of the horde are already showing, in the colors of {vilao}."], "pt": ["O barril está pela metade, e quem o carregava saiu correndo, porque deixou a tampa e as luvas no chão. Do outro lado da ponte, os estandartes da horda já aparecem, com as cores de {vilao}."]}}, "ultima": {"en": ["This is the heart of the place, where the passage narrows. Behind you, someone lights the first torch."], "pt": ["Aqui é o coração do lugar, onde a passagem se estreita. Atrás de vocês, alguém acende a primeira tocha."]}, "narr": {"en": ["The horde halts at the entrance, and {vilao} sniffs the air, catching the smell of oil."], "pt": ["A horda para na entrada, e {vilao} fareja o ar: sente o cheiro do óleo."]}, "vil": {"en": ["Are you going to burn the bridge with yourselves on it?"], "pt": ["Vão queimar a ponte com vocês em cima?"]}, "hc": {"en": ["If we must."], "pt": ["Se for preciso."]}, "hs": {"en": ["Only after you."], "pt": ["Só depois de vocês."]}, "fim": {"en": ["The last wave breaks, and behind you the bridge catches fire from one end to the other. When it falls into the river, the horde is left on the far side."], "pt": ["A última onda se quebra, e atrás de vocês a ponte pega fogo de uma ponta à outra. Quando ela cai no rio, a horda fica do outro lado."]}, "fecho": {"en": ["In {povoado}, everyone sees the smoke from the bridge, and no one complains about losing the road to market."], "pt": ["Em {povoado}, a fumaça da ponte é vista por todo mundo, e ninguém reclama de ter perdido o caminho para o mercado."]}, "pa": {"en": ["The smell of oil."], "pt": ["Cheiro de óleo."]}, "pb": {"en": ["A lot of oil. Someone is preparing a very large bonfire."], "pt": ["Muito óleo. Alguém está preparando uma fogueira bem grande."]}, "entr": {"en": ["The bridge of {lugar} is soaked in oil. And that dust on the far side is the horde."], "pt": ["A ponte de {lugar} está encharcada de óleo. E aquela poeira do outro lado é a horda."]}, "chave": {"en": ["Someone shouts from the bridge that the fire has caught. The horde hears it too, and charges all at once."], "pt": ["Alguém grita da ponte que o fogo pegou. A horda também ouve, e avança de uma vez."]}, "chc": {"en": ["Someone shouts from the bridge that the fire has caught. The horde hears it too, and charges all at once. Now the fire needs time to bring the bridge down."], "pt": ["Alguém grita da ponte que o fogo pegou. A horda também ouve, e avança de uma vez. Agora o fogo precisa de tempo para derrubar a ponte."]}, "chs": {"en": ["Someone shouts from the bridge that the fire has caught. The horde hears it too, and charges all at once. That is what the oil was for: the bridge is going to fall, and someone has to hold the horde until it does."], "pt": ["Alguém grita da ponte que o fogo pegou. A horda também ouve, e avança de uma vez. Era para isso o óleo: a ponte vai cair, e alguém precisa segurar a horda até lá."]}, "elos": [{"t": "n", "txt": {"en": ["At the head of the bridge, barrels of oil are stacked up, and a man is soaking the beams with a bucket."], "pt": ["Na entrada da ponte, há barris de óleo empilhados e um homem encharcando as vigas com um balde."]}}, {"t": "h", "txt": {"en": ["The bridge from the notice. Smell that: they are already preparing the fire."], "pt": ["A ponte do aviso. Sintam o cheiro: já estão preparando o fogo."]}}]}, "selos": {"tit": {"en": ["Close the Veil", "The Rifts of {lugar}", "Where the World Is Thin"], "pt": ["Fechem o Véu", "As Fendas de {lugar}", "Onde o Mundo É Fino"]}, "aviso": {"en": ["Help {povoado}. Ever since the air of {lugar} cracked, things have been crawling out at night and attacking those who live nearby.", "Please close the rifts of {lugar}. {desde}, {sinal}, and {gente} {gentefaz}.", "{povoado} is calling for help. The old wards of {lugar} have been broken {desde}, and few are left who know how to close them."], "pt": ["Ajudem {povoado}. Desde que o ar de {lugar} rachou, coisas rastejam para fora à noite e atacam quem mora perto.", "Por favor, fechem as fendas de {lugar}. {desde}, {sinal}, e {gente} {gentefaz}.", "{povoado} pede socorro. As velhas proteções de {lugar} se romperam {desde}, e restam poucos que saibam fechá-las."]}, "abert": {"en": ["The heroes reach {lugar} and taste iron in the air."], "pt": ["Os heróis chegam a {lugar} e sentem no ar um gosto de ferro."]}, "fala": {"en": ["First there was one rift, then three. {vilao} broke the first ward and is feeding the others. Close them one by one, before they join into a single rift, because no word can close a rift that size."], "pt": ["Primeiro foi uma fenda, depois três. {vilao} rompeu a primeira proteção e alimenta as outras. Fechem uma a uma, antes que se juntem numa só, porque uma fenda desse tamanho nenhuma palavra fecha."]}, "pista": {"nome": {"en": "A bleeding rift", "pt": "Uma fenda que sangra"}, "olhar": {"en": "A rift in the air itself, dripping red light.", "pt": "Uma fenda no próprio ar, pingando luz vermelha."}, "revela": {"en": "There is a red glow in the air near the entrance.", "pt": "Há um brilho vermelho no ar perto da entrada."}, "texto": {"en": ["The red light drips from the rift like blood from a wound, and its edges bear the marks of a knife: someone forced it open. On the floor, footprints go up to the edge of the rift and back, several times, as if someone comes to feed it. From deep inside, a chant calls the name of the one who does this: {vilao}."], "pt": ["A luz vermelha pinga da fenda como sangue de uma ferida, e as bordas estão marcadas de faca: alguém a abriu à força. No chão, há pegadas que entram até a beira da fenda e voltam, várias vezes, como de alguém que vem alimentá-la. Lá do fundo, um canto chama pelo nome de quem faz isso: {vilao}."]}}, "ultima": {"en": ["The last rift pulses in the middle of the room, and {vilao} has one hand plunged into it up to the wrist."], "pt": ["A última fenda pulsa no meio da sala, e {vilao} tem uma das mãos enfiada nela até o pulso."]}, "narr": {"en": ["As you come in, the rift opens a palm's width wider."], "pt": ["Quando vocês entram, a fenda se abre mais um palmo."]}, "vil": {"en": ["Come to watch the world end? Good seats."], "pt": ["Vieram ver o mundo acabar? Bons lugares."]}, "hc": {"en": ["{povoado} wants its nights back."], "pt": ["{povoado} quer as noites de volta."]}, "hs": {"en": ["We came to close the door."], "pt": ["Viemos fechar a porta."]}, "fim": {"en": ["The last rift closes with a sound like a sigh, and the light falls straight again. For the first time, you notice the crickets singing."], "pt": ["A última fenda se fecha com um som de suspiro, e a luz volta a cair reta. Pela primeira vez, vocês notam o canto dos grilos."]}, "fecho": {"en": ["In {povoado}, the first night goes by without anything crawling up to the doors."], "pt": ["Em {povoado}, a primeira noite passa sem que nada rasteje até as portas."]}, "pa": {"en": ["Look at the light. It bends just ahead."], "pt": ["Olhem a luz. Ela entorta ali adiante."]}, "pb": {"en": ["And the birds fly around that spot, always on the outside."], "pt": ["E os pássaros dão a volta naquele ponto, sempre por fora."]}, "entr": {"en": ["Can you taste that iron in the air? And look at the light at the entrance of {lugar}: it bends as it does in still water."], "pt": ["Vocês sentem esse gosto de ferro no ar? E olhem a luz na entrada de {lugar}: ela se dobra como numa água parada."]}, "chave": {"en": ["The air tears with a sound like wet cloth. Another rift has opened, and things are crawling through it."], "pt": ["O ar se rasga com um som de pano molhado. Mais uma fenda se abriu, e coisas rastejam por ela."]}, "chc": {"en": ["The air tears with a sound like wet cloth. Another rift has opened, and things are crawling through it. It is through rifts like this that things come out at night to attack {povoado}."], "pt": ["O ar se rasga com um som de pano molhado. Mais uma fenda se abriu, e coisas rastejam por ela. É por fendas assim que as coisas saem à noite para atacar {povoado}."]}, "chs": {"en": ["The air tears with a sound like wet cloth. Another rift has opened, and things are crawling through it. The bent light on the road was the air cracking."], "pt": ["O ar se rasga com um som de pano molhado. Mais uma fenda se abriu, e coisas rastejam por ela. A luz torta da estrada era o ar rachando."]}, "elos": [{"t": "h", "txt": {"en": ["Did you hear that crack? That is the air splitting, as the notice described. The rifts must be close by."], "pt": ["Ouviram esse estalo? É o ar rachando, como o aviso contava. As fendas devem estar logo ali."]}}, {"t": "n", "txt": {"en": ["At the entrance, a line of red light cuts through the air, and something trickles from it that vanishes before it touches the ground."], "pt": ["Na entrada, uma linha de luz vermelha corta o ar, e por ela escorre alguma coisa que some antes de tocar o chão."]}}]}, "selos/crescimento": {"tit": {"en": ["The Rifts Are Growing", "Before the Full Moon", "The Tear of {lugar}"], "pt": ["As Fendas Crescem", "Antes da Lua Cheia", "O Rasgo de {lugar}"]}, "aviso": {"en": ["Help {povoado} {ate}. The rift of {lugar} grows a palm's width every night, and the other side can already be seen through it.", "Please close the rift of {lugar} while there is still time. {desde} it has been growing, and what comes out of it is bigger each time.", "{povoado} needs help {ate}. The rift of {lugar} is growing, and once it is the size of a door, anything can come through."], "pt": ["Ajudem {povoado} {ate}. A fenda de {lugar} cresce um palmo por noite, e já dá para ver o outro lado.", "Por favor, fechem a fenda de {lugar} enquanto é tempo. {desde} ela cresce, e o que sai dela é cada vez maior.", "{povoado} precisa de ajuda {ate}. A fenda de {lugar} cresce, e quando ficar do tamanho de uma porta, qualquer coisa passa."]}, "abert": {"en": ["The heroes reach {lugar}. In the air, a line of red light cuts across the entrance from top to bottom."], "pt": ["Os heróis chegam a {lugar}. No ar, uma linha de luz vermelha corta a entrada de cima a baixo."]}, "fala": {"en": ["The rift grows because someone is feeding it: {vilao} throws things into it every night, and each thing that goes in opens it a palm's width more. The smaller rifts scattered around here are its roots. Close the smaller ones first, and the great one will weaken."], "pt": ["A fenda cresce porque alguém a alimenta: {vilao} joga coisas lá dentro toda noite, e cada coisa que entra abre mais um palmo. As fendas menores, espalhadas por aqui, são as raízes dela. Fechem as menores primeiro, e a grande enfraquece."]}, "pista": {"nome": {"en": "A mark on the floor", "pt": "Uma marca no chão"}, "olhar": {"en": "A chalk mark on the floor, measuring something night by night.", "pt": "Uma marca de giz no chão, medindo alguma coisa noite a noite."}, "revela": {"en": "There are chalk marks on the floor near the entrance.", "pt": "Há marcas de giz no chão perto da entrada."}, "texto": {"en": ["Someone has measured the rift night after night, with chalk strokes and dates beside them, and each stroke is longer than the last. The final stroke carries a message: “When it reaches the door, {vilao} will cross over.”"], "pt": ["Alguém mediu a fenda noite após noite, com riscos de giz e datas ao lado, e cada risco é maior que o anterior. O último risco tem um recado: «Quando chegar à porta, {vilao} vai atravessar.»"]}}, "ultima": {"en": ["The great rift fills the whole room, and {vilao} stands at its edge, back turned to you."], "pt": ["A grande fenda ocupa a sala inteira, e {vilao} está na beira dela, de costas para vocês."]}, "narr": {"en": ["As you come in, the rift opens a palm's width wider, and something on the other side moves."], "pt": ["Quando vocês entram, a fenda se abre mais um palmo, e alguma coisa do outro lado se mexe."]}, "vil": {"en": ["One more palm's width, and I cross over. Care to come along?"], "pt": ["Mais um palmo, e eu atravesso. Querem vir junto?"]}, "hc": {"en": ["{povoado} wants that door closed."], "pt": ["{povoado} quer essa porta fechada."]}, "hs": {"en": ["No one crosses over today."], "pt": ["Ninguém atravessa hoje."]}, "fim": {"en": ["The great rift closes all at once, with a crack, and the silence it leaves seems to weigh on the air."], "pt": ["A grande fenda se fecha de uma vez, com um estalo, e o silêncio que fica parece pesar no ar."]}, "fecho": {"en": ["In {povoado}, the chalk marks are rubbed out, and no one needs to measure anything anymore."], "pt": ["Em {povoado}, as marcas de giz são apagadas, e ninguém mais precisa medir nada."]}, "pa": {"en": ["Was that red line in the air there yesterday?"], "pt": ["Aquela linha vermelha no ar estava ali ontem?"]}, "pb": {"en": ["It was. Only smaller."], "pt": ["Estava. Só que menor."]}, "entr": {"en": ["Do you see that red line cutting across the entrance of {lugar}? It looks as if the air has torn there."], "pt": ["Estão vendo essa linha vermelha cortando a entrada de {lugar}? Parece que o ar rasgou ali."]}, "chave": {"en": ["A loud crack, and the great rift grows all at once. On the other side, something is pushing to get out."], "pt": ["Um estalo forte, e a grande fenda cresce de uma vez. Do outro lado, alguma coisa empurra para sair."]}, "chc": {"en": ["A loud crack, and the great rift grows all at once. On the other side, something is pushing to get out. It is the rift from the notice, and it has just grown by more than a palm's width."], "pt": ["Um estalo forte, e a grande fenda cresce de uma vez. Do outro lado, alguma coisa empurra para sair. É a fenda do aviso, e ela acaba de crescer mais que um palmo."]}, "chs": {"en": ["A loud crack, and the great rift grows all at once. On the other side, something is pushing to get out. The red line on the road is this very rift, and it is growing."], "pt": ["Um estalo forte, e a grande fenda cresce de uma vez. Do outro lado, alguma coisa empurra para sair. A linha vermelha da estrada é esta mesma fenda, e ela cresce."]}, "elos": [{"t": "n", "txt": {"en": ["On the stone at the entrance are chalk strokes measuring something, night after night. The last stroke is the longest."], "pt": ["Na pedra da entrada, há riscos de giz medindo alguma coisa, noite após noite. O último risco é o maior."]}}, {"t": "h", "txt": {"en": ["Remember what the notice said? The rift is growing. Look at yesterday's mark, and look at today's."], "pt": ["Lembram do que o aviso dizia? A fenda cresce. Olhem a marca de ontem, e olhem a de hoje."]}}]}, "selos/guardia": {"tit": {"en": ["The Warden Who Did Not Return", "The Lost Words", "The Last Ward"], "pt": ["A Guardiã que Não Voltou", "As Palavras Perdidas", "A Última Proteção"]}, "aviso": {"en": ["Help {povoado}. The warden of the old wards went to close the rifts of {lugar}, and {desde} no one has had word of her.", "Please find the warden. She went into {lugar} to close the rifts, and ever since, {sinal} in {povoado}.", "{povoado} is calling for help. The only one who knew how to close the rifts of {lugar} has vanished in there."], "pt": ["Ajudem {povoado}. A guardiã das velhas proteções foi fechar as fendas de {lugar}, e {desde} ninguém tem notícia dela.", "Por favor, achem a guardiã. Ela entrou em {lugar} para fechar as fendas, e desde então {sinal} em {povoado}.", "{povoado} pede socorro. A única que sabia fechar as fendas de {lugar} sumiu lá dentro."]}, "abert": {"en": ["The heroes reach {lugar} and find a warden's staff lying at the entrance."], "pt": ["Os heróis chegam a {lugar} e acham um bastão de guardiã caído na entrada."]}, "fala": {"en": ["The warden closed two rifts before she was caught. {vilao} is keeping her alive for her words, spoken backward: to open instead of to close. Close the rifts that remain, and she will be of no use to them."], "pt": ["A guardiã fechou duas fendas antes de ser pega. {vilao} a mantém viva porque precisa das palavras dela, ao contrário: para abrir, em vez de fechar. Fechem as fendas que restam, e ela fica sem utilidade para eles."]}, "pista": {"nome": {"en": "A warden's staff", "pt": "Um bastão de guardiã"}, "olhar": {"en": "A wooden staff, carved with ancient words, lying on the floor.", "pt": "Um bastão de madeira, entalhado com palavras antigas, caído no chão."}, "revela": {"en": "A staff lies near the entrance.", "pt": "Há um bastão caído perto da entrada."}, "texto": {"en": ["The staff belongs to the warden, and it was dropped in haste: there are signs of a struggle all around. Among the carved words, someone has scratched some out and written others over them in fresh ink, and signed: {vilao}."], "pt": ["O bastão é da guardiã, e foi largado na pressa, porque há marcas de luta em volta. Nas palavras entalhadas, alguém riscou algumas e escreveu outras por cima, com tinta fresca, e assinou: {vilao}."]}}, "ultima": {"en": ["The warden is held in the middle of a circle of rifts. {vilao} reads her words aloud, backward."], "pt": ["A guardiã está presa no meio de um círculo de fendas. {vilao} lê em voz alta as palavras dela, de trás para frente."]}, "narr": {"en": ["As you come in, the warden lifts her head and cries out one word, the only one she still remembers."], "pt": ["Quando vocês entram, a guardiã levanta a cabeça e grita uma palavra, a única que ainda lembra."]}, "vil": {"en": ["She is going to teach me to open everything. You may watch."], "pt": ["Ela vai me ensinar a abrir tudo. Vocês podem assistir."]}, "hc": {"en": ["{povoado} wants its warden back."], "pt": ["{povoado} quer a guardiã de volta."]}, "hs": {"en": ["She is coming with us."], "pt": ["Ela vem com a gente."]}, "fim": {"en": ["The last rift closes, and the warden falls to her knees. She looks at you and asks, in a hoarse voice, that someone learn the words."], "pt": ["A última fenda se fecha, e a guardiã cai de joelhos. Ela olha para vocês e pede, com a voz rouca, que alguém aprenda as palavras."]}, "fecho": {"en": ["In {povoado}, the warden begins teaching the words to two children, so that they never again depend on one person alone."], "pt": ["Em {povoado}, a guardiã começa a ensinar as palavras a duas crianças, para que nunca mais dependa de uma pessoa só."]}, "pa": {"en": ["A strange glow in the air, just ahead."], "pt": ["Um brilho estranho no ar, ali adiante."]}, "pb": {"en": ["And a staff lying on the ground, right below it."], "pt": ["E um bastão caído no chão, logo abaixo."]}, "entr": {"en": ["There is a warden's staff lying at the entrance of {lugar}. And the air here tastes of iron."], "pt": ["Tem um bastão de guardiã caído na entrada de {lugar}. E o ar aqui tem gosto de ferro."]}, "chave": {"en": ["From deep inside comes the warden's voice, crying out a word. A moment later, {vilao} orders her to be silent."], "pt": ["Lá do fundo vem a voz da guardiã, gritando uma palavra. Logo depois, {vilao} a manda calar."]}, "chc": {"en": ["From deep inside comes the warden's voice, crying out a word. A moment later, {vilao} orders her to be silent. It is the warden of {povoado}, and she is alive."], "pt": ["Lá do fundo vem a voz da guardiã, gritando uma palavra. Logo depois, {vilao} a manda calar. É a guardiã de {povoado}, e ela está viva."]}, "chs": {"en": ["From deep inside comes the warden's voice, crying out a word. A moment later, {vilao} orders her to be silent. The staff lying on the road was hers, and she is alive."], "pt": ["Lá do fundo vem a voz da guardiã, gritando uma palavra. Logo depois, {vilao} a manda calar. O bastão caído na estrada era dela, e ela está viva."]}, "elos": [{"t": "n", "txt": {"en": ["Beside the staff is a scrap of cloth with a word written in blood, the same word the warden used to close the rifts."], "pt": ["Ao lado do bastão, há um pedaço de pano com uma palavra escrita a sangue, a mesma que a guardiã usava para fechar as fendas."]}}, {"t": "h", "txt": {"en": ["This staff belongs to the warden from the notice. She came through here, and was taken by force."], "pt": ["Esse bastão é da guardiã do aviso. Ela passou por aqui, e foi levada à força."]}}]}, "escolta": {"tit": {"en": ["The Old Path", "On the Far Side of {lugar}", "Who Knows the Path"], "pt": ["O Velho Caminho", "Do Outro Lado de {lugar}", "Quem Conhece o Caminho"]}, "aviso": {"en": ["Help us take the one who knows the old path through {lugar}. That is the way the people of {povoado} will flee the war, and all the others who knew the path have been killed, one a week.", "Please escort our guide to the far side of {lugar}. {povoado} depends on that crossing to flee {ate}.", "{povoado} needs an escort. Those who knew the path through {lugar} were killed, one by one, and only one person is left."], "pt": ["Ajudem a levar quem conhece o velho caminho através de {lugar}. É por ali que o povo de {povoado} vai fugir da guerra, e todos os outros que conheciam o caminho foram mortos, um por semana.", "Por favor, escoltem nosso guia até o outro lado de {lugar}. {povoado} depende dessa travessia para fugir {ate}.", "{povoado} precisa de escolta. Quem conhecia o caminho através de {lugar} foi morto, um por um, e só sobrou uma pessoa."]}, "abert": {"en": ["The heroes follow the guide, who walks too fast for someone that old. Behind them, the road is already being watched."], "pt": ["Os heróis seguem quem guia, que anda depressa demais para a idade. Atrás deles, a estrada já está vigiada."]}, "intro": {"en": ["The other guides are dead. {vilao} got them all, one a week, and now I am the only one left. Take me to the far side of {lugar}, and I will open the path for you and for those who come after. Stay close. I tire quickly."], "pt": ["Os outros guias estão mortos. {vilao} pegou todos, um por semana, e agora só falto eu. Me levem ao outro lado de {lugar}, e eu abro o caminho para vocês e para quem vier depois. Fiquem perto. Eu canso rápido."]}, "ultima": {"en": ["The way out is right there, and {vilao} stands smiling in front of it."], "pt": ["A saída está logo ali, e {vilao} sorri na frente dela."]}, "narr": {"en": ["The guide hides behind you."], "pt": ["Quem guia se esconde atrás de vocês."]}, "vil": {"en": ["So you have brought the last guide to me. The journey ends here."], "pt": ["Então vocês trouxeram o último guia até mim. A viagem termina aqui."]}, "hc": {"en": ["The journey ends on the far side."], "pt": ["A viagem termina do outro lado."]}, "hs": {"en": ["The journey ends on the far side."], "pt": ["A viagem termina do outro lado."]}, "fim": {"en": ["On the far side, three words are enough for the path to close behind you like water. {vilao} is left on the wrong side, pounding on the stone."], "pt": ["Do outro lado, três palavras bastam para o caminho se fechar atrás de vocês como água. {vilao} fica do lado errado, batendo na pedra."]}, "fecho": {"en": ["Tomorrow, the people of {povoado} will come this way, and the three words will be taught to someone younger. “Someone who runs faster,” they say."], "pt": ["Amanhã, o povo de {povoado} passa por aqui, e as três palavras vão ser ensinadas a alguém mais novo. «Alguém que corra mais», dizem."]}, "pa": {"en": ["Someone is following us. Since the last bend."], "pt": ["Alguém vem atrás de nós. Desde a última curva."]}, "pb": {"en": ["And in plain sight. Whoever it is wants to be seen."], "pt": ["E às claras. Quem quer que seja, quer ser visto."]}, "entr": {"en": ["Someone came running up to us asking for protection, and says there is a need to cross {lugar}."], "pt": ["Alguém veio correndo até nós pedindo proteção, e disse que precisa atravessar {lugar}."]}, "chave": {"en": ["Torches appear behind you, a sign that they have found your trail. Now the only thing left is to press on."], "pt": ["Aparecem tochas atrás de vocês, sinal de que acharam o rastro. Agora só resta seguir em frente."]}, "chc": {"en": ["Torches appear behind you, a sign that they have found your trail. Now the only thing left is to press on. They are the same ones who killed the others who knew the path."], "pt": ["Aparecem tochas atrás de vocês, sinal de que acharam o rastro. Agora só resta seguir em frente. São os mesmos que mataram os outros que conheciam o caminho."]}, "chs": {"en": ["Torches appear behind you, a sign that they have found your trail. Now the only thing left is to press on. They are the ones who have been following you since the last bend."], "pt": ["Aparecem tochas atrás de vocês, sinal de que acharam o rastro. Agora só resta seguir em frente. É quem vinha seguindo vocês desde a última curva."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance is a stone marked with an ancient symbol, the same one the guides use to show the old path."], "pt": ["Na entrada, há uma pedra marcada com um símbolo antigo, o mesmo que os guias usam para indicar o velho caminho."]}}, {"t": "h", "txt": {"en": ["This is where the path from the notice begins. From here on, no one leaves our side."], "pt": ["É aqui que começa o caminho do aviso. Daqui para frente, ninguém sai do nosso lado."]}}]}, "escolta/testemunha": {"tit": {"en": ["The Witness", "Alive to the Courthouse", "What the Carter Saw"], "pt": ["A Testemunha", "Vivo até o Tribunal", "O Que o Carroceiro Viu"]}, "aviso": {"en": ["Help us take a witness to the court. A carter saw the baron kill the tax collector, and only his testimony can bring a baron to trial. The court lies on the far side of {lugar}.", "Please escort the witness through {lugar}. The baron has plenty of gold and little patience, and he wants the carter silenced {ate}.", "{povoado} asks for justice. The only man who saw the baron's crime has to reach the court alive, and the way runs through {lugar}."], "pt": ["Ajudem a levar uma testemunha até o tribunal. Um carroceiro viu o barão matar o cobrador de impostos, e só o testemunho dele leva um barão a julgamento. O tribunal fica do outro lado de {lugar}.", "Por favor, escoltem a testemunha através de {lugar}. O barão tem muito ouro e pouca paciência, e quer o carroceiro calado {ate}.", "{povoado} pede justiça. O único que viu o crime do barão precisa chegar vivo ao tribunal, e o caminho passa por {lugar}."]}, "abert": {"en": ["The heroes set off with the witness, who trembles the whole way. Behind them, the road is already being watched."], "pt": ["Os heróis seguem com a testemunha, que treme o caminho todo. Atrás deles, a estrada já está vigiada."]}, "intro": {"en": ["I saw it. The baron wiped his knife on the dead man's coat and had the body thrown in the river. Now he has paid {vilao} to find me before the trial. I have children. Get me to the court in one piece."], "pt": ["Eu vi. O barão limpou a faca no casaco do morto e mandou jogar o corpo no rio. Agora pagou {vilao} para me achar antes do julgamento. Eu tenho filhos. Me levem inteiro até o tribunal."]}, "ultima": {"en": ["The doors of the court are right there, and so is {vilao}."], "pt": ["As portas do tribunal estão logo ali, e {vilao} também."]}, "narr": {"en": ["The witness grabs the arm of the nearest hero."], "pt": ["A testemunha agarra o braço do herói mais próximo."]}, "vil": {"en": ["The baron pays well for that one. He pays even better for you."], "pt": ["O barão paga bem por esse aí. Paga melhor ainda por vocês."]}, "hc": {"en": ["The baron is going to pay another way."], "pt": ["O barão vai pagar de outro jeito."]}, "hs": {"en": ["The baron is going to pay another way."], "pt": ["O barão vai pagar de outro jeito."]}, "fim": {"en": ["The witness takes the stand with shaking hands and tells everything, from beginning to end. When he is done, the hall is silent, and the baron is pale."], "pt": ["A testemunha sobe ao banco com as mãos tremendo e conta tudo, do começo ao fim. Quando termina, o salão está em silêncio, e o barão, pálido."]}, "fecho": {"en": ["In {povoado}, news of the trial runs through the streets, and {vilao} goes unpaid."], "pt": ["Em {povoado}, a notícia do julgamento corre as ruas, e {vilao} fica sem a paga."]}, "pa": {"en": ["Someone is following us. Since the last bend."], "pt": ["Alguém vem atrás de nós. Desde a última curva."]}, "pb": {"en": ["And in plain sight. Whoever it is wants to be seen."], "pt": ["E às claras. Quem quer que seja, quer ser visto."]}, "entr": {"en": ["This carter says he saw a crime and that they want him silenced. He needs to cross {lugar}."], "pt": ["Esse carroceiro diz que viu um crime e que querem calá-lo. Ele precisa atravessar {lugar}."]}, "chave": {"en": ["Torches appear behind you, a sign that those hunting the witness have found your trail."], "pt": ["Aparecem tochas atrás de vocês, sinal de que quem procura a testemunha achou o rastro."]}, "chc": {"en": ["Torches appear behind you, a sign that those hunting the witness have found your trail. They are the baron's men."], "pt": ["Aparecem tochas atrás de vocês, sinal de que quem procura a testemunha achou o rastro. São os homens do barão."]}, "chs": {"en": ["Torches appear behind you, a sign that those hunting the witness have found your trail. They are the ones who have been following you since the last bend."], "pt": ["Aparecem tochas atrás de vocês, sinal de que quem procura a testemunha achou o rastro. É quem vinha seguindo vocês desde a última curva."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance is a poster torn from some post, with a drawing of a carter and a reward in gold."], "pt": ["Na entrada, há um cartaz arrancado de algum poste, com o desenho de um carroceiro e uma recompensa em ouro."]}}, {"t": "h", "txt": {"en": ["The baron has already put up posters with the witness's face. We will have company on the way."], "pt": ["O barão já espalhou cartazes com o rosto da testemunha. Vamos ter companhia no caminho."]}}]}, "maquina": {"tit": {"en": ["Iron in {lugar}", "The Engine of {vilao}", "Before It Is Finished"], "pt": ["Ferro em {lugar}", "A Máquina de {vilao}", "Antes que Fique Pronta"]}, "aviso": {"en": ["Help {povoado}. For months the army of the Legion has surrounded the region, and they say it is hauling timber and iron to {lugar}. They say it is to build {alvo}, and against {alvo} the walls will fall.", "Please find out whether the rumor about {lugar} is true. {desde} hammers have been heard in there, and {povoado} fears that the Legion, the army surrounding the region, is building {alvo}.", "{povoado} needs help {ate}. The Legion, the army surrounding the region, is building {alvo} in {lugar}, and the walls will not withstand it."], "pt": ["Ajudem {povoado}. Há meses o exército da Legião cerca a região, e dizem que estão levando madeira e ferro para {lugar}. Dizem que é para montar {alvo}, e contra {alvo} as muralhas vão cair.", "Por favor, confirmem o boato de {lugar}. {desde} se ouvem martelos lá dentro, e {povoado} teme que a Legião, o exército que cerca a região, esteja montando {alvo}.", "{povoado} precisa de ajuda {ate}. A Legião, o exército que cerca a região, está montando {alvo} em {lugar}, e as muralhas não aguentam."]}, "abert": {"en": ["The heroes reach {lugar} and, before they see anything, they hear hammers inside."], "pt": ["Os heróis chegam a {lugar} e, antes de ver qualquer coisa, ouvem martelos lá dentro."]}, "fala": {"en": ["I spent a whole week hauling beams, and now I know what for. {vilao} is building {alvo}, and has already brought down walls greater than those of {povoado}. Listen to the hammers. When they stop, it is ready."], "pt": ["Passei uma semana inteira carregando vigas, e agora sei para quê. {vilao} está montando {alvo}, e já derrubou muralhas maiores que as de {povoado}. Ouçam os martelos. Quando pararem, ⟨alvo:ele|ela|eles|elas⟩ está pront⟨alvo:o|a|os|as⟩."]}, "pista": {"nome": {"en": "Siege plans", "pt": "Planos de cerco"}, "olhar": {"en": "Rolled-up plans, stained with grease.", "pt": "Planos enrolados, manchados de graxa."}, "revela": {"en": "Rolls of paper lie near the entrance.", "pt": "Há rolos de papel caídos perto da entrada."}, "texto": {"en": ["On the plans, beside {alvo}, they have drawn the wall of {povoado} for comparison, and {alvo} is bigger. In the corner is the seal of the Legion, with the name of the chief engineer below it: {vilao}."], "pt": ["Nos planos, ao lado de {alvo}, desenharam a muralha de {povoado} para comparar, e {alvo} é maior. No canto, o selo da Legião, com o nome do engenheiro-chefe embaixo: {vilao}."]}}, "ultima": {"en": ["{alvo} is nearly finished, taller than the walls it is meant to bring down, and {vilao} stands guard over it."], "pt": ["{alvo} está quase pront⟨alvo:o|a|os|as⟩, mais alt⟨alvo:o|a|os|as⟩ que as muralhas que deve derrubar, e {vilao} ⟨alvo:o|a|os|as⟩ guarda."]}, "narr": {"en": ["As you come in, the hammers stop, and all the workers look to {vilao}."], "pt": ["Quando vocês entram, os martelos param, e todos os operários olham para {vilao}."]}, "vil": {"en": ["Come to see the work? The finest part is still to come."], "pt": ["Vieram ver a obra? Ainda falta a parte mais bonita."]}, "hc": {"en": ["{povoado} sent us to carry out an inspection."], "pt": ["{povoado} mandou fazer uma vistoria."]}, "hs": {"en": ["We came to take it apart."], "pt": ["Viemos desmontar."]}, "fim": {"en": ["{alvo} groans, leans and collapses with a crash that throws up dust everywhere. When the dust settles, what is left is a very expensive pile of firewood."], "pt": ["{alvo} geme, se inclina e desaba com um estrondo que levanta pó por todo lado. Quando a poeira assenta, sobra uma pilha de lenha muito cara."]}, "fecho": {"en": ["From the walls of {povoado}, they hear the crash, and someone orders the last barrel of wine opened. They are celebrating early, and this time they are right to."], "pt": ["Das muralhas de {povoado}, ouvem o estrondo, e alguém manda abrir o último barril de vinho. Comemoram antes da hora, e desta vez têm razão."]}, "pa": {"en": ["Hammering. All night long, without a pause."], "pt": ["Marteladas. A noite inteira, sem parar."]}, "pb": {"en": ["Whoever builds in such a hurry is building something bad."], "pt": ["Quem constrói com tanta pressa constrói coisa ruim."]}, "entr": {"en": ["Can you hear those hammers inside {lugar}? And these beams at the entrance bear the mark of the Legion, the army surrounding the region."], "pt": ["Estão ouvindo esses martelos dentro de {lugar}? E essas vigas na entrada têm a marca da Legião, o exército que cerca a região."]}, "chave": {"en": ["The hammering stops. In its place comes the creak of a great arm being drawn back."], "pt": ["As marteladas param. No lugar delas, ouve-se o rangido de um grande braço sendo puxado para trás."]}, "chc": {"en": ["The hammering stops. In its place comes the creak of a great arm being drawn back. {alvo} from the notice ⟨alvo:is|is|are|are⟩ nearly finished."], "pt": ["As marteladas param. No lugar delas, ouve-se o rangido de um grande braço sendo puxado para trás. {alvo} do aviso ⟨alvo:está|está|estão|estão⟩ quase pront⟨alvo:o|a|os|as⟩."]}, "chs": {"en": ["The hammering stops. In its place comes the creak of a great arm being drawn back. The hammering on the road came from this work, and it is nearly finished."], "pt": ["As marteladas param. No lugar delas, ouve-se o rangido de um grande braço sendo puxado para trás. As marteladas da estrada eram desta obra, e ela está quase pronta."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance are stacks of beams bearing the mark of the Legion, the army surrounding the region. It is the rumor from the notice, confirmed."], "pt": ["Na entrada, há pilhas de vigas com a marca da Legião, o exército que cerca a região. É o boato do aviso, confirmado."]}}, {"t": "h", "txt": {"en": ["Listen to the hammers. The rumor in the notice was true."], "pt": ["Escutem os martelos. O boato do aviso era verdade."]}}, {"t": "n", "txt": {"en": ["From inside comes the creak of heavy timber being fitted together, and a voice counting: “One more.”"], "pt": ["Lá de dentro vem o rangido de madeira grossa sendo encaixada, e uma voz contando: «Mais uma.»"]}}]}, "maquina/ferreiros": {"tit": {"en": ["The Smiths of {povoado}", "The Cold Forges", "The Iron of {vilao}"], "pt": ["Os Ferreiros de {povoado}", "As Forjas Apagadas", "O Ferro de {vilao}"]}, "aviso": {"en": ["Help {povoado}. {desde}, our smiths have been missing, and the forges are cold. They say the Legion, the army surrounding the region, took them to {lugar}.", "Please bring the smiths of {povoado} back. They were taken to {lugar}, and there they are being forced to forge {alvo}.", "{povoado} has lost its smiths. The Legion, the army surrounding the region, needs hands for {alvo}, and came here to get them."], "pt": ["Ajudem {povoado}. {desde}, os nossos ferreiros estão sumidos, e as forjas estão apagadas. Dizem que a Legião, o exército que cerca a região, os levou para {lugar}.", "Por favor, tragam os ferreiros de {povoado} de volta. Foram levados para {lugar}, e lá estão sendo obrigados a forjar {alvo}.", "{povoado} perdeu os seus ferreiros. A Legião, o exército que cerca a região, precisa de mãos para {alvo}, e foi buscá-las aqui."]}, "abert": {"en": ["The heroes follow the sound of hammers to {lugar}. It is the rhythm of the smiths of {povoado}, and they would know it anywhere."], "pt": ["Os heróis seguem o som de martelos até {lugar}. É o ritmo dos ferreiros de {povoado}, e eles o reconheceriam em qualquer lugar."]}, "fala": {"en": ["{vilao} brought us here and has us forging the parts of {alvo} day and night. Whoever stops gets the whip. If the engine is finished, {povoado} falls first. Break the engine, and we all walk out together."], "pt": ["{vilao} nos trouxe para cá e nos faz forjar as peças de {alvo} dia e noite. Quem para leva chicotada. Se a máquina ficar pronta, {povoado} cai primeiro. Quebrem a máquina, e nós saímos juntos."]}, "pista": {"nome": {"en": "A smith's apron", "pt": "Um avental de ferreiro"}, "olhar": {"en": "A leather apron, scorched, left on the floor.", "pt": "Um avental de couro, queimado, largado no chão."}, "revela": {"en": "A leather apron has been left near the entrance.", "pt": "Há um avental de couro largado perto da entrada."}, "texto": {"en": ["The apron has the name of a smith of {povoado} sewn inside it. You can tell it was torn off by force: the straps are ripped. In the pocket is a paper with the measurements of parts, and at the top the name of the one who ordered them: {vilao}."], "pt": ["O avental tem o nome de um ferreiro de {povoado} costurado por dentro. Vocês percebem que foi arrancado à força, porque as tiras estão rasgadas. No bolso, um papel com medidas de peças, e no alto o nome de quem as encomendou: {vilao}."]}}, "ultima": {"en": ["{alvo} is nearly finished, and the smiths of {povoado} work in chains all around it. {vilao} keeps watch from above."], "pt": ["{alvo} está quase pront⟨alvo:o|a|os|as⟩, e os ferreiros de {povoado} trabalham acorrentados em volta. {vilao} vigia de cima."]}, "narr": {"en": ["As you come in, the smiths stop hammering, and they all look at you at the same moment."], "pt": ["Quando vocês entram, os ferreiros param de bater, e todos olham para vocês ao mesmo tempo."]}, "vil": {"en": ["Who told you to stop? Strike. And you there, do you know how to beat iron too?"], "pt": ["Quem mandou parar? Batam. Vocês aí, também sabem bater ferro?"]}, "hc": {"en": ["{povoado} wants its smiths back."], "pt": ["{povoado} quer os ferreiros de volta."]}, "hs": {"en": ["Today the iron beats you."], "pt": ["Hoje o ferro bate em você."]}, "fim": {"en": ["{alvo} collapses, and the smiths break one another's chains with their own tools."], "pt": ["{alvo} desaba, e os ferreiros soltam as correntes uns dos outros com as próprias ferramentas."]}, "fecho": {"en": ["In {povoado}, the forges are lit again, and the first thing the smiths make is a new lock for the village gate."], "pt": ["Em {povoado}, as forjas voltam a acender, e a primeira coisa que os ferreiros fazem é uma fechadura nova para a porta da vila."]}, "pa": {"en": ["Listen. Hammers."], "pt": ["Escutem. Martelos."]}, "pb": {"en": ["All striking in the same rhythm. Those are people who know their trade."], "pt": ["Batendo no mesmo ritmo. Isso é gente que sabe o que faz."]}, "entr": {"en": ["That hammer rhythm coming from {lugar} is a smith's. And do you see the chains left at the entrance?"], "pt": ["Esse ritmo de martelo vindo de {lugar} é de ferreiro. E estão vendo as correntes largadas na entrada?"]}, "chave": {"en": ["A smith cries out from deep inside, and the whip cracks. A moment later, the hammers start again, faster."], "pt": ["Um ferreiro grita lá do fundo, e o chicote estala. Logo depois, os martelos voltam a bater, mais depressa."]}, "chc": {"en": ["A smith cries out from deep inside, and the whip cracks. A moment later, the hammers start again, faster. They are the smiths of {povoado}, working in chains."], "pt": ["Um ferreiro grita lá do fundo, e o chicote estala. Logo depois, os martelos voltam a bater, mais depressa. São os ferreiros de {povoado}, trabalhando presos."]}, "chs": {"en": ["A smith cries out from deep inside, and the whip cracks. A moment later, the hammers start again, faster. The hammers on the road belonged to captive smiths."], "pt": ["Um ferreiro grita lá do fundo, e o chicote estala. Logo depois, os martelos voltam a bater, mais depressa. Os martelos da estrada eram de ferreiros presos."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance lies a smith's apron, with a name from {povoado} sewn inside it."], "pt": ["Na entrada, há um avental de ferreiro largado, com um nome de {povoado} costurado por dentro."]}}, {"t": "h", "txt": {"en": ["That hammer rhythm belongs to the smiths from the notice. I know how the people of that village strike."], "pt": ["Esse ritmo de martelo é dos ferreiros do aviso. Eu conheço o jeito de bater de gente da vila."]}}]}, "maquina/contagem": {"tit": {"en": ["Three Days to the Siege", "The Countdown of {vilao}", "Before the Attack"], "pt": ["Três Dias para o Cerco", "A Contagem de {vilao}", "Antes do Ataque"]}, "aviso": {"en": ["Help {povoado} {ate}. A deserter from the Legion says that {alvo} will be finished in three days, in {lugar}, and that the attack comes right after.", "Please reach {lugar} before the work is done. {alvo} of the Legion, the army surrounding the region, is nearly finished, and {povoado} lies right in its path.", "{povoado} has little time. The Legion, the army surrounding the region, has finished almost everything in {lugar}, and all that is left is to assemble {alvo}."], "pt": ["Ajudem {povoado} {ate}. Um desertor da Legião contou que {alvo} fica pront⟨alvo:o|a|os|as⟩ em três dias, em {lugar}, e que o ataque vem logo depois.", "Por favor, cheguem a {lugar} antes do fim da obra. {alvo} da Legião, o exército que cerca a região, está quase pront⟨alvo:o|a|os|as⟩, e {povoado} está bem no caminho.", "{povoado} tem pouco tempo. A Legião, o exército que cerca a região, terminou quase tudo em {lugar}, e só falta montar {alvo}."]}, "abert": {"en": ["The heroes reach {lugar}. Inside, the hammers are striking at a hurried pace."], "pt": ["Os heróis chegam a {lugar}. Lá dentro, os martelos batem num ritmo apressado."]}, "fala": {"en": ["They work in shifts, without a pause, because {vilao} has promised the attack for the day after tomorrow. Only the last parts are missing. If it is finished, {povoado} falls in a single night."], "pt": ["Eles trabalham em turnos, sem parar, porque {vilao} prometeu o ataque para depois de amanhã. Faltam só as últimas peças. Se ⟨alvo:ele|ela|eles|elas⟩ ficar pront⟨alvo:o|a|os|as⟩, {povoado} cai em uma noite."]}, "pista": {"nome": {"en": "A tally board", "pt": "Um quadro de contagem"}, "olhar": {"en": "A board with chalk strokes, counting the days.", "pt": "Uma tábua com riscos de giz, contando os dias."}, "revela": {"en": "A board marked with chalk stands near the entrance.", "pt": "Há uma tábua riscada perto da entrada."}, "texto": {"en": ["On the board is a tally of days in chalk, and only one stroke is missing to complete it. Beside each day is a part assembled, and at the top of the board an order: “Finished before the attack. {vilao}.”"], "pt": ["Na tábua há uma contagem de dias riscada a giz, e só falta um risco para completar. Ao lado de cada dia, uma peça montada, e no alto da tábua uma ordem: «Pront⟨alvo:o|a|os|as⟩ antes do ataque. {vilao}.»"]}}, "ultima": {"en": ["{alvo} is nearly finished, with only one part missing. {vilao} is holding that part in both hands."], "pt": ["{alvo} está quase pront⟨alvo:o|a|os|as⟩, e falta só uma peça. {vilao} a segura nas mãos."]}, "narr": {"en": ["As you come in, {vilao} lifts the last part, ready to fit it in place."], "pt": ["Quando vocês entram, {vilao} levanta a última peça, pronto para encaixá-la."]}, "vil": {"en": ["One part. Only one part is missing. You are just in time for the unveiling."], "pt": ["Uma peça. Só falta uma peça. Vocês chegaram para ver a inauguração."]}, "hc": {"en": ["{povoado} says it is canceled."], "pt": ["{povoado} manda cancelar."]}, "hs": {"en": ["That part stays with us."], "pt": ["Essa peça fica com a gente."]}, "fim": {"en": ["{alvo} collapses before it ever receives its last part, and the tally on the board stays unfinished forever."], "pt": ["{alvo} desaba antes de receber a última peça, e a contagem na tábua fica para sempre incompleta."]}, "fecho": {"en": ["In {povoado}, the night of the attack passes in silence, and the next morning the Legion pulls back."], "pt": ["Em {povoado}, a noite do ataque passa em silêncio, e na manhã seguinte a Legião recua."]}, "pa": {"en": ["Hammers, and fast ones."], "pt": ["Martelos, e rápidos."]}, "pb": {"en": ["Whoever hammers like that is late for something."], "pt": ["Quem martela assim está atrasado para alguma coisa."]}, "entr": {"en": ["Can you hear those hurried hammers in {lugar}? Someone is racing to finish something."], "pt": ["Estão ouvindo esses martelos apressados em {lugar}? Alguém está correndo para terminar alguma coisa."]}, "chave": {"en": ["A whistle sounds, and the hammers stop. Someone shouts that the last part has arrived."], "pt": ["Um apito soa, e os martelos param. Alguém grita que a última peça chegou."]}, "chc": {"en": ["A whistle sounds, and the hammers stop. Someone shouts that the last part has arrived. {alvo} will be finished sooner than the deserter said."], "pt": ["Um apito soa, e os martelos param. Alguém grita que a última peça chegou. {alvo} vai ficar pront⟨alvo:o|a|os|as⟩ antes do que o desertor disse."]}, "chs": {"en": ["A whistle sounds, and the hammers stop. Someone shouts that the last part has arrived. This is what the hurried hammers on the road meant: the work is nearly finished."], "pt": ["Um apito soa, e os martelos param. Alguém grita que a última peça chegou. A pressa dos martelos da estrada era esta: a obra está quase pronta."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance is a board with days marked off in chalk. Only one stroke is missing."], "pt": ["Na entrada, há uma tábua com dias riscados a giz. Falta só um risco."]}}, {"t": "h", "txt": {"en": ["The hammers are in a hurry. The notice was right: it is nearly finished."], "pt": ["Os martelos estão apressados. O aviso tinha razão: falta pouco para ficar pronto."]}}]}, "escolta/lua": {"tit": {"en": ["The Night of the Path", "Before the Path Closes", "New Moon over {lugar}"], "pt": ["A Noite do Caminho", "Antes que o Caminho Feche", "Lua Nova em {lugar}"]}, "aviso": {"en": ["Help us cross {lugar} tonight. The old path only opens at the new moon, and if we miss it, the people of {povoado} wait another month, and no one here has another month.", "Please escort our guide through {lugar} this very night. The path closes at dawn, and {vilao} knows it.", "{povoado} has one night only. The path through {lugar} opens at the new moon, and the one who knows how to open it needs protection to get there."], "pt": ["Ajudem a atravessar {lugar} esta noite. O velho caminho só se abre na lua nova, e se passarmos depois, o povo de {povoado} espera mais um mês, e esse mês ninguém aqui tem.", "Por favor, escoltem nosso guia através de {lugar} ainda hoje. O caminho fecha ao amanhecer, e {vilao} sabe disso.", "{povoado} tem uma noite só. O caminho por {lugar} se abre na lua nova, e quem sabe abri-lo precisa de proteção para chegar até lá."]}, "abert": {"en": ["The heroes follow the guide through the dark night of the new moon. The guide lights a small lantern and asks for silence."], "pt": ["Os heróis seguem quem guia pela noite escura de lua nova. Quem guia acende uma lanterna pequena e pede silêncio."]}, "intro": {"en": ["The path opens tonight and closes at dawn. {vilao} knows that, and will try to slow us down until sunrise. If the sun rises before we get there, {povoado} waits another month. Keep moving."], "pt": ["O caminho abre hoje e fecha ao amanhecer. {vilao} sabe disso, e vai tentar nos atrasar até o sol nascer. Se o sol nascer antes da gente chegar, {povoado} espera mais um mês. Andem."]}, "ultima": {"en": ["The way out is right there, and the first light of day is already showing in the sky. {vilao} waits in front of it."], "pt": ["A saída está logo ali, e no céu a primeira claridade do dia já aparece. {vilao} espera na frente dela."]}, "narr": {"en": ["The guide looks up at the sky, which is beginning to pale."], "pt": ["Quem guia olha para o céu, que começa a clarear."]}, "vil": {"en": ["The sun is on its way. All I have to do is wait."], "pt": ["O sol já vem vindo. Eu só preciso esperar."]}, "hc": {"en": ["Then we will not wait."], "pt": ["Então a gente não espera."]}, "hs": {"en": ["Then we will not wait."], "pt": ["Então a gente não espera."]}, "fim": {"en": ["On the far side, the three words are spoken at the last moment, and the path closes as the first ray of sun touches the stone."], "pt": ["Do outro lado, as três palavras são ditas no último instante, e o caminho se fecha quando o primeiro raio de sol toca a pedra."]}, "fecho": {"en": ["At the next new moon, the people of {povoado} cross in silence, and no one is left behind."], "pt": ["Na próxima lua nova, o povo de {povoado} atravessa em silêncio, e ninguém fica para trás."]}, "pa": {"en": ["It is too dark."], "pt": ["Está escuro demais."]}, "pb": {"en": ["It is the new moon. All the better, if no one sees us."], "pt": ["É lua nova. Melhor assim, se ninguém nos vir."]}, "entr": {"en": ["Our guide says the path through {lugar} only opens tonight. Do you see the lantern up ahead?"], "pt": ["Quem nos guia disse que o caminho por {lugar} só abre esta noite. Estão vendo a lanterna lá adiante?"]}, "chave": {"en": ["The sky begins to pale in the east. Dawn is not far off."], "pt": ["O céu começa a clarear do lado do leste. Falta pouco para o amanhecer."]}, "chc": {"en": ["The sky begins to pale in the east. Dawn is not far off. If day breaks before the crossing, the people of {povoado} wait another month."], "pt": ["O céu começa a clarear do lado do leste. Falta pouco para o amanhecer. Se o dia nascer antes da travessia, o povo de {povoado} espera mais um mês."]}, "chs": {"en": ["The sky begins to pale in the east. Dawn is not far off. With daylight, the darkness of the road ends, and the passage with it."], "pt": ["O céu começa a clarear do lado do leste. Falta pouco para o amanhecer. Com o dia, acaba a escuridão da estrada, e com ela a passagem."]}, "elos": [{"t": "n", "txt": {"en": ["On the stone at the entrance is a symbol of the old path, and it glows faintly, as it only does on moonless nights."], "pt": ["Na pedra da entrada, há um símbolo do velho caminho, e ele brilha fraco, como só brilha nas noites sem lua."]}}, {"t": "h", "txt": {"en": ["The new moon, just as the notice said. If the path only opens tonight, we had better start now."], "pt": ["Lua nova, como o aviso dizia. Se o caminho só abre hoje, é bom começarmos agora."]}}]}, "carga": {"tit": {"en": ["The Plundered Caravan", "What the Road Took", "The Wagons of {povoado}"], "pt": ["A Caravana Saqueada", "O Que a Estrada Levou", "As Carroças de {povoado}"]}, "aviso": {"en": ["Help {povoado} recover {alvo}. The wagons vanished on the road, and the wheel tracks leave the way and go into {lugar}.", "Please find our wagons. They were carrying {alvo} to {povoado}, and without ⟨alvo:it|it|them|them⟩ {gente} will not last the winter.", "{povoado} needs help {ate}. The caravan carrying {alvo} was attacked on the road, and the raiders took everything to {lugar}."], "pt": ["Ajudem {povoado} a recuperar {alvo}. As carroças sumiram na estrada, e as marcas de roda saem do caminho e entram em {lugar}.", "Por favor, achem as nossas carroças. Levavam {alvo} para {povoado}, e sem ⟨alvo:ele|ela|eles|elas⟩ {gente} não passam do inverno.", "{povoado} precisa de ajuda {ate}. A caravana com {alvo} foi atacada na estrada, e os saqueadores levaram tudo para {lugar}."]}, "abert": {"en": ["The heroes follow the wheel tracks, which leave the road and go straight into {lugar}."], "pt": ["Os heróis seguem as marcas de roda, que saem da estrada e entram direto em {lugar}."]}, "fala": {"en": ["I was the carter. {vilao} gathered the raiders of the road and fell on the caravan at the bend of the river. They dragged the crates inside. They do not even know the worth of what they took: they are opening everything to see if it is drink."], "pt": ["Eu era o carroceiro. {vilao} juntou os saqueadores da estrada e caiu em cima da caravana na curva do rio. Arrastaram os caixotes para dentro. Eles nem sabem o valor do que levaram: estão abrindo tudo para ver se é bebida."]}, "pista": {"nome": {"en": "A broken wheel", "pt": "Uma roda quebrada"}, "olhar": {"en": "A wagon wheel, cracked, in the colors of the caravan.", "pt": "Uma roda de carroça, rachada, com as cores da caravana."}, "revela": {"en": "A broken wheel lies near the entrance.", "pt": "Há uma roda quebrada perto da entrada."}, "texto": {"en": ["The axle of the wheel was cut clean through, on purpose, to stop the wagon right there. Over the colors of the caravan, someone has hastily painted another mark, a crow with its wings spread. On the road, everyone knows the crow: it is the sign of the band of {vilao}."], "pt": ["O eixo da roda foi cortado rente, de propósito, para a carroça parar ali. Por cima das cores da caravana, alguém pintou às pressas outra marca, um corvo de asas abertas. Na estrada, todo mundo conhece o corvo: é o sinal do bando de {vilao}."]}}, "ultima": {"en": ["The last crates are stacked up, and {vilao} sits on top of them, eating bread that belonged to {povoado}."], "pt": ["Os últimos caixotes estão empilhados, e {vilao} está sentad⟨vilao:o|a⟩ em cima deles, comendo um pão que era de {povoado}."]}, "narr": {"en": ["As you come in, {vilao} wipes a sleeve across a full mouth."], "pt": ["Quando vocês entram, {vilao} limpa a boca com a manga."]}, "vil": {"en": ["Want a piece? For now, there is enough for everyone."], "pt": ["Querem um pedaço? Por enquanto, tem para todo mundo."]}, "hc": {"en": ["That bread has an owner."], "pt": ["Esse pão tem dono."]}, "hs": {"en": ["We want all of it."], "pt": ["Queremos tudo."]}, "fim": {"en": ["The crates go back onto the wagons, nearly all of them whole. One is half empty, and one of the raiders, lying nearby, looks very pleased with himself."], "pt": ["Os caixotes voltam às carroças, quase todos inteiros. Um está pela metade, e um dos saqueadores, caído ali perto, parece muito satisfeito."]}, "fecho": {"en": ["In {povoado}, {alvo} ⟨alvo:arrives|arrives|arrive|arrive⟩ that very night, and {gente} help unload the wagons without anyone asking."], "pt": ["Em {povoado}, {alvo} ⟨alvo:chega|chega|chegam|chegam⟩ naquela mesma noite, e {gente} ajudam a descarregar as carroças sem que ninguém peça."]}, "pa": {"en": ["A broken wheel, and the axle cut clean through."], "pt": ["Uma roda quebrada, e o eixo cortado rente."]}, "pb": {"en": ["Cut. Someone stopped this wagon on purpose."], "pt": ["Cortado. Alguém parou essa carroça de propósito."]}, "entr": {"en": ["The wheel tracks leave the road and go into {lugar}. Look at this empty crate at the entrance: it bears the mark of a caravan."], "pt": ["As marcas de roda saem da estrada e entram em {lugar}. Olhem esse caixote vazio na entrada: tem a marca de uma caravana."]}, "chave": {"en": ["You find a crate with the mark of the caravan, empty and split for firewood. It seems they are burning what they could not sell."], "pt": ["Vocês acham um caixote com a marca da caravana, vazio e rachado para lenha. Parece que estão queimando o que não conseguiram vender."]}, "chc": {"en": ["You find a crate with the mark of the caravan, empty and split for firewood. It is one of the crates of {povoado}. It seems they are burning what they could not sell."], "pt": ["Vocês acham um caixote com a marca da caravana, vazio e rachado para lenha. É um dos caixotes de {povoado}. Parece que estão queimando o que não conseguiram vender."]}, "chs": {"en": ["You find a crate with the mark of the caravan, empty and split for firewood. The wagon with the cut axle, on the road, was carrying crates like this one. It seems they are burning what they could not sell."], "pt": ["Vocês acham um caixote com a marca da caravana, vazio e rachado para lenha. A carroça do eixo cortado, na estrada, levava caixotes como este. Parece que estão queimando o que não conseguiram vender."]}, "elos": [{"t": "h", "txt": {"en": ["A broken crate, with the mark of the caravan from the notice. The rest of the cargo went in here."], "pt": ["Um caixote quebrado, com a marca da caravana do aviso. O resto da carga entrou aqui."]}}, {"t": "n", "txt": {"en": ["At the entrance lies a torn piece of canvas, with the name of {povoado} painted in large letters."], "pt": ["Na entrada, há um pedaço de lona rasgado, com o nome de {povoado} pintado em letras grandes."]}}]}, "carga/sal": {"tit": {"en": ["The Salt of {povoado}", "At Three Times the Price", "Before the Snow"], "pt": ["O Sal de {povoado}", "Pelo Triplo do Preço", "Antes da Neve"]}, "aviso": {"en": ["Help {povoado} before winter. The salt wagons are stuck on the far side of the bridge near {lugar}, and without salt the meat will rot before the snow.", "Please bring the salt of {povoado}. It was already paid for, but someone has taken the bridge at {lugar} and wants to sell it all over again.", "{povoado} needs the salt {ate}. The wagons stopped near {lugar} and never moved again."], "pt": ["Ajudem {povoado} antes do inverno. As carroças de sal ficaram presas do outro lado da ponte perto de {lugar}, e sem sal a carne apodrece antes da neve.", "Por favor, tragam o sal de {povoado}. Ele já estava pago, mas alguém tomou a ponte de {lugar} e quer vendê-lo de novo.", "{povoado} precisa do sal {ate}. As carroças pararam perto de {lugar} e nunca mais andaram."]}, "abert": {"en": ["The heroes reach the bridge of the salt wagons, near {lugar}."], "pt": ["Os heróis chegam à ponte das carroças de sal, perto de {lugar}."]}, "fala": {"en": ["They took the bridge at the end of summer and carried the salt inside. Now {vilao} wants to sell {povoado} its own salt, at three times the price. There is even a price list nailed to the wall."], "pt": ["Tomaram a ponte no fim do verão e levaram o sal para dentro. Agora {vilao} quer vender o próprio sal a {povoado}, pelo triplo do preço. Já tem até tabela pregada na parede."]}, "pista": {"nome": {"en": "A broken wheel", "pt": "Uma roda quebrada"}, "olhar": {"en": "A wagon wheel, with salt caked on the spokes.", "pt": "Uma roda de carroça, com sal grudado nos raios."}, "revela": {"en": "A broken wheel lies near the entrance.", "pt": "Há uma roda quebrada perto da entrada."}, "texto": {"en": ["The wheel is from one of the salt wagons: there is still salt caked on the spokes, and someone tore it off so that the wagon would stay put. Beside it, nailed to the wall, is a price list with every number tripled, and a heading in large letters: “Salt of {vilao}.”"], "pt": ["A roda é de uma das carroças de sal, porque ainda há sal grudado nos raios, e alguém a arrancou para que a carroça ficasse. Ao lado, pregada na parede, há uma tabela de preços com os números aumentados três vezes, e um título em letra grande: «Sal de {vilao}.»"]}}, "ultima": {"en": ["The sacks of salt are stacked to the ceiling, and {vilao} is checking the price list."], "pt": ["Os sacos de sal estão empilhados até o teto, e {vilao} confere a tabela de preços."]}, "narr": {"en": ["As you come in, {vilao} raises one more number on the list."], "pt": ["Quando vocês entram, {vilao} aumenta mais um número na tabela."]}, "vil": {"en": ["Customers? The price just went up."], "pt": ["Clientes? O preço acabou de subir."]}, "hc": {"en": ["That salt has already been paid for."], "pt": ["Esse sal já foi pago."]}, "hs": {"en": ["Today it is free."], "pt": ["Hoje é de graça."]}, "fim": {"en": ["The sacks of salt leave stacked on the wagons, which creak under the weight. The price list stays behind, nailed to the wall."], "pt": ["Os sacos de sal saem empilhados nas carroças, que rangem com o peso. A tabela de preços fica para trás, pregada na parede."]}, "fecho": {"en": ["In {povoado}, the meat is already hanging in wait, and the smell of the smokehouse rises before nightfall."], "pt": ["Em {povoado}, a carne já espera pendurada, e o cheiro de defumado sobe antes do anoitecer."]}, "pa": {"en": ["Is that salt on the ground?"], "pt": ["Isto no chão é sal?"]}, "pb": {"en": ["Spilled salt is bad luck. Stolen salt, even more so."], "pt": ["Sal derramado dá azar. Sal roubado, mais ainda."]}, "entr": {"en": ["There is salt on the ground, in a trail that leads into {lugar}."], "pt": ["Tem sal no chão, num rastro que entra em {lugar}."]}, "chave": {"en": ["On the wall is a price list, with the numbers crossed out and raised. Someone means to profit from other people's winter."], "pt": ["Na parede há uma tabela de preços, com os números riscados e aumentados. Alguém quer lucrar com o inverno dos outros."]}, "chc": {"en": ["On the wall is a price list, with the numbers crossed out and raised. Someone means to profit from other people's winter. It is the salt of {povoado}, and someone means to sell it dear."], "pt": ["Na parede há uma tabela de preços, com os números riscados e aumentados. Alguém quer lucrar com o inverno dos outros. É o sal de {povoado}, e alguém quer vendê-lo caro."]}, "chs": {"en": ["On the wall is a price list, with the numbers crossed out and raised. Someone means to profit from other people's winter. The salt spilled on the road came from this stolen cargo."], "pt": ["Na parede há uma tabela de preços, com os números riscados e aumentados. Alguém quer lucrar com o inverno dos outros. O sal derramado na estrada era desta carga roubada."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance, the ground is white with salt, in a trail leading inside."], "pt": ["Na entrada, o chão está branco de sal, num rastro que vai para dentro."]}}, {"t": "h", "txt": {"en": ["Salt on the ground. The wagons of {povoado} came through here, and they are leaking."], "pt": ["Sal no chão. As carroças de {povoado} passaram por aqui, e estão vazando."]}}]}, "carga/fantasma": {"tit": {"en": ["The Empty Caravan", "The Carters Who Forgot", "What Vanished from the Wagons"], "pt": ["A Caravana Vazia", "Os Carroceiros que Esqueceram", "O Que Sumiu das Carroças"]}, "aviso": {"en": ["Help {povoado} understand what happened. The caravan carrying {alvo} arrived empty, and the carters remember nothing after {lugar}.", "Please find out what happened in {lugar}. The wagons of {povoado} went through there full and came out empty, and those who drove them weep now and then without knowing why.", "{povoado} needs help. {desde}, the caravans that pass through {lugar} have been arriving without their cargo and without their memory."], "pt": ["Ajudem {povoado} a entender o que houve. A caravana com {alvo} chegou vazia, e os carroceiros não lembram de nada desde {lugar}.", "Por favor, descubram o que aconteceu em {lugar}. As carroças de {povoado} passaram por lá cheias e saíram vazias, e quem as conduzia volta e meia chora sem saber por quê.", "{povoado} precisa de ajuda. {desde}, as caravanas que passam por {lugar} chegam sem a carga e sem a memória."]}, "abert": {"en": ["The heroes follow the wheel tracks to {lugar}. They go in deep, from a loaded wagon, and come out shallow, from an empty one."], "pt": ["Os heróis seguem as marcas de roda até {lugar}. Elas entram fundas, de carroça pesada, e saem rasas, de carroça vazia."]}, "fala": {"en": ["We stopped here to ask for water, and the one who welcomed us was {vilao}, with a sweet-smelling tea. After that, all I remember is waking up on the road. The cargo stayed in here, and I think the other carters left something behind as well: their memory."], "pt": ["Paramos aqui para pedir água, e quem nos recebeu foi {vilao}, com um chá de cheiro doce. Depois disso, eu só lembro de acordar na estrada. A carga ficou aqui dentro, e acho que os outros carroceiros também deixaram alguma coisa: a memória."]}, "pista": {"nome": {"en": "A cup of tea", "pt": "Uma xícara de chá"}, "olhar": {"en": "A clay cup, with the dregs of a sweet-smelling tea.", "pt": "Uma xícara de barro, com um resto de chá de cheiro doce."}, "revela": {"en": "A cup has been forgotten near the entrance.", "pt": "Há uma xícara esquecida perto da entrada."}, "texto": {"en": ["The tea smells far too sweet, and you can tell it was served to many people: other cups just like it are scattered across the floor. On the bottom of one of them, pressed into the clay, is the mark of their maker: {vilao}."], "pt": ["O chá tem um cheiro doce demais, e vocês percebem que alguém o serviu a muita gente, porque há outras xícaras iguais espalhadas pelo chão. No fundo de uma delas, gravada no barro, a marca de quem as fez: {vilao}."]}}, "ultima": {"en": ["The cargo is stacked at the back, and {vilao} is brewing more tea in a cauldron."], "pt": ["A carga está empilhada no fundo, e {vilao} prepara mais chá num caldeirão."]}, "narr": {"en": ["As you come in, {vilao} fills a cup and holds it out to you."], "pt": ["Quando vocês entram, {vilao} enche uma xícara e estende para vocês."]}, "vil": {"en": ["Tired from the journey? Drink. It will help you forget."], "pt": ["Estão cansados da viagem? Bebam. Vai ajudar a esquecer."]}, "hc": {"en": ["We came to remember, on behalf of {povoado}."], "pt": ["Viemos lembrar por {povoado}."]}, "hs": {"en": ["Thank you, but we brought water."], "pt": ["Obrigado, mas trouxemos água."]}, "fim": {"en": ["The cargo is all there, and when you pour the tea out on the floor, one of the carters hidden at the back begins to remember his own name."], "pt": ["A carga está toda lá, e quando vocês derramam o chá no chão, um dos carroceiros escondidos no fundo começa a lembrar o próprio nome."]}, "fecho": {"en": ["In {povoado}, {alvo} ⟨alvo:arrives|arrives|arrive|arrive⟩ with the carters, and each of them tells a different piece of what he has remembered."], "pt": ["Em {povoado}, {alvo} ⟨alvo:chega|chega|chegam|chegam⟩ com os carroceiros, e cada um conta um pedaço diferente do que lembrou."]}, "pa": {"en": ["Wheel tracks, deep ones here."], "pt": ["Marcas de roda, fundas aqui."]}, "pb": {"en": ["And shallow farther on. The cargo stayed somewhere in between."], "pt": ["E rasas lá adiante. A carga ficou em algum lugar no meio."]}, "entr": {"en": ["The wheel tracks go into {lugar} deep and come out shallow. Can you smell that sweetness coming from inside?"], "pt": ["As marcas de roda entram em {lugar} fundas e saem rasas. Sentem esse cheiro doce vindo lá de dentro?"]}, "chave": {"en": ["The sweet smell grows stronger, and one of you feels your head grow heavy. It seems the tea of {vilao} is in the air."], "pt": ["O cheiro doce fica mais forte, e um de vocês sente a cabeça pesar. Parece que o chá de {vilao} está no ar."]}, "chc": {"en": ["The sweet smell grows stronger, and one of you feels your head grow heavy. It seems the tea of {vilao} is in the air. This is why the carters of {povoado} lost their memory."], "pt": ["O cheiro doce fica mais forte, e um de vocês sente a cabeça pesar. Parece que o chá de {vilao} está no ar. É por isso que os carroceiros de {povoado} perderam a memória."]}, "chs": {"en": ["The sweet smell grows stronger, and one of you feels your head grow heavy. It seems the tea of {vilao} is in the air. This is where the cargo from the deep tracks was left."], "pt": ["O cheiro doce fica mais forte, e um de vocês sente a cabeça pesar. Parece que o chá de {vilao} está no ar. Era aqui que a carga das marcas fundas ficava."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance is a clay cup with the dregs of a sweet-smelling tea. Beside it lies the hat of a carter from {povoado}."], "pt": ["Na entrada, há uma xícara de barro com um resto de chá de cheiro doce. Ao lado, um chapéu de carroceiro de {povoado}."]}}, {"t": "h", "txt": {"en": ["Can you smell that sweetness? The carters from the notice lost their memory, and that must be the cause."], "pt": ["Sentem esse cheiro doce? Os carroceiros do aviso perderam a memória, e deve ser por causa dele."]}}]}, "tenente": {"tit": {"en": ["Sealed Orders", "The Messenger of {vilao}", "Before Nightfall"], "pt": ["Ordens Lacradas", "O Mensageiro de {vilao}", "Antes do Anoitecer"]}, "aviso": {"en": ["Help {povoado}. The Legion, the army surrounding the region, is preparing an attack, and {alvo} ⟨alvo:is|is|are|are⟩ on the way to the troops. Whoever reaches ⟨alvo:it|it|them|them⟩ first will know where the blow is going to fall.", "Please intercept {alvo} of the Legion, the army surrounding the region. ⟨alvo:It passes|It passes|They pass|They pass⟩ through {lugar} {ate}, and {povoado} needs to know what ⟨alvo:it says|it says|they say|they say⟩.", "{povoado} needs discreet people. {alvo} of the Legion ⟨alvo:is|is|are|are⟩ being kept in {lugar} until nightfall."], "pt": ["Ajudem {povoado}. A Legião, o exército que cerca a região, prepara um ataque, e {alvo} ⟨alvo:está|está|estão|estão⟩ a caminho das tropas. Quem chegar até ⟨alvo:ele|ela|eles|elas⟩ primeiro saberá onde o golpe vai cair.", "Por favor, interceptem {alvo} da Legião, o exército que cerca a região. ⟨alvo:Passa|Passa|Passam|Passam⟩ por {lugar} {ate}, e {povoado} precisa saber o que ⟨alvo:diz|diz|dizem|dizem⟩.", "{povoado} precisa de gente discreta. {alvo} da Legião ⟨alvo:está|está|estão|estão⟩ guardad⟨alvo:o|a|os|as⟩ em {lugar} até o anoitecer."]}, "abert": {"en": ["The heroes follow at a distance a Legion patrol heading for {lugar}."], "pt": ["Os heróis seguem de longe uma patrulha da Legião que passa rumo a {lugar}."]}, "fala": {"en": ["The rider arrived last night, with a scroll sealed in red wax. {vilao} keeps {alvo} close at hand and leaves at nightfall. You have until then. Once you are seen, it will be a race."], "pt": ["O cavaleiro chegou ontem à noite, com um rolo selado em cera vermelha. {vilao} guarda {alvo} consigo e parte ao anoitecer. Vocês têm até lá. Depois que forem vistos, vai ser uma corrida."]}, "pista": {"nome": {"en": "A dropped dispatch", "pt": "Um despacho caído"}, "olhar": {"en": "A dispatch case, dropped in a hurry.", "pt": "Um estojo de despachos, largado às pressas."}, "revela": {"en": "A leather case lies near the entrance.", "pt": "Há um estojo de couro caído perto da entrada."}, "texto": {"en": ["The case holds a half-burnt dispatch, and its edges are still warm: someone tried to destroy it and fled before finishing. What is left is a list of names with guard hours. At the top is the order of the day: “No one comes near {vilao} until the departure, at nightfall.”"], "pt": ["O estojo tem um despacho meio queimado, e as bordas ainda estão quentes: alguém tentou destruí-lo e fugiu antes de terminar. O que sobrou é uma lista de nomes com horários de guarda. No alto, a ordem do dia: «Ninguém se aproxima de {vilao} até a partida, ao anoitecer.»"]}}, "ultima": {"en": ["There is a saddled horse and a lit lantern, and {vilao} is holding {alvo}."], "pt": ["Há um cavalo selado e uma lanterna acesa, e {vilao} segura {alvo}."]}, "narr": {"en": ["As you come in, {vilao} thrusts {alvo} into the saddlebag."], "pt": ["Quando vocês entram, {vilao} enfia {alvo} na sela."]}, "vil": {"en": ["You have seen what you should not have."], "pt": ["Vocês viram o que não deviam."]}, "hc": {"en": ["{povoado} sent us to collect the mail."], "pt": ["{povoado} mandou buscar a correspondência."]}, "hs": {"en": ["Then let us read the rest."], "pt": ["Então vamos ler o resto."]}, "fim": {"en": ["The seal breaks in your hands. There it is, map and all: the place where the blow was going to fall, and the hour."], "pt": ["O lacre se parte nas mãos de vocês. Ali está, com mapa e tudo, o lugar onde o golpe ia cair, e a hora."]}, "fecho": {"en": ["In {povoado}, the Legion will find the defense exactly where it was counting on finding none."], "pt": ["Em {povoado}, a Legião vai encontrar a defesa exatamente onde contava com o vazio."]}, "pa": {"en": ["A rider went by at a gallop, with no banner."], "pt": ["Um cavaleiro passou a galope, sem estandarte."]}, "pb": {"en": ["A rider with no banner carries what no one is meant to read."], "pt": ["Cavaleiro sem estandarte leva o que ninguém deve ler."]}, "entr": {"en": ["There is a horse tied up at the entrance of {lugar}, with a Legion saddle. The tracks we were following end here."], "pt": ["Tem um cavalo amarrado na entrada de {lugar}, com a sela da Legião. As marcas que seguíamos terminam aqui."]}, "chave": {"en": ["Someone is saddling a horse farther on. {vilao} is about to leave."], "pt": ["Alguém sela um cavalo mais adiante. {vilao} está de partida."]}, "chc": {"en": ["Someone is saddling a horse farther on. {vilao} is about to leave. {vilao} is about to carry {alvo} away."], "pt": ["Alguém sela um cavalo mais adiante. {vilao} está de partida. {vilao} vai levar {alvo}."]}, "chs": {"en": ["Someone is saddling a horse farther on. {vilao} is about to leave. {vilao} is carrying off what the rider with no banner brought."], "pt": ["Alguém sela um cavalo mais adiante. {vilao} está de partida. {vilao} leva o que o cavaleiro sem estandarte trouxe."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance, a horse with a Legion saddle is tied up, still lathered in sweat. The rider arrived not long ago."], "pt": ["Na entrada, há um cavalo amarrado com a sela da Legião, ainda suado. O cavaleiro chegou faz pouco tempo."]}}, {"t": "h", "txt": {"en": ["The tracks we followed end here. What the notice asked us to fetch is in there."], "pt": ["As marcas que seguimos terminam aqui. O que o aviso pediu para buscar está lá dentro."]}}]}, "tenente/desertor": {"tit": {"en": ["The Deserter", "The Offer at {lugar}", "Who Changed Sides"], "pt": ["O Desertor", "A Oferta de {lugar}", "Quem Trocou de Lado"]}, "aviso": {"en": ["Help {povoado}. A deserter from the Legion, the army surrounding the region, has fled with {alvo} and wants to hand ⟨alvo:it|it|them|them⟩ over to us, but he has been surrounded in {lugar}.", "Please reach the deserter before the Legion does. He is hiding in {lugar} with {alvo}, and the Legion is after him.", "{povoado} has received a message from a deserter of the Legion: he has {alvo} and wants to trade for his own life. He is waiting in {lugar}, and he will not wait long."], "pt": ["Ajudem {povoado}. Um desertor da Legião, o exército que cerca a região, fugiu com {alvo} e quer ⟨alvo:entregá-lo|entregá-la|entregá-los|entregá-las⟩ a nós, mas foi cercado em {lugar}.", "Por favor, cheguem ao desertor antes da Legião. Ele está escondido em {lugar} com {alvo}, e a Legião está atrás dele.", "{povoado} recebeu um recado de um desertor da Legião: tem {alvo} e quer trocar pela própria vida. Ele espera em {lugar}, e não vai esperar muito."]}, "abert": {"en": ["The heroes reach {lugar} and find signs of a struggle at the entrance. A trail of blood leads deep inside."], "pt": ["Os heróis chegam a {lugar} e acham marcas de luta na entrada. Um rastro de sangue entra para o fundo."]}, "fala": {"en": ["The deserter hid deep inside with {alvo}, but {vilao} came after him with half a garrison. If they catch him, {alvo} ⟨alvo:goes|goes|go|go⟩ back to the Legion, and the deserter goes to the gallows. Get there before they do."], "pt": ["O desertor se escondeu lá no fundo com {alvo}, mas {vilao} veio atrás dele com meia guarnição. Se o pegarem, {alvo} ⟨alvo:volta|volta|voltam|voltam⟩ para a Legião, e o desertor vai para a forca. Cheguem antes deles."]}, "pista": {"nome": {"en": "A Legion shield", "pt": "Um escudo da Legião"}, "olhar": {"en": "A shield with the crest of the Legion, abandoned and scratched.", "pt": "Um escudo com o brasão da Legião, largado e arranhado."}, "revela": {"en": "A shield has been left near the entrance.", "pt": "Há um escudo largado perto da entrada."}, "texto": {"en": ["The shield was dropped by someone who had to run, and the crest was scratched out on purpose, with the point of a knife: it is the deserter's shield. Beside it are the prints of soldiers' boots, a great many, and an order nailed to the wall: “Alive or dead, and {alvo} unharmed. {vilao}.”"], "pt": ["O escudo foi largado por quem precisava correr, e o brasão foi arranhado de propósito, com a ponta de uma faca: é o escudo do desertor. Ao lado, pegadas de botas de soldado, muitas, e uma ordem pregada na parede: «Vivo ou morto, e {alvo} intact⟨alvo:o|a|os|as⟩. {vilao}.»"]}}, "ultima": {"en": ["The deserter is cornered at the back, clutching {alvo}. In front of him stands {vilao}, sword in hand."], "pt": ["O desertor está encurralado no fundo, abraçado a {alvo}. Na frente dele está {vilao}, de espada na mão."]}, "narr": {"en": ["As you come in, the deserter looks at you like a man who cannot tell whether help has arrived or more enemies."], "pt": ["Quando vocês entram, o desertor olha para vocês como quem não sabe se chegou ajuda ou mais inimigos."]}, "vil": {"en": ["That traitor is mine. And so is what he carries."], "pt": ["Esse traidor é meu. E o que ele carrega também."]}, "hc": {"en": ["{povoado} wants both in one piece."], "pt": ["{povoado} quer os dois inteiros."]}, "hs": {"en": ["He is coming with us."], "pt": ["Ele vem com a gente."]}, "fim": {"en": ["The deserter hands over {alvo} with shaking hands, and asks only one thing: that no one tell where he is going."], "pt": ["O desertor entrega {alvo} com as mãos tremendo, e pede só uma coisa: que ninguém conte para onde ele vai."]}, "fecho": {"en": ["In {povoado}, {alvo} ⟨alvo:is|is|are|are⟩ read by candlelight, and the defense of the town is moved that very night."], "pt": ["Em {povoado}, {alvo} ⟨alvo:é|é|são|são⟩ lid⟨alvo:o|a|os|as⟩ à luz de vela, e a defesa da cidade muda de lugar naquela mesma noite."]}, "pa": {"en": ["A Legion shield, left on the road."], "pt": ["Um escudo da Legião, largado na estrada."]}, "pb": {"en": ["With the crest scratched out. Someone no longer wants to belong to the Legion."], "pt": ["Com o brasão arranhado. Alguém não quer mais ser da Legião."]}, "entr": {"en": ["There is a trail of blood going into {lugar}, and the marks of many boots behind it."], "pt": ["Tem um rastro de sangue entrando em {lugar}, e marcas de muitas botas atrás dele."]}, "chave": {"en": ["From deep inside comes a soldier's shout: “I have found his trail!” The Legion is reaching the deserter before you."], "pt": ["Lá do fundo vem um grito de soldado: «Achei o rastro dele!» A Legião está chegando ao desertor antes de vocês."]}, "chc": {"en": ["From deep inside comes a soldier's shout: “I have found his trail!” The Legion is reaching the deserter before you. The deserter still has {alvo}."], "pt": ["Lá do fundo vem um grito de soldado: «Achei o rastro dele!» A Legião está chegando ao desertor antes de vocês. O desertor ainda tem {alvo}."]}, "chs": {"en": ["From deep inside comes a soldier's shout: “I have found his trail!” The Legion is reaching the deserter before you. The owner of the shield left on the road is this deserter."], "pt": ["Lá do fundo vem um grito de soldado: «Achei o rastro dele!» A Legião está chegando ao desertor antes de vocês. O dono do escudo largado na estrada é este desertor."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance, a Legion shield lies on the ground, its crest scratched out with a knife."], "pt": ["Na entrada, há um escudo da Legião largado no chão, com o brasão arranhado a faca."]}}, {"t": "h", "txt": {"en": ["Those boots behind the trail are the Legion's. They are hunting the deserter from the notice."], "pt": ["Essas botas atrás do rastro são da Legião. Estão caçando o desertor do aviso."]}}]}, "tenente/mapa": {"tit": {"en": ["Sold to the Legion", "The Traitor of {povoado}", "Before It Reaches the Troops"], "pt": ["Vendido à Legião", "O Traidor de {povoado}", "Antes que Chegue às Tropas"]}, "aviso": {"en": ["Help {povoado}. Someone inside the village has sold {alvo} to the Legion, the army surrounding the region, and the handover will take place in {lugar} {ate}.", "Please stop the handover in {lugar}. {alvo} of {povoado} ⟨alvo:has|has|have|have⟩ been sold, and the Legion will know exactly where to attack.", "{povoado} has been sold out. {alvo} ⟨alvo:is|is|are|are⟩ in {lugar}, waiting to be collected, and the one coming to collect is the Legion."], "pt": ["Ajudem {povoado}. Alguém de dentro da vila vendeu {alvo} à Legião, o exército que cerca a região, e a entrega vai ser feita em {lugar} {ate}.", "Por favor, impeçam a entrega em {lugar}. {alvo} de {povoado} ⟨alvo:foi|foi|foram|foram⟩ vendid⟨alvo:o|a|os|as⟩, e a Legião vai saber exatamente onde atacar.", "{povoado} foi vendid⟨povoado:o|a⟩. {alvo} ⟨alvo:está|está|estão|estão⟩ em {lugar}, esperando quem venha buscar, e quem vem buscar é a Legião."]}, "abert": {"en": ["The heroes reach {lugar} before nightfall. Inside, someone is counting coins aloud."], "pt": ["Os heróis chegam a {lugar} antes do anoitecer. Lá dentro, alguém conta moedas em voz alta."]}, "fala": {"en": ["The buyer of {alvo} is {vilao}, an officer of the Legion, and the seller is someone from {povoado}. The exchange is at nightfall, deep inside. If {vilao} leaves here with {alvo}, {povoado} falls within a week."], "pt": ["Quem comprou {alvo} foi {vilao}, oficial da Legião, e quem vendeu é gente de {povoado}. A troca é ao anoitecer, lá no fundo. Se {vilao} sair daqui com {alvo}, {povoado} cai em uma semana."]}, "pista": {"nome": {"en": "A purse of coins", "pt": "Uma bolsa de moedas"}, "olhar": {"en": "A leather purse, heavy, full of Legion coins.", "pt": "Uma bolsa de couro, pesada, com moedas da Legião."}, "revela": {"en": "A purse lies near the entrance.", "pt": "Há uma bolsa caída perto da entrada."}, "texto": {"en": ["The purse holds coins minted by the Legion, and it fell from the belt of someone in a hurry. Inside is a folded receipt: “Payment for {alvo}, half now, half on delivery.” Signed: {vilao}."], "pt": ["A bolsa tem moedas cunhadas pela Legião, e caiu do cinto de alguém com pressa. Dentro, um recibo dobrado: «Pagamento por {alvo}, metade agora, metade na entrega.» Assinado: {vilao}."]}}, "ultima": {"en": ["On a table ⟨alvo:lies|lies|lie|lie⟩ {alvo}, and to one side {vilao} is counting out the payment."], "pt": ["Sobre uma mesa está {alvo}, e de um lado {vilao} conta o pagamento."]}, "narr": {"en": ["As you come in, {vilao} covers {alvo} with one hand."], "pt": ["Quando vocês entram, {vilao} cobre {alvo} com a mão."]}, "vil": {"en": ["The deal is done. You are too late."], "pt": ["Negócio fechado. Vocês chegaram atrasados."]}, "hc": {"en": ["{povoado} is calling the deal off."], "pt": ["{povoado} desfaz o negócio."]}, "hs": {"en": ["The deal just fell through."], "pt": ["O negócio acabou de desandar."]}, "fim": {"en": ["{alvo} ⟨alvo:is|is|are|are⟩ back in your hands, still whole. The Legion will wait for a delivery that is never going to come."], "pt": ["{alvo} ⟨alvo:volta|volta|voltam|voltam⟩ para as mãos de vocês, ainda inteir⟨alvo:o|a|os|as⟩. A Legião vai esperar uma entrega que não vai chegar."]}, "fecho": {"en": ["In {povoado}, the seller's name runs through the streets before dawn, and the guard changes every watch."], "pt": ["Em {povoado}, o nome do vendedor corre as ruas antes do amanhecer, e a guarda muda todos os turnos."]}, "pa": {"en": ["Legion coins in the middle of the road."], "pt": ["Moedas da Legião no meio da estrada."]}, "pb": {"en": ["Someone is paying dearly for something."], "pt": ["Alguém está pagando caro por alguma coisa."]}, "entr": {"en": ["There is a purse of Legion coins lying at the entrance of {lugar}. Can you hear someone counting money in there?"], "pt": ["Tem uma bolsa de moedas da Legião caída na entrada de {lugar}. Estão ouvindo alguém contando dinheiro lá dentro?"]}, "chave": {"en": ["A whistle from outside: the Legion's escort has come to collect {alvo}."], "pt": ["Um assobio do lado de fora: a escolta da Legião chegou para buscar {alvo}."]}, "chc": {"en": ["A whistle from outside: the Legion's escort has come to collect {alvo}. The handover the notice spoke of is about to happen."], "pt": ["Um assobio do lado de fora: a escolta da Legião chegou para buscar {alvo}. A entrega de que o aviso falava vai ser agora."]}, "chs": {"en": ["A whistle from outside: the Legion's escort has come to collect {alvo}. The coins on the road were the payment."], "pt": ["Um assobio do lado de fora: a escolta da Legião chegou para buscar {alvo}. As moedas da estrada eram o pagamento."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance lies a purse of Legion coins, still tied shut."], "pt": ["Na entrada, há uma bolsa de moedas da Legião caída, ainda amarrada."]}}, {"t": "h", "txt": {"en": ["Legion coins. The sale the notice spoke of is going to happen here."], "pt": ["Moedas da Legião. A venda de que o aviso falava vai acontecer aqui."]}}]}, "pocos": {"tit": {"en": ["The Springs of {lugar}", "The Black Water", "The Plague of the Springs"], "pt": ["As Fontes de {lugar}", "A Água Negra", "A Praga das Nascentes"]}, "aviso": {"en": ["Help {povoado}. Whoever drinks the water that comes from {lugar} falls sick, and {desde} {sinal}.", "Please cleanse {alvo} of {lugar}. The water from there runs down to {povoado}, and {gente} {gentefaz}.", "{povoado} is calling for help. The water has been black {desde}, and whoever drinks it dies and then rises again."], "pt": ["Ajudem {povoado}. Quem bebe da água que vem de {lugar} adoece, e {desde} {sinal}.", "Por favor, limpem {alvo} de {lugar}. A água de lá desce para {povoado}, e {gente} {gentefaz}.", "{povoado} pede socorro. A água está negra {desde}, e quem bebe dela morre e depois se levanta."]}, "abert": {"en": ["The heroes follow the streams that run down from {lugar}. They run dark, and the animals keep well away from them."], "pt": ["Os heróis seguem os riachos que descem de {lugar}. Eles correm escuros, e os bichos passam longe deles."]}, "fala": {"en": ["Whoever drinks that water dies and then rises again. {vilao} came back from the grave at the last moon and poisoned {alvo}, one by one. Cleanse each of them before the plague runs down to {povoado}."], "pt": ["Quem bebe dessa água morre e depois se levanta. {vilao} voltou do túmulo na última lua e envenenou {alvo}, ⟨alvo:um por um|uma por uma|um por um|uma por uma⟩. Limpem ⟨alvo:cada um|cada uma|cada um|cada uma⟩ antes que a praga desça até {povoado}."]}, "pista": {"nome": {"en": "A dead goat", "pt": "Uma cabra morta"}, "olhar": {"en": "A dead goat beside the water. Its eyes open when you look at it.", "pt": "Uma cabra morta junto à água. Os olhos dela se abrem quando vocês olham."}, "revela": {"en": "An animal lies beside the water, near the entrance.", "pt": "Há um animal caído junto à água, perto da entrada."}, "texto": {"en": ["The goat died beside the water, and its eyes open as you come near: the water killed it and then raised it. The shepherds of {povoado} already tell the same of other springs, always with the same name in the middle of the story: {vilao}, who came back from the grave at the last moon."], "pt": ["A cabra morreu junto à água, e os olhos dela se abrem quando vocês se aproximam: a água a matou e depois a levantou. Os pastores de {povoado} já contam isso de outras nascentes, sempre com o mesmo nome no meio da história: {vilao}, que voltou do túmulo na última lua."]}}, "ultima": {"en": ["The spring bubbles black, and {vilao} stands in the middle of it."], "pt": ["A nascente borbulha negra, e {vilao} está de pé dentro dela."]}, "narr": {"en": ["As you come in, the black water rises to the ankles of {vilao}."], "pt": ["Quando vocês entram, a água negra sobe até os tornozelos de {vilao}."]}, "vil": {"en": ["Thirsty? Drink."], "pt": ["Estão com sede? Bebam."]}, "hc": {"en": ["In {povoado}, they told us to drink from our flasks."], "pt": ["Em {povoado} mandaram beber do cantil."]}, "hs": {"en": ["We brought our own."], "pt": ["Trouxemos o nosso."]}, "fim": {"en": ["The water clears little by little, and a live fish darts between your boots."], "pt": ["A água clareia aos poucos, e um peixe vivo passa entre as botas de vocês."]}, "fecho": {"en": ["In {povoado}, the water runs clear again, and {gente} go back to work with their flasks full."], "pt": ["Em {povoado}, a água volta a correr clara, e {gente} voltam ao trabalho com os cantis cheios."]}, "pa": {"en": ["Put down your flasks. Look at the color of this water."], "pt": ["Larguem os cantis. Olhem a cor dessa água."]}, "pb": {"en": ["Black. And the fish are floating."], "pt": ["Preta. E os peixes estão boiando."]}, "entr": {"en": ["See how the stream that comes out of {lugar} runs black and thick. There are even white-eyed fish floating in it."], "pt": ["Vejam como o riacho que sai de {lugar} corre negro e grosso. Tem até peixes de olhos brancos boiando."]}, "chave": {"en": ["You see a dead dog beside the trough, its muzzle black. That means the plague has reached the animals."], "pt": ["Vocês veem um cão morto junto ao cocho, de focinho preto. Isso quer dizer que a praga chegou aos animais."]}, "chc": {"en": ["You see a dead dog beside the trough, its muzzle black. That means the plague has reached the animals. The sickness of {povoado} has already spread to the animals."], "pt": ["Vocês veem um cão morto junto ao cocho, de focinho preto. Isso quer dizer que a praga chegou aos animais. A doença de {povoado} já passou para os bichos."]}, "chs": {"en": ["You see a dead dog beside the trough, its muzzle black. That means the plague has reached the animals. The black water on the road comes from here."], "pt": ["Vocês veem um cão morto junto ao cocho, de focinho preto. Isso quer dizer que a praga chegou aos animais. A água preta da estrada vem daqui."]}, "elos": [{"t": "h", "txt": {"en": ["Look at the color of the water. This is the water the notice spoke of."], "pt": ["Olhem a cor da água. É desta água que o aviso falava."]}}, {"t": "n", "txt": {"en": ["At the entrance, a goat lies beside the stream. When you come close, it opens its eyes, and they are white."], "pt": ["Na entrada, há uma cabra caída junto ao riacho. Quando vocês chegam perto, ela abre os olhos, e eles estão brancos."]}}]}, "pocos/peste": {"tit": {"en": ["The Plague of {povoado}", "Before the Fair", "The Plague Pits of the Graveyard"], "pt": ["A Peste de {povoado}", "Antes da Feira", "Os Focos do Cemitério"]}, "aviso": {"en": ["Help {povoado} before the fair. Every day more houses shutter their windows, because the plague rises from the open graves of the graveyard of {lugar}.", "Please burn out the sources of the plague in {lugar}. If the fair of {povoado} opens with the plague still here, the sickness will leave in the merchants' wagons.", "{povoado} needs help {ate}. The plague rises from the graves of {lugar}, and every window in the village is shut."], "pt": ["Ajudem {povoado} antes da feira. A cada dia mais casas fecham as janelas, porque a peste sai das covas abertas do cemitério de {lugar}.", "Por favor, queimem os focos da peste em {lugar}. Se a feira de {povoado} abrir com a peste, a doença vai embora nas carroças dos mercadores.", "{povoado} precisa de ajuda {ate}. A peste sobe das covas de {lugar}, e as janelas da vila estão todas fechadas."]}, "abert": {"en": ["The heroes pass through {povoado}, where every window is shut, and go on to the graveyard of {lugar}, at the end of the road."], "pt": ["Os heróis passam por {povoado}, de janelas todas fechadas, e seguem até o cemitério de {lugar}, no fim da estrada."]}, "fala": {"en": ["The graves opened from the inside. A yellow smoke comes out of them, and whoever breathes it coughs until they spit blood. It was {vilao}, back from the grave, who spread this. Cover your mouths and burn out the sources."], "pt": ["As covas se abriram por dentro. Sai uma fumaça amarela delas, e quem respira tosse até cuspir sangue. Foi {vilao}, que voltou do túmulo, quem espalhou isso. Cubram a boca e queimem os focos."]}, "pista": {"nome": {"en": "A scraped headstone", "pt": "Uma lápide raspada"}, "olhar": {"en": "A headstone with its name scraped off, beside an open grave.", "pt": "Uma lápide com o nome raspado, junto a uma cova aberta."}, "revela": {"en": "There is an open grave near the entrance.", "pt": "Há uma cova aberta perto da entrada."}, "texto": {"en": ["The grave has been opened from the inside out, and a yellow smoke seeps from it, hugging the ground. On the headstone, the dead man's name has been scraped off. In its place, someone has carved another, deep into the stone, like a mark of territory: {vilao}."], "pt": ["A cova está aberta de dentro para fora, e dela sai uma fumaça amarela rente ao chão. Na lápide, o nome do morto foi raspado. No lugar, alguém gravou outro, fundo na pedra, como quem marca território: {vilao}."]}}, "ultima": {"en": ["The largest source smolders among the graves, and {vilao} is tending it."], "pt": ["O maior foco fumega no meio das covas, e {vilao} cuida dele."]}, "narr": {"en": ["As you come in, the yellow smoke curls around the feet of {vilao}."], "pt": ["Quando vocês entram, a fumaça amarela se enrola nos pés de {vilao}."]}, "vil": {"en": ["Breathe deep. It is the last clean air you will get."], "pt": ["Respirem fundo. É o último ar limpo que vão ter."]}, "hc": {"en": ["We came with our mouths covered."], "pt": ["Viemos com a boca coberta."]}, "hs": {"en": ["[covering the mouth] This is where the plague comes from."], "pt": ["[cobrindo a boca] É daqui que sai a peste."]}, "fim": {"en": ["The last source goes out with a hiss, and the yellow smoke scatters on the wind. The only smell left is that of wet earth."], "pt": ["O último foco se apaga com um chiado, e a fumaça amarela se desfaz no vento. O cheiro que fica é só de terra molhada."]}, "fecho": {"en": ["In {povoado}, one window opens, then another, and in the square someone starts setting up the stalls for the fair."], "pt": ["Em {povoado}, uma janela se abre, depois outra, e na praça alguém começa a montar as barracas da feira."]}, "pa": {"en": ["What is that yellow smoke, low to the ground?"], "pt": ["Que fumaça amarela é essa, rente ao chão?"]}, "pb": {"en": ["No idea. And I am not about to breathe it in to find out."], "pt": ["Sei lá. E eu é que não vou respirar para descobrir."]}, "entr": {"en": ["Every window in {povoado} is shut, and the yellow smoke comes from {lugar}. Cover your mouths."], "pt": ["Todas as janelas de {povoado} estão fechadas, e a fumaça amarela vem de {lugar}. Cubram a boca."]}, "chave": {"en": ["There is a grave opened from the inside out, still giving off smoke. That is where the plague comes from, and it is still coming."], "pt": ["Há uma cova aberta de dentro para fora, ainda soltando fumaça. É dali que a peste sai, e ela continua saindo."]}, "chc": {"en": ["There is a grave opened from the inside out, still giving off smoke. That is where the plague comes from, and it is still coming. It is the plague that shutters the windows of {povoado}."], "pt": ["Há uma cova aberta de dentro para fora, ainda soltando fumaça. É dali que a peste sai, e ela continua saindo. É a peste que fecha as janelas de {povoado}."]}, "chs": {"en": ["There is a grave opened from the inside out, still giving off smoke. That is where the plague comes from, and it is still coming. The yellow smoke on the road comes from here."], "pt": ["Há uma cova aberta de dentro para fora, ainda soltando fumaça. É dali que a peste sai, e ela continua saindo. A fumaça amarela da estrada vem daqui."]}, "elos": [{"t": "n", "txt": {"en": ["At the graveyard gate, a kerchief is tied to a post, the sign {povoado} uses to warn of plague."], "pt": ["Na entrada do cemitério, há um lenço amarrado num poste, o sinal que {povoado} usa para avisar que ali tem peste."]}}, {"t": "h", "txt": {"en": ["The yellow smoke the notice spoke of is coming out of the graves. Cover your mouths before going in."], "pt": ["A fumaça amarela de que o aviso falava sai das covas. Cubram a boca antes de entrar."]}}]}, "pocos/sonambulos": {"tit": {"en": ["Those Who Walk Asleep", "The Spring That Calls", "The Nights of {povoado}"], "pt": ["Os que Andam Dormindo", "A Fonte que Chama", "As Noites de {povoado}"]}, "aviso": {"en": ["Help {povoado}. {desde}, those who drink the water of {lugar} have been leaving their homes asleep, at night, and walking there.", "Please find out what is in {alvo} of {lugar}. The people of {povoado} wake up with wet feet and do not know why.", "{povoado} is calling for help. Three people walked to {lugar} in their sleep and did not come back."], "pt": ["Ajudem {povoado}. {desde}, quem bebe da água de {lugar} sai de casa dormindo, à noite, e anda até lá.", "Por favor, descubram o que há em {alvo} de {lugar}. As pessoas de {povoado} acordam com os pés molhados e não sabem por quê.", "{povoado} pede socorro. Três pessoas foram até {lugar} dormindo e não voltaram."]}, "abert": {"en": ["The heroes follow the bare footprints from the road to {lugar}. There are many, all heading the same way."], "pt": ["Os heróis seguem as pegadas descalças da estrada até {lugar}. São muitas, todas na mesma direção."]}, "fala": {"en": ["The water has a voice, and those who drink it hear it at night. The voice belongs to {vilao}, who came back from the grave and wants people to serve down there. Cleanse {alvo}, one by one, and the voice will fall silent."], "pt": ["A água tem uma voz, e quem bebe dela escuta à noite. A voz é de {vilao}, que voltou do túmulo e quer gente para servir lá no fundo. Limpem {alvo}, ⟨alvo:um por um|uma por uma|um por um|uma por uma⟩, e a voz se cala."]}, "pista": {"nome": {"en": "Bare footprints", "pt": "Pegadas descalças"}, "olhar": {"en": "Prints of bare feet, wet, leading inside.", "pt": "Pegadas de pés descalços, molhadas, indo para dentro."}, "revela": {"en": "There are wet footprints on the ground near the entrance.", "pt": "Há pegadas molhadas no chão perto da entrada."}, "texto": {"en": ["The footprints belong to many people, all barefoot and wet, and all go the same way, with none coming back. Beside the water, someone has left a note pinned under a stone: “Drink and come. {vilao} is waiting.”"], "pt": ["As pegadas são de muita gente, todas descalças e molhadas, e vão todas na mesma direção, sem nenhuma voltar. Ao lado da água, alguém deixou um bilhete preso numa pedra: «Bebam e venham. {vilao} espera.»"]}}, "ultima": {"en": ["Those who came in their sleep stand in the water, eyes closed. In their midst stands {vilao}."], "pt": ["Os que vieram dormindo estão de pé dentro da água, de olhos fechados. No meio deles está {vilao}."]}, "narr": {"en": ["As you come in, all the sleepers turn their heads toward you at the same moment."], "pt": ["Quando vocês entram, todos os que dormem viram a cabeça para vocês ao mesmo tempo."]}, "vil": {"en": ["More visitors. Did the water call you too?"], "pt": ["Mais visitas. A água chamou vocês também?"]}, "hc": {"en": ["We came for the people of {povoado}."], "pt": ["Viemos buscar a gente de {povoado}."]}, "hs": {"en": ["We came awake."], "pt": ["A gente veio acordado."]}, "fim": {"en": ["The water clears, and the sleepers wake all at once, shivering with cold, not knowing where they are."], "pt": ["A água clareia, e os que dormiam acordam de uma vez, tremendo de frio, sem saber onde estão."]}, "fecho": {"en": ["In {povoado}, everyone sleeps at home that night, and in the morning no one wakes up with wet feet."], "pt": ["Em {povoado}, todo mundo dorme em casa naquela noite, e de manhã ninguém acorda com os pés molhados."]}, "pa": {"en": ["Bare footprints on the road."], "pt": ["Pegadas descalças na estrada."]}, "pb": {"en": ["A lot of them. And no one walks barefoot in this cold."], "pt": ["Muitas. E ninguém anda descalço com esse frio."]}, "entr": {"en": ["Look at these bare footprints going into {lugar}. All heading the same way."], "pt": ["Olhem essas pegadas descalças entrando em {lugar}. Todas na mesma direção."]}, "chave": {"en": ["From deep inside comes the murmur of many voices, repeating the same sentence. The sleepers seem to be calling more people."], "pt": ["Lá do fundo vem um murmúrio de muitas vozes, repetindo a mesma frase. Parece que os que dormem estão chamando mais gente."]}, "chc": {"en": ["From deep inside comes the murmur of many voices, repeating the same sentence. The sleepers seem to be calling more people. Among those voices are the ones from {povoado}."], "pt": ["Lá do fundo vem um murmúrio de muitas vozes, repetindo a mesma frase. Parece que os que dormem estão chamando mais gente. Entre essas vozes estão as de {povoado}."]}, "chs": {"en": ["From deep inside comes the murmur of many voices, repeating the same sentence. The sleepers seem to be calling more people. They are the owners of the bare footprints on the road."], "pt": ["Lá do fundo vem um murmúrio de muitas vozes, repetindo a mesma frase. Parece que os que dormem estão chamando mais gente. São os donos das pegadas descalças da estrada."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance, a pair of shoes has been carefully set down, and bare footprints lead on inside."], "pt": ["Na entrada, há um par de sapatos deixado com cuidado, e pegadas descalças seguindo para dentro."]}}, {"t": "h", "txt": {"en": ["These bare footprints belong to people of {povoado}. They walked here in their sleep, just as the notice said."], "pt": ["Essas pegadas descalças são de gente de {povoado}. Andaram até aqui dormindo, como o aviso dizia."]}}]}, "rei": {"tit": {"en": ["The Awakening of {morto}", "The Tomb of {lugar}", "The Cold from Below"], "pt": ["O Despertar de {morto}", "A Tumba de {lugar}", "O Frio que Vem de Baixo"]}, "aviso": {"en": ["Help {povoado}. {desde}, {sinal}, and the cold comes from {lugar}, where {morto} has lain buried {origem}.", "Please put {morto} back to sleep. Someone opened the tomb in {lugar}, and ever since, {sinal} around {povoado}.", "{povoado} is calling for help. The tombs of {lugar} are opening from the inside out, and the elders say that {morto} is waking."], "pt": ["Ajudem {povoado}. {desde}, {sinal}, e o frio vem de {lugar}, onde {morto} foi enterrad⟨morto:o|a⟩ {origem}.", "Por favor, façam {morto} voltar a dormir. Alguém abriu a tumba em {lugar}, e desde então {sinal} em volta de {povoado}.", "{povoado} pede socorro. Os túmulos de {lugar} estão se abrindo de dentro para fora, e os mais velhos dizem que {morto} está acordando."]}, "abert": {"en": ["The heroes reach the entrance of {lugar} and feel the icy air that flows from it, as if something down there were breathing."], "pt": ["Os heróis chegam à entrada de {lugar} e sentem o ar gelado que sai dela, como se algo lá embaixo respirasse."]}, "fala": {"en": ["The keys to the mausoleum were stolen. {vilao} found the tomb of {morto}, who ruled these lands by the gallows and by blood, and is calling the dead ruler back. The deeper you go, the colder it gets. If someone down there calls your names, keep silent."], "pt": ["Roubaram as chaves do mausoléu. {vilao} achou a tumba de {morto}, que governou estas terras na forca e no sangue, e está chamando de volta. Quanto mais fundo vocês forem, mais frio. Se alguém lá embaixo chamar seus nomes, fiquem calados."]}, "pista": {"nome": {"en": "A broken seal", "pt": "Um lacre quebrado"}, "olhar": {"en": "A tomb seal, cracked from the inside.", "pt": "Um lacre de tumba, rachado por dentro."}, "revela": {"en": "A cracked stone lies near the entrance.", "pt": "Há uma pedra rachada perto da entrada."}, "texto": {"en": ["The seal is cracked from the inside out: someone forced it open and let {morto} breathe. The inscription around it is an old warning against whoever might wake the one who sleeps there, and over it someone has written in fresh ink, as an answer: “I, {vilao}, call the sleeper back.”"], "pt": ["O lacre está rachado de dentro para fora: alguém o abriu à força e deixou {morto} respirar. A inscrição em volta é um aviso antigo contra quem acordasse quem dorme ali, e por cima dela alguém escreveu com tinta fresca, como resposta: «Eu, {vilao}, chamo de volta.»"]}}, "ultima": {"en": ["The sarcophagus of {morto} stands open, and {vilao} stands beside it, reciting."], "pt": ["O sarcófago de {morto} está aberto, e {vilao} está de pé ao lado, recitando."]}, "narr": {"en": ["{morto} sits up in the sarcophagus, and {vilao} laughs."], "pt": ["{morto} se senta no sarcófago, e {vilao} ri."]}, "vil": {"en": ["Kneel. {morto} has awakened."], "pt": ["Ajoelhem-se. {morto} acordou."]}, "hc": {"en": ["{povoado} needs the sun. Go back to sleep."], "pt": ["{povoado} precisa de sol. Volte a dormir."]}, "hs": {"en": ["Go back to sleep. Today."], "pt": ["Volte a dormir hoje."]}, "fim": {"en": ["{morto} lies down again, this time forever. When you come out, the frost is already melting on the grass, and the sun warms your backs."], "pt": ["{morto} volta a se deitar, desta vez para sempre. Quando vocês saem, a geada já derrete na grama, e o sol esquenta as costas."]}, "fecho": {"en": ["Around {povoado}, the frost melts, and {gente} are already talking of planting again."], "pt": ["Em volta de {povoado}, a geada derrete, e {gente} já falam em plantar de novo."]}, "pa": {"en": ["Frost on the grass, in the middle of summer."], "pt": ["Geada na grama, em pleno verão."]}, "pb": {"en": ["Only around the tombs. Do you see?"], "pt": ["Só em volta dos túmulos. Estão vendo?"]}, "entr": {"en": ["Can you feel that icy air coming from the entrance of {lugar}? The grass all around is covered in frost."], "pt": ["Estão sentindo esse ar gelado que sai da entrada de {lugar}? A grama em volta está toda coberta de geada."]}, "chave": {"en": ["The cold grows so fierce that your breath freezes in the air. Down below, a stone lid scrapes aside: {morto} is waking."], "pt": ["O frio fica tão forte que a respiração congela no ar. Lá embaixo, uma tampa de pedra se arrasta: {morto} está acordando."]}, "chc": {"en": ["The cold grows so fierce that your breath freezes in the air. Down below, a stone lid scrapes aside: {morto} is waking. That is where the cold of {povoado} comes from."], "pt": ["O frio fica tão forte que a respiração congela no ar. Lá embaixo, uma tampa de pedra se arrasta: {morto} está acordando. É de lá que vem o frio de {povoado}."]}, "chs": {"en": ["The cold grows so fierce that your breath freezes in the air. Down below, a stone lid scrapes aside: {morto} is waking. The frost on the road came from this cold."], "pt": ["O frio fica tão forte que a respiração congela no ar. Lá embaixo, uma tampa de pedra se arrasta: {morto} está acordando. A geada da estrada vinha deste frio."]}, "elos": [{"t": "h", "txt": {"en": ["Can you feel that cold? It is the cold from the notice, and it comes from inside."], "pt": ["Sentem esse frio? É o frio do aviso, e vem lá de dentro."]}}, {"t": "n", "txt": {"en": ["At the entrance, there is frost on the grass in the middle of summer, and a stone door stands ajar."], "pt": ["Na entrada, há geada na grama, em pleno verão, e uma porta de pedra entreaberta."]}}]}, "rei/coroacao": {"tit": {"en": ["The Coronation of the Dead", "A Crown for {morto}", "The Night of the Coronation"], "pt": ["A Coroação dos Mortos", "Uma Coroa para {morto}", "A Noite da Coroação"]}, "aviso": {"en": ["Help {povoado} {ate}. A cult means to crown {morto} again, in {lugar}, and the tombs around it are already opening to watch.", "Please stop the coronation in {lugar}. {morto} has lain buried there {origem}, and someone is preparing a feast for the return.", "{povoado} is calling for help. Ever since the cult came to {lugar}, {sinal}, and they say the coronation will be at the full moon."], "pt": ["Ajudem {povoado} {ate}. Um culto quer coroar {morto} de novo, em {lugar}, e os túmulos em volta já estão se abrindo para assistir.", "Por favor, impeçam a coroação em {lugar}. {morto} foi enterrad⟨morto:o|a⟩ lá {origem}, e alguém está preparando uma festa para a volta.", "{povoado} pede socorro. Desde que o culto chegou a {lugar}, {sinal}, e dizem que a coroação vai ser na lua cheia."]}, "abert": {"en": ["The heroes reach the entrance of {lugar} and smell incense and freshly turned earth."], "pt": ["Os heróis chegam à entrada de {lugar} e sentem um cheiro de incenso e de terra revirada."]}, "fala": {"en": ["The cult of {vilao} is going to set the crown on the head of {morto}, and when that happens, every dead soul that ever served the throne will rise to serve again. The crown is in the hall at the back. There is still time."], "pt": ["O culto de {vilao} vai pôr a coroa na cabeça de {morto}, e quando isso acontecer, todo morto que já serviu ao trono se levanta para servir de novo. A coroa está no salão do fundo. Ainda dá tempo."]}, "pista": {"nome": {"en": "A mourning invitation", "pt": "Um convite de luto"}, "olhar": {"en": "An invitation on black paper, in silver letters.", "pt": "Um convite em papel negro, com letras de prata."}, "revela": {"en": "A black paper lies near the entrance.", "pt": "Há um papel negro caído perto da entrada."}, "texto": {"en": ["The invitation is to the coronation of {morto}, and it was written in a careful hand, as if for a real feast. You can tell many were sent: others just like it lie trampled on the ground. At the bottom is the signature of the host: {vilao}."], "pt": ["O convite é para a coroação de {morto}, e foi escrito com letra caprichada, como para uma festa de verdade. Vocês percebem que foram mandados muitos, porque há outros iguais pisoteados no chão. Embaixo, a assinatura de quem convida: {vilao}."]}}, "ultima": {"en": ["{morto} sits on a stone throne, and {vilao} holds the crown above ⟨morto:his|her⟩ head."], "pt": ["{morto} está sentad⟨morto:o|a⟩ num trono de pedra, e {vilao} segura a coroa sobre a cabeça d⟨morto:ele|ela⟩."]}, "narr": {"en": ["As you come in, the dead around the throne turn their heads toward you."], "pt": ["Quando vocês entram, os mortos em volta do trono viram a cabeça para vocês."]}, "vil": {"en": ["You are here for the coronation. Kneel like the others."], "pt": ["Chegaram para a coroação. Ajoelhem-se como os outros."]}, "hc": {"en": ["{povoado} has no dead king."], "pt": ["{povoado} não tem rei morto."]}, "hs": {"en": ["That crown stays on the floor."], "pt": ["Essa coroa fica no chão."]}, "fim": {"en": ["The crown rolls across the floor, and {morto} crumbles on the throne, turning to dust before the fall is even over."], "pt": ["A coroa rola pelo chão, e {morto} desmorona no trono, virando pó antes de terminar de cair."]}, "fecho": {"en": ["In {povoado}, the tombs are closed again, and the full moon passes without anyone rising."], "pt": ["Em {povoado}, os túmulos são fechados de novo, e a lua cheia passa sem que ninguém se levante."]}, "pa": {"en": ["The smell of incense, out here in the brush."], "pt": ["Cheiro de incenso, aqui no meio do mato."]}, "pb": {"en": ["And of turned earth. That is the smell of a burial."], "pt": ["E de terra revirada. Isso é cheiro de enterro."]}, "entr": {"en": ["Can you smell that incense coming from {lugar}? And look at the open tombs all around."], "pt": ["Sentem esse cheiro de incenso vindo de {lugar}? E olhem os túmulos abertos em volta."]}, "chave": {"en": ["From deep inside comes a solemn chant, like one from a church. The coronation seems to have begun."], "pt": ["Lá do fundo vem um canto solene, como de igreja. Parece que a coroação começou."]}, "chc": {"en": ["From deep inside comes a solemn chant, like one from a church. The coronation seems to have begun. It is the cult from the notice, and {morto} is about to be crowned."], "pt": ["Lá do fundo vem um canto solene, como de igreja. Parece que a coroação começou. É o culto do aviso, e {morto} vai ser coroad⟨morto:o|a⟩."]}, "chs": {"en": ["From deep inside comes a solemn chant, like one from a church. The coronation seems to have begun. The incense on the road came from this ceremony."], "pt": ["Lá do fundo vem um canto solene, como de igreja. Parece que a coroação começou. O incenso da estrada era desta cerimônia."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance lies an invitation on black paper in silver letters, trampled. It is for a coronation."], "pt": ["Na entrada, há um convite de papel negro com letras de prata, pisoteado. É para uma coroação."]}}, {"t": "h", "txt": {"en": ["Open tombs all around, just as the notice said. And that smell is incense."], "pt": ["Túmulos abertos em volta, como o aviso dizia. E esse cheiro é de incenso."]}}]}, "rei/herdeiro": {"tit": {"en": ["The Descendant", "The Call of {morto}", "Old Blood"], "pt": ["O Descendente", "O Chamado de {morto}", "Sangue Antigo"]}, "aviso": {"en": ["Help {povoado}. A young man from here, a descendant of {morto}, has been hearing a voice {desde}, and yesterday he went into {lugar} alone.", "Please bring the young man back from {lugar}. He is of the blood of {morto}, and the voice that called him came from there.", "{povoado} has lost one of its own. The last of the blood of {morto} went to {lugar} during the night, and ever since, {sinal}."], "pt": ["Ajudem {povoado}. Um moço daqui, descendente de {morto}, começou a ouvir uma voz {desde}, e ontem entrou em {lugar} sozinho.", "Por favor, tragam o moço de volta de {lugar}. Ele é do sangue de {morto}, e a voz que o chamava vinha de lá.", "{povoado} perdeu um dos seus. O último do sangue de {morto} foi até {lugar} durante a noite, e desde então {sinal}."]}, "abert": {"en": ["The heroes follow the footprints of a single person, which lead into {lugar}."], "pt": ["Os heróis seguem as pegadas de uma pessoa só, que entram em {lugar}."]}, "fala": {"en": ["The young man is of the blood of {morto}, and {vilao} needs that blood to wake what lies in the tomb. He was called in a dream, and he came alone. If you get there in time, he can still be brought out."], "pt": ["O moço é do sangue de {morto}, e {vilao} precisa desse sangue para acordar o que está na tumba. Ele foi chamado em sonho, e veio sozinho. Se chegarem a tempo, ainda dá para tirá-lo de lá."]}, "pista": {"nome": {"en": "A dropped cloak", "pt": "Uma capa largada"}, "olhar": {"en": "A plain woolen cloak, dropped on the ground.", "pt": "Uma capa de lã, simples, largada no chão."}, "revela": {"en": "A cloak has been dropped near the entrance.", "pt": "Há uma capa largada perto da entrada."}, "texto": {"en": ["The cloak is the kind worn in {povoado}, and whoever wore it dropped it without noticing: the footprints go on in a straight line, without a pause. On the lining, someone embroidered an ancient crest, that of {morto}. And on the wall beside it, written in chalk: “Come, blood of my blood. {vilao} awaits you.”"], "pt": ["A capa é de gente de {povoado}, e quem a usava a largou sem perceber, porque as pegadas seguem em linha reta, sem parar. No forro, alguém bordou um brasão antigo, o de {morto}. E na parede ao lado, escrito com giz: «Venha, sangue do meu sangue. {vilao} te espera.»"]}}, "ultima": {"en": ["The young man lies on the tomb of {morto}, and {vilao} raises a knife above him."], "pt": ["O moço está deitado sobre a tumba de {morto}, e {vilao} ergue uma faca sobre ele."]}, "narr": {"en": ["As you come in, the young man opens his eyes and calls out to you."], "pt": ["Quando vocês entram, o moço abre os olhos e chama por vocês."]}, "vil": {"en": ["One drop is all I need. You are just in time to watch."], "pt": ["Uma gota é tudo o que preciso. Vocês chegaram para ver."]}, "hc": {"en": ["{povoado} wants the young man back."], "pt": ["{povoado} quer o moço de volta."]}, "hs": {"en": ["His blood stays with him."], "pt": ["O sangue dele fica com ele."]}, "fim": {"en": ["The knife falls to the floor, and the young man sits up, dazed, asking where he is. The tomb of {morto} stays shut."], "pt": ["A faca cai no chão, e o moço se senta, tonto, perguntando onde está. A tumba de {morto} continua fechada."]}, "fecho": {"en": ["In {povoado}, the young man goes back home, and never hears the voice again."], "pt": ["Em {povoado}, o moço volta para casa, e nunca mais ouve a voz."]}, "pa": {"en": ["The footprints of a single person."], "pt": ["Pegadas de uma pessoa só."]}, "pb": {"en": ["Walking straight, stepping around nothing. Whoever walks like that is not awake."], "pt": ["Andando reto, sem desviar de nada. Quem anda assim não está acordado."]}, "entr": {"en": ["There are footprints of a single person at the entrance of {lugar}, and they all lead inside. It looks as if that person walked without stopping."], "pt": ["Tem pegadas de uma pessoa só na entrada de {lugar}, e todas vão para dentro. Parece que ela andou sem parar."]}, "chave": {"en": ["From deep inside comes the young man's voice, talking with someone. A moment later, another voice answers, cold as stone."], "pt": ["Lá do fundo vem a voz do moço, conversando com alguém. Logo depois, outra voz responde, fria como pedra."]}, "chc": {"en": ["From deep inside comes the young man's voice, talking with someone. A moment later, another voice answers, cold as stone. It is the young man who left {povoado}."], "pt": ["Lá do fundo vem a voz do moço, conversando com alguém. Logo depois, outra voz responde, fria como pedra. É o moço que saiu de {povoado}."]}, "chs": {"en": ["From deep inside comes the young man's voice, talking with someone. A moment later, another voice answers, cold as stone. The footprints on the road were his."], "pt": ["Lá do fundo vem a voz do moço, conversando com alguém. Logo depois, outra voz responde, fria como pedra. As pegadas da estrada eram dele."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance, a woolen cloak from {povoado} lies on the ground, as if its owner never even felt the cold."], "pt": ["Na entrada, há uma capa de lã de {povoado} largada no chão, como se o dono nem tivesse sentido o frio."]}}, {"t": "h", "txt": {"en": ["He even dropped his knife, look. Whoever walks like this is hearing the voice the notice spoke of."], "pt": ["Ele largou até a faca, olhem. Quem anda assim está ouvindo a voz de que o aviso falava."]}}]}, "refugio": {"tit": {"en": ["Sanctuary", "The Survivors of {povoado}", "The Night of the Beasts"], "pt": ["Santuário", "Os Sobreviventes de {povoado}", "A Noite das Feras"]}, "aviso": {"en": ["Help for {lugar}. The bells rang all night: beasts attacked all at once, and there are still people there, too badly hurt to flee. The old sanctuary will hold, if someone takes the wounded to it.", "Please help the neighbors of {povoado}. The beasts of {vilao} attacked {lugar}, and {desde} those who survived have been hiding in the houses.", "{povoado} asks for help for {lugar}. Beasts have taken the streets, and the wounded need to reach the sanctuary before the next nightfall."], "pt": ["Socorro para {lugar}. Os sinos tocaram a noite inteira: feras atacaram de uma vez, e ainda há gente lá, ferida demais para fugir. O velho santuário aguenta, se alguém levar os feridos até ele.", "Por favor, ajudem os vizinhos de {povoado}. As feras de {vilao} atacaram {lugar}, e {desde} quem sobreviveu está escondido nas casas.", "{povoado} pede socorro por {lugar}. Feras tomaram as ruas, e os feridos precisam chegar ao santuário antes da próxima noite."]}, "abert": {"en": ["The heroes reach {lugar}, where smoke is still rising. Somewhere, someone is knocking on a door from the inside."], "pt": ["Os heróis chegam a {lugar}, de onde ainda sobe fumaça. Em algum lugar, alguém bate numa porta por dentro."]}, "fala": {"en": ["The beasts came all at once, in a single night. The one who set them loose was {vilao}, who had been prowling the fields for weeks. There are still people hiding, too badly hurt to walk. The old sanctuary, at the far end, will hold. Take everyone there."], "pt": ["As feras vieram todas de uma vez, numa noite só. Quem soltou foi {vilao}, que rondava os campos havia semanas. Ainda tem gente escondida, ferida demais para andar. O velho santuário, lá no fundo, aguenta. Levem todos para lá."]}, "pista": {"nome": {"en": "A child's crying", "pt": "Um choro de criança"}, "olhar": {"en": "A faint crying, somewhere in the rubble.", "pt": "Um choro fraco, em algum lugar nos escombros."}, "revela": {"en": "A faint crying can be heard near the entrance.", "pt": "Ouve-se um choro fraco perto da entrada."}, "texto": {"en": ["The crying comes from under an overturned table, where a child is hiding. The child will not let go of a piece of hide torn from one of the beasts, marked with a brand. Anyone who knows the region knows the brand: it is that of {vilao}, who had been prowling the fields for weeks."], "pt": ["O choro vem de debaixo de uma mesa virada, onde uma criança se esconde. Ela não larga um pedaço de couro arrancado de uma das feras, marcado a ferro. Quem conhece a região conhece a marca: é a de {vilao}, que rondava os campos havia semanas."]}}, "ultima": {"en": ["The doors of the sanctuary are right there, and {vilao} sits on the steps, waiting."], "pt": ["As portas do santuário estão logo ali, e {vilao} está sentad⟨vilao:o|a⟩ nos degraus, esperando."]}, "narr": {"en": ["The beasts lie down around {vilao} as you arrive."], "pt": ["As feras se deitam em volta de {vilao} quando vocês chegam."]}, "vil": {"en": ["(A growl, and the beasts all rise at once.)"], "pt": ["(Um rosnado, e as feras se levantam todas de uma vez.)"]}, "hc": {"en": ["The bells of {povoado} will ring again today. For another reason."], "pt": ["Os sinos de {povoado} vão tocar de novo hoje. Por outro motivo."]}, "hs": {"en": ["No one else gets left behind."], "pt": ["Ninguém mais fica para trás."]}, "fim": {"en": ["Inside the sanctuary, the survivors sleep for the first time in days. A child sleeps clinging to the boot of one of you, and no one has the heart to move her."], "pt": ["Dentro do santuário, os sobreviventes dormem pela primeira vez em dias. Uma criança dorme agarrada à bota de um de vocês, e ninguém tem coragem de tirá-la dali."]}, "fecho": {"en": ["In {povoado}, the survivors of {lugar} are welcomed with bread and blankets, and the bells ring one last time, slowly, to say that it is over."], "pt": ["Em {povoado}, os sobreviventes de {lugar} são recebidos com pão e cobertores, e os sinos tocam uma última vez, devagar, para avisar que acabou."]}, "pa": {"en": ["Every chimney is cold."], "pt": ["Todas as chaminés estão frias."]}, "pb": {"en": ["And every door is open."], "pt": ["E todas as portas estão abertas."]}, "entr": {"en": ["Smoke is still rising from {lugar}. And listen: someone is knocking on a door, from the inside."], "pt": ["Ainda sobe fumaça de {lugar}. E ouçam: alguém está batendo numa porta, por dentro."]}, "chave": {"en": ["From the howling, the beasts are surrounding the place, and those still in hiding will be found tonight."], "pt": ["Pelos uivos, as feras estão cercando o lugar, e quem ainda se esconde vai ser achado esta noite."]}, "chc": {"en": ["From the howling, the beasts are surrounding the place, and those still in hiding will be found tonight. The wounded must reach the sanctuary before that happens."], "pt": ["Pelos uivos, as feras estão cercando o lugar, e quem ainda se esconde vai ser achado esta noite. Os feridos precisam chegar ao santuário antes que isso aconteça."]}, "chs": {"en": ["From the howling, the beasts are surrounding the place, and those still in hiding will be found tonight. That is why the chimneys were cold and the doors open."], "pt": ["Pelos uivos, as feras estão cercando o lugar, e quem ainda se esconde vai ser achado esta noite. Por isso as chaminés estavam frias e as portas abertas."]}, "elos": [{"t": "n", "txt": {"en": ["From inside comes a faint knocking on a door, and then a voice calling for help."], "pt": ["Lá de dentro vem um bater fraco numa porta, e depois uma voz pedindo socorro."]}}, {"t": "h", "txt": {"en": ["Listen to that knocking on the door. There are people alive in there, just as the notice said, hidden and hurt."], "pt": ["Escutem essas batidas na porta. Tem gente viva lá dentro, como o aviso dizia, escondida e ferida."]}}]}, "refugio/incendio": {"tit": {"en": ["Fire in {povoado}", "The Beasts and the Flames", "Before Everything Burns"], "pt": ["Fogo em {povoado}", "As Feras e as Chamas", "Antes que Tudo Queime"]}, "aviso": {"en": ["Help for {lugar}. The beasts of {vilao} knocked over the lamps, and the fire is spreading through the houses, with people trapped inside.", "Please go to {lugar}. There are fire and beasts in the streets, and the wounded need to reach the stone sanctuary, the only place the fire cannot touch.", "{povoado} asks for help for {lugar}, which is burning. The beasts attacked during the night, and now the fire is doing the rest."], "pt": ["Socorro para {lugar}. As feras de {vilao} derrubaram as lamparinas, e o fogo se espalha pelas casas, com gente presa lá dentro.", "Por favor, vão até {lugar}. Há fogo e feras nas ruas, e os feridos precisam chegar ao santuário de pedra, o único lugar que o fogo não alcança.", "{povoado} pede socorro por {lugar}, que está queimando. As feras atacaram durante a noite, e agora o fogo faz o resto."]}, "abert": {"en": ["The heroes reach {lugar} under the smoke that covers the sky. Among the burning houses, the beasts run with no fear of the fire."], "pt": ["Os heróis chegam a {lugar} sob a fumaça que cobre o céu. Entre as casas em chamas, as feras correm sem medo do fogo."]}, "fala": {"en": ["The beasts of {vilao} came in at night and knocked everything over, even the lamps, and the fire caught. There are people trapped in the houses still standing. Take them all to the stone sanctuary, at the far end. The fire does not get in there, and the beasts fear its walls."], "pt": ["As feras de {vilao} entraram de noite e derrubaram tudo, até as lamparinas, e o fogo pegou. Tem gente presa nas casas que ainda estão de pé. Levem todos para o santuário de pedra, lá no fundo. O fogo não entra lá, e as feras têm medo das paredes."]}, "pista": {"nome": {"en": "A broken lamp", "pt": "Uma lamparina quebrada"}, "olhar": {"en": "A fallen lamp, still dripping burning oil.", "pt": "Uma lamparina caída, ainda pingando óleo em chamas."}, "revela": {"en": "There is fire on the ground near the entrance.", "pt": "Há fogo no chão perto da entrada."}, "texto": {"en": ["The lamp was knocked over by a beast: there are claw marks in the metal. The fire started here and ran through the houses. On the burnt door beside it, the beasts left their master's mark, bitten into the wood: that of {vilao}."], "pt": ["A lamparina foi derrubada por uma fera, porque há marcas de garra no metal. O fogo começou aqui e correu pelas casas. Na porta queimada ao lado, as feras deixaram a marca do dono, cravada a dentes na madeira: a de {vilao}."]}}, "ultima": {"en": ["The stone sanctuary is right there, wreathed in smoke, and {vilao} waits on the steps."], "pt": ["O santuário de pedra está logo ali, cercado de fumaça, e {vilao} espera nos degraus."]}, "narr": {"en": ["The fire lights up {vilao}, and the beasts all around rise to their feet."], "pt": ["O fogo ilumina {vilao}, e as feras em volta se levantam."]}, "vil": {"en": ["(A growl, and the beasts leap over the embers.)"], "pt": ["(Um rosnado, e as feras saltam por cima das brasas.)"]}, "hc": {"en": ["No one else burns today."], "pt": ["Ninguém mais queima hoje."]}, "hs": {"en": ["No one else burns today."], "pt": ["Ninguém mais queima hoje."]}, "fim": {"en": ["Inside the stone sanctuary, the survivors breathe without coughing for the first time in hours. Outside, rain begins to fall on the embers."], "pt": ["Dentro do santuário de pedra, os sobreviventes respiram sem tossir pela primeira vez em horas. Lá fora, a chuva começa a cair sobre as brasas."]}, "fecho": {"en": ["In {povoado}, the survivors of {lugar} are taken in, and the first thing the smiths make is nails to rebuild the houses."], "pt": ["Em {povoado}, os sobreviventes de {lugar} são acolhidos, e a primeira coisa que os ferreiros fazem é pregos para reconstruir as casas."]}, "pa": {"en": ["Smoke on the horizon."], "pt": ["Fumaça no horizonte."]}, "pb": {"en": ["And howling. Smoke and howling together mean nothing good."], "pt": ["E uivos. Fumaça e uivos juntos é coisa ruim."]}, "entr": {"en": ["Do you see the smoke rising from {lugar}? And listen: howling in the middle of the fire."], "pt": ["Estão vendo a fumaça saindo de {lugar}? E escutem: uivos no meio do fogo."]}, "chave": {"en": ["A house collapses, and the fire spreads into the street. From the howling, the beasts are surrounding those still in hiding."], "pt": ["Uma casa desaba, e o fogo se espalha para a rua. Pelos uivos, as feras estão cercando quem ainda se esconde."]}, "chc": {"en": ["A house collapses, and the fire spreads into the street. From the howling, the beasts are surrounding those still in hiding. There are still people trapped in the houses, as the notice said."], "pt": ["Uma casa desaba, e o fogo se espalha para a rua. Pelos uivos, as feras estão cercando quem ainda se esconde. Ainda há gente presa nas casas, como dizia o aviso."]}, "chs": {"en": ["A house collapses, and the fire spreads into the street. From the howling, the beasts are surrounding those still in hiding. The smoke and the howling on the road came from here."], "pt": ["Uma casa desaba, e o fogo se espalha para a rua. Pelos uivos, as feras estão cercando quem ainda se esconde. A fumaça e os uivos da estrada vinham daqui."]}, "elos": [{"t": "n", "txt": {"en": ["The fire is still running across the rooftops, and amid the noise someone is shouting for help from inside a house."], "pt": ["O fogo ainda corre pelos telhados, e no meio do barulho alguém grita por ajuda de dentro de uma casa."]}}, {"t": "h", "txt": {"en": ["The stone sanctuary from the notice must be that one at the far end. That is where we have to take everyone."], "pt": ["O santuário de pedra do aviso deve ser aquele lá no fundo. É para lá que temos que levar todo mundo."]}}]}, "refugio/acampamento": {"tit": {"en": ["The Silent Camp", "The Woodcutters of {povoado}", "Silence in the Woods"], "pt": ["O Acampamento Silencioso", "Os Lenhadores de {povoado}", "Silêncio na Mata"]}, "aviso": {"en": ["Help {povoado}. The woodcutters' camp, near {lugar}, has sent no word {desde}.", "Please go to the camp at {lugar}. The woodcutters of {povoado} did not come back for the fair, and nothing is heard from there but howling.", "{povoado} is calling for help. No one answers at the camp of {lugar}, and the campfires are out."], "pt": ["Ajudem {povoado}. O acampamento dos lenhadores, perto de {lugar}, está sem mandar notícias {desde}.", "Por favor, vão até o acampamento de {lugar}. Os lenhadores de {povoado} não voltaram para a feira, e de lá só se ouvem uivos.", "{povoado} pede socorro. Ninguém responde no acampamento de {lugar}, e as fogueiras estão apagadas."]}, "abert": {"en": ["The heroes reach the camp near {lugar}. Everything is silent, the campfires are out, and axes lie abandoned on the ground."], "pt": ["Os heróis chegam ao acampamento perto de {lugar}. Tudo está em silêncio, as fogueiras estão apagadas, e há machados largados no chão."]}, "fala": {"en": ["The beasts of {vilao} surrounded the camp three nights ago, and since then no one has been able to leave. There are wounded people hiding in the huts. The old sanctuary lies deep in the woods: if we reach it, the beasts will not come in."], "pt": ["As feras de {vilao} cercaram o acampamento três noites atrás, e desde então ninguém consegue sair. Tem gente ferida escondida nas cabanas. O velho santuário fica no fundo da mata: se chegarmos lá, as feras não entram."]}, "pista": {"nome": {"en": "An abandoned axe", "pt": "Um machado largado"}, "olhar": {"en": "A woodcutter's axe, buried in a log, with blood on the handle.", "pt": "Um machado de lenhador, cravado num tronco, com sangue no cabo."}, "revela": {"en": "An axe is buried in a log near the entrance.", "pt": "Há um machado cravado num tronco perto da entrada."}, "texto": {"en": ["The axe was driven into the log by someone who fought to the end: the handle is broken where the hand gripped it. On the ground all around are the tracks of many beasts and of one single person, who walked among them: {vilao}, of whom the woodcutters of {povoado} already spoke with fear."], "pt": ["O machado foi cravado no tronco por alguém que lutou até o fim, porque o cabo está quebrado na mão de quem o segurou. No chão em volta, pegadas de muitas feras e de uma só pessoa, que andava no meio delas: {vilao}, de quem os lenhadores de {povoado} já falavam com medo."]}}, "ultima": {"en": ["The doors of the sanctuary are right there, and {vilao} sits on the steps, surrounded by beasts."], "pt": ["As portas do santuário estão logo ali, e {vilao} está sentad⟨vilao:o|a⟩ nos degraus, cercad⟨vilao:o|a⟩ de feras."]}, "narr": {"en": ["The beasts lie down around {vilao} as you arrive."], "pt": ["As feras se deitam em volta de {vilao} quando vocês chegam."]}, "vil": {"en": ["(A growl, and the beasts all rise at once.)"], "pt": ["(Um rosnado, e as feras se levantam todas de uma vez.)"]}, "hc": {"en": ["{povoado} wants its woodcutters back."], "pt": ["{povoado} quer os lenhadores de volta."]}, "hs": {"en": ["No one else gets left behind."], "pt": ["Ninguém mais fica para trás."]}, "fim": {"en": ["Inside the sanctuary, the woodcutters light their first fire in three nights, and the warmth makes everyone weep a little."], "pt": ["Dentro do santuário, os lenhadores acendem a primeira fogueira em três noites, e o calor faz todo mundo chorar um pouco."]}, "fecho": {"en": ["In {povoado}, the woodcutters arrive in time for the fair, and sell all the firewood they managed to bring."], "pt": ["Em {povoado}, os lenhadores chegam a tempo da feira, e vendem toda a lenha que conseguiram trazer."]}, "pa": {"en": ["The silence here is strange."], "pt": ["O silêncio aqui está estranho."]}, "pb": {"en": ["In a woodcutters' camp, there is always someone chopping something."], "pt": ["Num acampamento de lenhador, sempre tem alguém cortando alguma coisa."]}, "entr": {"en": ["The camp near {lugar} is silent. Do you see the axes lying on the ground?"], "pt": ["O acampamento perto de {lugar} está em silêncio. Estão vendo os machados largados no chão?"]}, "chave": {"en": ["From the howling, the beasts are surrounding the huts, and those still in hiding will be found tonight."], "pt": ["Pelos uivos, as feras estão cercando as cabanas, e quem ainda se esconde vai ser achado esta noite."]}, "chc": {"en": ["From the howling, the beasts are surrounding the huts, and those still in hiding will be found tonight. The woodcutters of {povoado} are hiding in the huts."], "pt": ["Pelos uivos, as feras estão cercando as cabanas, e quem ainda se esconde vai ser achado esta noite. Os lenhadores de {povoado} estão escondidos nas cabanas."]}, "chs": {"en": ["From the howling, the beasts are surrounding the huts, and those still in hiding will be found tonight. That is why the camp was silent: the woodcutters are hiding."], "pt": ["Pelos uivos, as feras estão cercando as cabanas, e quem ainda se esconde vai ser achado esta noite. Por isso o acampamento estava em silêncio: os lenhadores estão escondidos."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance to the camp are a dead campfire and an axe buried in a log, with blood on the handle."], "pt": ["Na entrada do acampamento, há uma fogueira apagada e um machado cravado num tronco, com sangue no cabo."]}}, {"t": "h", "txt": {"en": ["Too much silence for a woodcutters' camp. The notice was right."], "pt": ["Silêncio demais para um acampamento de lenhadores. O aviso estava certo."]}}]}, "ovo": {"tit": {"en": ["The Dragon's Egg", "Before the Valley Burns", "What a Poacher Stole"], "pt": ["O Ovo da Dragoa", "Antes que o Vale Queime", "O Que Uma Presa Roubou"]}, "aviso": {"en": ["Help {povoado} before everything burns. Hunters stole an egg from the dragon's nest and hid it in {lugar}, and the mother has already burned two barns looking for it.", "Please return the egg to the nest. The dragon has been searching for it {desde}, and every night she burns a house in {povoado}.", "{povoado} is calling for help. The dragon's egg is in {lugar}, in the hands of hunters, and the mother will not stop until she finds it."], "pt": ["Ajudem {povoado} antes que tudo queime. Caçadores roubaram um ovo do ninho da dragoa e o esconderam em {lugar}, e a mãe já queimou dois celeiros procurando por ele.", "Por favor, devolvam o ovo ao ninho. A dragoa procura por ele {desde}, e cada noite ela queima uma casa de {povoado}.", "{povoado} pede socorro. O ovo da dragoa está em {lugar}, nas mãos de caçadores, e a mãe não vai parar até achá-lo."]}, "abert": {"en": ["The heroes reach {lugar}, and the dragon's shadow passes over them. She is still searching."], "pt": ["Os heróis chegam a {lugar}, e a sombra da dragoa passa sobre eles. Ela ainda está procurando."]}, "fala": {"en": ["They climbed to the nest before dawn and came down with the egg wrapped in furs. {vilao} sold the hide of the last dragon to a duke and means to sell this one too. The mother will burn first and ask questions later. If she asks at all."], "pt": ["Subiram ao ninho de madrugada e desceram com o ovo embrulhado em peles. {vilao} vendeu o couro do último dragão a um duque e quer vender este também. A mãe vai queimar primeiro e perguntar depois. Se é que pergunta."]}, "pista": {"nome": {"en": "A piece of shell", "pt": "Um pedaço de casca"}, "olhar": {"en": "A sliver of shell, hard as iron and still warm.", "pt": "Uma lasca de casca, dura como ferro e ainda morna."}, "revela": {"en": "Something hard and warm lies on the ground near the entrance.", "pt": "Há algo duro e quente no chão perto da entrada."}, "texto": {"en": ["The sliver of shell is still warm: the egg struck the stone when they dragged it through here. Beside it, a leather tag has fallen from the bundle: “For the duke. Price agreed with {vilao}.”"], "pt": ["A lasca de casca ainda está morna: o ovo bateu na pedra quando o arrastaram por aqui. Ao lado, caiu do embrulho uma etiqueta de couro: «Para o duque. Preço combinado com {vilao}.»"]}}, "ultima": {"en": ["The egg lies warm in a nest of furs, and {vilao} stands beside it, spear in hand."], "pt": ["O ovo está quente, num ninho de peles, e {vilao} está de pé ao lado dele, de lança na mão."]}, "narr": {"en": ["Outside, the dragon roars, and the walls shake."], "pt": ["Lá fora, a dragoa ruge, e as paredes tremem."]}, "vil": {"en": ["You want the egg? Make an offer. The duke has already made his."], "pt": ["Querem o ovo? Façam uma oferta. O duque já fez a dele."]}, "hc": {"en": ["The offer is outside, roaring."], "pt": ["A oferta está lá fora, rugindo."]}, "hs": {"en": ["Listen to the mother. She is making hers."], "pt": ["Escute a mãe. Ela está fazendo a dela."]}, "fim": {"en": ["The egg goes back to the nest, still warm. High above, the mother makes one slow circle over the valley, stares at you for a moment and flies away."], "pt": ["O ovo volta ao ninho, ainda quente. Lá no alto, a mãe dá uma volta lenta sobre o vale, encara vocês por um instante e vai embora."]}, "fecho": {"en": ["In {povoado}, for the first time in a week, no one looks up at the sky before leaving the house."], "pt": ["Em {povoado}, pela primeira vez em uma semana, ninguém olha para o céu antes de sair de casa."]}, "pa": {"en": ["Did you hear that? It sounded like thunder, but the sky is clear."], "pt": ["Vocês ouviram isso? Parecia trovão, mas o céu está limpo."]}, "pb": {"en": ["Thunder never roars twice in the same place."], "pt": ["Trovão nunca ruge duas vezes no mesmo lugar."]}, "entr": {"en": ["Did you see that shadow passing over us? It was a dragon, and she seems to be looking for something near {lugar}."], "pt": ["Vocês viram aquela sombra passando por cima de nós? Era uma dragoa, e parece que ela está procurando alguma coisa perto de {lugar}."]}, "chave": {"en": ["A roar shakes the walls: the mother has come down into the valley. The egg goes back now, or no one leaves here alive."], "pt": ["Um rugido sacode as paredes: a mãe já desceu ao vale. O ovo volta agora, ou ninguém sai daqui vivo."]}, "chc": {"en": ["A roar shakes the walls: the mother has come down into the valley. The egg goes back now, or no one leaves here alive. This time she will burn more than barns."], "pt": ["Um rugido sacode as paredes: a mãe já desceu ao vale. O ovo volta agora, ou ninguém sai daqui vivo. Desta vez ela vai queimar mais que celeiros."]}, "chs": {"en": ["A roar shakes the walls: the mother has come down into the valley. The egg goes back now, or no one leaves here alive. The thunder on the road was her."], "pt": ["Um rugido sacode as paredes: a mãe já desceu ao vale. O ovo volta agora, ou ninguém sai daqui vivo. O trovão da estrada era ela."]}, "elos": [{"t": "n", "txt": {"en": ["On the ground at the entrance are claw marks the size of a man, and a strong smell of sulfur."], "pt": ["No chão da entrada, há marcas de garra do tamanho de um homem, e um cheiro forte de enxofre."]}}, {"t": "h", "txt": {"en": ["These drag marks lead inside. The hunters from the notice brought the egg this way."], "pt": ["Essas marcas de arrasto vão para dentro. Os caçadores do aviso trouxeram o ovo por aqui."]}}]}, "ovo/leilao": {"tit": {"en": ["The Auction of the Egg", "Sold to the Duke", "Before the Auction"], "pt": ["O Leilão do Ovo", "Vendido ao Duque", "Antes do Leilão"]}, "aviso": {"en": ["Help {povoado} {ate}. The dragon's egg is going to be auctioned in {lugar}, and if it is sold, the mother will burn every village on the way to the buyer.", "Please reach {lugar} before the auction. The hunters are selling the dragon's egg, and {povoado} lies in the mother's path.", "{povoado} asks for help. The buyers of the dragon's egg have already arrived in {lugar}, and the auction is tonight."], "pt": ["Ajudem {povoado} {ate}. O ovo da dragoa vai ser leiloado em {lugar}, e se for vendido, a mãe vai queimar todas as vilas no caminho até o comprador.", "Por favor, cheguem a {lugar} antes do leilão. Os caçadores estão vendendo o ovo da dragoa, e {povoado} fica no caminho da mãe.", "{povoado} pede ajuda. Os compradores do ovo da dragoa já chegaram a {lugar}, e o leilão é esta noite."]}, "abert": {"en": ["The heroes reach {lugar}. Fine carriages are drawn up at the entrance, and guards in livery talk in low voices."], "pt": ["Os heróis chegam a {lugar}. Há carroças de luxo paradas na entrada, e guardas de libré conversam baixo."]}, "fala": {"en": ["The seller is {vilao}, and the buyers come from far away: a duke, a mage, two collectors. The egg is in the hall at the back, displayed like a jewel. The mother is outside, circling. If the egg leaves here in a carriage, she will follow that carriage to the end of the world."], "pt": ["Quem vende é {vilao}, e os compradores vêm de longe: um duque, um mago, dois colecionadores. O ovo está no salão do fundo, exposto como uma joia. A mãe está lá fora, rondando. Se o ovo sair daqui numa carroça, ela segue a carroça até o fim do mundo."]}, "pista": {"nome": {"en": "An auction catalog", "pt": "Um catálogo do leilão"}, "olhar": {"en": "A finely made paper, listing what is to be sold.", "pt": "Um papel caprichado, com a lista do que vai ser vendido."}, "revela": {"en": "A paper lies near the entrance.", "pt": "Há um papel caído perto da entrada."}, "texto": {"en": ["The catalog was printed with care, for wealthy people. At the top of the list, in golden letters: “Dragon's egg, still warm. Opening bid: one castle.” Below it is the auctioneer's name: {vilao}."], "pt": ["O catálogo foi impresso com capricho, para gente rica. No alto da lista, em letras douradas: «Ovo de dragoa, ainda quente. Lance mínimo: um castelo.» Embaixo, o nome do leiloeiro: {vilao}."]}}, "ultima": {"en": ["The egg rests on a velvet cushion, and {vilao} raps the auction hammer."], "pt": ["O ovo está sobre uma almofada de veludo, e {vilao} bate o martelo do leilão."]}, "narr": {"en": ["As you come in, the hall falls silent, and outside the dragon roars."], "pt": ["Quando vocês entram, o salão fica em silêncio, e lá fora a dragoa ruge."]}, "vil": {"en": ["Going once, going twice…"], "pt": ["Dou-lhe uma, dou-lhe duas…"]}, "hc": {"en": ["The auction is canceled."], "pt": ["Leilão cancelado."]}, "hs": {"en": ["Sold to the mother."], "pt": ["Vendido para a mãe."]}, "fim": {"en": ["The egg goes back to the nest, and the buyers flee in their fine carriages before the dragon decides to collect from all of them."], "pt": ["O ovo volta ao ninho, e os compradores fogem nas carroças de luxo antes que a dragoa decida cobrar a todos."]}, "fecho": {"en": ["In {povoado}, the buyers' carriages race through, and no one takes the trouble to ask them to stop."], "pt": ["Em {povoado}, as carroças dos compradores passam correndo, e ninguém se dá ao trabalho de pedir que parem."]}, "pa": {"en": ["Fine carriages on this road?"], "pt": ["Carroças de luxo nesta estrada?"]}, "pb": {"en": ["And with guards. Someone is selling something costly around here."], "pt": ["E com guardas. Alguém está vendendo coisa cara por aqui."]}, "entr": {"en": ["Look at the fine carriages drawn up at the entrance of {lugar}. Those are rich people who have come to buy something."], "pt": ["Olhem as carroças de luxo paradas na entrada de {lugar}. Isso é gente rica que veio comprar alguma coisa."]}, "chave": {"en": ["From the hall comes the auctioneer's voice: “Last bid!” Outside, the dragon roars closer."], "pt": ["Lá do salão vem a voz do leiloeiro: «Último lance!» Lá fora, a dragoa ruge mais perto."]}, "chc": {"en": ["From the hall comes the auctioneer's voice: “Last bid!” Outside, the dragon roars closer. It is the auction of the egg, and it is coming to an end."], "pt": ["Lá do salão vem a voz do leiloeiro: «Último lance!» Lá fora, a dragoa ruge mais perto. É o leilão do ovo, e ele está terminando."]}, "chs": {"en": ["From the hall comes the auctioneer's voice: “Last bid!” Outside, the dragon roars closer. The rich folk in the carriages came to buy the dragon's egg."], "pt": ["Lá do salão vem a voz do leiloeiro: «Último lance!» Lá fora, a dragoa ruge mais perto. Os ricos das carroças vieram comprar o ovo da dragoa."]}, "elos": [{"t": "n", "txt": {"en": ["The buyers for the auction have already arrived. One of them hands a sack of coins to a guard, without a word."], "pt": ["Os compradores do leilão já chegaram. Um deles passa um saco de moedas para um guarda, sem dizer nada."]}}, {"t": "h", "txt": {"en": ["The auction from the notice is here. Look at the carriages: only very rich people travel like that."], "pt": ["O leilão do aviso é aqui. Olhem as carroças: só gente muito rica anda assim."]}}]}, "ovo/ferida": {"tit": {"en": ["The Wounded Mother", "Fire and Pain", "The Fury of the Dragon"], "pt": ["A Mãe Ferida", "Fogo e Dor", "A Fúria da Dragoa"]}, "aviso": {"en": ["Help {povoado}. The hunters wounded the dragon when they stole her egg, and now she burns everything she finds, out of pain and rage.", "Please return the egg to the dragon before she burns {povoado}. She is wounded, and a wounded creature does not think.", "{povoado} is calling for help. The wounded dragon has been flying over {lugar} {desde}, and her egg is hidden in there."], "pt": ["Ajudem {povoado}. Os caçadores feriram a dragoa quando roubaram o ovo, e agora ela queima tudo o que encontra, de dor e de raiva.", "Por favor, devolvam o ovo à dragoa antes que ela queime {povoado}. Ela está ferida, e ferida não pensa.", "{povoado} pede socorro. A dragoa ferida voa sobre {lugar} {desde}, e o ovo dela está escondido lá dentro."]}, "abert": {"en": ["The heroes reach {lugar} and see a huge arrow stuck in the stone at the entrance, with dragon's blood on its tip."], "pt": ["Os heróis chegam a {lugar} e veem uma flecha enorme cravada na pedra da entrada, com sangue de dragão na ponta."]}, "fala": {"en": ["{vilao} wounded the dragon with a harpoon while taking the egg. Now she no longer searches, she only burns. If the egg comes back to her, she may calm down. If it does not, nothing will be left of {povoado}."], "pt": ["{vilao} feriu a dragoa com um arpão quando pegou o ovo. Agora ela não procura mais, só queima. Se o ovo voltar para perto dela, talvez ela se acalme. Se não voltar, não sobra nada de {povoado}."]}, "pista": {"nome": {"en": "A broken harpoon", "pt": "Um arpão quebrado"}, "olhar": {"en": "A huge harpoon, broken, with dark blood on its tip.", "pt": "Um arpão enorme, quebrado, com sangue escuro na ponta."}, "revela": {"en": "A broken harpoon lies near the entrance.", "pt": "Há um arpão quebrado perto da entrada."}, "texto": {"en": ["The harpoon is too big for hunting any ordinary animal, and the dark blood on its tip is still warm. On the shaft, carved by knife, is the name of the one who threw it, as a boast: {vilao}."], "pt": ["O arpão é grande demais para caçar qualquer bicho comum, e o sangue escuro na ponta ainda está quente. Na haste, gravado a faca, o nome de quem o atirou, para contar vantagem: {vilao}."]}}, "ultima": {"en": ["The egg lies in a nest of furs, and {vilao} stands beside it, another harpoon in hand."], "pt": ["O ovo está num ninho de peles, e {vilao} está ao lado, com outro arpão na mão."]}, "narr": {"en": ["Outside, the dragon roars in pain, and the ceiling shakes."], "pt": ["Lá fora, a dragoa ruge de dor, e o teto treme."]}, "vil": {"en": ["One harpoon for the mother, another for you. I brought several."], "pt": ["Um arpão para a mãe, outro para vocês. Eu trouxe vários."]}, "hc": {"en": ["{povoado} wants the dragon calm."], "pt": ["{povoado} quer a dragoa calma."]}, "hs": {"en": ["No one else shoots today."], "pt": ["Hoje ninguém mais atira."]}, "fim": {"en": ["The egg goes back to the nest, and the mother curls around it. The wound still bleeds, but she closes her eyes and stops burning."], "pt": ["O ovo volta ao ninho, e a mãe se deita em volta dele. A ferida ainda sangra, mas ela fecha os olhos e para de queimar."]}, "fecho": {"en": ["In {povoado}, the fire stops that night, and in the morning {gente} count the damage without looking up at the sky."], "pt": ["Em {povoado}, o fogo para naquela noite, e de manhã {gente} contam os estragos sem olhar para o céu."]}, "pa": {"en": ["Blood on the stone. A lot of it."], "pt": ["Sangue na pedra. Muito."]}, "pb": {"en": ["And too dark to be a person's."], "pt": ["E escuro demais para ser de gente."]}, "entr": {"en": ["There is a huge arrow stuck in the entrance of {lugar}, with dark blood on its tip. That was shot at something very large."], "pt": ["Tem uma flecha enorme cravada na entrada de {lugar}, com sangue escuro na ponta. Isso foi atirado em alguma coisa muito grande."]}, "chave": {"en": ["The ceiling cracks, and a blast of fire comes through the gap. The dragon is trying to get in."], "pt": ["O teto racha, e uma rajada de fogo entra pela fresta. A dragoa está tentando entrar."]}, "chc": {"en": ["The ceiling cracks, and a blast of fire comes through the gap. The dragon is trying to get in. It is the wounded dragon from the notice, and she will tear everything down to reach her egg."], "pt": ["O teto racha, e uma rajada de fogo entra pela fresta. A dragoa está tentando entrar. É a dragoa ferida do aviso, e ela vai derrubar tudo para chegar ao ovo."]}, "chs": {"en": ["The ceiling cracks, and a blast of fire comes through the gap. The dragon is trying to get in. The blood on the road was hers."], "pt": ["O teto racha, e uma rajada de fogo entra pela fresta. A dragoa está tentando entrar. O sangue da estrada era dela."]}, "elos": [{"t": "n", "txt": {"en": ["Around the arrow, the stone has melted. The wounded dragon from the notice has already been here."], "pt": ["Em volta da flecha, a pedra está derretida. A dragoa ferida do aviso já passou por aqui."]}}, {"t": "h", "txt": {"en": ["This blood is the dragon's. The notice said she was wounded."], "pt": ["Esse sangue é da dragoa. O aviso dizia que ela estava ferida."]}}]}, "matilha": {"tit": {"en": ["The Tamed Pack", "The Cages of {lugar}", "Before the Fair"], "pt": ["A Matilha Domesticada", "As Jaulas de {lugar}", "Antes da Feira"]}, "aviso": {"en": ["Help {povoado} {ate}. {feras} were seen being hauled in cages to {lugar}, a few days before the fair, and no one knows what for.", "Please find out what is in the cages of {lugar}. Roars have been heard from there {desde}, and the fair of {povoado} is about to open.", "{povoado} asks for help. Someone is gathering starving {feras} in {lugar}, and the square will be full on the day of the fair."], "pt": ["Ajudem {povoado} {ate}. Viram {feras} sendo levad⟨feras:o|a|os|as⟩ em jaulas para {lugar}, poucos dias antes da feira, e ninguém sabe para quê.", "Por favor, descubram o que há nas jaulas de {lugar}. Ouvem-se rugidos de lá {desde}, e a feira de {povoado} está para abrir.", "{povoado} pede ajuda. Alguém está juntando {feras} famint⟨feras:o|a|os|as⟩ em {lugar}, e a praça vai estar cheia no dia da feira."]}, "abert": {"en": ["The heroes follow the tracks of the heavy wagons to {lugar}. From inside comes a growl."], "pt": ["Os heróis seguem o rastro das carroças pesadas até {lugar}. Lá de dentro vem um rosnado."]}, "fala": {"en": ["They are keeping {feras} hungry on purpose. {vilao}, who was driven out of {povoado} for setting a bear on a merchant, means to open the cages in the middle of the square, on the day of the fair. Open them here first, and deal with whatever comes out."], "pt": ["Estão deixando {feras} com fome de propósito. {vilao}, que foi expuls⟨vilao:o|a⟩ de {povoado} por soltar um urso em cima de um mercador, quer abrir as jaulas no meio da praça, no dia da feira. Abram aqui primeiro, e deem conta do que sair."]}, "pista": {"nome": {"en": "A bent cage bar", "pt": "Uma barra de jaula torta"}, "olhar": {"en": "A cage bar bent outward, with tufts of fur caught on it.", "pt": "Uma barra de jaula entortada para fora, com tufos de pelo presos nela."}, "revela": {"en": "A bent iron bar lies near the entrance.", "pt": "Há uma barra de ferro torta perto da entrada."}, "texto": {"en": ["The bar was bent from the inside out, and there are chain marks on the floor: an animal escaped and was caught again. On a board beside it is the list of cages, with the day of the fair circled, and at the foot of the list a note for the henchmen: “Hunger. No food until the day. {vilao}.”"], "pt": ["A barra foi entortada de dentro para fora, e há marcas de corrente no chão: um bicho escapou e foi recapturado. Numa tábua ao lado, a lista das jaulas, com o dia da feira circulado, e no pé da lista um bilhete para os capangas: «Fome. Nada de comida até o dia. {vilao}.»"]}}, "ultima": {"en": ["This is the largest cage, with the hungriest animal. {vilao} carries the key on a chain around the neck."], "pt": ["Esta é a maior jaula, com o bicho mais faminto. {vilao} carrega a chave numa corrente no pescoço."]}, "narr": {"en": ["As you come in, {vilao} takes hold of the key and smiles."], "pt": ["Quando vocês entram, {vilao} segura a chave e sorri."]}, "vil": {"en": ["Here for the fair? You are early."], "pt": ["Vieram para a feira? Chegaram cedo."]}, "hc": {"en": ["The fair of {povoado} will open without your attraction."], "pt": ["A feira de {povoado} vai abrir sem a sua atração."]}, "hs": {"en": ["We came to close the stall."], "pt": ["Viemos fechar a barraca."]}, "fim": {"en": ["The cages are empty, and the animal smell will take a long time to leave this place. The fair, at least, will open in peace."], "pt": ["As jaulas estão vazias, e o cheiro de bicho vai demorar a sair dali. A feira, pelo menos, vai abrir em paz."]}, "fecho": {"en": ["In the square of {povoado}, the merchant of the bear tells his story again to anyone who will listen, now with you at the end of it."], "pt": ["Na praça de {povoado}, o mercador do urso conta a história de novo para quem quiser ouvir, agora com vocês no final."]}, "pa": {"en": ["The tracks of a heavy wagon. And this here is bear fur."], "pt": ["Rastro de carroça pesada. E isto aqui é pelo de urso."]}, "pb": {"en": ["Bears go on foot. Someone is carrying this one by wagon."], "pt": ["Urso anda a pé. Esse aí alguém está levando de carroça."]}, "entr": {"en": ["The wagon tracks lead into {lugar}. Did you hear that growl inside?"], "pt": ["O rastro das carroças entra em {lugar}. Ouviram esse rosnado lá dentro?"]}, "chave": {"en": ["The bars all rattle at once. The animals smell blood, and the padlocks are old."], "pt": ["As grades tremem todas de uma vez. Os bichos sentem cheiro de sangue, e os cadeados são velhos."]}, "chc": {"en": ["The bars all rattle at once. The animals smell blood, and the padlocks are old. They are {feras} that were brought here in cages."], "pt": ["As grades tremem todas de uma vez. Os bichos sentem cheiro de sangue, e os cadeados são velhos. São {feras} que trouxeram em jaulas para cá."]}, "chs": {"en": ["The bars all rattle at once. The animals smell blood, and the padlocks are old. These were the cages on the heavy wagon from the road."], "pt": ["As grades tremem todas de uma vez. Os bichos sentem cheiro de sangue, e os cadeados são velhos. Eram estas as jaulas da carroça pesada da estrada."]}, "elos": [{"t": "n", "txt": {"en": ["The growl is followed by another, and another, from different animals. The cages from the notice are here."], "pt": ["O rosnado vem acompanhado de outro, e mais outro, de bichos diferentes. As jaulas do aviso estão aqui."]}}, {"t": "h", "txt": {"en": ["The tracks of a heavy wagon and animal fur. This is where the cages the notice spoke of are kept."], "pt": ["Rastro de carroça pesada e pelo de bicho. É aqui que estão as jaulas de que o aviso falava."]}}]}, "matilha/rinha": {"tit": {"en": ["The Fighting Pit of {vilao}", "Bets in {lugar}", "The Hidden Arena"], "pt": ["A Rinha de {vilao}", "Apostas em {lugar}", "A Arena Escondida"]}, "aviso": {"en": ["Help {povoado}. In {lugar}, someone sets {feras} to fight, and the bets are paid in people: whoever loses a bet goes into the cage.", "Please put an end to the fighting pit of {lugar}. {desde}, men of {povoado} have been going there to bet, and some do not come back.", "{povoado} needs help. The fighting pit of {lugar} grows bigger all the time, and now they are buying {feras} from far away."], "pt": ["Ajudem {povoado}. Em {lugar}, alguém põe {feras} para brigar, e as apostas são pagas com gente: quem perde a aposta entra na jaula.", "Por favor, acabem com a rinha de {lugar}. {desde}, homens de {povoado} vão apostar lá, e alguns não voltam.", "{povoado} precisa de ajuda. A rinha de {lugar} está cada vez maior, e agora estão comprando {feras} de longe."]}, "abert": {"en": ["The heroes follow the shouted bets and the roars to the entrance of {lugar}."], "pt": ["Os heróis seguem os gritos de aposta e os rugidos até a entrada de {lugar}."]}, "fala": {"en": ["{vilao} runs the pit. Starving {feras} are set to fight, and whoever cannot pay a bet goes into the cage as well. The cages are scattered around here. Open them all, and the pit is finished."], "pt": ["{vilao} cuida da rinha. Põe {feras} famint⟨feras:o|a|os|as⟩ para brigar, e quem não paga a aposta vai para dentro da jaula também. As jaulas estão espalhadas por aqui. Abram todas, e a rinha acaba."]}, "pista": {"nome": {"en": "A betting slip", "pt": "Um bilhete de aposta"}, "olhar": {"en": "A paper with numbers and names, crumpled and stained with blood.", "pt": "Um papel com números e nomes, amassado e manchado de sangue."}, "revela": {"en": "A crumpled paper lies near the entrance.", "pt": "Há um papel amassado perto da entrada."}, "texto": {"en": ["The slip is for a bet, and the name crossed out at the top is that of a man from {povoado}. You can tell he lost: beside the name is written “to the cage”. At the bottom is the stamp of the betting house, with the name of the one who runs it: {vilao}."], "pt": ["O bilhete é de uma aposta, e o nome riscado no alto é de um homem de {povoado}. Vocês percebem que ele perdeu, porque ao lado do nome está escrito «para a jaula». Embaixo, o carimbo da casa de apostas, com o nome de quem a manda: {vilao}."]}}, "ultima": {"en": ["At the center of the arena, the largest cage stands open, and {vilao} calls the bets from the top of a bench."], "pt": ["No centro da arena, a maior jaula está aberta, e {vilao} chama as apostas de cima de um banco."]}, "narr": {"en": ["As you come in, the shouting stops, and {vilao} points at you."], "pt": ["Quando vocês entram, a gritaria para, e {vilao} aponta para vocês."]}, "vil": {"en": ["New fighters! Place your bets."], "pt": ["Novos lutadores! Façam suas apostas."]}, "hc": {"en": ["The bet of {povoado} is against you."], "pt": ["A aposta de {povoado} é contra você."]}, "hs": {"en": ["I bet on us."], "pt": ["Aposto em nós."]}, "fim": {"en": ["The cages are empty, and the gamblers flee through the back door. On the sand of the arena lie the coins no one had time to gather."], "pt": ["As jaulas estão vazias, e os apostadores fogem pela porta dos fundos. Na areia da arena, ficam as moedas que ninguém teve tempo de recolher."]}, "fecho": {"en": ["In {povoado}, the men who came back from the pit swear never to bet again. Some of them, at least."], "pt": ["Em {povoado}, os homens que voltaram da rinha juram nunca mais apostar. Alguns, pelo menos."]}, "pa": {"en": ["Did you hear that? Shouting."], "pt": ["Ouviram isso? Gritaria."]}, "pb": {"en": ["The shouting of bets. And roaring in the middle of it."], "pt": ["Gritaria de aposta. E rugido no meio."]}, "entr": {"en": ["Listen to the shouted bets coming from {lugar}. And that in the middle is the roar of a large animal."], "pt": ["Escutem os gritos de aposta vindo de {lugar}. E isso no meio é rugido de bicho grande."]}, "chave": {"en": ["A huge roar, and the crowd screams. It seems someone has just lost a bet."], "pt": ["Um rugido enorme, e a plateia grita. Parece que alguém acabou de perder uma aposta."]}, "chc": {"en": ["A huge roar, and the crowd screams. It seems someone has just lost a bet. Whoever lost goes into the cage."], "pt": ["Um rugido enorme, e a plateia grita. Parece que alguém acabou de perder uma aposta. Quem perdeu vai para a jaula."]}, "chs": {"en": ["A huge roar, and the crowd screams. It seems someone has just lost a bet. It is the shouting you heard from the road."], "pt": ["Um rugido enorme, e a plateia grita. Parece que alguém acabou de perder uma aposta. É a gritaria que vocês ouviram da estrada."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance, a man counts coins and crosses names off a board. Those are the night's bets."], "pt": ["Na entrada, um homem conta moedas e risca nomes numa tábua. São as apostas da noite."]}}, {"t": "h", "txt": {"en": ["The fighting pit from the notice. Listen to the bets: those are people of {povoado} in there."], "pt": ["A rinha do aviso. Escutem as apostas: é gente de {povoado} lá dentro."]}}]}, "matilha/soltas": {"tit": {"en": ["The Open Cages", "Beasts on the Road", "What Escaped"], "pt": ["As Jaulas Abertas", "Feras na Estrada", "O Que Escapou"]}, "aviso": {"en": ["Help {povoado}. Some of the cages of {lugar} have opened, and {feras} are roaming loose on the road. {gente} {gentefaz}.", "Please close the cages of {lugar} before the rest escape. {desde}, {feras} have been attacking those who pass near {povoado}.", "{povoado} is calling for help. {feras} have escaped from the cages of {lugar}, and whoever caged them is letting the rest out little by little."], "pt": ["Ajudem {povoado}. Algumas jaulas de {lugar} se abriram, e {feras} andam soltos pela estrada. {gente} {gentefaz}.", "Por favor, fechem as jaulas de {lugar} antes que o resto escape. {desde}, {feras} atacam quem passa perto de {povoado}.", "{povoado} pede socorro. Escaparam {feras} das jaulas de {lugar}, e quem os prendeu está soltando o resto aos poucos."]}, "abert": {"en": ["The heroes reach {lugar} and find empty cages at the entrance, their doors torn off."], "pt": ["Os heróis chegam a {lugar} e acham jaulas vazias na entrada, com as portas arrancadas."]}, "fala": {"en": ["{vilao} is letting the animals out little by little, one a night, to see how far they get. There are still full cages in here. Close the ones that are open, and deal with what has already got out."], "pt": ["{vilao} está soltando os bichos aos poucos, um por noite, para ver até onde chegam. Ainda tem jaulas cheias aqui dentro. Fechem as que estão abertas, e cuidem do que já saiu."]}, "pista": {"nome": {"en": "A broken cage", "pt": "Uma jaula arrombada"}, "olhar": {"en": "A cage with its door torn from the hinges.", "pt": "Uma jaula com a porta arrancada das dobradiças."}, "revela": {"en": "A broken cage stands near the entrance.", "pt": "Há uma jaula arrombada perto da entrada."}, "texto": {"en": ["The cage door was opened from the outside: the hinges were sawn through, on purpose, to let the animal out. On the saw left beside it, carved into the handle, is the owner's name: {vilao}."], "pt": ["A porta da jaula foi aberta por fora: as dobradiças foram serradas, de propósito, para o bicho sair. Na serra largada ao lado, gravado no cabo, o nome do dono: {vilao}."]}}, "ultima": {"en": ["The last cage is shut, and {vilao} holds the key, ready to open it."], "pt": ["A última jaula está fechada, e {vilao} segura a chave, pront⟨vilao:o|a⟩ para abrir."]}, "narr": {"en": ["As you come in, {vilao} slides the key into the lock."], "pt": ["Quando vocês entram, {vilao} enfia a chave na fechadura."]}, "vil": {"en": ["Want to see what is in here?"], "pt": ["Querem ver o que tem aqui dentro?"]}, "hc": {"en": ["{povoado} wants that cage shut."], "pt": ["{povoado} quer essa jaula fechada."]}, "hs": {"en": ["That one stays locked."], "pt": ["Essa fica trancada."]}, "fim": {"en": ["The last cage stays locked, and the animals that are left lie down, tired of roaring."], "pt": ["A última jaula fica trancada, e os bichos que sobraram se deitam, cansados de rugir."]}, "fecho": {"en": ["In {povoado}, the road is safe again, and {gente} go back to work."], "pt": ["Em {povoado}, a estrada volta a ser segura, e {gente} voltam ao trabalho."]}, "pa": {"en": ["The footprints of a large animal, on the road."], "pt": ["Pegadas de bicho grande, na estrada."]}, "pb": {"en": ["And no chain. That one is loose."], "pt": ["E nenhuma corrente. Esse aí está solto."]}, "entr": {"en": ["Look at the empty cages at the entrance of {lugar}, their doors torn off."], "pt": ["Olhem as jaulas vazias na entrada de {lugar}, com as portas arrancadas."]}, "chave": {"en": ["A cage is heard opening deep inside, and a moment later a roar. One more animal is out."], "pt": ["Ouve-se uma jaula se abrindo lá no fundo, e logo depois um rugido. Mais um bicho saiu."]}, "chc": {"en": ["A cage is heard opening deep inside, and a moment later a roar. One more animal is out. This is how {feras} reach the road."], "pt": ["Ouve-se uma jaula se abrindo lá no fundo, e logo depois um rugido. Mais um bicho saiu. É assim que {feras} chegam à estrada."]}, "chs": {"en": ["A cage is heard opening deep inside, and a moment later a roar. One more animal is out. The animal that left the footprints on the road came out of one of these cages."], "pt": ["Ouve-se uma jaula se abrindo lá no fundo, e logo depois um rugido. Mais um bicho saiu. O bicho das pegadas da estrada saiu de uma destas jaulas."]}, "elos": [{"t": "n", "txt": {"en": ["One of the empty cages is still swinging. The animal that was in it left a short while ago."], "pt": ["Uma das jaulas vazias ainda balança. O bicho que estava nela saiu há pouco."]}}, {"t": "h", "txt": {"en": ["The open cages from the notice. From the size of the footprints, what got out of here is big."], "pt": ["As jaulas abertas do aviso. Pelo tamanho das pegadas, o que saiu daqui é grande."]}}]}, "santo": {"tit": {"en": ["The Defiled Saint", "What {vilao} Took from the Chapel", "The Bones of {santo}"], "pt": ["O Santo Profanado", "O Que {vilao} Tirou da Capela", "Os Ossos de {santo}"]}, "aviso": {"en": ["Help the chapel of {povoado}. The body of {santo} was stolen from the tomb, and since that night {sinal}.", "Please bring {santo} back. The body was stolen from the chapel of {povoado}, and the tracks lead to {lugar}.", "{povoado} is calling for help. Without the body of {santo} in the tomb, the dead of the graveyard do not rest."], "pt": ["Ajudem a capela de {povoado}. O corpo de {santo} foi roubado do túmulo, e desde aquela noite {sinal}.", "Por favor, tragam {santo} de volta. Roubaram o corpo da capela de {povoado}, e os rastros vão até {lugar}.", "{povoado} pede socorro. Sem o corpo de {santo} no túmulo, os mortos do cemitério não descansam."]}, "abert": {"en": ["The heroes follow the drops of black wax, which lead out of the graveyard and all the way to {lugar}."], "pt": ["Os heróis seguem as gotas de cera negra, que saem do cemitério e levam até {lugar}."]}, "fala": {"en": ["They opened the tomb from the outside, with tools and with care, like people who know their work. {vilao} spent the winter buying bones from grave robbers, and now has taken {santo}. Without {santo} in the tomb, the dead walk. Bring the body back."], "pt": ["Abriram o túmulo por fora, com ferramenta e com cuidado, como quem sabe o que faz. {vilao} passou o inverno comprando ossos de saqueadores de túmulos, e agora levou {santo}. Sem {santo} no túmulo, os mortos andam. Tragam o corpo de volta."]}, "pista": {"nome": {"en": "A trail of wax", "pt": "Um rastro de cera"}, "olhar": {"en": "Drops of black wax on the ground, as if from candles carried in a hurry.", "pt": "Gotas de cera negra no chão, como de velas carregadas às pressas."}, "revela": {"en": "There are drops of wax on the ground near the entrance.", "pt": "Há gotas de cera no chão perto da entrada."}, "texto": {"en": ["The drops of black wax fall in two rows, from the candles of those who carried the body, one on each side. At the end of them, lost on the ground, is a grave robber's receipt: “Paid for the body of {santo}. Delivered to {vilao}.”"], "pt": ["As gotas de cera negra caem em duas fileiras, das velas de quem carregou o corpo, um de cada lado. No fim delas, perdido no chão, há um recibo de saqueador de túmulos: «Pago pelo corpo de {santo}. Entregue a {vilao}.»"]}}, "ultima": {"en": ["The body of {santo} lies on a stone slab, ringed with black candles, and {vilao} stands beside it."], "pt": ["O corpo de {santo} está numa laje de pedra, cercado de velas negras, e {vilao} está de pé ao lado."]}, "narr": {"en": ["The black candles all lean toward {vilao} as you come in."], "pt": ["As velas negras se inclinam todas para {vilao} quando vocês entram."]}, "vil": {"en": ["Come to pray? The dead enjoy company."], "pt": ["Vieram rezar? Os mortos gostam de companhia."]}, "hc": {"en": ["The chapel of {povoado} wants {santo} back."], "pt": ["A capela de {povoado} quer {santo} de volta."]}, "hs": {"en": ["We came to take {santo} home."], "pt": ["Viemos levar {santo} para casa."]}, "fim": {"en": ["The body of {santo} weighs little, almost nothing, and you carry it more carefully than you would carry a wounded friend."], "pt": ["O corpo de {santo} pesa pouco, quase nada, e vocês o carregam com mais cuidado do que carregariam um ferido."]}, "fecho": {"en": ["In {povoado}, {santo} returns to the slab. The next morning, for the first time in weeks, the bell rings for service, and the chapel fills."], "pt": ["Em {povoado}, {santo} volta à laje. Na manhã seguinte, pela primeira vez em semanas, o sino toca para a missa, e a capela enche."]}, "pa": {"en": ["No bell has rung all day. Not even for service."], "pt": ["Sino nenhum tocou o dia inteiro. Nem para a missa."]}, "pb": {"en": ["In chapel country, that is a bad sign."], "pt": ["Em terra de capela, isso é mau sinal."]}, "entr": {"en": ["These drops of black wax on the ground make a trail, and it leads into {lugar}."], "pt": ["Essas gotas de cera negra no chão fazem uma trilha, e ela entra em {lugar}."]}, "chave": {"en": ["There is fresh earth on your boots, and hands are coming up out of the ground. The dead are rising faster and faster."], "pt": ["Há terra fresca nas botas de vocês, e mãos saindo do chão. Os mortos se levantam cada vez mais depressa."]}, "chc": {"en": ["There is fresh earth on your boots, and hands are coming up out of the ground. The dead are rising faster and faster. The dead are rising because {santo} has left the tomb."], "pt": ["Há terra fresca nas botas de vocês, e mãos saindo do chão. Os mortos se levantam cada vez mais depressa. Os mortos se levantam porque {santo} saiu do túmulo."]}, "chs": {"en": ["There is fresh earth on your boots, and hands are coming up out of the ground. The dead are rising faster and faster. This was the bad sign of the silent bell."], "pt": ["Há terra fresca nas botas de vocês, e mãos saindo do chão. Os mortos se levantam cada vez mais depressa. Era este o mau sinal do sino calado."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance, a piece of the shroud of {santo} is caught on a stone."], "pt": ["Na entrada, há um pedaço da mortalha de {santo}, preso numa pedra."]}}, {"t": "h", "txt": {"en": ["The black wax from the candles of those who took {santo}. The notice was right: they came here."], "pt": ["A cera negra das velas de quem levou {santo}. O aviso estava certo: vieram para cá."]}}]}, "santo/procissao": {"tit": {"en": ["The Procession of {santo}", "Before the Saint's Day", "The Empty Litter"], "pt": ["A Procissão de {santo}", "Antes do Dia do Santo", "O Andor Vazio"]}, "aviso": {"en": ["Help {povoado} {ate}. The day of {santo} is coming, and the body has been stolen from the tomb. Without {santo}, there is no procession, and the dead of the graveyard are already restless.", "Please find the body of {santo} before the day of the procession. {povoado} waits all year for that day.", "{povoado} asks for help. The litter of {santo} is ready, but the body is gone, and the tracks lead to {lugar}."], "pt": ["Ajudem {povoado} {ate}. O dia de {santo} está chegando, e o corpo foi roubado do túmulo. Sem {santo}, não há procissão, e os mortos do cemitério já estão inquietos.", "Por favor, achem o corpo de {santo} antes do dia da procissão. {povoado} espera o ano inteiro por esse dia.", "{povoado} pede ajuda. O andor de {santo} está pronto, mas o corpo sumiu, e os rastros vão até {lugar}."]}, "abert": {"en": ["The heroes follow the flowers from the litter, still fresh, along the road that leads to {lugar}."], "pt": ["Os heróis seguem as flores do andor, ainda frescas, pela estrada que leva a {lugar}."]}, "fala": {"en": ["{vilao} took {santo} at this very time because, on the day of the procession, the dead grow stronger. If the litter goes out empty, the whole graveyard of {povoado} will rise. The body is deep inside."], "pt": ["{vilao} levou {santo} justamente agora porque, no dia da procissão, os mortos ficam mais fortes. Se o andor sair vazio, o cemitério de {povoado} se levanta inteiro. O corpo está lá no fundo."]}, "pista": {"nome": {"en": "A flower from the litter", "pt": "Uma flor do andor"}, "olhar": {"en": "A white flower, trampled, lying in the way.", "pt": "Uma flor branca, pisoteada, caída no caminho."}, "revela": {"en": "There are trampled flowers near the entrance.", "pt": "Há flores pisoteadas perto da entrada."}, "texto": {"en": ["The flowers are from the litter of {santo}, and they were torn off in haste: petals are scattered all the way inside. Caught on a thorn is a procession ribbon with a sentence embroidered inside out: “This year, the saint belongs to {vilao}.”"], "pt": ["As flores são do andor de {santo}, e foram arrancadas na pressa, porque há pétalas espalhadas até o fundo. Presa num espinho, uma fita de procissão com uma frase bordada às avessas: «Este ano, o santo é de {vilao}.»"]}}, "ultima": {"en": ["The body of {santo} lies on a stolen litter, and {vilao} is decking it with black flowers."], "pt": ["O corpo de {santo} está deitado num andor roubado, e {vilao} o enfeita com flores negras."]}, "narr": {"en": ["As you come in, {vilao} sets the last black flower in place."], "pt": ["Quando vocês entram, {vilao} termina de pôr a última flor negra."]}, "vil": {"en": ["The procession will go out, oh yes. To my side."], "pt": ["A procissão vai sair, sim. Para o meu lado."]}, "hc": {"en": ["The procession of {povoado} goes out on the proper day."], "pt": ["A procissão de {povoado} sai no dia certo."]}, "hs": {"en": ["That litter goes back to the chapel."], "pt": ["Esse andor volta para a capela."]}, "fim": {"en": ["The body of {santo} goes back to the proper litter, and the black flowers are thrown away one by one."], "pt": ["O corpo de {santo} volta ao andor certo, e as flores negras são jogadas fora uma por uma."]}, "fecho": {"en": ["In {povoado}, the procession goes out on the appointed day, and those who carry the litter swear it is lighter this year."], "pt": ["Em {povoado}, a procissão sai no dia marcado, e quem carrega o andor jura que ele está mais leve este ano."]}, "pa": {"en": ["White flowers trampled on the road."], "pt": ["Flores brancas pisoteadas na estrada."]}, "pb": {"en": ["Those are procession flowers. Someone came by in a hurry."], "pt": ["São flores de procissão. Alguém passou com pressa."]}, "entr": {"en": ["There are procession flowers trampled on the road that leads into {lugar}."], "pt": ["Tem flores de procissão pisoteadas na estrada que entra em {lugar}."]}, "chave": {"en": ["From deep inside comes a procession hymn, sung backward. The dead behind you are rising."], "pt": ["Lá do fundo vem um canto de procissão, cantado ao contrário. Os mortos atrás de vocês se levantam."]}, "chc": {"en": ["From deep inside comes a procession hymn, sung backward. The dead behind you are rising. The day of {santo} is drawing nearer."], "pt": ["Lá do fundo vem um canto de procissão, cantado ao contrário. Os mortos atrás de vocês se levantam. O dia de {santo} está cada vez mais perto."]}, "chs": {"en": ["From deep inside comes a procession hymn, sung backward. The dead behind you are rising. The trampled flowers on the road came from this procession."], "pt": ["Lá do fundo vem um canto de procissão, cantado ao contrário. Os mortos atrás de vocês se levantam. As flores pisoteadas da estrada eram desta procissão."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance lie white flowers from the litter of {santo}, trampled."], "pt": ["Na entrada, há flores brancas do andor de {santo}, pisoteadas."]}}, {"t": "h", "txt": {"en": ["The flowers from the procession of {povoado}. Whoever took {santo} came this way."], "pt": ["As flores da procissão de {povoado}. Quem levou {santo} passou por aqui."]}}]}, "santo/sacristao": {"tit": {"en": ["The Sacristan of {povoado}", "The Empty Chapel", "Who Opened the Tomb"], "pt": ["O Sacristão de {povoado}", "A Capela Vazia", "Quem Abriu o Túmulo"]}, "aviso": {"en": ["Help {povoado}. The sacristan vanished on the same night the body of {santo} disappeared from the tomb.", "Please find out what happened in the chapel of {povoado}. The tomb of {santo} was found empty at dawn, and the sacristan, who slept there, vanished with it.", "{povoado} asks for help. Without {santo} and without the sacristan, {sinal}."], "pt": ["Ajudem {povoado}. O sacristão sumiu na mesma noite em que o corpo de {santo} desapareceu do túmulo.", "Por favor, descubram o que aconteceu na capela de {povoado}. O túmulo de {santo} amanheceu vazio, e o sacristão, que dormia lá, sumiu junto.", "{povoado} pede ajuda. Sem {santo} e sem o sacristão, {sinal}."]}, "abert": {"en": ["The heroes follow the sacristan's footprints, which lead out of the chapel and on to {lugar}. Beside them are other footprints, larger ones."], "pt": ["Os heróis seguem as pegadas do sacristão, que saem da capela e vão até {lugar}. Ao lado delas, há outras pegadas, maiores."]}, "fala": {"en": ["The sacristan tried to stop it, and {vilao} took him along with the body of {santo}. He is needed to open the prayers of the chapel, backward. If the sacristan is still alive, he is deep inside, near the body."], "pt": ["O sacristão tentou impedir, e {vilao} o levou junto com o corpo de {santo}. Precisa dele para abrir as orações da capela, ao contrário. Se o sacristão ainda estiver vivo, está lá no fundo, perto do corpo."]}, "pista": {"nome": {"en": "A ring of keys", "pt": "Um molho de chaves"}, "olhar": {"en": "A ring of chapel keys, lying on the ground.", "pt": "Um molho de chaves de capela, caído no chão."}, "revela": {"en": "A ring of keys lies near the entrance.", "pt": "Há um molho de chaves caído perto da entrada."}, "texto": {"en": ["The keys belong to the chapel of {povoado}, and the sacristan dropped them on purpose: they lie right in the middle of the path, where anyone would see them. Tied to the ring is a note in a shaky hand: “I was taken. {vilao}. Deep inside.”"], "pt": ["As chaves são da capela de {povoado}, e o sacristão as deixou cair de propósito, porque estão bem no meio do caminho, onde qualquer um veria. Na argola, alguém amarrou um bilhete com letra tremida: «Fui levado. {vilao}. Lá no fundo.»"]}}, "ultima": {"en": ["The body of {santo} lies on a slab, and the sacristan is tied up beside it, praying. {vilao} reads the prayers backward."], "pt": ["O corpo de {santo} está numa laje, e o sacristão está amarrado ao lado, rezando. {vilao} lê as orações de trás para frente."]}, "narr": {"en": ["As you come in, the sacristan stops praying and looks at you with relief."], "pt": ["Quando vocês entram, o sacristão para de rezar e olha para vocês com alívio."]}, "vil": {"en": ["He prays one way. I pray the other. Let us see whom the dead listen to."], "pt": ["Ele reza para um lado. Eu rezo para o outro. Vejamos quem os mortos escutam."]}, "hc": {"en": ["{povoado} wants both of them back."], "pt": ["{povoado} quer os dois de volta."]}, "hs": {"en": ["Both of them are coming with us."], "pt": ["Os dois vêm com a gente."]}, "fim": {"en": ["The sacristan is untied, and the first thing he does is cover the body of {santo} with his own cloak."], "pt": ["O sacristão é desamarrado, e a primeira coisa que faz é cobrir o corpo de {santo} com o próprio manto."]}, "fecho": {"en": ["In {povoado}, the sacristan sleeps in the chapel again, now with the door locked from the inside."], "pt": ["Em {povoado}, o sacristão volta a dormir na capela, agora com a porta trancada por dentro."]}, "pa": {"en": ["A chapel with its door open, before dawn."], "pt": ["Uma capela de porta aberta, de madrugada."]}, "pb": {"en": ["No sacristan leaves the chapel door open."], "pt": ["Sacristão nenhum deixa a porta da capela aberta."]}, "entr": {"en": ["There is a ring of chapel keys lying at the entrance of {lugar}. It looks as if someone dropped it on purpose."], "pt": ["Tem um molho de chaves de capela caído na entrada de {lugar}. Parece que alguém deixou cair de propósito."]}, "chave": {"en": ["From deep inside comes the sacristan's voice, praying louder and louder. A moment later, the dead behind you rise."], "pt": ["Lá do fundo vem a voz do sacristão, rezando cada vez mais alto. Logo depois, os mortos atrás de vocês se levantam."]}, "chc": {"en": ["From deep inside comes the sacristan's voice, praying louder and louder. A moment later, the dead behind you rise. The sacristan from the notice is alive."], "pt": ["Lá do fundo vem a voz do sacristão, rezando cada vez mais alto. Logo depois, os mortos atrás de vocês se levantam. O sacristão do aviso está vivo."]}, "chs": {"en": ["From deep inside comes the sacristan's voice, praying louder and louder. A moment later, the dead behind you rise. He was the one who looked after the chapel with the open door."], "pt": ["Lá do fundo vem a voz do sacristão, rezando cada vez mais alto. Logo depois, os mortos atrás de vocês se levantam. Era ele quem cuidava da capela de porta aberta."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance, a ring of keys from the chapel of {povoado} lies in the middle of the path, where anyone would see it."], "pt": ["Na entrada, há um molho de chaves da capela de {povoado} caído no meio do caminho, onde qualquer um veria."]}}, {"t": "h", "txt": {"en": ["These keys are from the chapel in the notice. The sacristan dropped them on purpose."], "pt": ["Essas chaves são da capela do aviso. O sacristão deixou cair de propósito."]}}]}, "coroa": {"tit": {"en": ["The False Crown", "The Heir Who Was Not", "The High Collar"], "pt": ["A Coroa Falsa", "O Herdeiro que Não Era", "A Gola Alta"]}, "aviso": {"en": ["Help {povoado} {ate}. A stranger has arrived claiming to be the heir to the barony, missing for ten years, and tomorrow he will hand the keys of the fief to the Legion. Those who knew the boy say this man is an impostor.", "Please find the proof before dawn. The false heir of {povoado} is going to hand the fief to the Legion, the army surrounding the region, and no one believes those who knew the boy.", "{povoado} will be handed to the Legion tomorrow by an impostor. The proof of the lie is kept in {lugar}."], "pt": ["Ajudem {povoado} {ate}. Um estranho chegou dizendo ser o herdeiro do baronato, sumido há dez anos, e amanhã vai entregar as chaves do feudo à Legião. Quem conheceu o menino diz que esse homem é um impostor.", "Por favor, achem a prova antes do amanhecer. O falso herdeiro de {povoado} vai entregar o feudo à Legião, o exército que cerca a região, e ninguém acredita em quem conheceu o menino.", "{povoado} vai ser entregue à Legião amanhã por um impostor. A prova da mentira está guardada em {lugar}."]}, "abert": {"en": ["The heroes go to {lugar}, where the papers of the baron's family are kept."], "pt": ["Os heróis vão até {lugar}, onde estão guardados os papéis da família do barão."]}, "fala": {"en": ["The true heir had a birthmark on his neck, and this one only ever wears a high collar. His name is {vilao}; he served the Legion on the border and tore the family's secrets out of a prisoner. The proof is in here. Find it before dawn."], "pt": ["O herdeiro verdadeiro tinha uma marca de nascença no pescoço, e esse aí só anda de gola alta. Chama-se {vilao}, serviu à Legião na fronteira e arrancou os segredos da família de um prisioneiro. A prova está aqui dentro. Achem antes do amanhecer."]}, "pista": {"nome": {"en": "A torn portrait", "pt": "Um retrato rasgado"}, "olhar": {"en": "A portrait of the baron's family, with the boy's face cut out.", "pt": "Um retrato da família do barão, com o rosto do menino recortado."}, "revela": {"en": "A painting lies near the entrance.", "pt": "Há um quadro caído perto da entrada."}, "texto": {"en": ["In the family portrait, the boy's face has been carefully cut out, so that no one would remember what the heir looked like. Behind the frame, forgotten, is a letter from the Legion addressed to the false heir by his true name: {vilao}."], "pt": ["No retrato da família, o rosto do menino foi recortado com cuidado, para que ninguém lembrasse como o herdeiro era. Atrás da moldura, esquecida, há uma carta da Legião endereçada ao falso herdeiro pelo nome verdadeiro: {vilao}."]}}, "ultima": {"en": ["In the great hall, the false heir sits in the baron's chair. {vilao} is smiling, because the Legion is already at the gates."], "pt": ["No grande salão, o falso herdeiro está sentado na cadeira do barão. {vilao} sorri, porque a Legião já está nos portões."]}, "narr": {"en": ["As you come in, {vilao} straightens the high collar."], "pt": ["Quando vocês entram, {vilao} ajeita a gola alta."]}, "vil": {"en": ["Visitors on the night I take my seat? What an honor."], "pt": ["Visitas na noite da minha posse? Que honra."]}, "hc": {"en": ["Those who knew the boy send their regards. Show your neck."], "pt": ["Quem conheceu o menino mandou lembrança. Mostre o pescoço."]}, "hs": {"en": ["We came to see your neck."], "pt": ["Viemos ver o seu pescoço."]}, "fim": {"en": ["The mask falls before the whole hall. For a moment, no one speaks. Then someone at the back asks, very quietly, where the true heir is."], "pt": ["A máscara cai diante de todo o salão. Por um momento, ninguém fala. Depois, alguém lá do fundo pergunta, baixinho, onde está o herdeiro de verdade."]}, "fecho": {"en": ["In {povoado}, the keys of the fief go back to the family, and at the gates the Legion waits for a handover that is not going to happen."], "pt": ["Em {povoado}, as chaves do feudo voltam para a família, e nos portões a Legião espera por uma entrega que não vai acontecer."]}, "pa": {"en": ["The colors of the Legion on the baron's road."], "pt": ["As cores da Legião na estrada do barão."]}, "pb": {"en": ["And the gate let them through."], "pt": ["E o portão deixou passar."]}, "entr": {"en": ["Do you see the banners over {lugar}? They belong to the Legion, the army surrounding the region."], "pt": ["Estão vendo as bandeiras sobre {lugar}? São da Legião, o exército que cerca a região."]}, "chave": {"en": ["A herald's voice carries from the hall: the keys change hands at dawn. The time for gathering proof is over."], "pt": ["A voz de um arauto chega do salão: as chaves mudam de mãos ao amanhecer. O tempo de juntar provas acabou."]}, "chc": {"en": ["A herald's voice carries from the hall: the keys change hands at dawn. The time for gathering proof is over. The proof against the impostor has to leave here before then."], "pt": ["A voz de um arauto chega do salão: as chaves mudam de mãos ao amanhecer. O tempo de juntar provas acabou. As provas contra o impostor precisam sair daqui antes disso."]}, "chs": {"en": ["A herald's voice carries from the hall: the keys change hands at dawn. The time for gathering proof is over. The colors of the Legion on the road were here for this handover."], "pt": ["A voz de um arauto chega do salão: as chaves mudam de mãos ao amanhecer. O tempo de juntar provas acabou. As cores da Legião na estrada eram para esta entrega."]}, "elos": [{"t": "n", "txt": {"en": ["Over {lugar} fly the banners of the Legion, the army surrounding the region. The handover of the keys from the notice is close."], "pt": ["Sobre {lugar} tremulam as bandeiras da Legião, o exército que cerca a região. A entrega das chaves do aviso está perto."]}}, {"t": "h", "txt": {"en": ["If there is proof that the heir from the notice is false, it is among these papers."], "pt": ["Se existe prova de que o herdeiro do aviso é falso, está entre esses papéis."]}}]}, "coroa/testamento": {"tit": {"en": ["The Baron's Will", "The Last Wish", "Before the Reading"], "pt": ["O Testamento do Barão", "A Última Vontade", "Antes da Leitura"]}, "aviso": {"en": ["Help {povoado}. The baron's will vanished on the night of his death, and whoever stole it wants the fief for himself. The reading is tomorrow.", "Please find the baron's will. It was taken to {lugar}, and without it the fief of {povoado} goes to the wrong hands.", "{povoado} asks for help {ate}. The baron died, the will vanished, and a distant relative turned up in a great hurry."], "pt": ["Ajudem {povoado}. O testamento do barão sumiu na noite da morte dele, e quem o roubou quer o feudo para si. A leitura é amanhã.", "Por favor, achem o testamento do barão. Ele foi levado para {lugar}, e sem ele o feudo de {povoado} vai para quem não deve.", "{povoado} pede ajuda {ate}. O barão morreu, o testamento sumiu, e um parente distante apareceu cheio de pressa."]}, "abert": {"en": ["The heroes follow the trail of the baron's stolen papers to {lugar}."], "pt": ["Os heróis seguem o rastro dos papéis roubados do barão até {lugar}."]}, "fala": {"en": ["The baron left the fief to the people of {povoado} to look after, and that is written in the will. {vilao} stole the paper and turned up claiming to be the baron's cousin. If the will is read, the lie is over. It is kept deep inside."], "pt": ["O barão deixou o feudo para o povo de {povoado} cuidar, e isso está escrito no testamento. {vilao} roubou o papel e apareceu dizendo ser primo do barão. Se o testamento for lido, a mentira acaba. Está guardado lá no fundo."]}, "pista": {"nome": {"en": "A broken seal", "pt": "Um selo partido"}, "olhar": {"en": "A wax seal with the baron's crest, broken in half.", "pt": "Um selo de cera com o brasão do barão, partido ao meio."}, "revela": {"en": "A broken wax seal lies near the entrance.", "pt": "Há um selo de cera partido perto da entrada."}, "texto": {"en": ["The seal is the baron's, and it was broken by someone who opened the will without the right to. Beside it is a draft sheet with the baron's signature copied over and over, better each time. The last copy is nearly perfect, and below it someone has practiced another signature: {vilao}."], "pt": ["O selo é do barão, e foi partido por alguém que abriu o testamento sem direito. Ao lado, uma folha de rascunho com a assinatura do barão copiada várias vezes, cada vez melhor. A última cópia está quase perfeita, e embaixo dela alguém treinou outra assinatura: {vilao}."]}}, "ultima": {"en": ["The will is on a table, and {vilao} holds it over a lit candle."], "pt": ["O testamento está numa mesa, e {vilao} o segura sobre uma vela acesa."]}, "narr": {"en": ["As you come in, {vilao} moves the paper closer to the flame."], "pt": ["Quando vocês entram, {vilao} aproxima o papel da chama."]}, "vil": {"en": ["One step, and the baron dies again, this time without a will."], "pt": ["Um passo, e o barão morre de novo, desta vez sem testamento."]}, "hc": {"en": ["{povoado} wants to hear the baron."], "pt": ["{povoado} quer ouvir o barão."]}, "hs": {"en": ["Drop the paper."], "pt": ["Larga o papel."]}, "fim": {"en": ["The will is saved with one corner burned. The name of the one who inherits the fief can still be read."], "pt": ["O testamento é salvo com uma ponta queimada. O nome de quem herda o feudo continua legível."]}, "fecho": {"en": ["In {povoado}, the will is read in the square, and the people listen in silence to the baron's last wish."], "pt": ["Em {povoado}, o testamento é lido na praça, e o povo ouve em silêncio a última vontade do barão."]}, "pa": {"en": ["A broken seal, in the middle of the road."], "pt": ["Um selo partido, no meio da estrada."]}, "pb": {"en": ["A baron's seal. Someone opened what they should not have."], "pt": ["Selo de barão. Alguém abriu o que não devia."]}, "entr": {"en": ["There is a broken wax seal at the entrance of {lugar}, with the baron's crest."], "pt": ["Tem um selo de cera partido na entrada de {lugar}, com o brasão do barão."]}, "chave": {"en": ["From deep inside comes the smell of burning paper. It seems someone is destroying documents."], "pt": ["Lá do fundo vem um cheiro de papel queimado. Parece que alguém está destruindo documentos."]}, "chc": {"en": ["From deep inside comes the smell of burning paper. It seems someone is destroying documents. The will may be among them."], "pt": ["Lá do fundo vem um cheiro de papel queimado. Parece que alguém está destruindo documentos. O testamento pode estar entre eles."]}, "chs": {"en": ["From deep inside comes the smell of burning paper. It seems someone is destroying documents. The broken seal on the road was from the baron's will."], "pt": ["Lá do fundo vem um cheiro de papel queimado. Parece que alguém está destruindo documentos. O selo partido da estrada era do testamento do barão."]}, "elos": [{"t": "n", "txt": {"en": ["At the entrance lies a wax seal of the baron, broken in half."], "pt": ["Na entrada, há um selo de cera do barão, partido ao meio."]}}, {"t": "h", "txt": {"en": ["The seal of the will the notice spoke of. Someone opened it without the right to."], "pt": ["O selo do testamento de que o aviso falava. Alguém o abriu sem direito."]}}]}, "coroa/prisioneiro": {"tit": {"en": ["The Imprisoned Heir", "Ten Years in {lugar}", "The True Heir"], "pt": ["O Herdeiro Preso", "Dez Anos em {lugar}", "O Verdadeiro Herdeiro"]}, "aviso": {"en": ["Help {povoado}. The heir to the barony, whom everyone has believed lost for ten years, is a prisoner in {lugar}, and the one sitting in the baron's chair is an impostor.", "Please free the true heir. Those who saw him say he is alive, imprisoned in {lugar}, and the impostor of {povoado} wants him to stay that way.", "{povoado} asks for help. A prisoner escaped from {lugar} and swore he had seen the baron's heir in there, in chains."], "pt": ["Ajudem {povoado}. O herdeiro do baronato, que todos davam por sumido há dez anos, está preso em {lugar}, e quem ocupa a cadeira do barão é um impostor.", "Por favor, libertem o herdeiro verdadeiro. Quem o viu diz que está vivo, preso em {lugar}, e o impostor de {povoado} quer que continue assim.", "{povoado} pede ajuda. Um prisioneiro fugiu de {lugar} e jurou ter visto o herdeiro do barão lá dentro, acorrentado."]}, "abert": {"en": ["The heroes reach {lugar} and see a reinforced door at the back, with three padlocks."], "pt": ["Os heróis chegam a {lugar} e veem uma porta reforçada no fundo, com três cadeados."]}, "fala": {"en": ["Ten years ago, {vilao} locked the heir up here and took his place. He has grown old in the cell, but he still has the birthmark on his neck. Get him out of there, and the lie is over."], "pt": ["Há dez anos, {vilao} prendeu o herdeiro aqui e tomou o lugar dele. Ele envelheceu na cela, mas ainda tem a marca de nascença no pescoço. Tirem ele de lá, e a mentira acaba."]}, "pista": {"nome": {"en": "A prisoner's letter", "pt": "Uma carta de prisioneiro"}, "olhar": {"en": "A paper folded many times, written in charcoal.", "pt": "Um papel dobrado muitas vezes, escrito com carvão."}, "revela": {"en": "A folded paper lies near the entrance.", "pt": "Há um papel dobrado perto da entrada."}, "texto": {"en": ["The letter was written in charcoal, in the careful hand of someone taught young: “I am the baron's heir. I have been here for ten years.” Whoever threw it through the bars hoped someone would find it, and at the end of the letter, underlined, is the name of the one who took his place: {vilao}."], "pt": ["A carta foi escrita com carvão, em letra cuidadosa de quem aprendeu cedo: «Sou o herdeiro do barão. Estou aqui há dez anos.» Quem a jogou pela grade esperava que alguém achasse, e no fim da carta, sublinhado, o nome de quem tomou o lugar dele: {vilao}."]}}, "ultima": {"en": ["The heir is chained at the back of the cell, and {vilao} stands in the doorway, keys in hand."], "pt": ["O herdeiro está acorrentado no fundo da cela, e {vilao} está na porta, com as chaves na mão."]}, "narr": {"en": ["As you come in, the prisoner lifts his head and shows his neck."], "pt": ["Quando vocês entram, o prisioneiro levanta a cabeça e mostra o pescoço."]}, "vil": {"en": ["Ten years I have kept that one. I am not losing him now."], "pt": ["Dez anos guardando esse daí. Não vou perder agora."]}, "hc": {"en": ["{povoado} wants its true baron."], "pt": ["{povoado} quer o barão verdadeiro."]}, "hs": {"en": ["He is leaving with us."], "pt": ["Ele sai com a gente."]}, "fim": {"en": ["The chains fall, and the heir steps slowly out into the light, shielding his eyes. He asks whether his mother is still alive."], "pt": ["As correntes caem, e o herdeiro sai para a luz devagar, protegendo os olhos. Ele pergunta se a mãe ainda está viva."]}, "fecho": {"en": ["In {povoado}, the heir comes home, and those who knew the boy recognize the man by the mark on his neck."], "pt": ["Em {povoado}, o herdeiro volta para casa, e quem conhecia o menino reconhece o homem pela marca no pescoço."]}, "pa": {"en": ["A door with three padlocks."], "pt": ["Uma porta com três cadeados."]}, "pb": {"en": ["No one locks something up like that unless they want it hidden."], "pt": ["Ninguém tranca assim o que não quer esconder."]}, "entr": {"en": ["Look at the reinforced door at the back of {lugar}. Three padlocks. Someone is locked in there."], "pt": ["Olhem a porta reforçada no fundo de {lugar}. Três cadeados. Tem alguém trancado ali."]}, "chave": {"en": ["From deep inside comes a hoarse voice, asking for water. It sounds like the heir."], "pt": ["Lá do fundo vem uma voz rouca, pedindo água. Parece que é o herdeiro."]}, "chc": {"en": ["From deep inside comes a hoarse voice, asking for water. It sounds like the heir. The heir from the notice is alive."], "pt": ["Lá do fundo vem uma voz rouca, pedindo água. Parece que é o herdeiro. O herdeiro do aviso está vivo."]}, "chs": {"en": ["From deep inside comes a hoarse voice, asking for water. It sounds like the heir. He is the one behind the door with three padlocks."], "pt": ["Lá do fundo vem uma voz rouca, pedindo água. Parece que é o herdeiro. É ele quem está atrás da porta dos três cadeados."]}, "elos": [{"t": "n", "txt": {"en": ["From deep inside comes a hoarse voice, asking for water. The speaker has the accent of the people of {povoado}."], "pt": ["Lá do fundo vem uma voz rouca, pedindo água. Quem fala tem o sotaque da gente de {povoado}."]}}, {"t": "h", "txt": {"en": ["Someone changed the padlocks recently: the iron still shines. If the heir from the notice is alive, he is behind that door."], "pt": ["Alguém trocou os cadeados há pouco, porque o ferro ainda brilha. Se o herdeiro do aviso está vivo, está atrás dessa porta."]}}]}, "sino": {"tit": {"en": ["The Cracked Bell", "Midnight in {lugar}", "Silence the Bell"], "pt": ["O Sino Rachado", "Meia-Noite em {lugar}", "Calem o Sino"]}, "aviso": {"en": ["Help {povoado}. The cult has taken {lugar} and recast the bell of the old chapel, and now it tolls every midnight. {desde}, {sinal}.", "Please silence the bell of {lugar}. Every time it tolls, the dead around {povoado} climb out of their graves.", "{povoado} is calling for help. The bell of {lugar} has been ringing at midnight {desde}, and in the morning there are more open graves."], "pt": ["Ajudem {povoado}. O culto tomou {lugar} e refundiu o sino da velha capela, e agora ele badala toda meia-noite. {desde}, {sinal}.", "Por favor, calem o sino de {lugar}. Cada vez que ele badala, os mortos em volta de {povoado} saem das covas.", "{povoado} pede socorro. O sino de {lugar} toca à meia-noite {desde}, e de manhã há mais covas abertas."]}, "abert": {"en": ["The heroes reach {lugar} hours before midnight. High above, the bell is still silent."], "pt": ["Os heróis chegam a {lugar} horas antes da meia-noite. Lá no alto, o sino ainda está em silêncio."]}, "fala": {"en": ["They recast the old bell with the bones of the founders. {vilao} pulls the rope in person, every night, at midnight exactly. Break the bell, and the dead go back to sleep. Until then, stop your ears as best you can."], "pt": ["Fundiram o sino velho com os ossos dos fundadores. {vilao} toca a corda pessoalmente, toda noite, à meia-noite em ponto. Quebrem o sino, e os mortos voltam a dormir. Até lá, tapem os ouvidos como puderem."]}, "pista": {"nome": {"en": "A shard of bronze", "pt": "Um caco de bronze"}, "olhar": {"en": "A shard of black bronze, which still hums when touched.", "pt": "Um caco de bronze negro, que ainda zune quando tocado."}, "revela": {"en": "A piece of dark metal lies near the entrance.", "pt": "Há um pedaço de metal escuro perto da entrada."}, "texto": {"en": ["The shard still hums when you touch it. Its edge bears a hammer mark: someone tried to break the bell before and got no further than the first blow. From high above, a voice counts the hours left until midnight and repeats, at each one, the name of the one who will ring: {vilao}."], "pt": ["O caco ainda zune quando vocês o tocam. A borda tem marca de martelo: alguém tentou quebrar o sino antes e não passou do primeiro golpe. Lá do alto, uma voz conta as horas que faltam para a meia-noite e repete, a cada uma, o nome de quem vai tocar: {vilao}."]}}, "ultima": {"en": ["The black bell hangs above you, still trembling from its last toll. {vilao} holds the rope."], "pt": ["O sino negro está pendurado acima de vocês, ainda tremendo da última badalada. {vilao} segura a corda."]}, "narr": {"en": ["As you come in, {vilao} winds the rope around one fist."], "pt": ["Quando vocês entram, {vilao} enrola a corda no punho."]}, "vil": {"en": ["You are in time for midnight."], "pt": ["Chegaram a tempo para a meia-noite."]}, "hc": {"en": ["{povoado} wants silence."], "pt": ["{povoado} quer silêncio."]}, "hs": {"en": ["Tonight the bell does not ring."], "pt": ["Hoje o sino não toca."]}, "fim": {"en": ["The bell breaks in two, and its last sound trails across the valley until it is gone. For a while, all you hear is your own heartbeat."], "pt": ["O sino se parte em dois, e o último som dele se arrasta pelo vale até sumir. Por um tempo, vocês ouvem só o próprio coração."]}, "fecho": {"en": ["In {povoado}, midnight passes in silence, and those who slept with wool in their ears sleep without it."], "pt": ["Em {povoado}, a meia-noite passa em silêncio, e quem dormia com lã nos ouvidos dorme sem ela."]}, "pa": {"en": ["Listen: a bell, so far off you can barely hear it."], "pt": ["Escutem: um sino, tão longe que mal se ouve."]}, "pb": {"en": ["At this hour? What church rings at this hour?"], "pt": ["A esta hora? Que igreja toca a esta hora?"]}, "entr": {"en": ["The sound of the bell comes from {lugar}. And look at the graves around it: the earth is all churned up."], "pt": ["O som do sino vem de {lugar}. E reparem nas covas em volta: a terra está toda revirada."]}, "chave": {"en": ["The bell tolls, and the dead behind you rise. The only way is forward, to the bell."], "pt": ["O sino badala, e os mortos atrás de vocês se levantam. O único caminho é para frente, até o sino."]}, "chc": {"en": ["The bell tolls, and the dead behind you rise. The only way is forward, to the bell. It is the bell of the old chapel."], "pt": ["O sino badala, e os mortos atrás de vocês se levantam. O único caminho é para frente, até o sino. É o sino da velha capela."]}, "chs": {"en": ["The bell tolls, and the dead behind you rise. The only way is forward, to the bell. It is the bell you heard from afar, on the road."], "pt": ["O sino badala, e os mortos atrás de vocês se levantam. O único caminho é para frente, até o sino. É o sino que vocês ouviram de longe, na estrada."]}, "elos": [{"t": "n", "txt": {"en": ["Around the tower, the earth of the graves is churned up. That is what the bell from the notice does every midnight."], "pt": ["Em volta da torre, a terra das covas está revirada. É o que o sino do aviso faz toda meia-noite."]}}, {"t": "h", "txt": {"en": ["The bell from the notice. Midnight is hours away. We have until then."], "pt": ["O sino do aviso. Faltam horas para a meia-noite. Temos até lá."]}}]}, "sino/surdos": {"tit": {"en": ["The Deaf Village", "The Sound That Deafens", "The Bell of {vilao}"], "pt": ["A Vila Surda", "O Som que Ensurdece", "O Sino de {vilao}"]}, "aviso": {"en": ["Help {povoado}. {desde}, the bell of {lugar} has been ringing before dawn, and whoever hears it loses their hearing for a whole day. Now it has been three days.", "Please silence the bell of {lugar}. The people of {povoado} are going deaf, and the deaf walk there in their sleep.", "{povoado} is calling for help. The bell of {lugar} rings louder and louder, and the whole village already speaks in gestures."], "pt": ["Ajudem {povoado}. {desde}, o sino de {lugar} toca de madrugada, e quem ouve perde a audição por um dia inteiro. Agora já são três dias.", "Por favor, calem o sino de {lugar}. As pessoas de {povoado} estão ficando surdas, e os surdos andam até lá dormindo.", "{povoado} pede socorro. O sino de {lugar} toca cada vez mais alto, e a vila inteira já fala por gestos."]}, "abert": {"en": ["The heroes follow the road to {lugar}, and the silence on it is strange: not even the birds sing."], "pt": ["Os heróis seguem a estrada para {lugar}, e o silêncio nela é estranho: nem os pássaros cantam."]}, "fala": {"en": ["The bell of {vilao} steals the sound from whoever hears it, and those who go deaf begin to hear nothing but the bell. That is how {vilao} calls people here. Break the bell, and the sound comes back to everyone. Stop your ears before going in."], "pt": ["O sino de {vilao} rouba o som de quem o ouve, e quem fica surdo começa a ouvir só ele. É assim que {vilao} chama gente para cá. Quebrem o sino, e o som volta para todo mundo. Tapem os ouvidos antes de entrar."]}, "pista": {"nome": {"en": "A wad of wool", "pt": "Um chumaço de lã"}, "olhar": {"en": "A wad of wool, dirty with wax, lying on the ground.", "pt": "Um chumaço de lã, sujo de cera, caído no chão."}, "revela": {"en": "A wad of wool lies on the ground near the entrance.", "pt": "Há um chumaço de lã no chão perto da entrada."}, "texto": {"en": ["Someone used the wool to stop their ears and lost it: there are other wads along the way, each dirtier than the last. On the wall, someone has scratched hand signs, for those who can no longer hear, and in the middle of them a name written large: {vilao}."], "pt": ["Alguém usou a lã para tapar os ouvidos e a perdeu, porque há outros chumaços pelo caminho, cada vez mais sujos. Na parede, alguém riscou sinais de gestos, para quem não ouve mais, e no meio deles um nome escrito com letra grande: {vilao}."]}}, "ultima": {"en": ["The bell hangs high above, and {vilao} draws the rope slowly, without a sound, waiting for the hour."], "pt": ["O sino está pendurado no alto, e {vilao} puxa a corda devagar, sem fazer barulho, esperando a hora."]}, "narr": {"en": ["As you come in, {vilao} smiles and hauls on the rope."], "pt": ["Quando vocês entram, {vilao} sorri e puxa a corda com força."]}, "vil": {"en": ["Did you hear that? Soon, it is all you will hear."], "pt": ["Ouviram? Daqui a pouco, vão ouvir só isso."]}, "hc": {"en": ["{povoado} wants to hear again."], "pt": ["{povoado} quer ouvir de novo."]}, "hs": {"en": ["[covering the ears] Quickly, before that bell rings again."], "pt": ["[tapando os ouvidos] Rápido, antes que esse sino toque de novo."]}, "fim": {"en": ["The bell breaks in two, and its last sound fades from the air. A moment later, you hear a small bird singing."], "pt": ["O sino se parte em dois, e o último som dele some no ar. Logo depois, vocês ouvem um passarinho cantar."]}, "fecho": {"en": ["In {povoado}, the sound comes back little by little, and the first thing many people hear is their own laughter."], "pt": ["Em {povoado}, o som volta aos poucos, e a primeira coisa que muita gente ouve é a própria risada."]}, "pa": {"en": ["It is too quiet."], "pt": ["Está quieto demais."]}, "pb": {"en": ["Not even the birds sing here. How strange."], "pt": ["Nem os pássaros cantam aqui. Que estranho."]}, "entr": {"en": ["The silence at the entrance of {lugar} is strange. Have you heard a single bird since we arrived?"], "pt": ["O silêncio na entrada de {lugar} está estranho. Vocês ouviram algum pássaro desde que chegamos?"]}, "chave": {"en": ["The bell rings once, and for a moment you hear nothing at all, not even your own voice."], "pt": ["O sino toca uma vez, e por um instante vocês não ouvem nada, nem a própria voz."]}, "chc": {"en": ["The bell rings once, and for a moment you hear nothing at all, not even your own voice. It is the bell that takes the hearing of whoever hears it."], "pt": ["O sino toca uma vez, e por um instante vocês não ouvem nada, nem a própria voz. É o sino que tira a audição de quem o ouve."]}, "chs": {"en": ["The bell rings once, and for a moment you hear nothing at all, not even your own voice. That is why the birds on the road were silent."], "pt": ["O sino toca uma vez, e por um instante vocês não ouvem nada, nem a própria voz. Por isso os pássaros da estrada estavam quietos."]}, "elos": [{"t": "n", "txt": {"en": ["All that can be heard, very far off, is the hum of the bell. Whoever hears it before dawn goes deaf for a day, as the notice told."], "pt": ["Só se ouve, muito longe, o zumbido do sino. Quem o ouve de madrugada fica surdo por um dia, como o aviso contava."]}}, {"t": "h", "txt": {"en": ["Stop your ears before going in. The notice said that whoever hears this bell loses their hearing."], "pt": ["Tapem os ouvidos antes de entrar. O aviso dizia que quem ouve esse sino perde a audição."]}}]}, "sino/sineiro": {"tit": {"en": ["The Missing Bell-Ringer", "Who Rings the Bell", "The Loose Rope"], "pt": ["O Sineiro Desaparecido", "Quem Toca o Sino", "A Corda Solta"]}, "aviso": {"en": ["Help {povoado}. The bell-ringer of {lugar} has been missing {desde}, and even so the bell goes on ringing every midnight.", "Please find out who is ringing the bell of {lugar}. The bell-ringer has disappeared, and the bell rings by itself.", "{povoado} is calling for help. Ever since the bell-ringer vanished, the bell of {lugar} rings at midnight, and {sinal}."], "pt": ["Ajudem {povoado}. O sineiro de {lugar} está sumido {desde}, e mesmo assim o sino continua tocando toda meia-noite.", "Por favor, descubram quem toca o sino de {lugar}. O sineiro desapareceu, e o sino toca sozinho.", "{povoado} pede socorro. Desde que o sineiro sumiu, o sino de {lugar} toca à meia-noite, e {sinal}."]}, "abert": {"en": ["The heroes reach the bell tower of {lugar} and find the door open. The rope is swinging, with no one pulling it."], "pt": ["Os heróis chegam à torre do sino de {lugar} e acham a porta aberta. A corda balança, sem ninguém puxando."]}, "fala": {"en": ["The bell-ringer has rung that bell for forty years. {vilao} tied him up at the top and forces him to ring it at midnight, because the bell only calls the dead when the true bell-ringer is the one ringing. Get up there before midnight."], "pt": ["O sineiro tocava o sino há quarenta anos. {vilao} o amarrou lá no alto e o obriga a tocar à meia-noite, porque o sino só chama os mortos quando quem toca é o sineiro de verdade. Cheguem lá antes da meia-noite."]}, "pista": {"nome": {"en": "A bell-ringer's cap", "pt": "Um gorro de sineiro"}, "olhar": {"en": "A worn woolen cap, lying on the floor.", "pt": "Um gorro gasto, de lã, caído no chão."}, "revela": {"en": "A cap lies near the entrance.", "pt": "Há um gorro caído perto da entrada."}, "texto": {"en": ["The cap belongs to the bell-ringer, and it fell when he was dragged upstairs: there are heel marks on the steps. Inside the lining, the bell-ringer scrawled in charcoal: “{vilao} has me. Midnight.”"], "pt": ["O gorro é do sineiro, e caiu quando ele foi arrastado para cima, porque há marcas de calcanhar nos degraus. No forro do gorro, o sineiro escreveu com carvão, às pressas: «{vilao} me prendeu. Meia-noite.»"]}}, "ultima": {"en": ["The bell-ringer is tied up beside the bell, and {vilao} is putting the rope into his hands."], "pt": ["O sineiro está amarrado ao lado do sino, e {vilao} põe a corda nas mãos dele."]}, "narr": {"en": ["As you come in, the bell-ringer looks at you and shakes his head, begging you to stop this."], "pt": ["Quando vocês entram, o sineiro olha para vocês e balança a cabeça, pedindo que não deixem."]}, "vil": {"en": ["Ring it, old man. It is midnight."], "pt": ["Toca, velho. É meia-noite."]}, "hc": {"en": ["{povoado} wants its bell-ringer back."], "pt": ["{povoado} quer o sineiro de volta."]}, "hs": {"en": ["He is done ringing for tonight."], "pt": ["Ele não toca mais hoje."]}, "fim": {"en": ["The bell cracks apart, and the bell-ringer is untied. He runs his hand slowly over the split bronze, like a man saying goodbye to a friend."], "pt": ["O sino se parte, e o sineiro é desamarrado. Ele passa a mão no bronze rachado, devagar, como quem se despede de um amigo."]}, "fecho": {"en": ["In {povoado}, the bell-ringer is given a new bell, a small one, which he rings only at noon."], "pt": ["Em {povoado}, o sineiro ganha um sino novo, pequeno, que ele toca só ao meio-dia."]}, "pa": {"en": ["The tower door is open."], "pt": ["A porta da torre está aberta."]}, "pb": {"en": ["And the rope is swinging by itself. That is no wind."], "pt": ["E a corda balançando sozinha. Isso não é vento."]}, "entr": {"en": ["The door of the bell tower of {lugar} stands open, and the rope swings with no one pulling it."], "pt": ["A torre do sino de {lugar} está de porta aberta, e a corda balança sem ninguém puxando."]}, "chave": {"en": ["From high above comes the bell-ringer's voice, praying. A moment later, {vilao} shouts: “Midnight is almost here!”"], "pt": ["Lá do alto vem a voz do sineiro, rezando. Logo depois, {vilao} grita: «Falta pouco para a meia-noite!»"]}, "chc": {"en": ["From high above comes the bell-ringer's voice, praying. A moment later, {vilao} shouts: “Midnight is almost here!” The bell-ringer from the notice is up there."], "pt": ["Lá do alto vem a voz do sineiro, rezando. Logo depois, {vilao} grita: «Falta pouco para a meia-noite!» O sineiro do aviso está lá em cima."]}, "chs": {"en": ["From high above comes the bell-ringer's voice, praying. A moment later, {vilao} shouts: “Midnight is almost here!” The keeper of this tower is up there, a prisoner."], "pt": ["Lá do alto vem a voz do sineiro, rezando. Logo depois, {vilao} grita: «Falta pouco para a meia-noite!» Quem cuida desta torre está lá em cima, preso."]}, "elos": [{"t": "n", "txt": {"en": ["On the first step of the tower lies the cap of the bell-ringer from the notice, trampled."], "pt": ["No primeiro degrau da torre, há o gorro do sineiro do aviso, pisado."]}}, {"t": "h", "txt": {"en": ["The bell-ringer from the notice must be up there."], "pt": ["O sineiro do aviso deve estar lá em cima."]}}]}, "colheita": {"tit": {"en": ["Bread for the Winter", "The Grain of {povoado}", "The Trail of Sacks"], "pt": ["Pão para o Inverno", "Os Grãos de {povoado}", "A Trilha dos Sacos"]}, "aviso": {"en": ["Help {povoado} recover {alvo}. The granary was broken into at night, and beasts dragged everything to {lugar}. Without {alvo}, the village will last to midwinter, if that.", "Please bring {alvo} back. The beasts took the harvest of {povoado}, and {desde} {gente} {gentefaz}.", "{povoado} needs help {ate}. The whole harvest is in {lugar}, guarded by beasts."], "pt": ["Ajudem {povoado} a recuperar {alvo}. O celeiro foi arrombado de noite, e feras arrastaram tudo para {lugar}. Sem {alvo}, a aldeia chega à metade do inverno, se tanto.", "Por favor, tragam {alvo} de volta. As feras levaram a colheita de {povoado}, e {desde} {gente} {gentefaz}.", "{povoado} precisa de ajuda {ate}. A colheita inteira está em {lugar}, guardada por feras."]}, "abert": {"en": ["The heroes follow the trail of grain that leads out of the granary and straight into {lugar}."], "pt": ["Os heróis seguem a trilha de grãos que sai do celeiro e entra direto em {lugar}."]}, "fala": {"en": ["They came down from the hills when the frost came early, a whole pack, and the one leading them is {vilao}. They hoard {alvo} in there the way a squirrel hoards nuts. Very large squirrels. Bring back every sack you can."], "pt": ["Vieram das colinas quando a geada chegou cedo, uma matilha inteira, e quem guia é {vilao}. Guardam {alvo} aí dentro como esquilo guarda nozes. Esquilos bem grandes. Tragam cada saco que der."]}, "pista": {"nome": {"en": "A trail of grain", "pt": "Uma trilha de grãos"}, "olhar": {"en": "Grain scattered on the ground, in a line that leads inside.", "pt": "Grãos espalhados no chão, numa linha que leva para dentro."}, "revela": {"en": "There is grain scattered on the ground near the entrance.", "pt": "Há grãos espalhados no chão perto da entrada."}, "texto": {"en": ["The grain fell from sacks torn open by teeth, in an unbroken trail, with no hurry at all. Among the smaller footprints are the marks of much larger paws, those of the pack leader, whom the farmers of {povoado} already know and call by name: {vilao}."], "pt": ["Os grãos caíram de sacos rasgados a dente, numa trilha contínua, sem pressa nenhuma. No meio das pegadas menores há marcas de patas muito maiores, as do líder da matilha, que os lavradores de {povoado} já conhecem e chamam pelo nome: {vilao}."]}}, "ultima": {"en": ["{vilao} guards the last sacks, teeth bared."], "pt": ["{vilao} guarda os últimos sacos, mostrando os dentes."]}, "narr": {"en": ["The pack rises as you come in, and {vilao} stands in front of the sacks."], "pt": ["A matilha se levanta quando vocês entram, e {vilao} fica na frente dos sacos."]}, "vil": {"en": ["(A low growl, and the pack takes one step forward.)"], "pt": ["(Um rosnado baixo, e a matilha avança um passo.)"]}, "hc": {"en": ["{povoado} wants its sacks back. All of them."], "pt": ["{povoado} quer os sacos de volta. Todos."]}, "hs": {"en": ["The harvest goes back to those who planted it."], "pt": ["A colheita volta para quem plantou."]}, "fim": {"en": ["The sacks come out torn, slobbered on and short of full, but they come out. There is still bread for the whole winter."], "pt": ["Os sacos saem rasgados, babados e incompletos, mas saem. Ainda dá pão para o inverno inteiro."]}, "fecho": {"en": ["In {povoado}, the sacks go back into the granary, and someone climbs onto the roof to patch the hole."], "pt": ["Em {povoado}, os sacos voltam ao celeiro, e alguém sobe no telhado para tapar o buraco."]}, "pa": {"en": ["The fields have already been harvested, but the granaries are empty."], "pt": ["Os campos já foram colhidos, mas os celeiros estão vazios."]}, "pb": {"en": ["And those claw marks on the door are far too big for a rat."], "pt": ["E essas marcas de garra na porta são grandes demais para rato."]}, "entr": {"en": ["This trail of grain leads into {lugar}. Look at the sacks torn open by teeth at the entrance."], "pt": ["Essa trilha de grãos entra em {lugar}. Olhem os sacos rasgados a dente na entrada."]}, "chave": {"en": ["You see a trail of husks and hear the sound of chewing. The beasts are eating {alvo}, sack by sack."], "pt": ["Vocês veem uma trilha de cascas e ouvem um som de mastigação. As feras estão comendo {alvo}, saco por saco."]}, "chc": {"en": ["You see a trail of husks and hear the sound of chewing. The beasts are eating {alvo}, sack by sack. Every sack that goes is less food for the winter of {povoado}."], "pt": ["Vocês veem uma trilha de cascas e ouvem um som de mastigação. As feras estão comendo {alvo}, saco por saco. Cada saco que vai embora é comida a menos para o inverno de {povoado}."]}, "chs": {"en": ["You see a trail of husks and hear the sound of chewing. The beasts are eating {alvo}, sack by sack. The empty granaries on the road were emptied by these beasts."], "pt": ["Vocês veem uma trilha de cascas e ouvem um som de mastigação. As feras estão comendo {alvo}, saco por saco. Os celeiros vazios da estrada foram esvaziados por estas feras."]}, "elos": [{"t": "h", "txt": {"en": ["Look at the sacks torn open by teeth. This is the harvest of {povoado}, the one from the notice."], "pt": ["Olhem os sacos rasgados a dente. É a colheita de {povoado}, a do aviso."]}}, {"t": "n", "txt": {"en": ["At the entrance lie sacks torn open by teeth, and from inside comes the sound of chewing."], "pt": ["Na entrada, há sacos rasgados a dente, e lá de dentro vem um som de mastigação."]}}]}, "colheita/pomar": {"tit": {"en": ["The Orchard of {povoado}", "The Uprooted Trees", "Before the Last Fruit"], "pt": ["O Pomar de {povoado}", "As Árvores Arrancadas", "Antes da Última Fruta"]}, "aviso": {"en": ["Help {povoado}. {desde}, beasts have been coming down from {lugar} every night and destroying the orchard, and not one tree is left bearing fruit.", "Please put an end to the beasts of {lugar}. They tear up the trees of {povoado} by the roots, and carry everything to their den.", "{povoado} is calling for help. The whole orchard has been dragged to {lugar}, branch by branch."], "pt": ["Ajudem {povoado}. {desde}, feras descem de {lugar} toda noite e destroem o pomar, e já não resta árvore com fruta.", "Por favor, acabem com as feras de {lugar}. Elas arrancam as árvores de {povoado} pela raiz, e levam tudo para a toca.", "{povoado} pede socorro. O pomar inteiro foi arrastado para {lugar}, galho por galho."]}, "abert": {"en": ["The heroes follow the trail of broken branches and trampled fruit to {lugar}."], "pt": ["Os heróis seguem a trilha de galhos quebrados e frutas pisadas até {lugar}."]}, "fala": {"en": ["The one leading the beasts is {vilao}, and they do not eat the fruit: they hoard it all in the den, for the winter. If you recover the sacks of fruit and seeds, {povoado} can replant in the spring. If not, the orchard is lost for good."], "pt": ["Quem guia as feras é {vilao}, e elas não comem as frutas: guardam tudo na toca, para o inverno. Se recuperarem os sacos de frutas e sementes, {povoado} replanta na primavera. Se não, perde o pomar para sempre."]}, "pista": {"nome": {"en": "A dragged branch", "pt": "Um galho arrastado"}, "olhar": {"en": "A branch from a fruit tree, with tooth marks on it.", "pt": "Um galho de árvore frutífera, com marcas de dente."}, "revela": {"en": "A broken branch lies near the entrance.", "pt": "Há um galho quebrado perto da entrada."}, "texto": {"en": ["The branch was dragged all the way from the orchard of {povoado}: it still has green leaves and fruit on it. The tooth marks are those of a large animal, which the farmers have already seen prowling at night and call by name: {vilao}."], "pt": ["O galho foi arrastado desde o pomar de {povoado}, porque ainda tem folhas verdes e frutas presas. As marcas de dente são de um bicho grande, que os lavradores já viram rondando à noite e chamam pelo nome: {vilao}."]}}, "ultima": {"en": ["Heaps of fruit and branches fill the den, and {vilao} lies on top of them."], "pt": ["Pilhas de frutas e galhos enchem a toca, e {vilao} está deitad⟨vilao:o|a⟩ em cima delas."]}, "narr": {"en": ["As you come in, {vilao} rises, and an apple rolls off its back."], "pt": ["Quando vocês entram, {vilao} se levanta, e uma maçã rola das costas del⟨vilao:e|a⟩."]}, "vil": {"en": ["(A growl, and the beasts all around stop chewing.)"], "pt": ["(Um rosnado, e as feras em volta param de mastigar.)"]}, "hc": {"en": ["{povoado} wants its orchard back."], "pt": ["{povoado} quer o pomar de volta."]}, "hs": {"en": ["That fruit has an owner."], "pt": ["Essas frutas têm dono."]}, "fim": {"en": ["The sacks of fruit and seeds come out of the den. The orchard will have to be replanted, but there will be something to replant it with."], "pt": ["Os sacos de frutas e sementes saem da toca. O pomar vai ter que ser replantado, mas vai ter com que replantar."]}, "fecho": {"en": ["In {povoado}, the seeds are stored in the driest place in the village, waiting for spring."], "pt": ["Em {povoado}, as sementes são guardadas no lugar mais seco da vila, esperando a primavera."]}, "pa": {"en": ["Trampled fruit in the middle of the road."], "pt": ["Frutas pisadas no meio da estrada."]}, "pb": {"en": ["And whole branches. This was torn off, not picked."], "pt": ["E galhos inteiros. Isso foi arrancado, não colhido."]}, "entr": {"en": ["Branches and trampled fruit make a trail that leads into {lugar}. Something dragged a whole orchard here."], "pt": ["Galhos e frutas pisadas fazem uma trilha que entra em {lugar}. Alguma coisa arrastou um pomar inteiro até aqui."]}, "chave": {"en": ["You hear the sound of a tree being dragged, and a moment later a growl. One more branch has reached the den."], "pt": ["Vocês ouvem um som de árvore sendo arrastada, e logo depois um rosnado. Mais um galho chegou à toca."]}, "chc": {"en": ["You hear the sound of a tree being dragged, and a moment later a growl. One more branch has reached the den. It is the orchard of {povoado}."], "pt": ["Vocês ouvem um som de árvore sendo arrastada, e logo depois um rosnado. Mais um galho chegou à toca. É o pomar de {povoado}."]}, "chs": {"en": ["You hear the sound of a tree being dragged, and a moment later a growl. One more branch has reached the den. The branches torn off along the road were on their way here."], "pt": ["Vocês ouvem um som de árvore sendo arrastada, e logo depois um rosnado. Mais um galho chegou à toca. Os galhos arrancados da estrada vinham para cá."]}, "elos": [{"t": "n", "txt": {"en": ["From inside comes the noise of a tree being dragged. It is the orchard of {povoado}, arriving in pieces."], "pt": ["Lá de dentro vem o barulho de uma árvore sendo arrastada. É o pomar de {povoado} chegando aos pedaços."]}}, {"t": "h", "txt": {"en": ["The trees of the orchard from the notice ended up here. Something dragged a whole orchard."], "pt": ["As árvores do pomar do aviso vieram parar aqui. Alguma coisa arrastou um pomar inteiro."]}}]}, "colheita/moleiro": {"tit": {"en": ["The Missing Miller", "The Flour of {povoado}", "The Idle Mill"], "pt": ["O Moleiro Sumido", "A Farinha de {povoado}", "O Moinho Parado"]}, "aviso": {"en": ["Help {povoado}. The miller took {alvo} to be ground in {lugar} and did not come back. {desde}, the mill has stood idle, and the village has had no flour.", "Please find the miller of {povoado}. He set out with his cart full of {alvo}, and only the cart came back, empty.", "{povoado} asks for help {ate}. The miller and the harvest vanished on the way to {lugar}, and without flour no one gets through the winter."], "pt": ["Ajudem {povoado}. O moleiro levou {alvo} para moer em {lugar} e não voltou. {desde}, o moinho está parado, e a aldeia está sem farinha.", "Por favor, achem o moleiro de {povoado}. Ele saiu com a carroça cheia de {alvo}, e só a carroça voltou, vazia.", "{povoado} pede ajuda {ate}. O moleiro e a colheita sumiram a caminho de {lugar}, e sem farinha ninguém passa o inverno."]}, "abert": {"en": ["The heroes follow the tracks of the miller's cart to {lugar}. Beside them are animal footprints."], "pt": ["Os heróis seguem as marcas da carroça do moleiro até {lugar}. Ao lado delas, há pegadas de bicho."]}, "fala": {"en": ["The miller was caught on the way by the beasts of {vilao}, and they dragged the sacks to their den. The miller is trapped deep inside, on top of the sacks, because that is the one place the beasts do not tread. Bring back the sacks, and bring him too."], "pt": ["O moleiro foi pego pelas feras de {vilao} no caminho, e elas arrastaram os sacos para a toca. O moleiro está preso lá no fundo, em cima dos sacos, porque é o único lugar onde as feras não pisam. Tragam os sacos, e tragam ele."]}, "pista": {"nome": {"en": "A sack of flour", "pt": "Um saco de farinha"}, "olhar": {"en": "A torn sack of flour, with the mark of the mill.", "pt": "Um saco de farinha rasgado, com a marca do moinho."}, "revela": {"en": "A torn sack lies near the entrance.", "pt": "Há um saco rasgado perto da entrada."}, "texto": {"en": ["The sack bears the mark of the mill of {povoado}, and it was torn open by teeth. The spilled flour shows the footprints of many beasts, and one larger than the rest, which the farmers know and call by name: {vilao}."], "pt": ["O saco tem a marca do moinho de {povoado}, e foi rasgado a dente. A farinha espalhada mostra pegadas de muitas feras, e uma maior que as outras, que os lavradores conhecem e chamam pelo nome: {vilao}."]}}, "ultima": {"en": ["The miller is huddled on top of a pile of sacks, and {vilao} prowls around the pile."], "pt": ["O moleiro está encolhido em cima de uma pilha de sacos, e {vilao} ronda a pilha."]}, "narr": {"en": ["As you come in, the miller waves his hat, white with flour."], "pt": ["Quando vocês entram, o moleiro acena com o chapéu, branco de farinha."]}, "vil": {"en": ["(A growl, and the pack closes in around the pile of sacks.)"], "pt": ["(Um rosnado, e a matilha cerca a pilha de sacos.)"]}, "hc": {"en": ["{povoado} wants its miller and its flour."], "pt": ["{povoado} quer o moleiro e a farinha."]}, "hs": {"en": ["Come down from there. We will hold them off."], "pt": ["Desce daí, que a gente segura."]}, "fim": {"en": ["The miller climbs down from the pile of sacks and hugs the first hero he meets, leaving a white floury mark on that hero's back."], "pt": ["O moleiro desce da pilha de sacos e abraça o primeiro herói que encontra, deixando uma marca branca de farinha nas costas dele."]}, "fecho": {"en": ["In {povoado}, the mill turns again, and the first loaf from the new flour is given to you."], "pt": ["Em {povoado}, o moinho volta a girar, e o primeiro pão da nova farinha é dado a vocês."]}, "pa": {"en": ["Flour on the road."], "pt": ["Farinha no chão da estrada."]}, "pb": {"en": ["And animal footprints over it. Someone lost a load."], "pt": ["E pegadas de bicho por cima. Alguém perdeu a carga."]}, "entr": {"en": ["The tracks of the miller's cart lead into {lugar}, and there is flour spilled at the entrance."], "pt": ["As marcas da carroça do moleiro entram em {lugar}, e tem farinha espalhada na entrada."]}, "chave": {"en": ["From deep inside comes the miller's voice, calling for help. A moment later, a growl silences him."], "pt": ["Lá do fundo vem a voz do moleiro, pedindo socorro. Logo depois, um rosnado manda ele calar."]}, "chc": {"en": ["From deep inside comes the miller's voice, calling for help. A moment later, a growl silences him. The miller from the notice is alive."], "pt": ["Lá do fundo vem a voz do moleiro, pedindo socorro. Logo depois, um rosnado manda ele calar. O moleiro do aviso está vivo."]}, "chs": {"en": ["From deep inside comes the miller's voice, calling for help. A moment later, a growl silences him. The flour on the road came from his load."], "pt": ["Lá do fundo vem a voz do moleiro, pedindo socorro. Logo depois, um rosnado manda ele calar. A farinha da estrada era da carga dele."]}, "elos": [{"t": "n", "txt": {"en": ["From deep inside comes the miller's voice, calling for help, and a moment later a growl."], "pt": ["Lá do fundo vem a voz do moleiro, pedindo socorro, e logo depois um rosnado."]}}, {"t": "h", "txt": {"en": ["Flour spilled at the entrance. The miller from the notice lost his load here."], "pt": ["Farinha espalhada na entrada. O moleiro do aviso perdeu a carga aqui."]}}]}};
