  // never drawn without it)
  const daLinha = fam => { const id = plano.linha && plano.linha[fam]; return id ? HIST(fam).find(s => s.id === id) || null : null; };
  const livre = s => !s.linha;
  if (t === 'selos') plano.roupaTruque = daLinha('pecas') || roupaDe(plano, 'pecas', s => livre(s) && carrega(s)) || roupaDe(plano, 'pecas', livre);
  if (t === 'escolta') plano.roupaGuia = daLinha('escolta') || roupaDe(plano, 'escolta', livre);
  if (t === 'resgate' || (!t && plano.premissa.id === 'resgate')) plano.roupaResgate = daLinha('resgate') || roupaDe(plano, 'resgate', s => livre(s) && carrega(s));
  // (the escape's collapse: a clock that fits running out of a place, a flood, a fire, a cave-in…)
  // (a flood is the tide, with its own rules (the extra rule "Tide"): never a mere count of rounds dressed as water)
  const semAgua = s => s.id !== 'inundacao';
  // (the defence: what the heroes hold out for, a clock of their own (until the tower burns, until dawn…); the tide: the water
  // of a clock tells why it rises)
  const semAgua0 = semAgua; const semAguaL = s => semAgua0(s) && !s.linha;
  plano.roupaRelogio = plano.premissa.relogio ? HIST('relogio').find(s => s.id === plano.premissa.relogio) || null
    : t === 'desabamento' && plano.premissa.id === 'fuga' ? roupaDe(plano, 'relogio', s => semAguaL(s) && ((s.p || []).includes('fuga') || s.id === 'desabamento'))
    : t === 'ninhos' ? roupaDe(plano, 'relogio', s => !!s.ninho && !s.linha)
    : t !== 'desabamento' && plano.premissa.id === 'defesa' ? roupaDe(plano, 'relogio', s => !!s.defesa && !s.linha)
    : t !== 'desabamento' && plano.modalidade?.id === 'mare' ? roupaDe(plano, 'relogio', s => AGUA_DA_MARE.includes(s.id) && !s.linha)
    : roupaDe(plano, 'relogio', semAguaL);
  plano.roupasComp = (plano.complicacoes || []).map(c => c === 'ondas' ? roupaDe(plano, 'ondas', carrega) || roupaDe(plano, 'ondas')
    : roupaDe(plano, 'pecas', s => s.modo === 'simples' && !s.linha && carrega(s)) || roupaDe(plano, 'pecas', s => s.modo === 'simples' && !s.linha));
  const m = plano.modalidade?.id; const R = k => roupaDe(plano, 'regras.' + k);
  if (m === 'mercador') plano.roupaRegra = R('mercador');
