  (pm.contadores || []).forEach(c => todosGatilhos(c).forEach(g => { if (g.tipo === 'give_item' && g.modo === 'newitem') achados.push({ g, si: -1 }); }));
  const ordem = achados.slice().sort((a, b) => (b.si === fim) - (a.si === fim)); let ficam = 0;
