      if (ilhaAntes.length || filhas(si).length) { const v4 = vigia(3); ev['conta:' + v4.uid] = ilhaAntes.concat(filhas(si).map(f => ({ uid: uid(), tipo: 'remove_room', sala: f, requisitos: [] }))); }
