  if (o.ajuste == null) { if (o.perigo != null) Object.assign(o, difEAjusteDoPerigo(perigoDe(o))); else o.ajuste = 0; } delete o.perigo;   // (v346: Easy, Normal or Hard, and the adjustment)
  if (!o.semente) o.semente = sementeCompleta(o.duracao, o.dificuldade, o.atos, '', null, o.ajuste);
