  const seguirSemente = () => { const ls = lerSemente($('#gm_sem').value); if (!ls) return; $('#gm_dur').value = ls.duracao; const da = ls.ajuste != null ? ls : difEAjusteDoPerigo(ls.perigo); $('#gm_dif').value = da.dificuldade; $('#gm_aj').value = String(da.ajuste); $('#gm_atos').value = String(ls.atos); $('#gm_sem').value = ls.semente; };
